export const EXDB=[{"id":"0001","n":"Abdominales 3/4","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0001-2gPfomN.jpg","gif":"0001-2gPfomN.gif"},{"id":"0002","n":"Flexión lateral a 45°","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia abajo a los lados.","Manteniendo la espalda recta y el core activado, flexiona lentamente el torso hacia un lado, bajando la mano hacia la rodilla.","Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.","Repite del otro lado.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0002-Hy9D21L.jpg","gif":"0002-Hy9D21L.gif"},{"id":"0003","n":"Air bike","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Túmbate sobre tu espalda con las manos colocadas detrás de la cabeza.","Levanta las piernas del suelo y flexiona las rodillas formando un ángulo de 90 grados.","Lleva el codo derecho hacia la rodilla izquierda mientras simultáneamente estiras la pierna derecha.","Regresa a la posición inicial y repite el movimiento del lado opuesto, llevando el codo izquierdo hacia la rodilla derecha mientras estiras la pierna izquierda.","Continúa alternando lados con un movimiento de pedaleo durante el número de repeticiones deseado."],"img":"0003-1ZFqTDN.jpg","gif":"0003-1ZFqTDN.gif"},{"id":"1512","n":"Estiramiento de sentadilla en cuatro apoyos","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Comienza apoyado sobre manos y rodillas, con las manos justo debajo de los hombros y las rodillas justo debajo de las caderas.","Extiende una pierna hacia atrás, manteniendo la rodilla flexionada y el pie en flexión.","Baja lentamente las caderas hacia el suelo, sintiendo un estiramiento en los cuádriceps.","Mantén esta posición durante 20-30 segundos.","Cambia de pierna y repite el estiramiento del otro lado."],"img":"1512-qBcKorM.jpg","gif":"1512-qBcKorM.gif"},{"id":"0006","n":"Toques de talón alternos","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Extiende los brazos hacia los lados, paralelos al suelo.","Activando el abdomen, levanta los hombros del suelo y lleva la mano derecha hacia el talón derecho.","Regresa a la posición inicial y repite del lado izquierdo, llevando la mano izquierda hacia el talón izquierdo.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0006-qaZVsGk.jpg","gif":"0006-qaZVsGk.gif"},{"id":"0007","n":"Jalón lateral alterno","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","rhomboids"],"st":["Siéntate en la máquina de cable con la espalda recta y los pies apoyados en el suelo.","Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.","Inclínate ligeramente hacia atrás y lleva las agarraderas hacia el pecho, juntando los omóplatos.","Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0007-4IKbhHV.jpg","gif":"0007-4IKbhHV.gif"},{"id":"1368","n":"Rotaciones de tobillo","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankle stabilizers","sm":["ankle stabilizers"],"st":["Siéntate en el suelo con las piernas extendidas frente a ti.","Levanta una pierna del suelo y rota el tobillo con un movimiento circular.","Realiza el número de círculos deseado en una dirección, luego cambia a la dirección contraria.","Repite con la otra pierna."],"img":"1368-uL9CsKm.jpg","gif":"1368-uL9CsKm.gif"},{"id":"3293","n":"Dominadas arqueras","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Comienza colgándote de una barra de dominadas con un agarre prono, un poco más separado que el ancho de los hombros.","Activa el core y lleva los omóplatos hacia abajo y atrás.","Mientras te elevas, flexiona un brazo y lleva el codo hacia el costado, manteniendo el otro brazo recto.","Continúa subiendo hasta que la barbilla quede por encima de la barra y el brazo flexionado esté completamente doblado.","Bájate de nuevo con control, estirando el brazo flexionado y repitiendo el movimiento del otro lado.","Alterna los lados en cada repetición."],"img":"3293-72BC5Za.jpg","gif":"3293-72BC5Za.gif"},{"id":"3294","n":"Flexiones arqueras","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Comienza en posición de flexión de brazos con las manos un poco más separadas que el ancho de los hombros.","Extiende un brazo hacia el lado, paralelo al suelo.","Baja el cuerpo flexionando los codos, manteniendo la espalda recta y el core activado.","Empuja hacia arriba para volver a la posición inicial.","Repite del otro lado, extendiendo el brazo opuesto hacia el lado.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"3294-A9qxk2F.jpg","gif":"3294-A9qxk2F.gif"},{"id":"2355","n":"Balanceo de brazos colgado con rodillas flexionadas","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","back"],"st":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las rodillas flexionadas formando un ángulo de 90 grados.","Activa el core y levanta las rodillas hacia el pecho, acercándolas lo más posible a los codos.","Baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2355-uWpxD4v.jpg","gif":"2355-uWpxD4v.gif"},{"id":"2333","n":"Balanceo de brazos colgado con piernas estiradas","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","back"],"st":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las piernas estiradas hacia abajo.","Activa el core y levanta las piernas hacia adelante hasta que queden paralelas al suelo.","Mantén un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2333-PXTIwgu.jpg","gif":"2333-PXTIwgu.gif"},{"id":"3214","n":"Toque de puntas circular con brazos abiertos (hombre)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados.","Manteniendo las piernas rectas, flexiona el torso hacia adelante desde la cintura y lleva la mano derecha hacia los dedos de los pies.","Mientras bajas, levanta simultáneamente la pierna izquierda recta detrás de ti, manteniendo el equilibrio.","Regresa a la posición inicial y repite el movimiento llevando la mano izquierda hacia los dedos de los pies y levantando la pierna derecha detrás de ti.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"3214-RtyAsy1.jpg","gif":"3214-RtyAsy1.gif"},{"id":"3204","n":"Abdominales completos con brazos sobre la cabeza (hombre)","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Extiende los brazos por encima de la cabeza, manteniéndolos rectos.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que el torso quede erguido.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3204-NAkmgdx.jpg","gif":"3204-NAkmgdx.gif"},{"id":"0009","n":"Fondos de pecho asistidos (de rodillas)","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Ajusta la máquina a la altura deseada y asegura las rodillas sobre la almohadilla.","Agarra las agarraderas con las palmas hacia abajo y los brazos completamente extendidos.","Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.","Haz una pausa por un momento, luego empuja tu cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0009-PAgTVaK.jpg","gif":"0009-PAgTVaK.gif"},{"id":"0011","n":"Elevación de rodillas colgado asistida","bp":"waist","eq":"assisted","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.","Activa el core y levanta las rodillas hacia el pecho, flexionando las caderas y las rodillas.","Haz una pausa por un momento en la parte superior del movimiento, apretando el abdomen.","Baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0011-03lzqwk.jpg","gif":"0011-03lzqwk.gif"},{"id":"0010","n":"Elevación de rodillas colgado asistida con descenso brusco","bp":"waist","eq":"assisted","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.","Activa el core y levanta las rodillas hacia el pecho, manteniendo las piernas juntas.","Una vez que las rodillas estén a la altura del pecho, lanza las piernas explosivamente hacia el suelo, extendiéndolas por completo.","Deja que las piernas se balanceen de vuelta hacia arriba y repite el movimiento el número de repeticiones deseado."],"img":"0010-8K0w2yA.jpg","gif":"0010-8K0w2yA.gif"},{"id":"1708","n":"Estiramiento de gemelos tumbado asistido","bp":"lower legs","eq":"assisted","tg":"calves","mg":"hamstrings","sm":["hamstrings"],"st":["Túmbate sobre tu espalda con las piernas extendidas.","Flexiona una rodilla y coloca el pie plano sobre el suelo.","Con las manos o una toalla, jala suavemente los dedos del pie hacia tu cuerpo, sintiendo un estiramiento en la pantorrilla.","Mantén el estiramiento durante 20-30 segundos.","Suelta el estiramiento y repite con la otra pierna."],"img":"1708-GxDwDX0.jpg","gif":"1708-GxDwDX0.gif"},{"id":"1709","n":"Estiramiento de glúteos tumbado asistido","bp":"upper legs","eq":"assisted","tg":"glutes","mg":"hamstrings","sm":["hamstrings"],"st":["Túmbate sobre tu espalda con las piernas extendidas.","Flexiona la rodilla derecha y coloca el tobillo derecho sobre el muslo izquierdo, justo encima de la rodilla.","Agarra el muslo izquierdo con ambas manos y jálalo suavemente hacia el pecho.","Mantén el estiramiento durante 20-30 segundos.","Suelta y repite del otro lado."],"img":"1709-yn0LjwL.jpg","gif":"1709-yn0LjwL.gif"},{"id":"1710","n":"Estiramiento de glúteo y piramidal tumbado asistido","bp":"upper legs","eq":"assisted","tg":"glutes","mg":"hamstrings","sm":["hamstrings"],"st":["Túmbate sobre tu espalda con las piernas extendidas.","Flexiona la rodilla derecha y coloca el tobillo derecho sobre el muslo izquierdo, justo encima de la rodilla.","Agarra el muslo izquierdo con ambas manos y jálalo suavemente hacia el pecho.","Mantén el estiramiento durante 20-30 segundos.","Suelta el estiramiento y repite del otro lado."],"img":"1710-RQNVT10.jpg","gif":"1710-RQNVT10.gif"},{"id":"0012","n":"Elevación de pierna tumbada asistida con descenso lateral brusco","bp":"waist","eq":"assisted","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques"],"st":["Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.","Coloca las manos debajo de los glúteos como apoyo.","Activa el abdomen y levanta las piernas del suelo, manteniéndolas rectas.","Manteniendo las piernas juntas, bájalas hacia un lado hasta que queden a pocos centímetros del suelo.","Haz una pausa por un momento, luego levanta las piernas de vuelta a la posición inicial.","Repite el movimiento hacia el otro lado.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0012-UGhRD1A.jpg","gif":"0012-UGhRD1A.gif"},{"id":"0013","n":"Elevación de piernas asistida en decúbito supino con descenso rápido","bp":"waist","eq":"assisted","tg":"abs","mg":"hip flexors","sm":["hip flexors","quadriceps"],"st":["Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.","Coloca las manos debajo de los glúteos como apoyo.","Activa el core y levanta las piernas del suelo, manteniéndolas rectas.","Eleva las piernas hasta que queden perpendiculares al suelo.","Baja las piernas de vuelta a la posición inicial.","Simultáneamente, lanza las piernas hacia el suelo, manteniéndolas rectas.","Eleva las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0013-VX5YKR5.jpg","gif":"0013-VX5YKR5.gif"},{"id":"0014","n":"Giro ruso con movimiento asistido","bp":"waist","eq":"medicine ball","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Siéntate en el suelo con las rodillas flexionadas y los pies apoyados en el suelo.","Sostén el balón medicinal con ambas manos frente al pecho.","Inclínate ligeramente hacia atrás, activando el abdomen y manteniendo la espalda recta.","Gira lentamente el torso hacia la derecha, llevando el balón medicinal hacia el lado derecho del cuerpo.","Haz una pausa por un momento, luego gira el torso hacia la izquierda, llevando el balón medicinal hacia el lado izquierdo del cuerpo.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0014-r7cT9YD.jpg","gif":"0014-r7cT9YD.gif"},{"id":"0015","n":"Dominada asistida con agarre cerrado paralelo","bp":"back","eq":"leverage machine","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Ajusta la máquina al peso y la altura deseados.","Coloca las manos en las barras paralelas con un agarre cerrado, con las palmas mirándose entre sí.","Cuélgate de las barras con los brazos completamente extendidos y los pies sin tocar el suelo.","Activa los músculos de la espalda y lleva el cuerpo hacia arriba hacia las barras, manteniendo los codos cerca del cuerpo.","Continúa subiendo hasta que la barbilla quede por encima de las barras.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0015-vrhHa6D.jpg","gif":"0015-vrhHa6D.gif"},{"id":"0016","n":"Estiramiento de isquiotibiales asistido en prono","bp":"upper legs","eq":"assisted","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back"],"st":["Túmbate boca abajo sobre una esterilla o un banco con las piernas completamente extendidas.","Pide a un compañero o usa una banda elástica para sujetar tus tobillos.","Activa los isquiotibiales y levanta las piernas hacia los glúteos, manteniendo las rodillas rectas.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0016-VedGSby.jpg","gif":"0016-VedGSby.gif"},{"id":"1713","n":"Estiramiento de cuádriceps asistido en decúbito prono","bp":"upper legs","eq":"assisted","tg":"quads","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Túmbate boca abajo en el suelo con las piernas extendidas.","Flexiona la rodilla izquierda y lleva la mano izquierda hacia atrás para agarrar el pie o el tobillo izquierdo.","Jala suavemente el pie izquierdo hacia los glúteos, sintiendo un estiramiento en el cuádriceps izquierdo.","Mantén el estiramiento durante 20-30 segundos, luego suelta.","Repite con la pierna derecha."],"img":"1713-YUYAMEj.jpg","gif":"1713-YUYAMEj.gif"},{"id":"1714","n":"Estiramiento del recto femoral asistido en prono","bp":"waist","eq":"assisted","tg":"abs","mg":"quadriceps","sm":["quadriceps"],"st":["Túmbate boca abajo en el suelo con las piernas rectas.","Flexiona la rodilla derecha y lleva la mano derecha hacia atrás para agarrar el pie o el tobillo derecho.","Jala suavemente el pie o el tobillo derecho hacia los glúteos, sintiendo un estiramiento en la parte frontal del muslo derecho.","Mantén el estiramiento durante 20-30 segundos.","Suelta y repite del otro lado."],"img":"1714-2Ryn564.jpg","gif":"1714-2Ryn564.gif"},{"id":"0017","n":"Dominada asistida","bp":"back","eq":"leverage machine","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Ajusta la máquina a los valores de peso y altura deseados.","Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.","Cuélgate con los brazos completamente extendidos y los pies sin tocar el suelo.","Activa los músculos de la espalda y lleva el cuerpo hacia arriba hacia las agarraderas, manteniendo los codos cerca del cuerpo.","Continúa subiendo hasta que la barbilla quede por encima de las agarraderas.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0017-kiJ4Z2K.jpg","gif":"0017-kiJ4Z2K.gif"},{"id":"1716","n":"Estiramiento del pectoral mayor asistido sentado con pelota de estabilidad","bp":"chest","eq":"assisted","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta.","Sostén un balón de estabilidad con ambas manos y extiende los brazos rectos frente a ti.","Baja lentamente el balón de estabilidad hacia el pecho, sintiendo un estiramiento en los pectorales.","Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1716-RoV1Rfa.jpg","gif":"1716-RoV1Rfa.gif"},{"id":"1712","n":"Estiramiento de aductores asistido en decúbito lateral","bp":"upper legs","eq":"assisted","tg":"adductors","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Túmbate de lado con las piernas rectas y apiladas una sobre la otra.","Flexiona ligeramente la pierna de abajo para mayor estabilidad.","Coloca el pie de arriba sobre una superficie estable, como un banco o un escalón.","Manteniendo la pierna de arriba recta, bájala lentamente hacia el suelo, sintiendo un estiramiento en la parte interna del muslo.","Mantén el estiramiento durante 20-30 segundos.","Regresa a la posición inicial y repite del otro lado."],"img":"1712-hC6oYY5.jpg","gif":"1712-hC6oYY5.gif"},{"id":"1758","n":"Abdominales asistidos","bp":"waist","eq":"assisted","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Siéntate en el borde de un banco o pide a alguien que te sujete los pies.","Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1758-aumB2IV.jpg","gif":"1758-aumB2IV.gif"},{"id":"1431","n":"Dominada supinada asistida de pie","bp":"back","eq":"leverage machine","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Ajusta la máquina al nivel de asistencia deseado.","Sube a la plataforma para los pies y agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.","Mantén el pecho arriba y los hombros atrás, activa el core y flexiona ligeramente las rodillas.","Levanta el cuerpo flexionando los codos y llevándolos hacia abajo, en dirección a los costados.","Continúa subiendo hasta que la barbilla quede por encima de la barra.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1431-7OeHptV.jpg","gif":"1431-7OeHptV.gif"},{"id":"1432","n":"Dominada asistida de pie","bp":"back","eq":"leverage machine","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Ajusta la máquina a los valores de peso y altura deseados.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.","Activa los dorsales y los bíceps, y levántate hacia las agarraderas.","Haz una pausa por un momento en la parte superior, apretando los músculos de la espalda.","Bájate lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1432-f4xtKBj.jpg","gif":"1432-f4xtKBj.gif"},{"id":"0018","n":"Extensión de tríceps asistida de pie (con toalla)","bp":"upper arms","eq":"assisted","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén una toalla con ambas manos detrás de la cabeza.","Mantén los codos cerca de las orejas y la parte superior de los brazos quieta.","Extiende lentamente los antebrazos hacia arriba, apretando los tríceps en la parte superior.","Haz una pausa por un momento, luego baja lentamente la toalla de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0018-7HcfMBP.jpg","gif":"0018-7HcfMBP.gif"},{"id":"0019","n":"Fondos de tríceps asistidos (de rodillas)","bp":"upper arms","eq":"leverage machine","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Ajusta la máquina al peso y la altura deseados.","Arrodíllate sobre la almohadilla frente a la máquina, con las manos sujetando las agarraderas.","Baja el cuerpo flexionando los codos, manteniendo la espalda recta y cerca de la máquina.","Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0019-J60bN17.jpg","gif":"0019-J60bN17.gif"},{"id":"2364","n":"Fondos de pecho asistidos con agarre ancho (de rodillas)","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Ajusta la máquina a la altura deseada y asegura las rodillas sobre la almohadilla.","Agarra las agarraderas con un agarre amplio y mantén los codos ligeramente flexionados.","Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.","Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."],"img":"2364-PnZJIrk.jpg","gif":"2364-PnZJIrk.gif"},{"id":"3220","n":"Saltos abriendo piernas (hombre)","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros.","Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla.","Salta explosivamente hacia arriba, extendiendo las piernas y los brazos.","Mientras estás en el aire, separa las piernas y lleva los brazos hacia los lados.","Aterriza suavemente con los pies separados a la altura de los hombros, flexionando las rodillas para absorber el impacto.","Repite el número de repeticiones deseado."],"img":"3220-f9lVSSI.jpg","gif":"3220-f9lVSSI.gif"},{"id":"3672","n":"Paso adelante y atrás","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","glutes","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros.","Da un paso adelante con el pie derecho, flexionando la rodilla y bajando el cuerpo hacia una posición de zancada.","Empuja con el pie derecho y da un paso atrás para regresar a la posición inicial.","Repite el movimiento con el pie izquierdo, alternando las piernas en cada paso.","Continúa dando pasos hacia adelante y hacia atrás, manteniendo un ritmo constante.","Repite durante la duración o el número de repeticiones deseado."],"img":"3672-fNGumX0.jpg","gif":"3672-fNGumX0.gif"},{"id":"1314","n":"Extensión de espalda en pelota de ejercicio","bp":"back","eq":"stability ball","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él, con las caderas apoyadas en el balón y los pies contra una pared u otra superficie estable.","Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.","Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta los talones.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1314-qLpO4vV.jpg","gif":"1314-qLpO4vV.gif"},{"id":"3297","n":"Back lever","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","forearms","core"],"st":["Comienza colgándote de una barra de dominadas con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.","Activa el core y lleva los omóplatos hacia abajo y atrás.","Flexiona las rodillas y llévalas hacia el pecho.","Levanta lentamente las piernas, manteniéndolas rectas, hasta que el cuerpo quede paralelo al suelo.","Mantén esta posición durante unos segundos, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3297-GaSzzuh.jpg","gif":"3297-GaSzzuh.gif"},{"id":"1405","n":"Estiramiento pectoral posterior","bp":"back","eq":"body weight","tg":"lats","mg":"shoulders","sm":["shoulders","chest"],"st":["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.","Extiende los brazos rectos frente a ti, paralelos al suelo.","Cruza los brazos frente al cuerpo, con el brazo derecho sobre el brazo izquierdo.","Entrelaza los dedos y gira las palmas alejándolas del cuerpo.","Levanta lentamente los brazos hacia arriba y alejándolos del cuerpo, sintiendo un estiramiento en la espalda y el pecho.","Mantén el estiramiento durante 15-30 segundos, luego suelta.","Repite del lado opuesto."],"img":"1405-chfnQnM.jpg","gif":"1405-chfnQnM.gif"},{"id":"1473","n":"Salto hacia atrás","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hamstrings","sm":["hamstrings","glutes","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros.","Flexiona ligeramente las rodillas y salta hacia atrás, impulsándote con ambos pies.","Aterriza suavemente sobre la punta de los pies, flexionando las rodillas para absorber el impacto.","Repite el número de repeticiones deseado."],"img":"1473-SaDOwk7.jpg","gif":"1473-SaDOwk7.gif"},{"id":"0020","n":"Tabla de equilibrio","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","hamstrings","glutes"],"st":["Coloca la tabla de equilibrio sobre una superficie plana.","Sube a la tabla de equilibrio con un pie, asegurándote de que esté centrado.","Desplaza lentamente tu peso hacia el pie que está sobre la tabla de equilibrio, manteniendo el core activado.","Mantén el equilibrio y la estabilidad mientras sostienes la posición durante el tiempo deseado.","Repite el ejercicio con el otro pie."],"img":"0020-xAySMB0.jpg","gif":"0020-xAySMB0.gif"},{"id":"0968","n":"Curl de bíceps alterno con banda","bp":"upper arms","eq":"band","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén la banda con un agarre supino, con las palmas hacia arriba.","Mantén los codos cerca de los costados y flexiona lentamente un brazo hacia el hombro, apretando el bíceps en la parte superior.","Baja el brazo de vuelta a la posición inicial y repite con el otro brazo.","Continúa alternando los brazos durante el número de repeticiones deseado."],"img":"0968-3omWx6P.jpg","gif":"0968-3omWx6P.gif"},{"id":"0969","n":"V-up alterno con banda","bp":"waist","eq":"band","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Túmbate sobre tu espalda con las piernas rectas y los brazos extendidos por encima de la cabeza, sosteniendo la banda.","Activa el abdomen y levanta las piernas y la parte superior del cuerpo del suelo al mismo tiempo, llevando las manos hacia los dedos de los pies.","Mientras bajas las piernas y la parte superior del cuerpo de nuevo, cambia la posición de las piernas, cruzando una sobre la otra.","Repite el movimiento, alternando la posición de las piernas en cada repetición.","Continúa durante el número de repeticiones deseado."],"img":"0969-ztAa1RK.jpg","gif":"0969-ztAa1RK.gif"},{"id":"0970","n":"Dominadas asistidas con banda","bp":"back","eq":"band","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Sujeta la banda a una barra de dominadas o a un punto de anclaje resistente.","Pisa la banda y agarra la barra con las palmas mirando hacia afuera, con las manos un poco más separadas que el ancho de los hombros.","Cuélgate con los brazos completamente extendidos, manteniendo el core activado y los hombros abajo y atrás.","Sube el cuerpo hacia la barra juntando los omóplatos y llevando los codos hacia abajo, en dirección a las caderas.","Continúa subiendo hasta que la barbilla quede por encima de la barra, luego bájate lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0970-r1XNRYB.jpg","gif":"0970-r1XNRYB.gif"},{"id":"0971","n":"Wheel rollout asistido con banda","bp":"waist","eq":"band","tg":"abs","mg":"lower back","sm":["lower back"],"st":["Arrodíllate en el suelo y sostén las agarraderas de la banda con ambas manos, con las palmas hacia abajo.","Coloca la banda en el suelo frente a ti y posiciona las manos separadas a la altura de los hombros.","Activa el core y rueda lentamente la rueda hacia adelante, extendiendo el cuerpo lo más que puedas mientras mantienes el control.","Haz una pausa por un momento en el punto más lejano, luego rueda lentamente la rueda de vuelta hacia las rodillas para regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0971-zhF9lW4.jpg","gif":"0971-zhF9lW4.gif"},{"id":"1254","n":"Press de banca con banda","bp":"chest","eq":"band","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Agarra las agarraderas de la banda con un agarre prono, un poco más separadas que el ancho de los hombros.","Extiende los brazos por completo, empujando las bandas alejándolas del pecho.","Baja lentamente las bandas de vuelta hacia el pecho, manteniendo los codos en un ángulo de 90 grados.","Repite el número de repeticiones deseado."],"img":"1254-khlHMqs.jpg","gif":"1254-khlHMqs.gif"},{"id":"0980","n":"Extensión de cadera inclinado con banda","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Sujeta la banda a un punto de anclaje resistente a la altura del tobillo.","Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros.","Da un paso atrás para generar tensión en la banda, manteniendo las rodillas ligeramente flexionadas.","Flexiona las caderas e inclínate hacia adelante, manteniendo la columna en posición neutral.","Extiende la pierna derecha recta hacia atrás, apretando los glúteos en la parte superior.","Baja la pierna derecha de vuelta y repite con la pierna izquierda.","Continúa alternando las piernas durante el número de repeticiones deseado."],"img":"0980-wSScovH.jpg","gif":"0980-wSScovH.gif"},{"id":"0972","n":"Abdominales bicicleta con banda","bp":"waist","eq":"band","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques"],"st":["Túmbate sobre tu espalda con las manos detrás de la cabeza y las rodillas flexionadas.","Levanta los pies del suelo y lleva la rodilla derecha hacia el pecho mientras simultáneamente giras el torso para llevar el codo izquierdo hacia la rodilla derecha.","Estira la pierna derecha mientras llevas la rodilla izquierda hacia el pecho y giras el torso para llevar el codo derecho hacia la rodilla izquierda.","Continúa alternando el movimiento de giro, como si estuvieras pedaleando una bicicleta, manteniendo el core activado durante todo el movimiento.","Repite el número de repeticiones deseado."],"img":"0972-tZkGYZ9.jpg","gif":"0972-tZkGYZ9.gif"},{"id":"0974","n":"Jalón al pecho con agarre cerrado y banda","bp":"back","eq":"band","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Sujeta la banda a un punto de anclaje alto, como una barra de dominadas o una viga resistente.","Ponte de pie frente al punto de anclaje y agarra la banda con un agarre supino, con las manos separadas a la altura de los hombros.","Da un paso atrás para generar tensión en la banda, manteniendo los pies separados a la altura de las caderas.","Activa el core y mantén la espalda recta mientras tiras de la banda hacia el pecho, juntando los omóplatos.","Haz una pausa por un momento en la parte inferior del movimiento, luego suelta lentamente la banda de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0974-DptumMx.jpg","gif":"0974-DptumMx.gif"},{"id":"0975","n":"Flexiones con agarre cerrado y banda","bp":"upper arms","eq":"band","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Coloca una banda alrededor de la parte superior de los brazos, justo por encima de los codos.","Adopta una posición de flexión de brazos con las manos justo debajo de los hombros y el cuerpo en línea recta desde la cabeza hasta los talones.","Flexiona los codos y baja el pecho hacia el suelo, manteniendo los codos cerca de los costados.","Empuja con las palmas para extender los brazos y regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0975-ufaxB52.jpg","gif":"0975-ufaxB52.gif"},{"id":"0976","n":"Curl de concentración con banda","bp":"upper arms","eq":"band","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco o silla con las piernas separadas y los pies apoyados en el suelo.","Sostén un extremo de la banda en la mano y pisa el otro extremo con el pie del mismo lado.","Inclínate ligeramente hacia adelante y apoya el codo en la parte interna del muslo, justo encima de la rodilla.","Con la palma hacia arriba, flexiona lentamente la mano hacia el hombro, manteniendo quieta la parte superior del brazo.","Haz una pausa por un momento en la parte superior, luego baja lentamente la mano de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"0976-kmVVAfu.jpg","gif":"0976-kmVVAfu.gif"},{"id":"3117","n":"Jalón al pecho con agarre cerrado y banda fija","bp":"back","eq":"band","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Sujeta la banda a un punto fijo por encima de ti, como una barra de dominadas o una viga resistente.","Siéntate en un banco o silla frente a la banda, con los pies apoyados en el suelo y las rodillas flexionadas.","Agarra la banda con un agarre cerrado, con las palmas hacia ti.","Mantén la espalda recta y activa el core.","Tira de la banda hacia el pecho, juntando los omóplatos.","Haz una pausa por un momento en la parte inferior del movimiento, sintiendo la contracción en los dorsales.","Suelta lentamente la banda de vuelta a la posición inicial, manteniendo el control durante todo el movimiento.","Repite el número de repeticiones deseado."],"img":"3117-4LoWllp.jpg","gif":"3117-4LoWllp.gif"},{"id":"3116","n":"Jalón al pecho supino con banda fija","bp":"back","eq":"band","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Sujeta la banda a un punto de anclaje resistente por encima de tu cabeza.","Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.","Agarra la banda con un agarre supino, con las manos un poco más separadas que el ancho de los hombros.","Da un paso atrás para generar tensión en la banda, manteniendo los brazos completamente extendidos.","Activa el core y junta los omóplatos.","Tira de la banda hacia el pecho, guiando el movimiento con los codos.","Haz una pausa por un momento en la parte inferior del movimiento, sintiendo la contracción en los dorsales.","Suelta lentamente la tensión de la banda y regresa a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3116-ZH68exZ.jpg","gif":"3116-ZH68exZ.gif"},{"id":"0977","n":"Elevaciones laterales frontales con banda","bp":"shoulders","eq":"band","tg":"delts","mg":"traps","sm":["traps","upper back"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén la banda frente a los muslos con las palmas hacia abajo.","Mantén los brazos rectos y levanta la banda frente a ti hasta que los brazos queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente la banda de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0977-sTg7iys.jpg","gif":"0977-sTg7iys.gif"},{"id":"0978","n":"Elevaciones frontales con banda","bp":"shoulders","eq":"band","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén la banda frente a los muslos con las palmas hacia abajo.","Mantén los brazos rectos y levántalos lentamente hacia adelante hasta que queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0978-TFA88iB.jpg","gif":"0978-TFA88iB.gif"},{"id":"1408","n":"Elevación de cadera con banda","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca una banda elástica justo por encima de las rodillas.","Activa los glúteos y los músculos del core.","Presiona los talones contra el suelo y levanta las caderas del suelo, apretando los glúteos en la parte superior.","Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1408-E4R8Hz1.jpg","gif":"1408-E4R8Hz1.gif"},{"id":"0979","n":"Press Pallof horizontal con banda","bp":"waist","eq":"band","tg":"abs","mg":"obliques","sm":["obliques","glutes"],"st":["Sujeta la banda a un punto de anclaje resistente a la altura de la cintura.","Ponte de pie perpendicular al punto de anclaje con los pies separados a la altura de los hombros.","Agarra la agarradera de la banda con ambas manos y aléjate del punto de anclaje para generar tensión en la banda.","Lleva las manos hacia el pecho, manteniendo los codos flexionados y cerca del cuerpo.","Activa el core y mantén una postura estable.","Extiende los brazos rectos frente a ti, empujando la banda alejándola del cuerpo.","Mantén la posición extendida durante unos segundos, enfocándote en mantener la tensión en el core.","Lleva lentamente las manos de vuelta al pecho, resistiendo el tirón de la banda.","Repite el número de repeticiones deseado."],"img":"0979-9pa4H5m.jpg","gif":"0979-9pa4H5m.gif"},{"id":"0981","n":"Abdominales jack knife con banda","bp":"waist","eq":"band","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Túmbate sobre tu espalda con las piernas rectas y los brazos extendidos por encima de la cabeza, sosteniendo la banda.","Activa el abdomen y levanta las piernas y la parte superior del cuerpo simultáneamente, llevando las manos hacia los pies.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas y la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0981-KCBKjma.jpg","gif":"0981-KCBKjma.gif"},{"id":"0983","n":"Jalón a un brazo de rodillas con banda","bp":"back","eq":"band","tg":"lats","mg":"biceps","sm":["biceps","rhomboids"],"st":["Sujeta la banda a un punto de anclaje resistente por encima de tu cabeza.","Arrodíllate y sostén la banda con una mano, con la palma hacia abajo.","Extiende el brazo por completo por encima de la cabeza, manteniendo el codo ligeramente flexionado.","Activa los dorsales y tira de la banda hacia el costado, llevando el codo hacia las costillas.","Haz una pausa por un momento en la parte inferior, luego suelta lentamente la tensión y regresa a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"0983-pmnrOp0.jpg","gif":"0983-pmnrOp0.gif"},{"id":"0985","n":"Crunch con banda, de rodillas y con rotación","bp":"waist","eq":"band","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Sujeta la banda a un punto de anclaje resistente a la altura de la cintura.","Arrodíllate de espaldas al punto de anclaje y sostén la banda con ambas manos, manteniendo los codos flexionados y cerca de los costados.","Activa el abdomen y gira lentamente el torso hacia un lado, llevando las manos hacia la cadera opuesta.","Haz una pausa por un momento, luego regresa lentamente a la posición inicial.","Repite del otro lado.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0985-225x2Vd.jpg","gif":"0985-225x2Vd.gif"},{"id":"0984","n":"Rotación interna de cadera tumbado con banda","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Túmbate sobre tu espalda con las piernas rectas y una banda elástica enrollada alrededor de los pies.","Flexiona las rodillas y llévalas hacia el pecho, manteniendo los pies juntos.","Rota lentamente las rodillas hacia afuera, separándolas entre sí, mientras mantienes los pies juntos.","Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0984-vIICElP.jpg","gif":"0984-vIICElP.gif"},{"id":"1002","n":"Elevación de pierna recta tumbado con banda","bp":"waist","eq":"band","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Túmbate sobre tu espalda con las piernas rectas y los pies juntos.","Coloca la banda alrededor de los arcos de los pies y sostén los extremos de la banda con las manos.","Activando el abdomen, levanta ambas piernas del suelo hasta que queden perpendiculares al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1002-bbLR7fB.jpg","gif":"1002-bbLR7fB.gif"},{"id":"0986","n":"Curl de bíceps a un brazo sobre la cabeza con banda","bp":"upper arms","eq":"band","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros y coloca un extremo de la banda bajo el pie.","Sostén el otro extremo de la banda con el brazo completamente extendido por encima de la cabeza, con la palma hacia adelante.","Manteniendo quieta la parte superior del brazo, flexiona el antebrazo hacia el hombro, apretando el bíceps.","Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"0986-UNAB8ak.jpg","gif":"0986-UNAB8ak.gif"},{"id":"0987","n":"Sentadilla búlgara a un brazo con banda","bp":"upper legs","eq":"band","tg":"quads","mg":"glutes","sm":["glutes","hamstrings"],"st":["Ponte de pie con los pies separados a la altura de las caderas y coloca una banda elástica alrededor de los tobillos.","Extiende una pierna hacia adelante y apoya la parte superior del pie sobre un banco o escalón detrás de ti.","Sujétate de un apoyo con una mano para mantener el equilibrio.","Flexiona la pierna de apoyo y baja el cuerpo hacia una posición de sentadilla, manteniendo la rodilla alineada con los dedos del pie.","Empuja con el talón para regresar a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."],"img":"0987-arsYEd3.jpg","gif":"0987-arsYEd3.gif"},{"id":"0988","n":"Remo bajo de pie a un brazo con banda","bp":"back","eq":"band","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Sujeta la banda a un punto de anclaje estable a la altura de la cintura.","Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.","Sostén la banda con una mano, con la palma hacia adentro, y da un paso atrás para generar tensión en la banda.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Tira de la banda hacia la cintura, juntando los omóplatos.","Haz una pausa por un momento en la parte superior del movimiento, luego suelta lentamente la banda de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"0988-km0sQC0.jpg","gif":"0988-km0sQC0.gif"},{"id":"0989","n":"Press de pecho con rotación a un brazo con banda","bp":"chest","eq":"band","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Sujeta la banda a un punto de anclaje resistente a la altura del pecho.","Ponte de pie con el costado hacia el punto de anclaje y agarra la banda con una mano.","Aléjate del punto de anclaje para generar tensión en la banda.","Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas.","Lleva la mano que sostiene la banda a través del cuerpo, hacia el hombro opuesto.","Manteniendo la tensión en la banda, empuja la mano hacia adelante y alejándola del cuerpo, extendiendo el brazo.","Regresa lentamente a la posición inicial y repite el número de repeticiones deseado.","Cambia de lado y repite el ejercicio con la otra mano."],"img":"0989-c16nYGA.jpg","gif":"0989-c16nYGA.gif"},{"id":"0990","n":"Remo sentado con rotación a un brazo con banda","bp":"back","eq":"band","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Siéntate en un banco o silla con los pies apoyados en el suelo y la espalda recta.","Sostén la banda con una mano y extiende el brazo completamente frente a ti.","Manteniendo la espalda recta, tira de la banda hacia el cuerpo flexionando el codo y juntando los omóplatos.","Al mismo tiempo, gira el torso hacia el lado del brazo que tira.","Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión de la banda y regresa a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"0990-DKBwJrL.jpg","gif":"0990-DKBwJrL.gif"},{"id":"0991","n":"Pull through con banda","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Sujeta una banda elástica a un punto de anclaje resistente a nivel del suelo.","Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros.","Da un paso adelante para generar tensión en la banda, manteniendo las rodillas ligeramente flexionadas.","Flexiona las caderas y lleva los glúteos hacia atrás, manteniendo una ligera flexión en las rodillas.","Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales.","Empuja las caderas hacia adelante y aprieta los glúteos para regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0991-VtTbiP3.jpg","gif":"0991-VtTbiP3.gif"},{"id":"0992","n":"Abdominales con empuje y banda","bp":"waist","eq":"band","tg":"abs","mg":"shoulders","sm":["shoulders","chest"],"st":["Sujeta la banda de forma segura a un punto de anclaje estable.","Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Sostén la banda con ambas manos y extiende los brazos rectos hacia el techo.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0992-zFzbBfL.jpg","gif":"0992-zFzbBfL.gif"},{"id":"0993","n":"Aperturas inversas con banda","bp":"shoulders","eq":"band","tg":"delts","mg":"upper back","sm":["upper back","trapezius"],"st":["Sujeta la banda a un objeto fijo a la altura del pecho.","Ponte de pie con los pies separados a la altura de los hombros y sostén la banda con ambas manos frente a ti.","Mantén los brazos rectos y levántalos hacia los lados hasta que queden paralelos al suelo.","Junta los omóplatos en la parte superior del movimiento.","Baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0993-sTfvVsG.jpg","gif":"0993-sTfvVsG.gif"},{"id":"0994","n":"Curl de muñeca inverso con banda","bp":"lower arms","eq":"band","tg":"forearms","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco o silla con los pies apoyados en el suelo.","Sostén la banda con un agarre prono, con las palmas hacia abajo, y envuélvela alrededor de los dedos.","Apoya los antebrazos sobre los muslos, con las muñecas colgando del borde.","Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos.","Haz una pausa por un momento en la parte superior, luego baja lentamente las muñecas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0994-Ezpnw9d.jpg","gif":"0994-Ezpnw9d.gif"},{"id":"0996","n":"Rotación interna de cadera sentado con banda","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo.","Coloca una banda elástica alrededor de los muslos, justo por encima de las rodillas.","Mantén las rodillas flexionadas formando un ángulo de 90 grados y los pies separados a la altura de los hombros.","Activa los glúteos y rota lentamente las rodillas hacia afuera, empujando contra la resistencia de la banda.","Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0996-9gbyYKk.jpg","gif":"0996-9gbyYKk.gif"},{"id":"1011","n":"Giro de torso sentado con banda","bp":"waist","eq":"band","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Siéntate en el suelo con las piernas extendidas frente a ti y la espalda recta.","Envuelve la banda alrededor de la cintura y sostén los extremos con ambas manos.","Activa el abdomen y gira lentamente el torso hacia un lado, manteniendo la espalda recta y los pies en el suelo.","Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.","Repite el giro hacia el otro lado.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"1011-S1JXDAG.jpg","gif":"1011-S1JXDAG.gif"},{"id":"0997","n":"Press de hombros con banda","bp":"shoulders","eq":"band","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies.","Sostén la banda con las palmas hacia adelante y eleva las manos a la altura de los hombros, con los codos flexionados.","Empuja la banda por encima de la cabeza, extendiendo completamente los brazos.","Haz una pausa por un momento en la parte superior, luego baja lentamente la banda de vuelta a la altura de los hombros.","Repite el número de repeticiones deseado."],"img":"0997-peAeMR3.jpg","gif":"0997-peAeMR3.gif"},{"id":"1018","n":"Encogimientos con banda","bp":"back","eq":"band","tg":"traps","mg":"shoulders","sm":["shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies, sosteniendo los extremos con las manos.","Mantén los brazos rectos y relajados, y deja que la banda cuelgue frente a los muslos.","Activa los trapecios encogiendo los hombros hacia arriba, levantando la banda lo más alto posible.","Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1018-trmte8s.jpg","gif":"1018-trmte8s.gif"},{"id":"0998","n":"Extensión de tríceps lateral con banda","bp":"upper arms","eq":"band","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén la banda con ambas manos, con las palmas hacia abajo.","Extiende los brazos hacia los lados, manteniéndolos paralelos al suelo.","Flexiona lentamente los codos y lleva las manos hacia los hombros, manteniendo quieta la parte superior de los brazos.","Haz una pausa por un momento, luego extiende lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0998-obe5LMq.jpg","gif":"0998-obe5LMq.gif"},{"id":"0999","n":"Elevación de talones a una pierna con banda","bp":"lower legs","eq":"band","tg":"calves","mg":"ankles","sm":["ankles","feet"],"st":["Ponte de pie con los pies separados a la altura de las caderas y coloca la banda alrededor de la base de los dedos del pie izquierdo.","Sujétate de un objeto estable para mantener el equilibrio si es necesario.","Levanta lentamente el talón izquierdo del suelo, llevando el peso del cuerpo hacia la punta del pie.","Haz una pausa por un momento en la parte superior, luego baja lentamente el talón izquierdo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia a la pierna derecha."],"img":"0999-9JprnPh.jpg","gif":"0999-9JprnPh.gif"},{"id":"1000","n":"Elevación de talones inversa a una pierna con banda","bp":"lower legs","eq":"band","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Ponte de pie con los pies separados a la altura de las caderas y coloca la banda alrededor de la base de los dedos del pie.","Sujétate de un objeto estable para mantener el equilibrio.","Levanta lentamente el talón del suelo, llevando el peso del cuerpo hacia la punta del pie.","Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia a la otra pierna."],"img":"1000-QsSQWbf.jpg","gif":"1000-QsSQWbf.gif"},{"id":"1001","n":"Sentadilla búlgara con banda","bp":"upper legs","eq":"band","tg":"quads","mg":"glutes","sm":["glutes","hamstrings"],"st":["Ponte de pie con los pies separados a la altura de las caderas y coloca una banda elástica alrededor de los tobillos.","Da un paso grande hacia adelante con el pie derecho y un paso más pequeño hacia atrás con el pie izquierdo.","Flexiona las rodillas y baja el cuerpo hasta que el muslo derecho quede paralelo al suelo, manteniendo la rodilla izquierda ligeramente por encima del suelo.","Empuja con el talón derecho para regresar a la posición inicial.","Repite del otro lado."],"img":"1001-y8bYM8w.jpg","gif":"1001-y8bYM8w.gif"},{"id":"1004","n":"Sentadilla con banda","bp":"upper legs","eq":"band","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros, con la banda colocada justo por encima de las rodillas.","Manteniendo el pecho arriba y el core activado, lleva las caderas hacia atrás y flexiona las rodillas para bajar a una posición de sentadilla.","Asegúrate de que las rodillas se alineen con los dedos de los pies y de que el peso recaiga en los talones.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1004-TUZLh71.jpg","gif":"1004-TUZLh71.gif"},{"id":"1003","n":"Sentadilla con remo con banda","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","back"],"st":["Sujeta la banda a un punto de anclaje resistente a la altura de la cintura.","Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.","Sostén las agarraderas de la banda con las palmas mirándose entre sí y los brazos extendidos frente a ti.","Flexiona las rodillas y baja a una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.","Desde la posición de sentadilla, tira de las agarraderas de la banda hacia el cuerpo, juntando los omóplatos.","Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1003-w1NOByi.jpg","gif":"1003-w1NOByi.gif"},{"id":"1005","n":"Crunch de pie con banda","bp":"waist","eq":"band","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Sujeta la banda a un punto de anclaje resistente a la altura de la cintura.","Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros.","Sostén la banda con ambas manos y llévala hacia el pecho, manteniendo los codos flexionados y cerca del cuerpo.","Activa el abdomen y flexiona lentamente el torso hacia adelante, llevando el pecho hacia las rodillas.","Haz una pausa por un momento en la parte más alta del movimiento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1005-Kzg30R7.jpg","gif":"1005-Kzg30R7.gif"},{"id":"1022","n":"Remo para deltoides posterior de pie con banda","bp":"shoulders","eq":"band","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids","biceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies.","Sostén las agarraderas de la banda con las palmas mirándose entre sí y los brazos extendidos frente a ti.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Tira de la banda hacia el pecho, juntando los omóplatos.","Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1022-tc5dYrf.jpg","gif":"1022-tc5dYrf.gif"},{"id":"1007","n":"Crunch con giro de pie con banda","bp":"waist","eq":"band","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de la parte superior de la espalda, cruzándola frente al pecho.","Sujeta los extremos de la banda con las manos, manteniendo los codos flexionados y cerca de los costados.","Activa el abdomen y gira el torso hacia un lado, llevando el codo hacia la rodilla opuesta.","Haz una pausa breve y luego vuelve a la posición inicial.","Repite del otro lado.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"1007-euq4pwp.jpg","gif":"1007-euq4pwp.gif"},{"id":"1008","n":"Step-up con banda","bp":"upper legs","eq":"band","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Coloca una banda alrededor de los muslos, justo por encima de las rodillas.","Ponte de pie frente a un escalón o plataforma con los pies separados a la altura de las caderas.","Sube a la plataforma con el pie derecho, empujando con el talón.","Extiende la pierna izquierda hacia atrás, manteniéndola recta.","Baja el pie izquierdo de nuevo hasta el suelo.","Repite subiendo a la plataforma con el pie izquierdo.","Continúa alternando las piernas durante el número de repeticiones deseado."],"img":"1008-d5bTEPV.jpg","gif":"1008-d5bTEPV.gif"},{"id":"1009","n":"Peso muerto con piernas rígidas con banda","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de los tobillos.","Sujeta la banda con ambas manos frente a los muslos, con las palmas mirando hacia el cuerpo.","Manteniendo la espalda recta y el core activado, flexiona las caderas y baja lentamente la parte superior del cuerpo hacia el suelo.","Mientras bajas, empuja las caderas hacia atrás y deja que las rodillas se flexionen ligeramente.","Baja la banda hacia el suelo, sintiendo un estiramiento en los isquiotibiales.","Haz una pausa breve en la posición baja, luego activa los glúteos y los isquiotibiales para levantar la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1009-kuMiR2T.jpg","gif":"1009-kuMiR2T.gif"},{"id":"1023","n":"Peso muerto con espalda recta y piernas rígidas con banda","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de la parte superior de las piernas.","Sujeta la banda con ambas manos frente a los muslos, con las palmas mirando hacia el cuerpo.","Manteniendo la espalda recta y las rodillas ligeramente flexionadas, flexiona las caderas y baja la banda hacia el suelo.","Siente el estiramiento en los isquiotibiales mientras bajas la banda.","Activa los glúteos y los isquiotibiales para levantar el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1023-lHeUULr.jpg","gif":"1023-lHeUULr.gif"},{"id":"1010","n":"Peso muerto con piernas rectas con banda","bp":"back","eq":"band","tg":"spine","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de los pies.","Sujeta la banda con ambas manos, con las palmas mirando hacia el cuerpo, y mantén los brazos rectos.","Activa el core y mantén una ligera flexión en las rodillas.","Inclínate lentamente hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado.","Baja la banda hacia el suelo manteniendo las piernas rectas.","Haz una pausa breve en la posición baja y luego contrae los glúteos y los isquiotibiales para volver a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1010-KUaoUV8.jpg","gif":"1010-KUaoUV8.gif"},{"id":"1012","n":"Press militar con giro con banda","bp":"shoulders","eq":"band","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies.","Sujeta las asas de la banda a la altura de los hombros con las palmas mirando hacia delante.","Activa el core y empuja la banda por encima de la cabeza, extendiendo completamente los brazos.","Mientras empujas, gira el torso hacia un lado, manteniendo las caderas estables.","Haz una pausa breve en la parte alta y luego vuelve a la posición inicial.","Repite el empuje y el giro hacia el lado opuesto.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"1012-u4bAmKp.jpg","gif":"1012-u4bAmKp.gif"},{"id":"1369","n":"Elevación de talones a dos piernas con banda (banda bajo ambas piernas) v. 2","bp":"lower legs","eq":"band","tg":"calves","mg":"ankles","sm":["ankles","feet"],"st":["Ponte de pie con los pies separados a la altura de los hombros y coloca una banda elástica bajo ambos pies.","Sujeta los extremos de la banda con las manos para mantener el equilibrio.","Levanta los talones del suelo lo más alto posible, usando las pantorrillas.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1369-jl6uxZV.jpg","gif":"1369-jl6uxZV.gif"},{"id":"1013","n":"Jalón con agarre supino con banda","bp":"back","eq":"band","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Sujeta la banda a un punto de anclaje alto, como una barra de dominadas o una viga resistente.","Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.","Agarra la banda con un agarre supino, con las manos un poco más separadas que el ancho de los hombros.","Extiende completamente los brazos por encima de la cabeza, manteniendo los codos ligeramente flexionados.","Activa los dorsales y tira de la banda hacia abajo en dirección al pecho, juntando los omóplatos.","Haz una pausa breve en la parte baja del movimiento, luego libera lentamente la tensión y vuelve a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1013-k6tUeqS.jpg","gif":"1013-k6tUeqS.gif"},{"id":"1014","n":"V-up con banda","bp":"waist","eq":"band","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Túmbate sobre tu espalda con las piernas rectas y los brazos extendidos por encima de la cabeza, sosteniendo la banda.","Activando el abdomen, levanta las piernas y la parte superior del cuerpo del suelo al mismo tiempo, llevando las manos hacia los dedos de los pies.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas y la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1014-H6ETwO9.jpg","gif":"1014-H6ETwO9.gif"},{"id":"1015","n":"Press pallof vertical con banda","bp":"waist","eq":"band","tg":"abs","mg":"obliques","sm":["obliques","glutes"],"st":["Ponte de pie con los pies separados a la altura de los hombros y enrolla la banda alrededor de un objeto firme a la altura del pecho.","Sujeta la banda con ambas manos y aléjate del punto de anclaje, creando tensión en la banda.","Colócate perpendicular al punto de anclaje, con el costado mirando hacia la banda.","Extiende los brazos rectos hacia delante, manteniendo las manos a la altura del pecho.","Activa el core y empuja la banda alejándola del pecho, extendiendo completamente los brazos.","Mantén la posición durante unos segundos y luego lleva lentamente la banda de vuelta hacia el pecho.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"1015-G7PXMlT.jpg","gif":"1015-G7PXMlT.gif"},{"id":"1016","n":"Curl de muñeca con banda","bp":"lower arms","eq":"band","tg":"forearms","mg":"biceps","sm":["biceps","triceps"],"st":["Siéntate en un banco o silla con los pies apoyados en el suelo.","Sujeta la banda con ambas manos, con las palmas hacia arriba, y apoya los antebrazos sobre los muslos.","Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos.","Haz una pausa por un momento en la parte superior, luego baja lentamente las muñecas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1016-vUTfFHw.jpg","gif":"1016-vUTfFHw.gif"},{"id":"1017","n":"Elevaciones en Y con banda","bp":"shoulders","eq":"band","tg":"delts","mg":"traps","sm":["traps","rhomboids"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta la banda frente a los muslos con las palmas mirando hacia adentro.","Mantén los brazos rectos y levántalos hacia arriba y hacia los lados, formando una 'Y' con el cuerpo.","Junta los omóplatos en la parte superior del movimiento.","Baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1017-aHDy5O5.jpg","gif":"1017-aHDy5O5.gif"},{"id":"0023","n":"Curl de bíceps alterno con barra","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra en cada mano, con las palmas mirando hacia delante.","Mantén los brazos superiores fijos y exhala mientras levantas el peso contrayendo los bíceps.","Continúa levantando las barras hasta que los bíceps estén completamente contraídos y las barras estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala mientras comienzas a bajar lentamente las barras de vuelta a la posición inicial.","Repite el número de repeticiones deseado, alternando los brazos."],"img":"0023-Yza7XrQ.jpg","gif":"0023-Yza7XrQ.gif"},{"id":"0024","n":"Sentadilla frontal con barra apoyada en banco","bp":"upper legs","eq":"barbell","tg":"quads","mg":"hamstrings","sm":["hamstrings","glutes","calves"],"st":["Empieza de pie con los pies separados a la altura de los hombros y la barra apoyada en la parte superior del pecho, justo debajo de la clavícula.","Sujeta la barra con un agarre pronado, manteniendo los codos elevados y los brazos superiores paralelos al suelo.","Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y las caderas, manteniendo la espalda recta y el pecho elevado.","Haz una pausa breve en la parte baja de la sentadilla y luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0024-Y7YcmIJ.jpg","gif":"0024-Y7YcmIJ.gif"},{"id":"0025","n":"Press de banca con barra","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.","Baja la barra lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.","Haz una pausa breve cuando la barra toque el pecho.","Empuja la barra de vuelta a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."],"img":"0025-EIeI8Vf.jpg","gif":"0025-EIeI8Vf.gif"},{"id":"0026","n":"Sentadilla con barra apoyada en banco","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Coloca una barra en un soporte de sentadillas a la altura del pecho.","Ponte de pie de espaldas al soporte, con los pies separados a la altura de los hombros.","Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Levanta la barra del soporte y retrocede un paso, asegurándote de que los pies sigan separados a la altura de los hombros.","Baja el cuerpo hacia una sentadilla, manteniendo las rodillas alineadas con los dedos de los pies.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0026-W9pFVv1.jpg","gif":"0026-W9pFVv1.gif"},{"id":"1316","n":"Pullover con barra y brazos flexionados","bp":"back","eq":"barbell","tg":"lats","mg":"triceps","sm":["triceps","chest"],"st":["Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo.","Sujeta una barra con un agarre a la altura de los hombros y extiende los brazos rectos por encima del pecho.","Baja la barra detrás de la cabeza manteniendo los brazos ligeramente flexionados.","Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1316-cA9FuWG.jpg","gif":"1316-cA9FuWG.gif"},{"id":"0027","n":"Remo con barra","bp":"back","eq":"barbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Inclínate hacia delante desde las caderas manteniendo la espalda recta y el pecho elevado.","Agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.","Tira de la barra hacia la parte inferior del pecho retrayendo los omóplatos y contrayendo los músculos de la espalda.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0027-eZyBC3j.jpg","gif":"0027-eZyBC3j.gif"},{"id":"2407","n":"Curl de bíceps con barra (con arm blaster)","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas hacia arriba.","Coloca los brazos superiores contra el soporte para brazos, manteniendo los codos cerca del torso.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2407-aee2Fcj.jpg","gif":"2407-aee2Fcj.gif"},{"id":"0028","n":"Clean and press con barra","bp":"upper legs","eq":"barbell","tg":"quads","mg":"hamstrings","sm":["hamstrings","glutes","shoulders","triceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros y la barra en el suelo frente a ti.","Flexiona las rodillas y las caderas para bajar y agarrar la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.","Empuja con los talones y extiende las caderas y las rodillas para levantar la barra del suelo, manteniéndola cerca del cuerpo.","Cuando la barra llegue a los muslos, extiende las caderas de forma explosiva, encoge los hombros y tira de la barra hacia el pecho.","Cuando la barra llegue a la altura del pecho, baja rápidamente debajo de ella y atrápala a la altura de los hombros, con los codos apuntando hacia delante y las palmas hacia arriba.","Desde la posición de recepción, empuja la barra por encima de la cabeza extendiendo los brazos y llevando la barra recta hacia arriba.","Baja la barra de vuelta a la posición inicial y repite el número de repeticiones deseado."],"img":"0028-SGY8Zui.jpg","gif":"0028-SGY8Zui.gif"},{"id":"0029","n":"Sentadilla frontal con agarre de clean con barra","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Empieza de pie con los pies separados a la altura de los hombros y la barra apoyada en la parte superior del pecho, con los codos apuntando hacia delante.","Baja el cuerpo flexionando las rodillas y empujando las caderas hacia atrás, como si te sentaras en una silla.","Mantén el pecho elevado y la espalda recta mientras bajas, asegurándote de que las rodillas no sobrepasen los dedos de los pies.","Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa breve en la parte baja y luego empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.","Repite el número de repeticiones deseado."],"img":"0029-qi996YS.jpg","gif":"0029-qi996YS.gif"},{"id":"0030","n":"Press de banca con agarre cerrado con barra","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros.","Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.","Haz una pausa breve cuando la barra toque el pecho.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"0030-J6Dx1Mu.jpg","gif":"0030-J6Dx1Mu.gif"},{"id":"0031","n":"Curl con barra","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas mirando hacia delante.","Mantén los codos cerca del torso y exhala mientras levantas el peso contrayendo los bíceps.","Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala mientras comienzas a bajar lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0031-25GPyDY.jpg","gif":"0031-25GPyDY.gif"},{"id":"0032","n":"Peso muerto con barra","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Ponte de pie con los pies separados a la altura de los hombros y la barra en el suelo frente a ti.","Flexiona las rodillas y las caderas para bajar el torso y agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.","Mantén la espalda recta y el pecho elevado mientras empujas con los talones para levantar la barra del suelo, extendiendo las caderas y las rodillas.","Al ponerte de pie, aprieta los glúteos y mantén el core activado.","Baja la barra de vuelta al suelo flexionando las caderas y las rodillas, manteniendo la espalda recta.","Repite el número de repeticiones deseado."],"img":"0032-ila4NZS.jpg","gif":"0032-ila4NZS.gif"},{"id":"0033","n":"Press de banca declinado con barra","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.","Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0033-GrO65fd.jpg","gif":"0033-GrO65fd.gif"},{"id":"0034","n":"Pullover declinado con barra y brazos flexionados","bp":"back","eq":"barbell","tg":"lats","mg":"triceps","sm":["triceps","chest"],"st":["Túmbate en un banco declinado con la cabeza más baja que las caderas y los pies sujetos.","Sujeta una barra con un agarre pronado (palmas mirando hacia afuera) y extiende los brazos rectos por encima del pecho.","Baja la barra detrás de la cabeza de forma controlada, manteniendo los brazos ligeramente flexionados.","Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial contrayendo los dorsales.","Repite el número de repeticiones deseado."],"img":"0034-hMEptv0.jpg","gif":"0034-hMEptv0.gif"},{"id":"0035","n":"Press francés declinado con agarre cerrado con barra","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Túmbate en un banco declinado con la cabeza más baja que los pies y sujeta una barra con un agarre cerrado.","Baja la barra hacia la frente flexionando los codos, manteniendo los brazos superiores fijos.","Haz una pausa breve y luego extiende los brazos para empujar la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0035-LMGXZn8.jpg","gif":"0035-LMGXZn8.gif"},{"id":"1255","n":"Pullover declinado con barra","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Túmbate en un banco declinado con la cabeza más baja que las caderas y los pies sujetos.","Sujeta la barra con un agarre pronado (palmas mirando hacia afuera) y las manos un poco más separadas que el ancho de los hombros.","Extiende los brazos por encima del pecho, manteniendo una ligera flexión en los codos.","Baja la barra describiendo un arco detrás de la cabeza, sintiendo un estiramiento en el pecho y los hombros.","Haz una pausa breve y luego devuelve la barra a la posición inicial invirtiendo el movimiento.","Repite el número de repeticiones deseado."],"img":"1255-9sgNE2O.jpg","gif":"1255-9sgNE2O.gif"},{"id":"0036","n":"Press declinado con agarre ancho con barra","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.","Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros.","Baja la barra hacia el pecho, manteniendo los codos hacia los lados.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"0036-hl8DUh8.jpg","gif":"0036-hl8DUh8.gif"},{"id":"0037","n":"Pullover declinado con agarre ancho con barra","bp":"back","eq":"barbell","tg":"lats","mg":"triceps","sm":["triceps","chest"],"st":["Túmbate en un banco declinado con la cabeza más baja que las caderas y los pies sujetos.","Sujeta una barra con un agarre amplio y extiende los brazos rectos por encima del pecho.","Baja la barra detrás de la cabeza de forma controlada, manteniendo los brazos rectos.","Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0037-Hj4FOCd.jpg","gif":"0037-Hj4FOCd.gif"},{"id":"0038","n":"Curl drag con barra","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas hacia arriba.","Deja que la barra cuelgue a la longitud del brazo frente a los muslos.","Manteniendo los brazos superiores fijos, levanta la barra hacia el pecho contrayendo los bíceps.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0038-IENzBdA.jpg","gif":"0038-IENzBdA.gif"},{"id":"1370","n":"Elevación de talones en suelo con barra","bp":"lower legs","eq":"barbell","tg":"calves","mg":"hamstrings","sm":["hamstrings"],"st":["Coloca una barra en el suelo frente a ti.","Ponte de pie con la parte delantera de los pies sobre el borde de la barra, dejando los talones colgando.","Sujétate de un objeto estable para mantener el equilibrio si es necesario.","Levanta los talones lo más alto posible, usando las pantorrillas para elevar el cuerpo.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1370-2IHEa2T.jpg","gif":"1370-2IHEa2T.gif"},{"id":"0039","n":"Sentadilla frontal con barra sobre el pecho","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Empieza de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Sujeta la barra frente al pecho con las manos separadas a la altura de los hombros, los codos apuntando hacia delante.","Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, empujando las caderas hacia atrás y flexionando las rodillas.","Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0039-IeTIEqg.jpg","gif":"0039-IeTIEqg.gif"},{"id":"0041","n":"Elevaciones frontales con barra","bp":"shoulders","eq":"barbell","tg":"delts","mg":"biceps","sm":["biceps","triceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a los muslos con un agarre pronado.","Mantén los brazos rectos y levanta la barra hacia delante y hacia arriba hasta que alcance la altura de los hombros.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0041-b2Uoz54.jpg","gif":"0041-b2Uoz54.gif"},{"id":"0040","n":"Elevaciones frontales y pullover con barra","bp":"chest","eq":"barbell","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre pronado, con las palmas hacia abajo.","Mantén los brazos rectos y levanta la barra frente a ti hasta que alcance la altura de los hombros.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","A continuación, baja la barra detrás de la cabeza, manteniendo los brazos rectos.","Haz una pausa breve en la parte baja y luego levanta la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0040-33AzZeV.jpg","gif":"0040-33AzZeV.gif"},{"id":"0042","n":"Sentadilla frontal con barra","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Empieza de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Sujeta la barra frente a los hombros, apoyándola sobre la clavícula y los hombros.","Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, empujando las caderas hacia atrás y flexionando las rodillas.","Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0042-zG0zs85.jpg","gif":"0042-zG0zs85.gif"},{"id":"0043","n":"Sentadilla completa con barra","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.","Activa el core y mantén el pecho elevado mientras comienzas a bajar el cuerpo.","Flexiona las rodillas y las caderas, empujando las caderas hacia atrás y hacia abajo como si te sentaras en una silla.","Baja hasta que los muslos queden paralelos al suelo o un poco por debajo.","Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones.","Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.","Repite el número de repeticiones deseado."],"img":"0043-qXTaZnJ.jpg","gif":"0043-qXTaZnJ.gif"},{"id":"1461","n":"Sentadilla completa con barra (vista trasera)","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.","Activa el core y mantén el pecho elevado mientras comienzas a bajar el cuerpo.","Flexiona las rodillas y las caderas, empujando las caderas hacia atrás y hacia abajo como si te sentaras en una silla.","Baja el cuerpo hasta que los muslos queden paralelos al suelo o un poco por debajo.","Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones.","Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.","Repite el número de repeticiones deseado."],"img":"1461-DhMl549.jpg","gif":"1461-DhMl549.gif"},{"id":"1462","n":"Sentadilla completa con barra (vista lateral)","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.","Activa el core y mantén el pecho elevado mientras comienzas a bajar el cuerpo.","Flexiona las rodillas y las caderas, empujando las caderas hacia atrás y hacia abajo como si te sentaras en una silla.","Baja el cuerpo hasta que los muslos queden paralelos al suelo o un poco por debajo.","Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones.","Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.","Repite el número de repeticiones deseado."],"img":"1462-iYzB0Cz.jpg","gif":"1462-iYzB0Cz.gif"},{"id":"1545","n":"Sentadilla zercher completa con barra","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.","Sujeta la barra en el pliegue de los codos, agarrándola con las manos para mantener la estabilidad.","Activa el core y mantén el pecho elevado mientras bajas las caderas hacia atrás y hacia abajo en una posición de sentadilla.","Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones.","Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Empuja con los talones para volver a ponerte de pie, apretando los glúteos en la parte alta del movimiento.","Repite el número de repeticiones deseado."],"img":"1545-vR1vold.jpg","gif":"1545-vR1vold.gif"},{"id":"1409","n":"Puente de glúteo con barra","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Empieza tumbado boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo.","Coloca una barra sobre las caderas, sujetándola con firmeza con ambas manos.","Activa los glúteos y el core, luego levanta las caderas del suelo hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.","Haz una pausa breve en la parte alta, apretando los glúteos.","Baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1409-qKBpF7I.jpg","gif":"1409-qKBpF7I.gif"},{"id":"3562","n":"Puente de glúteo con barra y pies en banco (hombre)","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Empieza sentado en el borde de un banco con la parte superior de la espalda apoyada contra él y los pies planos sobre el suelo, separados a la altura de las caderas.","Coloca una barra sobre las caderas, sujetándola con firmeza con ambas manos.","Activa los glúteos y el core, luego empuja con los talones para levantar las caderas del banco, creando una línea recta desde las rodillas hasta los hombros.","Haz una pausa breve en la parte alta, apretando los glúteos.","Baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3562-qg2PGl6.jpg","gif":"3562-qg2PGl6.gif"},{"id":"0044","n":"Buenos días con barra","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"lower back","sm":["lower back"],"st":["Empieza de pie con los pies separados a la altura de los hombros y la barra apoyada sobre la parte superior de la espalda.","Manteniendo la espalda recta y el core activado, flexiona las caderas hacia delante, empujando los glúteos hacia atrás como si intentaras tocar la pared detrás de ti con ellos.","Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales.","Haz una pausa breve y luego vuelve a la posición inicial apretando los glúteos y empujando las caderas hacia delante.","Repite el número de repeticiones deseado."],"img":"0044-XlZ4lAC.jpg","gif":"0044-XlZ4lAC.gif"},{"id":"0045","n":"Press de banca guillotine con barra","bp":"chest","eq":"barbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Baja la barra lentamente hacia el cuello, manteniendo los codos apuntando hacia afuera.","Haz una pausa breve cuando la barra esté justo encima del cuello.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"0045-GXoaSgn.jpg","gif":"0045-GXoaSgn.gif"},{"id":"0046","n":"Sentadilla hack con barra","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Empieza de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.","Sujeta la barra detrás de las piernas, apoyándola en la parte superior de los muslos.","Baja el cuerpo flexionando las rodillas y las caderas, manteniendo la espalda recta y el pecho elevado.","Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0046-5VCj6iH.jpg","gif":"0046-5VCj6iH.gif"},{"id":"1436","n":"Sentadilla con barra alta","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Coloca la barra sobre la parte superior de la espalda, apoyándola en los trapecios.","Activa el core y mantén el pecho elevado mientras comienzas a bajar en sentadilla, empujando las caderas hacia atrás y flexionando las rodillas.","Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.","Repite el número de repeticiones deseado."],"img":"1436-Gnfo4FM.jpg","gif":"1436-Gnfo4FM.gif"},{"id":"0047","n":"Press de banca inclinado con barra","bp":"chest","eq":"barbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Coloca un banco inclinado a un ángulo de 45 grados.","Túmbate en el banco con los pies planos sobre el suelo.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos a un ángulo de 45 grados.","Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0047-3TZduzM.jpg","gif":"0047-3TZduzM.gif"},{"id":"1719","n":"Press de banca inclinado con agarre cerrado y barra","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Coloca un banco inclinado a un ángulo de 45 grados.","Túmbate en el banco con los pies planos sobre el suelo.","Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros.","Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.","Haz una pausa breve cuando la barra toque el pecho.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"1719-gx7s7uF.jpg","gif":"1719-gx7s7uF.gif"},{"id":"0048","n":"Press inclinado con agarre inverso y barra","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Coloca un banco inclinado a un ángulo de 45 grados.","Recuéstate en el banco y agarra la barra con un agarre invertido, con las manos un poco más separadas que el ancho de los hombros.","Saca la barra del soporte y bájala hacia la parte superior del pecho, manteniendo los codos pegados al cuerpo.","Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0048-641mIfk.jpg","gif":"0048-641mIfk.gif"},{"id":"0049","n":"Remo inclinado con barra","bp":"back","eq":"barbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Coloca un banco inclinado a un ángulo de 45 grados.","Túmbate boca abajo en el banco con el pecho apoyado en el respaldo y los pies planos sobre el suelo.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Mantén la espalda recta y el core activado.","Tira de la barra hacia el pecho, juntando los omóplatos.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0049-dmgMp3n.jpg","gif":"0049-dmgMp3n.gif"},{"id":"0050","n":"Elevaciones frontales inclinadas con barra","bp":"chest","eq":"barbell","tg":"serratus anterior","mg":"deltoids","sm":["deltoids","trapezius"],"st":["Coloca un banco inclinado a un ángulo de 45 grados.","Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo.","Sujeta una barra con un agarre pronado, un poco más ancho que la separación de los hombros.","Levanta la barra hasta la altura de los hombros, manteniendo los codos ligeramente flexionados.","Levanta lentamente la barra por encima de la cabeza, extendiendo completamente los brazos.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la altura de los hombros.","Repite el número de repeticiones deseado."],"img":"0050-xi0yckC.jpg","gif":"0050-xi0yckC.gif"},{"id":"0051","n":"Sentadilla jefferson con barra","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.","Sujeta la barra con un agarre pronado, apoyándola en la parte delantera del cuerpo, justo debajo de la cintura.","Da un paso con el pie izquierdo hacia delante y el pie derecho hacia atrás, manteniendo los pies separados a la altura de los hombros.","Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.","Empuja con los talones para volver a ponerte de pie en la posición inicial.","Repite el movimiento, alternando el pie delantero y el trasero en cada repetición."],"img":"0051-pkSoCW9.jpg","gif":"0051-pkSoCW9.gif"},{"id":"0052","n":"Press de banca JM con barra","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"0052-ZsiqXYa.jpg","gif":"0052-ZsiqXYa.gif"},{"id":"0053","n":"Sentadilla con salto y barra","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Empieza de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda.","Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.","Al llegar a la parte baja de la sentadilla, impúlsate hacia arriba saltando desde el suelo.","Al saltar, extiende las caderas, las rodillas y los tobillos, empujando con la punta de los pies.","Aterriza con suavidad de vuelta en la posición de sentadilla y repite el movimiento de inmediato el número de repeticiones deseado."],"img":"0053-1gFNTZV.jpg","gif":"0053-1gFNTZV.gif"},{"id":"1410","n":"Zancada lateral con barra","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda.","Da un paso grande hacia el lado con el pie derecho, manteniendo el pie izquierdo fijo en el suelo.","Flexiona la rodilla derecha y baja el cuerpo hacia una posición de zancada, manteniendo la pierna izquierda recta.","Empuja con el pie derecho y vuelve a la posición inicial.","Repite hacia el otro lado, dando el paso con el pie izquierdo."],"img":"1410-py1HSzx.jpg","gif":"1410-py1HSzx.gif"},{"id":"1435","n":"Sentadilla con barra baja","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros y la barra apoyada sobre la parte superior de la espalda.","Manteniendo el pecho elevado y el core activado, baja lentamente el cuerpo flexionando las rodillas y empujando las caderas hacia atrás.","Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo.","Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1435-bTpEUcm.jpg","gif":"1435-bTpEUcm.gif"},{"id":"0054","n":"Estocada con barra","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Empieza de pie con los pies separados a la altura de los hombros y una barra apoyada sobre la parte superior de la espalda.","Da un paso hacia delante con el pie derecho, manteniendo el torso erguido.","Baja el cuerpo flexionando la rodilla derecha hasta que el muslo quede paralelo al suelo.","Empuja con el talón derecho para regresar a la posición inicial.","Repite con la pierna izquierda, alternando las piernas el número de repeticiones deseado."],"img":"0054-t8iSghb.jpg","gif":"0054-t8iSghb.gif"},{"id":"1720","n":"Extensión de tríceps con barra tumbado tras nuca","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.","Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho.","Manteniendo los brazos superiores fijos, baja lentamente la barra detrás de la cabeza flexionando los codos.","Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1720-yg8Totb.jpg","gif":"1720-yg8Totb.gif"},{"id":"0055","n":"Press de banca con agarre cerrado","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Agarra la barra con un agarre cerrado, manos separadas a la altura de los hombros, con las palmas mirando hacia los pies.","Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.","Baja la barra lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.","Haz una pausa breve cuando la barra toque el pecho y luego empújala de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0055-EcaV7aL.jpg","gif":"0055-EcaV7aL.gif"},{"id":"0056","n":"Extensión de tríceps con barra tumbado y agarre cerrado","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.","Agarra la barra con un agarre cerrado, manos separadas a la altura de los hombros, con las palmas hacia arriba.","Extiende completamente los brazos, levantando la barra por encima del pecho.","Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos.","Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0056-HJ63mSO.jpg","gif":"0056-HJ63mSO.gif"},{"id":"0057","n":"Extensión con barra tumbado","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.","Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho.","Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos.","Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0057-EMpUwRI.jpg","gif":"0057-EMpUwRI.gif"},{"id":"0058","n":"Levantamiento de cadera con barra (hip thrust)","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Túmbate boca arriba en un banco con los pies planos sobre el suelo y las rodillas flexionadas.","Sujeta la barra con un agarre pronado y colócala sobre las caderas.","Activando los glúteos, levanta las caderas del banco hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.","Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0058-SNFfUff.jpg","gif":"0058-SNFfUff.gif"},{"id":"0059","n":"Curl de bíceps con barra tumbado en banco predicador","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco predicador con el pecho apoyado en el respaldo y los brazos extendidos sobre el borde, sujetando una barra con un agarre supino.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0059-SYJ4Bkt.jpg","gif":"0059-SYJ4Bkt.gif"},{"id":"0061","n":"Extensión de tríceps con barra tumbado","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.","Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho.","Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos.","Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0061-iZop9xO.jpg","gif":"0061-iZop9xO.gif"},{"id":"0060","n":"Press francés con barra (skull crusher)","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.","Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho.","Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos.","Haz una pausa breve cuando la barra esté justo encima de la frente y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0060-h8LFzo9.jpg","gif":"0060-h8LFzo9.gif"},{"id":"0063","n":"Sentadilla con barra y postura cerrada","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.","Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.","Activa el core y mantén el pecho elevado mientras bajas lentamente el cuerpo flexionando las rodillas y empujando las caderas hacia atrás.","Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo.","Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0063-elhhVgj.jpg","gif":"0063-elhhVgj.gif"},{"id":"0064","n":"Remo con barra a una mano inclinado","bp":"back","eq":"barbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una barra con una mano usando un agarre pronado.","Inclínate hacia delante desde las caderas, manteniendo la espalda recta y la cabeza en posición neutral.","Tira de la barra hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos.","Baja la barra de vuelta a la posición inicial de forma controlada.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"0064-Jsgsc27.jpg","gif":"0064-Jsgsc27.gif"},{"id":"0065","n":"Press de suelo con barra a una mano","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo.","Sujeta la barra con una mano, con la palma hacia arriba, y extiende el brazo recto por encima del pecho.","Baja la barra lentamente hacia el pecho, manteniendo el codo cerca del cuerpo.","Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"0065-vtusOWT.jpg","gif":"0065-vtusOWT.gif"},{"id":"0066","n":"Peso muerto lateral con barra a una mano","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","lower back"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra en una mano con un agarre pronado.","Mantén la espalda recta y el core activado.","Flexiona las caderas y baja la barra hacia el exterior de la pierna, manteniendo el brazo recto y el pecho elevado.","Baja la barra tanto como puedas manteniendo una buena forma.","Haz una pausa por un momento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"0066-2DxtqHL.jpg","gif":"0066-2DxtqHL.gif"},{"id":"0067","n":"Arranque con barra a una mano","bp":"shoulders","eq":"barbell","tg":"delts","mg":"traps","sm":["traps","forearms","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.","Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros.","Flexiona las rodillas y baja las caderas hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.","Extiende las caderas, las rodillas y los tobillos de forma explosiva, impulsando la barra hacia arriba.","Cuando la barra llegue a la altura del pecho, tira de ella hacia arriba con el brazo, manteniéndola cerca del cuerpo.","Rota el codo por debajo de la barra y extiende el brazo completamente por encima de la cabeza, bloqueando el codo.","Baja la barra de vuelta a la posición inicial de forma controlada.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"0067-xHKN2s8.jpg","gif":"0067-xHKN2s8.gif"},{"id":"0068","n":"Sentadilla búlgara con barra con banco","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra sobre la parte superior de la espalda.","Levanta un pie del suelo y extiéndelo hacia delante, manteniéndolo paralelo al suelo.","Flexiona la pierna de apoyo y baja el cuerpo como si te sentaras en una silla, manteniendo el pecho elevado y la espalda recta.","Baja hasta que el muslo quede paralelo al suelo, luego empuja con el talón para volver a la posición inicial.","Repite el número de repeticiones deseado y luego cambia de pierna y repite."],"img":"0068-uKyN64F.jpg","gif":"0068-uKyN64F.gif"},{"id":"0069","n":"Sentadilla overhead con barra","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.","Sujeta la barra con un agarre amplio, colocándola por encima de la cabeza con los brazos completamente extendidos.","Activa el core y baja el cuerpo hacia una posición de sentadilla, manteniendo el pecho elevado y las rodillas alineadas con los dedos de los pies.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0069-gfk9kD4.jpg","gif":"0069-gfk9kD4.gif"},{"id":"1411","n":"Curl de muñeca invertido con barra sobre banco","bp":"lower arms","eq":"barbell","tg":"forearms","mg":"biceps","sm":["biceps","brachialis"],"st":["Siéntate en un banco con los pies planos sobre el suelo y los antebrazos apoyados sobre los muslos, con las palmas hacia abajo.","Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros.","Baja la barra hacia el suelo flexionando las muñecas, manteniendo los antebrazos fijos.","Haz una pausa breve en la parte baja y luego levanta lentamente la barra extendiendo las muñecas.","Repite el número de repeticiones deseado."],"img":"1411-yzYH9pI.jpg","gif":"1411-yzYH9pI.gif"},{"id":"1412","n":"Curl de muñeca con barra sobre banco","bp":"lower arms","eq":"barbell","tg":"forearms","mg":"biceps","sm":["biceps","shoulders"],"st":["Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre supino, con las palmas hacia arriba.","Apoya los antebrazos sobre el banco, dejando que las muñecas cuelguen del borde.","Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible.","Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1412-SJAA2IQ.jpg","gif":"1412-SJAA2IQ.gif"},{"id":"3017","n":"Remo Pendlay con barra","bp":"back","eq":"barbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Inclínate hacia delante desde las caderas manteniendo la espalda recta y el pecho elevado.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Tira de la barra hacia la parte superior del abdomen, juntando los omóplatos.","Baja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3017-r0z6xzQ.jpg","gif":"3017-r0z6xzQ.gif"},{"id":"1751","n":"Press con barra en pines","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Coloca una barra en un rack de potencia a la altura del pecho.","Ponte de pie frente a la barra y colócate debajo de ella, con los pies separados a la altura de los hombros.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.","Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo.","Haz una pausa breve cuando la barra toque el pecho.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"1751-bndCa3Q.jpg","gif":"1751-bndCa3Q.gif"},{"id":"0070","n":"Curl de bíceps con barra en banco predicador","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco predicador con los brazos superiores apoyados en el cojín y el pecho contra el soporte.","Agarra la barra con un agarre supino, un poco más ancho que la separación de los hombros.","Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0070-qOgPVf6.jpg","gif":"0070-qOgPVf6.gif"},{"id":"0071","n":"Abdominales con press de barra","bp":"waist","eq":"barbell","tg":"abs","mg":"shoulders","sm":["shoulders","chest"],"st":["Túmbate boca arriba en una esterilla con las rodillas flexionadas y los pies planos sobre el suelo.","Sujeta la barra con un agarre pronado, apoyándola sobre el pecho.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0071-wnEscH8.jpg","gif":"0071-wnEscH8.gif"},{"id":"0072","n":"Curl con barra en banco inclinado prono","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Coloca un banco inclinado a un ángulo de 45 grados.","Túmbate boca abajo en el banco con el pecho y el abdomen apoyados contra él.","Sujeta una barra con un agarre supino, separado a la altura de los hombros.","Extiende completamente los brazos, dejando que la barra cuelgue hacia el suelo.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0072-WLvTAv5.jpg","gif":"0072-WLvTAv5.gif"},{"id":"0073","n":"Pullover con barra","bp":"back","eq":"barbell","tg":"lats","mg":"chest","sm":["chest","triceps"],"st":["Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo.","Sujeta una barra con un agarre a la altura de los hombros y extiende los brazos rectos por encima del pecho.","Manteniendo los brazos rectos, baja la barra detrás de la cabeza de forma controlada hasta sentir un estiramiento en los dorsales.","Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0073-i6LWjok.jpg","gif":"0073-i6LWjok.gif"},{"id":"0022","n":"Pullover con barra y press","bp":"back","eq":"barbell","tg":"lats","mg":"triceps","sm":["triceps","chest","shoulders"],"st":["Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo.","Sujeta una barra con un agarre pronado (palmas mirando hacia afuera) y extiende los brazos rectos por encima del pecho.","Manteniendo los brazos rectos, baja la barra detrás de la cabeza con un movimiento en forma de arco hasta sentir un estiramiento en los dorsales.","Haz una pausa breve, luego invierte el movimiento y empuja la barra de vuelta a la posición inicial por encima del pecho.","Repite el número de repeticiones deseado."],"img":"0022-znLogoF.jpg","gif":"0022-znLogoF.gif"},{"id":"0074","n":"Rack pull con barra","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Coloca una barra en un soporte a la altura de la rodilla.","Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.","Flexiona las caderas y las rodillas para bajar y agarrar la barra con un agarre pronado, manos separadas a la altura de los hombros.","Activa el core y levanta la barra extendiendo las caderas y las rodillas, llevando los hombros hacia atrás y apretando los glúteos en la parte alta.","Baja la barra de vuelta a la posición inicial flexionando las caderas y las rodillas.","Repite el número de repeticiones deseado."],"img":"0074-za9Ni4z.jpg","gif":"0074-za9Ni4z.gif"},{"id":"0075","n":"Elevaciones posteriores con barra","bp":"shoulders","eq":"barbell","tg":"delts","mg":"traps","sm":["traps","rhomboids"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre pronado, con las palmas hacia abajo.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Levanta la barra hacia los lados, manteniendo los brazos rectos, hasta que queden paralelos al suelo.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0075-Ln9iTbU.jpg","gif":"0075-Ln9iTbU.gif"},{"id":"0076","n":"Remo para deltoides posterior con barra","bp":"shoulders","eq":"barbell","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids","biceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta una barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros.","Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado.","Tira de la barra hacia el pecho, juntando los omóplatos.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0076-S9zHIvU.jpg","gif":"0076-S9zHIvU.gif"},{"id":"0078","n":"Zancada trasera con barra","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Empieza de pie con los pies separados a la altura de los hombros y una barra apoyada sobre la parte superior de la espalda.","Da un paso hacia atrás con el pie derecho, apoyándote en la punta del pie.","Flexiona ambas rodillas para bajar el cuerpo hasta que el muslo izquierdo quede paralelo al suelo.","Empuja con el talón izquierdo para volver a la posición inicial.","Repite con la otra pierna."],"img":"0078-VaP75jl.jpg","gif":"0078-VaP75jl.gif"},{"id":"0077","n":"Zancada trasera con barra sobre step-up","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra sobre la parte superior de la espalda.","Da un paso hacia atrás con el pie derecho, apoyándote en la punta del pie.","Flexiona ambas rodillas para bajar el cuerpo hasta que el muslo izquierdo quede paralelo al suelo.","Empuja con el talón izquierdo para volver a la posición inicial.","Repite con la otra pierna."],"img":"0077-62Nw60O.jpg","gif":"0077-62Nw60O.gif"},{"id":"0079","n":"Curl de muñeca inverso con barra apoyo en piernas","bp":"lower arms","eq":"barbell","tg":"forearms","mg":"biceps","sm":["biceps","brachialis"],"st":["Siéntate en un banco con los pies planos sobre el suelo y las rodillas flexionadas.","Sujeta una barra con un agarre pronado, palmas hacia abajo, y las manos separadas a la altura de los hombros.","Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde.","Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible.","Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0079-qDnGfDb.jpg","gif":"0079-qDnGfDb.gif"},{"id":"2187","n":"Press de banca agarre cerrado inverso con barra","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Agarra la barra con un agarre invertido, manos separadas a la altura de los hombros.","Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.","Baja la barra lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.","Haz una pausa breve cuando la barra esté justo encima del pecho.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"2187-YqJw82s.jpg","gif":"2187-YqJw82s.gif"},{"id":"0080","n":"Curl inverso con barra","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre pronado, con las palmas hacia abajo.","Mantén los brazos superiores fijos y exhala mientras levantas la barra hacia arriba, contrayendo los bíceps.","Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala mientras bajas lentamente la barra de vuelta a la posición inicial, manteniendo los brazos superiores fijos.","Repite el número de repeticiones deseado."],"img":"0080-xNrS20v.jpg","gif":"0080-xNrS20v.gif"},{"id":"0118","n":"Remo con barra agarre supino","bp":"back","eq":"barbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta una barra con un agarre pronado, palmas hacia abajo, y las manos un poco más separadas que el ancho de los hombros.","Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado, hasta que el torso quede casi paralelo al suelo.","Tira de la barra hacia la parte inferior del pecho, juntando los omóplatos.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0118-SzX3uzM.jpg","gif":"0118-SzX3uzM.gif"},{"id":"1256","n":"Press de banca declinado agarre supino con barra","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.","Agarra la barra con un agarre invertido, un poco más ancho que la separación de los hombros.","Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.","Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1256-DotAgEF.jpg","gif":"1256-DotAgEF.gif"},{"id":"1257","n":"Press de banca inclinado agarre supino con barra","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Coloca un banco inclinado a un ángulo de 45 grados.","Túmbate en el banco con los pies planos sobre el suelo.","Agarra la barra con un agarre invertido, manos un poco más separadas que el ancho de los hombros.","Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.","Haz una pausa breve cuando la barra toque el pecho.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"1257-DU7I633.jpg","gif":"1257-DU7I633.gif"},{"id":"1317","n":"Remo inclinado agarre supino con barra","bp":"back","eq":"barbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Coloca un banco inclinado a un ángulo de 45 grados.","Siéntate en el banco frente al respaldo con el pecho apoyado contra él.","Sujeta la barra con un agarre invertido (palmas hacia abajo) y las manos un poco más separadas que el ancho de los hombros.","Mantén la espalda recta y el core activado.","Tira de la barra hacia la parte superior del abdomen, juntando los omóplatos.","Haz una pausa breve en la parte alta del movimiento.","Baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1317-8d8qJQI.jpg","gif":"1317-8d8qJQI.gif"},{"id":"1721","n":"Press francés agarre supino con barra","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"forearms","sm":["forearms"],"st":["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.","Sujeta la barra con un agarre invertido, palmas mirando hacia la cara, y las manos separadas a la altura de los hombros.","Extiende los brazos rectos por encima del pecho, manteniendo los codos hacia dentro y las muñecas rectas.","Baja lentamente la barra hacia la frente flexionando los codos, manteniendo los brazos superiores fijos.","Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1721-yRLPCLu.jpg","gif":"1721-yRLPCLu.gif"},{"id":"0081","n":"Curl inverso con barra en banco predicador","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco predicador con el pecho apoyado en el cojín y los brazos extendidos rectos hacia abajo, sujetando una barra con un agarre pronado.","Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia arriba mientras contraes los bíceps.","Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0081-4LIG9xr.jpg","gif":"0081-4LIG9xr.gif"},{"id":"0082","n":"Curl de muñeca inverso con barra apoyo en banco","bp":"lower arms","eq":"barbell","tg":"forearms","mg":"biceps","sm":["biceps","brachialis"],"st":["Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre pronado, con las palmas hacia abajo.","Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde.","Flexiona lentamente las muñecas hacia arriba, llevando la barra hacia el cuerpo.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0082-LsZkfU6.jpg","gif":"0082-LsZkfU6.gif"},{"id":"0084","n":"Rodillo con barra","bp":"waist","eq":"barbell","tg":"abs","mg":"lower back","sm":["lower back"],"st":["Ponte de rodillas en el suelo y sujeta una barra con ambas manos, separadas a la altura de los hombros.","Haz rodar la barra hacia delante, extendiendo los brazos y manteniendo el core activado.","Continúa rodando hacia delante hasta que el cuerpo esté completamente extendido y los brazos por encima de la cabeza.","Haz una pausa breve y luego haz rodar lentamente la barra de vuelta hacia las rodillas, manteniendo el control.","Repite el número de repeticiones deseado."],"img":"0084-7M66AVi.jpg","gif":"0084-7M66AVi.gif"},{"id":"0083","n":"Rodillo con barra desde banco","bp":"waist","eq":"barbell","tg":"abs","mg":"shoulders","sm":["shoulders","triceps"],"st":["Empieza de rodillas en el suelo con una barra colocada sobre un banco frente a ti.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Manteniendo el core activado y la espalda recta, haz rodar lentamente la barra hacia delante, extendiendo los brazos frente a ti.","Continúa haciendo rodar la barra hacia delante hasta que el cuerpo esté completamente extendido y los brazos por encima de la cabeza.","Haz una pausa breve en la posición de extensión total, luego haz rodar lentamente la barra de vuelta hacia el cuerpo, volviendo a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0083-Gxg9lDc.jpg","gif":"0083-Gxg9lDc.gif"},{"id":"0085","n":"Peso muerto rumano con barra","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies apuntando hacia delante.","Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros.","Flexiona las caderas, manteniendo la espalda recta y las rodillas ligeramente flexionadas.","Baja la barra hacia el suelo, manteniéndola cerca del cuerpo.","Siente el estiramiento en los isquiotibiales mientras bajas la barra.","Cuando sientas el estiramiento en los isquiotibiales, empuja las caderas hacia delante y ponte de pie.","Aprieta los glúteos en la parte alta del movimiento.","Baja la barra de vuelta a la posición inicial y repite el número de repeticiones deseado."],"img":"0085-wQ2c4XD.jpg","gif":"0085-wQ2c4XD.gif"},{"id":"0086","n":"Press militar sentado detrás de la nuca con barra","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta la barra con un agarre pronado, un poco más ancho que la separación de los hombros.","Levanta la barra del soporte y bájala a la altura de los hombros, detrás de la cabeza.","Empuja la barra hacia arriba hasta que los brazos queden completamente extendidos.","Baja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0086-ngPpyRS.jpg","gif":"0086-ngPpyRS.gif"},{"id":"0087","n":"Press de Bradford sentado con barra","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta la barra con un agarre pronado, un poco más ancho que la separación de los hombros.","Levanta la barra hasta la altura de los hombros, manteniendo los codos ligeramente flexionados y apuntando hacia delante.","Empuja la barra por encima de la cabeza, extendiendo completamente los brazos.","Baja la barra de vuelta a la altura de los hombros y repite el número de repeticiones deseado."],"img":"0087-0dCyly0.jpg","gif":"0087-0dCyly0.gif"},{"id":"0088","n":"Elevación de talones sentado con barra añadiendo peso","bp":"lower legs","eq":"barbell","tg":"calves","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Siéntate en un banco con los pies planos sobre el suelo y una barra apoyada sobre los muslos.","Coloca la parte delantera de los pies sobre una plataforma elevada, como un bloque o un escalón.","Coloca la barra sobre los muslos y sujétala con firmeza con las manos.","Manteniendo la espalda recta y el core activado, levanta los talones del suelo extendiendo los tobillos.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0088-ktsFQAZ.jpg","gif":"0088-ktsFQAZ.gif"},{"id":"1371","n":"Elevación de talones sentado solo con barra sin peso","bp":"lower legs","eq":"barbell","tg":"calves","mg":"hamstrings","sm":["hamstrings"],"st":["Siéntate en un banco con los pies planos sobre el suelo y una barra apoyada sobre los muslos.","Coloca la parte delantera de los pies sobre una plataforma elevada, como un bloque o un escalón.","Baja los talones tanto como sea posible, sintiendo un estiramiento en las pantorrillas.","Levanta los talones lo más alto posible, contrayendo las pantorrillas.","Repite el número de repeticiones deseado."],"img":"1371-ipvgBnC.jpg","gif":"1371-ipvgBnC.gif"},{"id":"1718","n":"Extensión de tríceps sentado con barra agarre cerrado detrás de la nuca","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta la barra con un agarre cerrado detrás del cuello, con las palmas mirando hacia delante.","Mantén los codos cerca de la cabeza y baja lentamente la barra hacia la parte de atrás de la cabeza.","Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1718-4CBIBOM.jpg","gif":"1718-4CBIBOM.gif"},{"id":"0089","n":"Curl de concentración sentado con barra agarre cerrado","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre supino, manos separadas a la altura de los hombros.","Apoya los brazos superiores contra el interior de los muslos, justo por encima de las rodillas, y deja que la barra cuelgue frente a ti.","Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros, contrayendo los bíceps.","Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0089-1V1gj1u.jpg","gif":"0089-1V1gj1u.gif"},{"id":"0090","n":"Buenos días sentado con barra","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Siéntate en un banco con los pies planos sobre el suelo y una barra apoyada sobre la parte superior de la espalda.","Mantén la espalda recta y el pecho elevado.","Inclínate lentamente hacia delante desde las caderas, bajando el torso hacia el suelo.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0090-d960PgE.jpg","gif":"0090-d960PgE.gif"},{"id":"0091","n":"Press militar sentado con barra","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta la barra con un agarre pronado, un poco más ancho que la separación de los hombros.","Levanta la barra del soporte y llévala a la altura de los hombros, con los codos flexionados y las palmas hacia delante.","Empuja la barra por encima de la cabeza extendiendo completamente los brazos.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la altura de los hombros.","Repite el número de repeticiones deseado."],"img":"0091-kTbSH9h.jpg","gif":"0091-kTbSH9h.gif"},{"id":"0092","n":"Extensión de tríceps sobre la cabeza sentado con barra","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y levántala por encima de la cabeza.","Baja la barra detrás de la cabeza flexionando los codos, manteniendo los brazos superiores cerca de la cabeza.","Haz una pausa breve y luego extiende los brazos para levantar la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0092-5uFK1xr.jpg","gif":"0092-5uFK1xr.gif"},{"id":"0094","n":"Giro de tronco sentado con barra","bp":"waist","eq":"barbell","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Siéntate en un banco plano con los pies planos sobre el suelo y las rodillas flexionadas.","Sujeta una barra con ambas manos frente al pecho, manteniendo los codos ligeramente flexionados.","Activa el core y gira lentamente el torso hacia un lado, manteniendo la espalda recta.","Haz una pausa breve al final del giro y luego rota lentamente de vuelta a la posición inicial.","Repite el giro hacia el otro lado.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0094-dFSNDOA.jpg","gif":"0094-dFSNDOA.gif"},{"id":"0095","n":"Encogimientos con barra","bp":"back","eq":"barbell","tg":"traps","mg":"shoulders","sm":["shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a ti con un agarre pronado.","Mantén los brazos rectos y la espalda recta durante todo el ejercicio.","Levanta los hombros hacia las orejas lo más alto posible, apretando los trapecios en la parte alta.","Mantén la posición por un momento y luego baja lentamente los hombros de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0095-dG7tG5y.jpg","gif":"0095-dG7tG5y.gif"},{"id":"0096","n":"Flexión lateral con barra v. 2","bp":"waist","eq":"barbell","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con ambas manos, con las palmas hacia abajo.","Mantén la espalda recta y el core activado durante todo el ejercicio.","Inclina lentamente el torso hacia el lado derecho, bajando la barra hacia tu rodilla derecha.","Haz una pausa breve y luego vuelve a la posición inicial.","Repite el movimiento hacia el lado izquierdo.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0096-i4JkUaL.jpg","gif":"0096-i4JkUaL.gif"},{"id":"0098","n":"Sentadilla búlgara lateral con barra","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera.","Sujeta una barra sobre la parte superior de la espalda, apoyándola en los trapecios.","Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, flexionando las rodillas y las caderas.","Al bajar, empuja las rodillas hacia los lados y mantén el peso sobre los talones.","Baja hasta que los muslos queden paralelos al suelo, luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0098-W31mMjd.jpg","gif":"0098-W31mMjd.gif"},{"id":"0097","n":"Sentadilla búlgara lateral con barra unilateral","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera.","Sujeta una barra sobre la parte superior de la espalda, apoyándola en los hombros.","Da un paso grande hacia el lado con el pie derecho, manteniendo el pie izquierdo fijo en el suelo.","Flexiona la rodilla derecha y baja el cuerpo hacia una posición de sentadilla, manteniendo el pecho elevado y la espalda recta.","Empuja con el talón derecho para regresar a la posición inicial.","Repite hacia el otro lado, dando el paso con el pie izquierdo.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0097-HUEqZ1y.jpg","gif":"0097-HUEqZ1y.gif"},{"id":"1756","n":"Peso muerto a una pierna con barra","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Ponte de pie con los pies separados a la altura de las caderas, sujetando una barra frente a los muslos con agarre prono.","Traslada el peso hacia el pie izquierdo y levanta el pie derecho ligeramente del suelo.","Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y la pierna derecha extendida detrás de ti para el equilibrio.","Baja la barra hacia el suelo, manteniéndola cerca del cuerpo y la pierna izquierda ligeramente flexionada.","Haz una pausa breve en la posición más baja, luego activa los glúteos y los isquiotibiales para levantar el torso de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"1756-gEyURal.jpg","gif":"1756-gEyURal.gif"},{"id":"0099","n":"Sentadilla split a una pierna con barra","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda.","Da un paso grande hacia adelante con una pierna, manteniendo el torso erguido.","Baja el cuerpo flexionando la rodilla delantera y la cadera, mientras mantienes la pierna trasera recta.","Continúa bajando hasta que el muslo delantero quede paralelo al suelo.","Haz una pausa breve, luego empuja con el talón delantero para volver a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."],"img":"0099-gGNQmVt.jpg","gif":"0099-gGNQmVt.gif"},{"id":"2799","n":"Elevación de piernas alternas sentado con barra","bp":"waist","eq":"barbell","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Siéntate en un banco con la espalda recta y sujeta una barra sobre los muslos.","Manteniendo las piernas rectas, levanta una pierna lo más alto posible mientras mantienes la otra pierna en el suelo.","Baja la pierna elevada y repite con la otra pierna.","Continúa alternando las piernas durante el número de repeticiones deseado."],"img":"2799-G7xoEzr.jpg","gif":"2799-G7xoEzr.gif"},{"id":"2800","n":"Elevación de pierna alterna sentada con barra (mujer)","bp":"waist","eq":"barbell","tg":"abs","mg":"hip flexors","sm":["hip flexors","quadriceps"],"st":["Siéntate en un banco con la espalda recta y sujeta una barra sobre los muslos.","Coloca las manos a los lados del banco para apoyarte.","Manteniendo las piernas rectas, levanta una pierna lo más alto posible manteniéndola paralela al suelo.","Baja la pierna y repite con la otra pierna.","Continúa alternando las piernas durante el número de repeticiones deseado."],"img":"2800-BCs0G2F.jpg","gif":"2800-BCs0G2F.gif"},{"id":"0100","n":"Barbell skier","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a los muslos con un agarre pronado.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.","Levanta simultáneamente la barra hacia los hombros mientras saltas ligeramente del suelo.","Al llegar a la parte más alta del movimiento, invierte rápidamente el movimiento y baja la barra de nuevo a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0100-4Leypho.jpg","gif":"0100-4Leypho.gif"},{"id":"0101","n":"Sentadilla rápida con barra","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.","Activa el core y mantén el pecho elevado mientras llevas las caderas hacia atrás y hacia abajo, como si te sentaras en una silla.","Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Empuja con los talones para volver a ponerte de pie, contrayendo los glúteos en la parte más alta.","Repite el número de repeticiones deseado."],"img":"0101-euI1BwR.jpg","gif":"0101-euI1BwR.gif"},{"id":"2810","n":"Sentadilla búlgara con barra bajo pierna","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Empieza de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda.","Da un paso grande hacia adelante con el pie derecho, manteniendo el torso erguido.","Baja el cuerpo flexionando las rodillas y las caderas hasta que el muslo derecho quede paralelo al suelo.","Haz una pausa breve, luego empuja con el talón derecho para volver a la posición inicial.","Repite con la pierna izquierda adelante el número de repeticiones deseado."],"img":"2810-HBYyX94.jpg","gif":"2810-HBYyX94.gif"},{"id":"0102","n":"Sentadilla con barra (sobre rodillas)","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Comienza arrodillado en el suelo con las rodillas separadas a la altura de las caderas y las puntas de los pies apuntando hacia adelante.","Coloca una barra sobre los hombros, sujetándola con agarre prono y las manos un poco más separadas que el ancho de los hombros.","Activa el core y mantén el pecho elevado mientras bajas lentamente el cuerpo flexionando las rodillas, manteniendo la espalda recta.","Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0102-oR7O9LW.jpg","gif":"0102-oR7O9LW.gif"},{"id":"2798","n":"Sentadilla con salto y zancada trasera con barra","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Empieza de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda.","Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.","Impúlsate explosivamente hacia arriba, saltando del suelo lo más alto que puedas.","Aterriza suavemente sobre los pies y de inmediato retrocede con una pierna hacia una zancada inversa.","Baja el cuerpo hasta que el muslo delantero quede paralelo al suelo, manteniendo la espalda recta.","Empuja con el talón delantero para volver a la posición inicial.","Repite la secuencia de salto y zancada con la otra pierna.","Continúa alternando las piernas durante el número de repeticiones deseado."],"img":"2798-RYcV1kH.jpg","gif":"2798-RYcV1kH.gif"},{"id":"0103","n":"Rodillo abdominal de pie con barra","bp":"waist","eq":"barbell","tg":"abs","mg":"shoulders","sm":["shoulders","lower back"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con ambas manos frente a los muslos.","Activa el core y enrolla lentamente la barra hacia el suelo, manteniendo la espalda recta y los brazos extendidos.","Continúa enrollando la barra hacia adelante hasta que el cuerpo esté completamente extendido y las manos queden justo sobre la cabeza.","Haz una pausa breve, luego enrolla lentamente la barra de vuelta hacia los muslos, manteniendo el control y el core activado.","Repite el número de repeticiones deseado."],"img":"0103-xnInPfE.jpg","gif":"0103-xnInPfE.gif"},{"id":"0104","n":"Curl de muñeca invertido de pie con barra","bp":"lower arms","eq":"barbell","tg":"forearms","mg":"biceps","sm":["biceps","shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono.","Apoya la barra sobre el dorso de las manos con las palmas hacia abajo y los dedos apuntando hacia el cuerpo.","Manteniendo los brazos superiores quietos, exhala y flexiona las muñecas hacia arriba lo más posible.","Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0104-2qTvJAZ.jpg","gif":"0104-2qTvJAZ.gif"},{"id":"0105","n":"Press de Bradford de pie con barra","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra frente a los hombros con agarre prono.","Empuja la barra por encima de la cabeza, extendiendo completamente los brazos.","Baja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0105-dCPESfR.jpg","gif":"0105-dCPESfR.gif"},{"id":"1372","n":"Elevación de talones de pie con barra libre piernas juntas","bp":"lower legs","eq":"barbell","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Ponte de pie con los pies separados a la altura de los hombros y coloca una barra sobre la parte superior de la espalda.","Levanta los talones del suelo lo más alto posible, apoyándote solo en las puntas de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1372-8ozhUIZ.jpg","gif":"1372-8ozhUIZ.gif"},{"id":"0106","n":"Curl de bíceps con agarre cerrado de pie con barra","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre supino, manos juntas.","Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento.","Exhala al flexionar el peso contrayendo los bíceps. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala mientras comienzas a llevar lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0106-4dUn2iv.jpg","gif":"0106-4dUn2iv.gif"},{"id":"1456","n":"Press militar con agarre cerrado de pie con barra","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con agarre prono, manos un poco más juntas que el ancho de los hombros.","Levanta la barra hasta la altura de los hombros, manteniendo los codos cerca del cuerpo.","Empuja la barra por encima de la cabeza, extendiendo completamente los brazos.","Baja la barra de nuevo a la altura de los hombros.","Repite el número de repeticiones deseado."],"img":"1456-wdRZISl.jpg","gif":"1456-wdRZISl.gif"},{"id":"2414","n":"Curl de concentración de pie con barra","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con una mano, con la palma hacia arriba.","Apoya la otra mano sobre el muslo para mayor estabilidad.","Manteniendo el brazo superior quieto, exhala y flexiona el peso hacia el hombro.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente el peso de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"2414-vsMcDi9.jpg","gif":"2414-vsMcDi9.gif"},{"id":"0107","n":"Elevación frontal sobre la cabeza de pie con barra","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra frente a los muslos con agarre prono.","Mantén la espalda recta y activa el core.","Levanta lentamente la barra frente a ti, manteniendo los brazos rectos y las palmas hacia abajo.","Continúa levantando hasta que la barra quede ligeramente por encima del nivel de los hombros.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0107-S8mo30S.jpg","gif":"0107-S8mo30S.gif"},{"id":"0108","n":"Elevación de talones de pie con barra libre piernas separadas","bp":"lower legs","eq":"barbell","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Ponte de pie con los pies separados a la altura de los hombros y coloca una barra sobre la parte superior de la espalda.","Levanta los talones del suelo lo más alto posible, usando las pantorrillas.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0108-rGwhJ5o.jpg","gif":"0108-rGwhJ5o.gif"},{"id":"0109","n":"Extensión de tríceps sobre la cabeza de pie con barra","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono.","Levanta la barra por encima de la cabeza, extendiendo completamente los brazos.","Manteniendo los brazos superiores cerca de la cabeza, baja lentamente la barra detrás de la cabeza flexionando los codos.","Haz una pausa breve, luego levanta la barra de vuelta a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."],"img":"0109-dZl9Q27.jpg","gif":"0109-dZl9Q27.gif"},{"id":"0110","n":"Curl con agarre inverso de pie con barra","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas hacia arriba.","Mantén los codos cerca del torso y los brazos superiores quietos.","Exhala y flexiona el peso contrayendo los bíceps, llevando la barra lo más cerca posible de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0110-LWuA3aZ.jpg","gif":"0110-LWuA3aZ.gif"},{"id":"0111","n":"Elevación de talones con balanceo de pie con barra","bp":"lower legs","eq":"barbell","tg":"calves","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra sobre la parte superior de la espalda.","Levanta los talones del suelo lo más alto posible, manteniendo el equilibrio sobre las puntas de los pies.","Baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0111-6HiHHe0.jpg","gif":"0111-6HiHHe0.gif"},{"id":"0112","n":"Giro de tronco de pie con barra","bp":"waist","eq":"barbell","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente al pecho con ambas manos, palmas hacia abajo.","Activa el core y mantén la espalda recta durante todo el ejercicio.","Gira lentamente el torso hacia la derecha, pivotando sobre los pies y las caderas, mientras mantienes estable la parte inferior del cuerpo.","Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.","Repite el giro hacia el lado izquierdo.","Continúa alternando los giros el número de repeticiones deseado."],"img":"0112-yQe5HpE.jpg","gif":"0112-yQe5HpE.gif"},{"id":"1629","n":"Curl de bíceps con agarre ancho de pie con barra","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre supino, manos más separadas que el ancho de los hombros.","Mantén la espalda recta y los codos cerca del torso.","Exhala y flexiona la barra hacia los hombros, manteniendo los brazos superiores quietos.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"1629-faHKVkK.jpg","gif":"1629-faHKVkK.gif"},{"id":"1457","n":"Press militar con barra de pie agarre ancho","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.","Levanta la barra hasta la altura de los hombros, manteniendo los codos ligeramente por delante de la barra.","Empuja la barra por encima de la cabeza, extendiendo completamente los brazos.","Baja la barra de vuelta a la altura de los hombros y repite el número de repeticiones deseado."],"img":"1457-Kyd9Rz5.jpg","gif":"1457-Kyd9Rz5.gif"},{"id":"0113","n":"Curl de bíceps con barra de pie agarre ancho","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos más separadas que el ancho de los hombros.","Deja que la barra cuelgue a la longitud del brazo frente a los muslos, con las palmas mirando hacia afuera del cuerpo.","Manteniendo los brazos superiores quietos, exhala y flexiona la barra hacia arriba contrayendo los bíceps.","Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0113-NdIb5Z1.jpg","gif":"0113-NdIb5Z1.gif"},{"id":"0114","n":"Step-up con barra","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie frente a un banco o escalón con una barra apoyada en la parte superior de la espalda.","Coloca un pie sobre el banco o escalón, asegurándote de que todo el pie esté en contacto con la superficie.","Empuja con el talón y sube al banco o escalón, extendiendo completamente la cadera y la rodilla.","Haz una pausa breve en la parte más alta, luego baja de vuelta a la posición inicial.","Repite con la pierna contraria.","Continúa alternando las piernas durante el número de repeticiones deseado."],"img":"0114-Kxquu2E.jpg","gif":"0114-Kxquu2E.gif"},{"id":"0115","n":"Buenos días con barra piernas rígidas","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios.","Manteniendo la espalda recta, inclínate hacia adelante desde las caderas, empujando los glúteos hacia atrás.","Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales.","Activa los glúteos y los isquiotibiales para volver a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0115-JrOHAZc.jpg","gif":"0115-JrOHAZc.gif"},{"id":"0116","n":"Peso muerto con barra piernas rectas","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back"],"st":["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies apuntando hacia delante.","Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros.","Flexiona las caderas y baja la barra hacia el suelo, manteniendo la espalda recta y las rodillas ligeramente flexionadas.","Baja la barra hasta que sientas un estiramiento en los isquiotibiales.","Activa los isquiotibiales y los glúteos para levantar la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0116-hrVQWvE.jpg","gif":"0116-hrVQWvE.gif"},{"id":"0117","n":"Peso muerto sumo con barra","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","lower back"],"st":["Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies hacia afuera.","Coloca una barra en el suelo frente a ti, centrada entre los pies.","Flexiona las rodillas y baja las caderas, manteniendo la espalda recta y el pecho elevado, para sujetar la barra con agarre prono.","Activa el core y empuja con los talones para levantar la barra del suelo, extendiendo las caderas y las rodillas simultáneamente.","Al levantar, mantén el pecho elevado y la espalda recta, y empuja las caderas hacia adelante para activar completamente los glúteos.","Haz una pausa breve en la parte más alta, luego baja lentamente la barra de vuelta a la posición inicial, manteniendo el control durante todo el movimiento.","Repite el número de repeticiones deseado."],"img":"0117-KgI0tqW.jpg","gif":"0117-KgI0tqW.gif"},{"id":"3305","n":"Thruster con barra","bp":"shoulders","eq":"barbell","tg":"delts","mg":"quadriceps","sm":["quadriceps","glutes","hamstrings","core"],"st":["Comienza de pie con los pies separados a la altura de los hombros, sujetando una barra a la altura de los hombros con agarre prono.","Baja a una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.","Al llegar a la parte más baja de la sentadilla, empuja explosivamente con los talones para ponerte de pie, presionando simultáneamente la barra por encima de la cabeza.","Baja la barra de nuevo a la altura de los hombros mientras vuelves a bajar a la posición de sentadilla.","Repite el número de repeticiones deseado."],"img":"3305-f7Y9eDZ.jpg","gif":"3305-f7Y9eDZ.gif"},{"id":"0120","n":"Remo al mentón con barra EZ pegado","bp":"shoulders","eq":"barbell","tg":"delts","mg":"traps","sm":["traps","biceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos un poco más separadas que el ancho de los hombros.","Deja que la barra cuelgue frente a los muslos, con los brazos completamente extendidos.","Manteniendo la espalda recta y el core activado, exhala y levanta la barra en línea recta hacia la barbilla, guiando el movimiento con los codos.","Haz una pausa breve en la parte más alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0120-UDlhcO8.jpg","gif":"0120-UDlhcO8.gif"},{"id":"0119","n":"Remo al mentón con barra recta separado","bp":"shoulders","eq":"barbell","tg":"delts","mg":"traps","sm":["traps","biceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos un poco más separadas que el ancho de los hombros.","Deja que la barra cuelgue frente a los muslos, con los brazos completamente extendidos.","Manteniendo la espalda recta, exhala y levanta la barra en línea recta hacia la barbilla, guiando el movimiento con los codos.","Haz una pausa breve en la parte más alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0119-83HoW9X.jpg","gif":"0119-83HoW9X.gif"},{"id":"0121","n":"Remo al mentón con barra recta pegado","bp":"shoulders","eq":"barbell","tg":"delts","mg":"traps","sm":["traps","biceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos un poco más separadas que el ancho de los hombros.","Deja que la barra cuelgue frente a los muslos, con los brazos completamente extendidos.","Manteniendo el core activado y la espalda recta, exhala mientras levantas la barra en línea recta hacia la barbilla, guiando el movimiento con los codos.","Haz una pausa breve en la parte más alta, luego inhala mientras bajas lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0121-fI18Rbc.jpg","gif":"0121-fI18Rbc.gif"},{"id":"0122","n":"Press de banca con barra agarre ancho","bp":"chest","eq":"barbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros.","Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.","Baja la barra lentamente hacia el pecho, manteniendo los codos ligeramente abiertos hacia afuera.","Haz una pausa breve cuando la barra toque el pecho y luego empújala de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0122-JsKq9so.jpg","gif":"0122-JsKq9so.gif"},{"id":"1258","n":"Press de banca con barra agarre ancho invertido","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Sujeta la barra con un agarre supino amplio, un poco más separado que el ancho de los hombros.","Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.","Baja la barra lentamente hacia el pecho, manteniendo los codos pegados al cuerpo y las muñecas rectas.","Haz una pausa breve cuando la barra toque el pecho y luego empújala de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1258-945zpRg.jpg","gif":"1258-945zpRg.gif"},{"id":"0124","n":"Sentadilla con barra agarre ancho","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera.","Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.","Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una sentadilla, empujando las caderas hacia atrás y flexionando las rodillas.","Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0124-s7HX1BY.jpg","gif":"0124-s7HX1BY.gif"},{"id":"0123","n":"Remo al mentón con barra agarre ancho","bp":"shoulders","eq":"barbell","tg":"delts","mg":"traps","sm":["traps","biceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos más separadas que el ancho de los hombros.","Deja que la barra cuelgue frente a los muslos, con los brazos completamente extendidos.","Manteniendo la espalda recta, exhala y levanta la barra en línea recta hacia la barbilla, guiando el movimiento con los codos.","Haz una pausa breve en la parte más alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0123-RgJDRR1.jpg","gif":"0123-RgJDRR1.gif"},{"id":"0126","n":"Curl de muñeca con barra apoyo en banco","bp":"lower arms","eq":"barbell","tg":"forearms","mg":"biceps","sm":["biceps","brachialis"],"st":["Siéntate en un banco con los pies planos en el suelo y los antebrazos apoyados sobre los muslos, sujetando una barra con agarre supino.","Deja que la barra ruede hacia las puntas de los dedos, manteniendo las muñecas rectas.","Enrolla lentamente la barra hacia los antebrazos flexionando las muñecas.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0126-82LxxkW.jpg","gif":"0126-82LxxkW.gif"},{"id":"0125","n":"Curl de muñeca con barra apoyo en piernas","bp":"lower arms","eq":"barbell","tg":"forearms","mg":"biceps","sm":["biceps","brachialis"],"st":["Siéntate en un banco con los pies planos sobre el suelo y las rodillas flexionadas.","Sujeta una barra con agarre supino, palmas hacia arriba, y las manos separadas a la altura de los hombros.","Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde.","Flexiona lentamente las muñecas hacia arriba, llevando la barra hacia los antebrazos.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0125-6kSxYnw.jpg","gif":"0125-6kSxYnw.gif"},{"id":"0127","n":"Sentadilla Zercher con barra","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.","Sujeta la barra en el pliegue de los codos, con las manos agarrando la barra para mayor estabilidad.","Activa el core y mantén el pecho elevado mientras bajas las caderas hacia atrás y hacia abajo en una posición de sentadilla.","Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones.","Haz una pausa breve en la parte baja de la sentadilla y luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0127-LSTChY9.jpg","gif":"0127-LSTChY9.gif"},{"id":"3212","n":"Toque de puntas básico (hombre)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros y los brazos a los costados.","Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y las rodillas ligeramente flexionadas.","Extiende las manos hacia las puntas de los pies, manteniendo las piernas lo más rectas posible.","Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3212-BbfB8Gb.jpg","gif":"3212-BbfB8Gb.gif"},{"id":"0128","n":"Cuerdas de batalla (battle ropes)","bp":"shoulders","eq":"rope","tg":"delts","mg":"forearms","sm":["forearms","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta un extremo de la cuerda en cada mano, con las palmas mirándose entre sí.","Levanta los brazos hasta la altura de los hombros, manteniendo los codos ligeramente flexionados.","Comienza a hacer ondas alternas con las cuerdas, levantando y bajando rápidamente cada brazo.","Continúa durante el tiempo o el número de repeticiones deseado."],"img":"0128-RJa4tCo.jpg","gif":"0128-RJa4tCo.gif"},{"id":"3360","n":"Marcha del oso","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"core","sm":["core","shoulders","triceps"],"st":["Comienza apoyado sobre manos y rodillas, con las manos justo debajo de los hombros y las rodillas justo debajo de las caderas.","Levanta las rodillas ligeramente del suelo, manteniendo la espalda plana y el core activado.","Mueve la mano derecha y el pie izquierdo hacia adelante simultáneamente, seguido de la mano izquierda y el pie derecho.","Continúa avanzando a gatas, alternando los movimientos de manos y pies.","Mantén un ritmo constante y el core firme durante todo el ejercicio.","Continúa durante la distancia o el tiempo deseado."],"img":"3360-0Yz8WdV.jpg","gif":"3360-0Yz8WdV.gif"},{"id":"1259","n":"Estiramiento de pecho con brazos tras la cabeza","bp":"chest","eq":"assisted","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.","Entrelaza los dedos detrás de la cabeza con los codos apuntando hacia afuera.","Junta lentamente los omóplatos y empuja el pecho hacia adelante.","Mantén el estiramiento durante 15-30 segundos.","Suelta el estiramiento y repite cuantas veces lo desees."],"img":"1259-QoHIhPl.jpg","gif":"1259-QoHIhPl.gif"},{"id":"0129","n":"Fondos en banco (rodillas flexionadas)","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Siéntate en el borde de un banco o silla con las manos sujetando el borde junto a las caderas.","Desliza los glúteos fuera del banco y estira las piernas frente a ti, manteniendo los talones en el suelo.","Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco.","Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0129-RrLske5.jpg","gif":"0129-RrLske5.gif"},{"id":"1399","n":"Fondos en banco en el suelo","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Siéntate en el borde de un banco o silla con las manos sujetando el borde, los dedos apuntando hacia adelante.","Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos.","Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.","Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."],"img":"1399-9RT8oQW.jpg","gif":"1399-9RT8oQW.gif"},{"id":"0130","n":"Extensión de cadera en banco","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings"],"st":["Siéntate en un banco con la espalda contra el banco y los pies planos en el suelo.","Coloca las manos sobre el banco para apoyarte.","Activa los glúteos y los isquiotibiales, luego levanta las caderas del banco hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.","Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0130-u27Kcdz.jpg","gif":"0130-u27Kcdz.gif"},{"id":"3019","n":"Dominadas en banco","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Colócate debajo de una barra o una superficie horizontal resistente que esté a la altura del pecho.","Sujeta la barra o la superficie con agarre prono, un poco más separado que el ancho de los hombros.","Cuélgate con los brazos completamente extendidos y el cuerpo recto.","Lleva el pecho hacia la barra o la superficie juntando los omóplatos y flexionando los codos.","Continúa tirando hasta que la barbilla quede por encima de la barra o la superficie.","Baja de nuevo a la posición inicial con control.","Repite el número de repeticiones deseado."],"img":"3019-mExgrF9.jpg","gif":"3019-mExgrF9.gif"},{"id":"3639","n":"Torsión tumbado con rodillas flexionadas (hombre)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"obliques","sm":["obliques","hip flexors"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Extiende los brazos hacia los lados, perpendiculares al cuerpo.","Manteniendo las rodillas juntas, bájalas lentamente hacia un lado, intentando tocar el suelo con las rodillas.","Haz una pausa breve, luego activa el core y levanta lentamente las rodillas de vuelta a la posición inicial.","Repite el movimiento hacia el otro lado.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"3639-6sYyrRX.jpg","gif":"3639-6sYyrRX.gif"},{"id":"1770","n":"Curl de bíceps concentrado con pierna","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco con las piernas separadas y los pies planos en el suelo.","Sujeta una mancuerna con una mano y coloca el codo en la parte interna del muslo, justo por encima de la rodilla.","Con la palma hacia arriba, flexiona la mancuerna hacia el hombro manteniendo el brazo superior quieto.","Contrae el bíceps en la parte más alta del movimiento, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1770-sJFIDIp.jpg","gif":"1770-sJFIDIp.gif"},{"id":"0139","n":"Dominadas cerradas para bíceps","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Cuélgate de una barra de dominadas con las palmas mirando hacia ti y las manos separadas a la altura de los hombros.","Activa el core y tira de tu cuerpo hacia la barra, enfocándote en usar los bíceps para levantar el cuerpo.","Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0139-50BETrz.jpg","gif":"0139-50BETrz.gif"},{"id":"0140","n":"Dominada para bíceps","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Cuélgate de una barra de dominadas con las palmas mirando hacia afuera y las manos separadas a la altura de los hombros.","Activa el core y tira de tu cuerpo hacia arriba flexionando los codos, llevando el pecho hacia la barra.","Haz una pausa en la parte más alta del movimiento, luego baja lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0140-guT8YnS.jpg","gif":"0140-guT8YnS.gif"},{"id":"0137","n":"Body-up","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Comienza colocando las manos sobre una superficie elevada, como un banco o unas barras paralelas, con las palmas hacia abajo y los dedos apuntando hacia adelante.","Extiende las piernas frente a ti, manteniendo los talones en el suelo y el cuerpo recto.","Baja el cuerpo flexionando los codos, manteniéndolos cerca del cuerpo, hasta que los brazos superiores queden paralelos al suelo.","Haz una pausa breve, luego empuja con las palmas para extender los brazos y levantar el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0137-U6G2gk9.jpg","gif":"0137-U6G2gk9.gif"},{"id":"3543","n":"Sentadilla con salto desde caída (peso corporal)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros.","Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.","Salta hacia arriba explosivamente, extendiendo las caderas, las rodillas y los tobillos.","Mientras estás en el aire, junta rápidamente los pies.","Aterriza suavemente sobre las puntas de los pies y de inmediato vuelve a bajar a una posición de sentadilla.","Repite el número de repeticiones deseado."],"img":"3543-wfotm7S.jpg","gif":"3543-wfotm7S.gif"},{"id":"3544","n":"Plancha lateral inclinada (peso corporal)","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","shoulders"],"st":["Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra.","Coloca el antebrazo en el suelo justo debajo del hombro, con el codo flexionado en un ángulo de 90 grados.","Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies.","Mantén esta posición durante el tiempo deseado.","Baja las caderas de nuevo al suelo y repite hacia el otro lado."],"img":"3544-5VXmnV5.jpg","gif":"3544-5VXmnV5.gif"},{"id":"1771","n":"Extensión de tríceps de rodillas (peso corporal)","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders","chest"],"st":["Ponte de rodillas en el suelo con las rodillas separadas a la altura de las caderas.","Coloca las manos en el suelo frente a ti, separadas a la altura de los hombros, con los dedos apuntando hacia adelante.","Extiende las piernas rectas detrás de ti, equilibrándote sobre las puntas de los pies y las manos, formando una línea recta desde la cabeza hasta los talones.","Flexiona los codos y baja la parte superior del cuerpo hacia el suelo, manteniendo los codos cerca del cuerpo.","Haz una pausa breve en la posición más baja, luego empuja con las manos para extender los brazos y volver a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1771-s0HKO2I.jpg","gif":"1771-s0HKO2I.gif"},{"id":"1769","n":"Curl de bíceps tumbado de lado (peso corporal)","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Túmbate de lado con las piernas extendidas y la cabeza apoyada sobre el brazo.","Mantén el brazo superior junto al cuerpo y flexiona el codo para llevar el antebrazo hacia el hombro.","Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1769-gscGLOU.jpg","gif":"1769-gscGLOU.gif"},{"id":"3168","n":"Remo en sentadilla (peso corporal)","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando un objeto resistente o un entrenador de suspensión con los brazos extendidos.","Baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y las rodillas detrás de las puntas de los pies.","Desde la posición de sentadilla, tira del cuerpo hacia arriba en dirección al objeto o al entrenador de suspensión, juntando los omóplatos.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3168-3xK09Sk.jpg","gif":"3168-3xK09Sk.gif"},{"id":"3167","n":"Remo en sentadilla con toalla (peso corporal)","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una toalla frente a ti con las palmas hacia abajo.","Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.","Mientras bajas a la sentadilla, tira simultáneamente de la toalla hacia el pecho, juntando los omóplatos.","Haz una pausa breve en la parte más baja de la sentadilla, luego vuelve lentamente a la posición inicial mientras extiendes los brazos.","Repite el número de repeticiones deseado."],"img":"3167-BReCuOn.jpg","gif":"3167-BReCuOn.gif"},{"id":"1373","n":"Elevación de talones de pie (peso corporal)","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","feet"],"st":["Ponte de pie con los pies separados a la altura de los hombros, con las puntas de los pies apuntando hacia adelante.","Coloca las manos sobre una pared o superficie estable para mantener el equilibrio.","Levanta lentamente los talones del suelo, llevando el peso del cuerpo hacia las puntas de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1373-bJYHBIN.jpg","gif":"1373-bJYHBIN.gif"},{"id":"3156","n":"Remo a una mano con agarre cerrado de pie (peso corporal)","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una mancuerna en una mano con agarre neutro.","Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.","Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"3156-v2DfH14.jpg","gif":"3156-v2DfH14.gif"},{"id":"3158","n":"Remo con agarre cerrado de pie (peso corporal)","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado.","Extiende los brazos rectos frente a ti, sujetando la barra o las agarraderas con un agarre cerrado.","Tira de la barra o las agarraderas hacia el cuerpo, juntando los omóplatos.","Haz una pausa breve en la parte más alta del movimiento, luego suelta lentamente y vuelve a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3158-tig3PXb.jpg","gif":"3158-tig3PXb.gif"},{"id":"3162","n":"Remo a una mano de pie (peso corporal)","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una mancuerna con una mano.","Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.","Deja que la mancuerna cuelgue recta frente a ti, con el brazo completamente extendido.","Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo.","Junta los omóplatos en la parte superior del movimiento.","Baja la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"3162-xbkPfaw.jpg","gif":"3162-xbkPfaw.gif"},{"id":"3161","n":"Remo a un brazo de pie con peso corporal (con toalla)","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una toalla con una mano.","Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.","Tira de la toalla hacia el pecho, juntando los omóplatos.","Haz una pausa breve en la parte más alta, luego baja lentamente la toalla de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"3161-O4oIqQD.jpg","gif":"3161-O4oIqQD.gif"},{"id":"3166","n":"Remo de pie con peso corporal","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta una barra o las agarraderas con agarre prono, palmas hacia abajo.","Mantén la espalda recta y el core activado.","Tira de la barra o las agarraderas hacia el cuerpo, juntando los omóplatos.","Haz una pausa breve en la parte alta del movimiento.","Suelta lentamente y extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3166-wd4ds3s.jpg","gif":"3166-wd4ds3s.gif"},{"id":"3165","n":"Remo de pie con peso corporal (con toalla)","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una toalla frente a ti con ambas manos.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Tira de la toalla hacia el pecho, juntando los omóplatos.","Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3165-uTv34oq.jpg","gif":"3165-uTv34oq.gif"},{"id":"0138","n":"Bottoms-up","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.","Flexiona las rodillas y llévalas hacia el pecho, manteniendo los pies fuera del suelo.","Activando el abdomen, levanta las caderas del suelo, llevando las rodillas hacia la cabeza.","Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0138-CI6baTY.jpg","gif":"0138-CI6baTY.gif"},{"id":"1374","n":"Salto desde cajón con estabilización a una pierna","bp":"lower legs","eq":"body weight","tg":"calves","mg":"quadriceps","sm":["quadriceps","hamstrings","glutes"],"st":["Ponte de pie frente a una caja o plataforma con los pies separados a la altura de los hombros.","Flexiona las rodillas y salta sobre la caja, aterrizando suavemente con un pie sobre la caja y el otro pie colgando del borde.","Estabilízate sobre la caja con el pie que está sobre ella, mientras mantienes el otro pie fuera del suelo.","Mantén esta posición durante unos segundos, activando los músculos de la pantorrilla para conservar el equilibrio.","Baja lentamente con el pie que está sobre la caja, volviendo a la posición inicial.","Repite el ejercicio con la otra pierna."],"img":"1374-iPm26QU.jpg","gif":"1374-iPm26QU.gif"},{"id":"2466","n":"Puente - mountain climber (cruzado)","bp":"waist","eq":"body weight","tg":"abs","mg":"glutes","sm":["glutes","quadriceps","hamstrings","shoulders","triceps"],"st":["Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta.","Activa el core y levanta el pie derecho del suelo, llevando la rodilla derecha hacia el codo izquierdo.","Vuelve a colocar el pie derecho en la posición inicial y repite el movimiento llevando el pie izquierdo hacia el codo derecho.","Continúa alternando los lados, moviéndote a un ritmo controlado.","Mantén las caderas niveladas y evita levantarlas demasiado alto o dejarlas caer demasiado bajo.","Mantén un patrón de respiración constante durante todo el ejercicio.","Repite el número de repeticiones deseado."],"img":"2466-9c6T1YX.jpg","gif":"2466-9c6T1YX.gif"},{"id":"1160","n":"Burpee","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","shoulders","chest"],"st":["Comienza de pie con los pies separados a la altura de los hombros.","Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y colocando las manos en el suelo frente a ti.","Lleva los pies hacia atrás de una patada hasta una posición de flexión de brazos.","Realiza una flexión de brazos, manteniendo el cuerpo en línea recta.","Salta con los pies de vuelta a la posición de sentadilla.","Salta hacia arriba explosivamente, llevando los brazos por encima de la cabeza.","Aterriza suavemente y baja de inmediato a una posición de sentadilla para comenzar la siguiente repetición."],"img":"1160-dK9394r.jpg","gif":"1160-dK9394r.gif"},{"id":"0870","n":"Butt-ups","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos a los lados, con las palmas hacia abajo.","Activando el abdomen, levanta las piernas del suelo, llevando las rodillas hacia el pecho.","En la parte más alta del movimiento, contrae el abdomen y haz una pausa breve.","Baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0870-qcNN2FN.jpg","gif":"0870-qcNN2FN.gif"},{"id":"1494","n":"Postura de yoga de la mariposa","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"hamstrings","sm":["hamstrings","groin"],"st":["Siéntate en el suelo con las piernas extendidas frente a ti.","Flexiona las rodillas y junta las plantas de los pies, dejando que las rodillas caigan hacia los lados.","Sujétate los tobillos o los pies con las manos.","Siéntate erguido y alarga la columna.","Presiona suavemente las rodillas hacia el suelo, sintiendo un estiramiento en la parte interna de los muslos.","Mantén esta posición durante unas cuantas respiraciones.","Para liberar, lleva lentamente las rodillas hacia arriba de nuevo y extiende las piernas."],"img":"1494-bWlZvXh.jpg","gif":"1494-bWlZvXh.gif"},{"id":"0148","n":"Press de hombros alterno con polea","bp":"shoulders","eq":"cable","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta las agarraderas de la máquina de cable con agarre prono.","Coloca las manos a la altura de los hombros, con las palmas mirando hacia adelante.","Mantén el core activado y la espalda recta.","Empuja una agarradera hacia arriba y hacia adelante hasta que el brazo quede completamente extendido.","Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera de vuelta a la posición inicial.","Repite con el otro brazo.","Alterna entre los brazos el número de repeticiones deseado."],"img":"0148-KHPZL0b.jpg","gif":"0148-KHPZL0b.gif"},{"id":"0149","n":"Extensión de tríceps alterna con polea","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Sujeta la agarradera del cable con la mano derecha y levanta el brazo de modo que el brazo superior quede paralelo al suelo y el codo flexionado en un ángulo de 90 grados.","Mantén el brazo superior quieto y extiende el antebrazo hacia atrás, estirando completamente el brazo.","Haz una pausa por un momento, luego regresa lentamente a la posición inicial.","Repite con el brazo izquierdo.","Continúa alternando los brazos durante el número de repeticiones deseado."],"img":"0149-Gchi5Tr.jpg","gif":"0149-Gchi5Tr.gif"},{"id":"3235","n":"Curl de pierna inverso asistido con polea","bp":"upper legs","eq":"cable","tg":"hamstrings","mg":"glutes","sm":["glutes","calves"],"st":["Ajusta la máquina de cable de modo que el accesorio para el tobillo quede en la posición más baja.","Túmbate boca abajo en el banco con las piernas rectas y el accesorio para el tobillo sujeto a los tobillos.","Sujétate de las agarraderas del banco para mantener la estabilidad.","Manteniendo quieta la parte superior del cuerpo, exhala y flexiona las piernas hacia los glúteos doblando las rodillas.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los isquiotibiales.","Inhala y baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3235-zHEpuuc.jpg","gif":"3235-zHEpuuc.gif"},{"id":"0150","n":"Jalón lateral con barra en polea","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Ajusta la polea del cable a una posición alta y coloca una barra recta.","Siéntate frente a la máquina de cable con los pies planos en el suelo y las rodillas ligeramente flexionadas.","Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.","Inclínate ligeramente hacia atrás y mantén el pecho elevado, conservando un ligero arco en la zona lumbar.","Tira de la barra hacia el pecho, guiando el movimiento con los codos y juntando los omóplatos.","Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente la barra a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0150-eYnzaCm.jpg","gif":"0150-eYnzaCm.gif"},{"id":"0151","n":"Press de banca con polea","bp":"chest","eq":"cable","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Ajusta la máquina de cable a la altura del pecho y coloca las agarraderas.","Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.","Sujeta las agarraderas con agarre prono y da un paso hacia adelante para crear tensión en los cables.","Coloca los pies firmemente en el suelo y activa el core.","Flexiona los codos y lleva las manos a la altura de los hombros, manteniendo los codos en un ángulo de 90 grados.","Empuja las agarraderas hacia adelante, extendiendo completamente los brazos frente a ti.","Haz una pausa breve, luego invierte lentamente el movimiento, llevando las manos de vuelta a la altura de los hombros.","Repite el número de repeticiones deseado."],"img":"0151-7xI5MXA.jpg","gif":"0151-7xI5MXA.gif"},{"id":"1630","n":"Curl de bíceps con agarre cerrado en polea","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Coloca una barra recta en una máquina de cable con polea baja.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.","Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio.","Exhala y flexiona la barra hacia los hombros, contrayendo los bíceps.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"1630-BCGQ6J5.jpg","gif":"1630-BCGQ6J5.gif"},{"id":"1631","n":"Curl de concentración con polea","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco o silla con los pies planos en el suelo y las rodillas ligeramente flexionadas.","Sujeta la agarradera del cable con agarre supino y apoya el codo en la parte interna del muslo.","Manteniendo el brazo superior quieto, exhala y flexiona la agarradera del cable hacia el hombro contrayendo el bíceps.","Haz una pausa breve en la parte más alta del movimiento, luego inhala y baja lentamente la agarradera del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1631-NvfE43H.jpg","gif":"1631-NvfE43H.gif"},{"id":"0152","n":"Extensión de concentración con polea (sobre la rodilla)","bp":"upper arms","eq":"cable","tg":"triceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco o silla con las rodillas flexionadas y los pies planos en el suelo.","Sujeta la agarradera del cable con la mano derecha y coloca el codo en la parte interna de la rodilla derecha.","Extiende completamente el brazo, manteniendo el codo quieto y cerca de la rodilla.","Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"0152-Db7eEgw.jpg","gif":"0152-Db7eEgw.gif"},{"id":"0153","n":"Jalón lateral cruzado en polea","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Coloca una agarradera de cable en cada lado de una máquina de cable a la altura de los hombros.","Ponte de pie en el centro de la máquina con los pies separados a la altura de los hombros.","Sujeta las agarraderas con agarre prono y da un paso hacia atrás para crear tensión en los cables.","Inclínate ligeramente hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.","Tira de las agarraderas hacia abajo y a través del cuerpo, juntando los omóplatos.","Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0153-OQ1otBN.jpg","gif":"0153-OQ1otBN.gif"},{"id":"0154","n":"Aperturas inversas cruzadas en polea","bp":"shoulders","eq":"cable","tg":"delts","mg":"rhomboids","sm":["rhomboids","trapezius"],"st":["Coloca una agarradera en D en cada cable de polea baja y ponte de pie en el centro de la máquina de cable cruzado.","Sujeta las agarraderas con agarre prono (palmas hacia abajo) y da un paso hacia adelante, colocando los pies separados a la altura de los hombros.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el abdomen activado.","Con los brazos extendidos hacia los lados y ligeramente flexionados en los codos, exhala y junta los omóplatos mientras tiras de los cables hacia atrás y hacia arriba en un movimiento de apertura inversa.","Haz una pausa breve en el punto máximo de contracción, luego inhala y vuelve lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0154-aqvSOQE.jpg","gif":"0154-aqvSOQE.gif"},{"id":"0155","n":"Variante de cruces de poleas","bp":"chest","eq":"cable","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Ajusta las poleas del cable a la altura del pecho.","Ponte de pie en el centro de la máquina de cable con un pie delante del otro.","Sujeta las agarraderas con las palmas hacia abajo y los brazos extendidos hacia los lados.","Da un paso hacia adelante, manteniendo los brazos ligeramente flexionados.","Con una ligera flexión en los codos, junta las manos frente al pecho.","Haz una pausa breve, luego vuelve lentamente los brazos a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0155-0CXGHya.jpg","gif":"0155-0CXGHya.gif"},{"id":"0868","n":"Curl con polea","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Sujeta el accesorio del cable con agarre supino, palmas hacia arriba.","Mantén los codos cerca de los costados y los brazos superiores quietos.","Exhala y flexiona el accesorio del cable hacia los hombros, contrayendo los bíceps.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0868-G08RZcQ.jpg","gif":"0868-G08RZcQ.gif"},{"id":"0157","n":"Peso muerto con polea","bp":"upper legs","eq":"cable","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","lower back"],"st":["Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Flexiona las caderas y las rodillas, bajando el torso hasta que la espalda quede paralela al suelo.","Sujeta las agarraderas del cable con agarre prono, manteniendo los brazos rectos y los hombros hacia atrás.","Activa los glúteos y los isquiotibiales para levantar las agarraderas del cable, extendiendo las caderas y poniéndote de pie.","Haz una pausa breve en la parte más alta, luego baja lentamente las agarraderas del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0157-eGDudUV.jpg","gif":"0157-eGDudUV.gif"},{"id":"0158","n":"Aperturas en declive con polea","bp":"chest","eq":"cable","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Ajusta la máquina de cable a una posición declinada.","Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.","Sujeta las agarraderas con las palmas hacia adelante y los brazos extendidos rectos frente a ti.","Manteniendo una ligera flexión en los codos, abre los brazos hacia los lados con un movimiento controlado.","Haz una pausa breve en la posición completamente extendida, luego vuelve lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0158-7saC5zz.jpg","gif":"0158-7saC5zz.gif"},{"id":"1260","n":"Press declinado a un brazo con polea","bp":"chest","eq":"cable","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Ajusta la máquina de cable a una posición declinada.","Ponte de pie de espaldas a la máquina y sujeta la agarradera con una mano.","Colócate con la espalda contra el banco declinado y el brazo extendido recto frente a ti.","Flexiona el codo y baja la agarradera hacia el pecho, manteniendo el brazo superior quieto.","Haz una pausa breve en la parte más baja, luego empuja la agarradera de vuelta hacia la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1260-KHGNa16.jpg","gif":"1260-KHGNa16.gif"},{"id":"1261","n":"Press declinado con polea","bp":"chest","eq":"cable","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Ajusta la máquina de cable a una posición declinada.","Siéntate en el banco declinado frente a la máquina de cable.","Sujeta las agarraderas con agarre prono y colócalas a la altura del pecho.","Mantén los pies planos en el suelo y la espalda firmemente apoyada en el banco.","Exhala y empuja las agarraderas alejándolas del cuerpo, extendiendo completamente los brazos.","Haz una pausa breve al final del movimiento, contrayendo los músculos del pecho.","Inhala y vuelve lentamente las agarraderas a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1261-2Pya1cP.jpg","gif":"1261-2Pya1cP.gif"},{"id":"0159","n":"Remo sentado con agarre ancho en declive con polea","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Siéntate en el banco declinado frente a la máquina de cable con los pies firmemente colocados en los reposapiés.","Sujeta el accesorio del cable con un agarre prono amplio, palmas hacia abajo.","Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el core activado.","Tira del cable hacia la parte inferior del pecho, juntando los omóplatos.","Haz una pausa breve en el punto máximo de la contracción, luego suelta lentamente el cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0159-kesXOpB.jpg","gif":"0159-kesXOpB.gif"},{"id":"1632","n":"Drag curl con polea","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.","Sujeta el accesorio del cable con agarre supino, palmas hacia arriba, y los brazos completamente extendidos.","Manteniendo los brazos superiores quietos, exhala y flexiona el accesorio del cable hacia los hombros contrayendo los bíceps.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"1632-dXz8zjF.jpg","gif":"1632-dXz8zjF.gif"},{"id":"0160","n":"Remo sentado en el suelo con agarre ancho con polea","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Siéntate en el suelo con las piernas extendidas y la espalda recta.","Coloca una agarradera de cable en una polea baja y ubica la máquina de cable detrás de ti.","Sujeta la agarradera con un agarre prono amplio, palmas hacia abajo.","Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el pecho elevado.","Tira de la agarradera hacia la cintura, juntando los omóplatos.","Haz una pausa breve en la parte más alta del movimiento, luego suelta lentamente la agarradera de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0160-veXwo0D.jpg","gif":"0160-veXwo0D.gif"},{"id":"0161","n":"Elevación hacia delante con polea","bp":"shoulders","eq":"cable","tg":"delts","mg":"triceps","sm":["triceps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta la agarradera del cable con agarre prono, palmas hacia abajo, y los brazos completamente extendidos frente a ti.","Manteniendo los brazos rectos, levanta la agarradera del cable hasta la altura de los hombros.","Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0161-hvHhCv8.jpg","gif":"0161-hvHhCv8.gif"},{"id":"0162","n":"Elevaciones frontales con polea","bp":"shoulders","eq":"cable","tg":"delts","mg":"triceps","sm":["triceps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta la agarradera del cable con agarre prono.","Mantén la espalda recta y el core activado.","Levanta la agarradera del cable frente a ti, manteniendo los brazos rectos y las palmas hacia abajo.","Continúa levantando hasta que los brazos queden paralelos al suelo.","Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0162-u2X71Np.jpg","gif":"0162-u2X71Np.gif"},{"id":"0164","n":"Elevaciones frontales de hombro con polea","bp":"shoulders","eq":"cable","tg":"delts","mg":"trapezius","sm":["trapezius","biceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta la agarradera del cable con agarre prono.","Mantén la espalda recta y el core activado.","Levanta la agarradera del cable frente a ti, manteniendo los brazos rectos y las palmas hacia abajo.","Continúa levantando hasta que los brazos queden paralelos al suelo.","Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0164-mTT3KLn.jpg","gif":"0164-mTT3KLn.gif"},{"id":"0165","n":"Curl martillo con polea (con cuerda)","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y una ligera flexión en las rodillas.","Sujeta el accesorio de cuerda del cable con agarre supino, palmas mirándose entre sí, y los brazos completamente extendidos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando el accesorio de cuerda del cable hasta que los bíceps estén completamente contraídos y la cuerda esté a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente el accesorio de cuerda del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0165-HPlPoQA.jpg","gif":"0165-HPlPoQA.gif"},{"id":"1722","n":"Extensión de tríceps sobre la cabeza en polea alta","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Coloca una cuerda en una polea alta y ponte de pie de espaldas a la máquina.","Sujeta la cuerda con ambas manos y extiende los brazos por encima de la cabeza.","Mantén los codos cerca de la cabeza y la parte superior de los brazos inmóvil.","Baja lentamente la cuerda detrás de la cabeza flexionando los codos.","Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1722-1xHyxys.jpg","gif":"1722-1xHyxys.gif"},{"id":"0167","n":"Remo alto con polea (de rodillas)","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Sujeta una barra recta a una máquina de cable a la altura del pecho.","Ponte de rodillas frente a la máquina de cable y agarra la barra con un agarre prono, con las manos separadas a la altura de los hombros.","Siéntate sobre los talones, manteniendo la espalda recta y el core activado.","Jala la barra hacia la parte superior del abdomen, apretando los omóplatos entre sí.","Haz una pausa por un momento en la parte más alta del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0167-ZSJNetl.jpg","gif":"0167-ZSJNetl.gif"},{"id":"0168","n":"Aducción de cadera con polea","bp":"upper legs","eq":"cable","tg":"adductors","mg":"glutes","sm":["glutes","quadriceps"],"st":["Sujeta el manguito de tobillo a tu tobillo y ponte de pie frente a la máquina de cable.","Colócate lo suficientemente alejado de la máquina para que haya tensión en el cable.","Coloca las manos sobre la máquina para apoyarte.","Manteniendo la pierna recta, mueve lentamente la pierna por delante del cuerpo hacia la línea media.","Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0168-hBGWILP.jpg","gif":"0168-hBGWILP.gif"},{"id":"0169","n":"Press de banca inclinado con polea","bp":"chest","eq":"cable","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Ajusta el banco a una inclinación de 45 grados.","Sujeta las agarraderas del cable a las poleas altas.","Siéntate en el banco frente a la máquina de cable con los pies apoyados planos en el suelo.","Sujeta las agarraderas con un agarre prono y llévalas a la altura de los hombros.","Empuja las agarraderas hacia adelante y hacia arriba hasta que los brazos queden completamente extendidos.","Haz una pausa por un momento y luego baja lentamente las agarraderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0169-Vh0GsK4.jpg","gif":"0169-Vh0GsK4.gif"},{"id":"1318","n":"Remo en banco inclinado con polea","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","rear deltoids"],"st":["Coloca un banco inclinado a un ángulo de 45 grados y sujeta una agarradera de cable a la polea baja.","Siéntate en el banco frente a la máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas.","Sujeta la agarradera del cable con un agarre prono y extiende los brazos completamente frente a ti.","Inclínate hacia adelante desde las caderas manteniendo la espalda recta y el core activado.","Jala la agarradera del cable hacia el pecho retrayendo los omóplatos y flexionando los codos.","Aprieta los músculos de la espalda en la parte más alta del movimiento y luego extiende lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1318-yaMIo4D.jpg","gif":"1318-yaMIo4D.gif"},{"id":"0171","n":"Aperturas inclinadas con polea","bp":"chest","eq":"cable","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Ajusta la máquina de cable a una posición baja y sujeta las agarraderas.","Siéntate en un banco inclinado con la espalda apoyada en el respaldo y los pies planos en el suelo.","Sujeta las agarraderas con un agarre prono y extiende los brazos rectos frente a ti.","Manteniendo una ligera flexión en los codos, abre los brazos hacia los lados con un movimiento controlado.","Haz una pausa breve en la posición completamente extendida, luego vuelve lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0171-tBWXbIT.jpg","gif":"0171-tBWXbIT.gif"},{"id":"0170","n":"Aperturas inclinadas con polea (en pelota de estabilidad)","bp":"chest","eq":"cable","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Coloca un balón de estabilidad en un ángulo inclinado.","Sujeta las agarraderas del cable a las poleas altas de una máquina de cable.","Siéntate sobre el balón de estabilidad de espaldas a la máquina, con los pies firmemente apoyados en el suelo.","Sujeta las agarraderas del cable con un agarre prono, con las palmas hacia adelante.","Inclínate ligeramente hacia adelante, manteniendo la espalda recta y el core activado.","Con un movimiento controlado, lleva los brazos hacia los lados, manteniendo una ligera flexión en los codos.","Continúa el movimiento hasta que los brazos queden paralelos al suelo.","Haz una pausa por un momento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0170-27NNGFr.jpg","gif":"0170-27NNGFr.gif"},{"id":"0172","n":"Pushdown inclinado con polea","bp":"back","eq":"cable","tg":"lats","mg":"triceps","sm":["triceps","shoulders"],"st":["Sujeta una barra recta a una máquina de cable con polea alta.","Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.","Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.","Inclínate ligeramente hacia adelante y mantén la espalda recta.","Jala la barra hacia abajo en dirección a tus muslos extendiendo los codos.","Haz una pausa por un momento en la parte baja y luego regresa lentamente la barra a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0172-1PK5Uo3.jpg","gif":"0172-1PK5Uo3.gif"},{"id":"0173","n":"Extensión de tríceps en polea inclinada","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Ajusta la máquina de cable a una posición de polea baja.","Sujeta una barra recta al cable.","Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.","Sujeta la barra con un agarre prono y extiende los brazos rectos por encima de la cabeza.","Inclínate ligeramente hacia adelante, manteniendo la espalda recta y el core activado.","Flexiona los codos y baja la barra detrás de la cabeza, manteniendo la parte superior de los brazos cerca de las orejas.","Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0173-Hx1WC8I.jpg","gif":"0173-Hx1WC8I.gif"},{"id":"0174","n":"Judo flip en polea","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques","shoulders"],"st":["Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Sujeta la agarradera del cable con ambas manos a la altura del pecho, con las palmas hacia abajo.","Activa el core y rota el torso hacia la derecha, jalando el cable a través del cuerpo.","Mientras rotas, gira el pie de atrás y permite que las caderas roten de forma natural.","Extiende los brazos completamente y termina el movimiento llevando la agarradera del cable por encima del hombro.","Vuelve a la posición inicial revirtiendo el movimiento, rotando el torso de regreso al centro.","Repite el movimiento en el lado opuesto.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0174-MvQPqVW.jpg","gif":"0174-MvQPqVW.gif"},{"id":"0860","n":"Patada de tríceps en polea","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.","Sujeta la agarradera del cable con la mano derecha y retrocede un paso para crear tensión en el cable.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Mantén la parte superior del brazo cerca del cuerpo y el codo flexionado en un ángulo de 90 grados.","Extiende el antebrazo hacia atrás, enderezando el brazo por completo.","Haz una pausa por un momento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"0860-HEJ6DIX.jpg","gif":"0860-HEJ6DIX.gif"},{"id":"0175","n":"Crunch de rodillas en polea","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Sujeta una agarradera de cuerda a una polea alta y ponte de rodillas de espaldas a la máquina.","Sujeta la agarradera de cuerda con ambas manos y colócala detrás de la cabeza, manteniendo los codos hacia afuera a los lados.","Manteniendo las caderas inmóviles, flexiona la cintura y encoge el torso hacia los muslos.","Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0175-WW95auq.jpg","gif":"0175-WW95auq.gif"},{"id":"3697","n":"Remo para deltoide posterior de rodillas en polea (con cuerda) (hombre)","bp":"shoulders","eq":"cable","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids","biceps"],"st":["Sujeta una agarradera de cuerda a una polea baja y ponte de rodillas frente a la máquina.","Sujeta la cuerda con un agarre neutro (las palmas una frente a la otra) y extiende los brazos completamente frente a ti.","Manteniendo la espalda recta y el core activado, jala la cuerda hacia el cuerpo retrayendo los omóplatos.","Aprieta los omóplatos al final del movimiento y mantén la posición por una breve pausa.","Libera lentamente la tensión y vuelve a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3697-G61cXLk.jpg","gif":"3697-G61cXLk.gif"},{"id":"0176","n":"Extensión de tríceps de rodillas en polea","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Sujeta una agarradera de cuerda a una polea alta y ponte de rodillas frente a la máquina de cable.","Sujeta la cuerda con un agarre neutro (las palmas una frente a la otra) y lleva las manos a los lados de la cabeza.","Mantén los codos cerca de la cabeza y la parte superior de los brazos inmóvil durante todo el ejercicio.","Extiende los antebrazos contrayendo los tríceps hasta que los brazos queden completamente extendidos.","Haz una pausa por un momento y luego vuelve lentamente a la posición inicial flexionando los codos.","Repite el número de repeticiones deseado."],"img":"0176-KWdF2JI.jpg","gif":"0176-KWdF2JI.gif"},{"id":"2330","n":"Jalón al pecho en polea (rango completo de movimiento)","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Siéntate en la máquina de jalón al pecho con las rodillas colocadas debajo de las almohadillas.","Sujeta la barra del cable con un agarre prono, un poco más separado que el ancho de los hombros.","Inclínate ligeramente hacia atrás y mantén el pecho elevado, conservando un ligero arco en la zona lumbar.","Jala la barra hacia la parte superior del pecho, apretando los omóplatos entre sí.","Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2330-LEprlgG.jpg","gif":"2330-LEprlgG.gif"},{"id":"0177","n":"Jalón lateral en polea (con accesorio de cuerda)","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Sujeta un accesorio de cuerda a la máquina de cable en una posición alta.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Sujeta la cuerda con un agarre prono, con las palmas una frente a la otra.","Mantén la espalda recta e inclínate ligeramente hacia atrás.","Jala la cuerda hacia los costados, apretando los omóplatos entre sí.","Haz una pausa por un momento en la parte baja del movimiento.","Libera lentamente la tensión y permite que la cuerda vuelva a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0177-CuaWCmC.jpg","gif":"0177-CuaWCmC.gif"},{"id":"2616","n":"Jalón lateral en polea con barra en V","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Siéntate en la máquina de jalón de cable y agarra el accesorio en V con un agarre prono.","Ajusta la almohadilla de rodillas para que tus muslos queden asegurados debajo de ella.","Mantén la espalda recta e inclínate ligeramente hacia atrás.","Jala el accesorio en V hacia la parte superior del pecho manteniendo los codos cerca del cuerpo.","Aprieta los músculos de la espalda en la parte baja del movimiento.","Regresa lentamente el accesorio en V a la posición inicial y repite el número de repeticiones deseado."],"img":"2616-4c9BhzB.jpg","gif":"2616-4c9BhzB.gif"},{"id":"0178","n":"Elevaciones laterales en polea","bp":"shoulders","eq":"cable","tg":"delts","mg":"traps","sm":["traps","triceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta las agarraderas del cable con un agarre prono.","Mantén los brazos rectos y el core activado.","Levanta los brazos hacia los lados hasta que queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0178-goJ6ezq.jpg","gif":"0178-goJ6ezq.gif"},{"id":"0179","n":"Aperturas bajas en polea","bp":"chest","eq":"cable","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Sujeta las agarraderas a las poleas bajas de una máquina de cable y selecciona un peso adecuado.","Ponte de pie en el centro de la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas.","Sujeta las agarraderas con un agarre prono y extiende los brazos hacia los lados, manteniendo una ligera flexión en los codos.","Manteniendo el control, lleva lentamente los brazos hacia adelante con un movimiento amplio, cruzándolos frente al cuerpo.","Haz una pausa por un momento en el punto más alto del movimiento, sintiendo el estiramiento en los músculos del pecho.","Invierte el movimiento y regresa lentamente los brazos a la posición inicial, manteniendo la tensión en los músculos del pecho durante todo el recorrido.","Repite el número de repeticiones deseado."],"img":"0179-FVmZVhk.jpg","gif":"0179-FVmZVhk.gif"},{"id":"0180","n":"Remo sentado bajo en polea","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Siéntate en la máquina con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas.","Sujeta las agarraderas con un agarre prono, con las palmas hacia abajo.","Mantén la espalda recta e inclínate ligeramente hacia adelante, manteniendo una ligera flexión en los codos.","Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí.","Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0180-hvV79Si.jpg","gif":"0180-hvV79Si.gif"},{"id":"1634","n":"Curl de bíceps tumbado en polea","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Coloca una barra recta en una máquina de cable con polea baja.","Túmbate boca arriba en un banco plano con los pies apoyados planos en el suelo.","Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.","Extiende los brazos por completo, manteniendo los codos cerca de los costados.","Manteniendo la parte superior de los brazos inmóvil, exhala y curva la barra hacia los hombros.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"1634-otqIxU4.jpg","gif":"1634-otqIxU4.gif"},{"id":"0182","n":"Curl con agarre cerrado tumbado en polea","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Coloca una barra recta en una máquina de cable con polea baja.","Túmbate boca arriba en un banco plano con los pies apoyados planos en el suelo.","Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.","Extiende los brazos por completo, manteniendo los codos cerca de los costados.","Manteniendo la parte superior de los brazos inmóvil, curva la barra hacia el pecho contrayendo los bíceps.","Haz una pausa breve en la parte alta, apretando los bíceps.","Baja lentamente la barra de vuelta a la posición inicial, extendiendo los brazos por completo.","Repite el número de repeticiones deseado."],"img":"0182-61GrD55.jpg","gif":"0182-61GrD55.gif"},{"id":"0184","n":"Pullover de extensión tumbado en polea (con accesorio de cuerda)","bp":"back","eq":"cable","tg":"lats","mg":"triceps","sm":["triceps","shoulders"],"st":["Sujeta una cuerda a una máquina de cable y coloca la polea en la posición más alta.","Túmbate en un banco con la cabeza orientada hacia la máquina de cable.","Sujeta la cuerda con ambas manos y extiende los brazos rectos por encima del pecho.","Manteniendo los brazos rectos, baja lentamente la cuerda detrás de la cabeza manteniendo el control.","Haz una pausa por un momento en la parte baja y luego sube lentamente la cuerda de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0184-Q2Eu1Ax.jpg","gif":"0184-Q2Eu1Ax.gif"},{"id":"0185","n":"Aperturas tumbado en polea","bp":"chest","eq":"cable","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Sujeta las agarraderas a los cables y túmbate boca arriba en un banco con los pies apoyados planos en el suelo.","Sujeta las agarraderas con las palmas una frente a la otra y los brazos extendidos rectos por encima del pecho.","Manteniendo una ligera flexión en los codos, baja los brazos hacia los lados en un amplio arco hasta sentir un estiramiento en el pecho.","Haz una pausa por un momento y luego aprieta los músculos del pecho para regresar los brazos a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0185-lJJ7Yq8.jpg","gif":"0185-lJJ7Yq8.gif"},{"id":"0186","n":"Extensión de tríceps tumbado en polea v. 2","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Sujeta una agarradera de cuerda a una máquina de cable con polea baja.","Túmbate boca arriba en un banco plano con la cabeza orientada hacia la máquina de cable.","Sujeta la agarradera de cuerda con ambas manos, con las palmas una frente a la otra, y extiende los brazos rectos por encima del pecho.","Manteniendo la parte superior de los brazos inmóvil, baja lentamente la agarradera de cuerda hacia la frente flexionando los codos.","Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0186-uxJcFUU.jpg","gif":"0186-uxJcFUU.gif"},{"id":"0188","n":"Aperturas medias en polea","bp":"chest","eq":"cable","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Sujeta los cables a ambos lados de una máquina de cable a la altura del pecho.","Ponte de pie en el centro de la máquina con un pie ligeramente delante del otro.","Sujeta las agarraderas con un agarre prono y extiende los brazos hacia los lados.","Mantén una ligera flexión en los codos y conserva una leve inclinación hacia adelante.","Activa los músculos del pecho y lleva los brazos hacia adelante con un movimiento amplio.","Haz una pausa por un momento en el centro y luego regresa lentamente los brazos a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0188-xLYSdtg.jpg","gif":"0188-xLYSdtg.gif"},{"id":"0189","n":"Remo a una mano inclinado en polea","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Sujeta la agarradera del cable con una mano, con la palma hacia adentro, y extiende el brazo por completo.","Jala la agarradera del cable hacia el cuerpo, manteniendo el codo cerca del costado, hasta que la mano llegue a la parte baja del pecho.","Haz una pausa por un momento y luego extiende lentamente el brazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"0189-EIsE3u8.jpg","gif":"0189-EIsE3u8.gif"},{"id":"0190","n":"Curl a una mano en polea","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Sujeta la agarradera del cable con un agarre supino, con la palma hacia arriba.","Mantén el codo cerca del costado y curva lentamente el antebrazo hacia el hombro.","Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0190-YTur5nR.jpg","gif":"0190-YTur5nR.gif"},{"id":"1262","n":"Aperturas de pecho declinadas a un brazo con polea","bp":"chest","eq":"cable","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Sujeta una agarradera en D a una máquina de cable con polea baja y coloca el banco en un ángulo declinado.","Túmbate en el banco con la cabeza orientada hacia la máquina y agarra la agarradera con la mano derecha.","Extiende el brazo recto por encima del pecho, manteniendo una ligera flexión en el codo.","Con un movimiento controlado, baja el brazo hacia el lado hasta que la mano quede alineada con el hombro.","Haz una pausa por un momento y luego invierte el movimiento para regresar el brazo a la posición inicial.","Repite el número de repeticiones deseado y luego cambia al brazo izquierdo y repite el ejercicio."],"img":"1262-w4dLzSx.jpg","gif":"1262-w4dLzSx.gif"},{"id":"1263","n":"Aperturas a un brazo con polea sobre balón fitball","bp":"chest","eq":"cable","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.","Sujeta una agarradera del cable con una mano y extiende el brazo hacia el lado, paralelo al suelo.","Mantén el codo ligeramente flexionado y la palma hacia adelante.","Lleva lentamente el brazo a través del cuerpo, apretando los músculos del pecho.","Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"1263-hHy8tQG.jpg","gif":"1263-hHy8tQG.gif"},{"id":"1264","n":"Aperturas inclinadas a un brazo con polea sobre balón fitball","bp":"chest","eq":"cable","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda contra un banco inclinado.","Sujeta una agarradera del cable con una mano, con el brazo extendido y la palma hacia adentro.","Manteniendo una ligera flexión en el codo, baja lentamente el brazo hacia el lado hasta que la mano quede alineada con el hombro.","Haz una pausa por un momento y luego aprieta los músculos del pecho para regresar el brazo a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1264-P14Dz9D.jpg","gif":"1264-P14Dz9D.gif"},{"id":"1265","n":"Press inclinado a un brazo con polea","bp":"chest","eq":"cable","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Ajusta la máquina de cable a una posición de polea baja.","Siéntate en un banco inclinado de espaldas a la máquina de cable.","Sujeta la agarradera con una mano y llévala hasta la altura del hombro.","Coloca los pies firmemente en el suelo y mantén una posición estable.","Empuja la agarradera hacia adelante y hacia arriba, extendiendo el brazo por completo.","Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"1265-GKEH6jj.jpg","gif":"1265-GKEH6jj.gif"},{"id":"1266","n":"Press inclinado a un brazo con polea sobre balón fitball","bp":"chest","eq":"cable","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda contra un banco inclinado.","Sujeta una agarradera del cable con una mano y coloca el brazo en un ángulo de 90 grados con el codo flexionado.","Empuja la agarradera del cable hacia adelante y hacia arriba, extendiendo el brazo por completo.","Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"1266-6t00BsF.jpg","gif":"1266-6t00BsF.gif"},{"id":"0191","n":"Elevaciones laterales inclinadas a un brazo con polea","bp":"chest","eq":"cable","tg":"pectorals","mg":"deltoids","sm":["deltoids","trapezius"],"st":["Ponte de pie con los pies separados a la altura de los hombros, frente a una máquina de cable.","Sujeta la agarradera con una mano y retrocede un paso para crear tensión en el cable.","Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado.","Extiende el brazo hacia el lado, paralelo al suelo, con una ligera flexión en el codo.","Regresa lentamente el brazo a la posición inicial, manteniendo el control durante todo el movimiento.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"0191-dB07vDu.jpg","gif":"0191-dB07vDu.gif"},{"id":"0192","n":"Elevaciones laterales a un brazo con polea","bp":"shoulders","eq":"cable","tg":"delts","mg":"traps","sm":["traps","triceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros, frente a la máquina de cable.","Sujeta la agarradera del cable con una mano, con la palma hacia abajo, y colócate lo suficientemente alejado de la máquina para que haya tensión en el cable.","Mantén el brazo recto y levántalo lentamente hacia el lado hasta que quede paralelo al suelo.","Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"0192-wEulIzp.jpg","gif":"0192-wEulIzp.gif"},{"id":"1633","n":"Curl predicador a un brazo con polea","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ajusta la máquina de cable de modo que la almohadilla para curl en banco scott quede a la altura del pecho.","Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Sujeta la agarradera del cable con un agarre supino y coloca la parte superior del brazo contra la almohadilla del banco scott.","Mantén la espalda recta y el core activado.","Curva lentamente la agarradera del cable hacia el hombro, manteniendo la parte superior del brazo contra la almohadilla.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Baja lentamente la agarradera del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado.","Cambia de brazo y repite el ejercicio."],"img":"1633-eHBlPsa.jpg","gif":"1633-eHBlPsa.gif"},{"id":"1267","n":"Press a un brazo con polea sobre balón fitball","bp":"chest","eq":"cable","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.","Sujeta una agarradera del cable con una mano y coloca el brazo a la altura del pecho, con el codo flexionado.","Coloca la otra mano en la cadera para mantener el equilibrio.","Empuja la agarradera del cable hacia adelante, extendiendo el brazo por completo.","Haz una pausa por un momento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1267-MKIelrR.jpg","gif":"1267-MKIelrR.gif"},{"id":"3563","n":"Jalón a un brazo con polea","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Sujeta una agarradera individual a una máquina de cable con polea alta.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Sujeta la agarradera con un agarre prono y extiende el brazo por completo.","Mantén la espalda recta y el core activado.","Jala la agarradera hacia abajo en dirección al costado, manteniendo el codo cerca del cuerpo.","Haz una pausa por un momento en la parte baja del movimiento, apretando el dorsal.","Suelta lentamente la agarradera de vuelta a la posición inicial.","Repite el número de repeticiones deseado.","Cambia de lado y repite el ejercicio con el otro brazo."],"img":"3563-U5INZY6.jpg","gif":"3563-U5INZY6.gif"},{"id":"1635","n":"Curl predicador inverso a un brazo con polea","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ajusta la máquina de cable de modo que la polea quede en la posición más baja.","Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Sujeta la agarradera del cable con un agarre supino y coloca la parte superior del brazo contra la almohadilla del banco scott.","Mantén la espalda recta y el core activado durante todo el ejercicio.","Curva lentamente el antebrazo hacia el bíceps, manteniendo la parte superior del brazo inmóvil contra la almohadilla.","Haz una pausa por un momento en la parte más alta del movimiento, apretando el bíceps.","Baja lentamente la agarradera del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado.","Cambia de brazo y repite el ejercicio."],"img":"1635-ZXnjcOQ.jpg","gif":"1635-ZXnjcOQ.gif"},{"id":"0193","n":"Remo alto a un brazo con polea espalda recta (de rodillas)","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Sujeta una agarradera a una máquina de cable a la altura de la cintura.","Ponte de rodillas frente a la máquina de cable y agarra la agarradera con una mano.","Mantén la espalda recta y el core activado.","Jala la agarradera hacia el pecho, apretando los omóplatos entre sí.","Haz una pausa breve en la parte alta del movimiento.","Suelta lentamente la agarradera de vuelta a la posición inicial.","Repite el número de repeticiones deseado.","Cambia de lado y repite el ejercicio con el otro brazo."],"img":"0193-WrYPP2g.jpg","gif":"0193-WrYPP2g.gif"},{"id":"1723","n":"Extensión de tríceps a un brazo con polea","bp":"upper arms","eq":"cable","tg":"triceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie frente a una máquina de cable con un accesorio de barra recta a la altura del pecho.","Sujeta la barra con un agarre prono y retrocede un paso para crear tensión en el cable.","Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas.","Mantén la espalda recta y el core activado durante todo el ejercicio.","Comienza con el brazo completamente extendido y perpendicular al suelo.","Manteniendo la parte superior del brazo inmóvil, exhala y empuja la barra hacia abajo hasta que el brazo quede completamente extendido.","Haz una pausa por un momento, luego inhala y regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1723-qRZ5S1N.jpg","gif":"1723-qRZ5S1N.gif"},{"id":"1636","n":"Curl sobre la cabeza con polea","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Sujeta una barra recta a una máquina de cable con polea alta.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.","Mantén los codos cerca de los costados y los brazos superiores quietos.","Exhala y curva la barra hacia la frente, manteniendo la parte superior de los brazos inmóvil.","Haz una pausa por un momento en la parte baja del movimiento, apretando los bíceps.","Inhala y regresa lentamente la barra a la posición inicial, extendiendo los brazos por completo.","Repite el número de repeticiones deseado."],"img":"1636-wDUqY2u.jpg","gif":"1636-wDUqY2u.gif"},{"id":"1637","n":"Curl sobre la cabeza con polea sobre balón fitball","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Siéntate sobre un balón de ejercicio y sujeta la agarradera del cable con un agarre supino.","Extiende los brazos completamente por encima de la cabeza, manteniendo los codos cerca de las orejas.","Curva lentamente el cable hacia la frente, manteniendo la parte superior de los brazos inmóvil.","Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1637-ioTf098.jpg","gif":"1637-ioTf098.gif"},{"id":"0194","n":"Extensión de tríceps sobre la cabeza con polea (con cuerda)","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Sujeta una cuerda a una máquina de cable en una posición alta.","Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.","Sujeta la cuerda con ambas manos, con las palmas una frente a la otra, y lleva las manos por encima de la cabeza.","Mantén la parte superior de los brazos cerca de la cabeza y los codos apuntando hacia adelante.","Baja lentamente la cuerda detrás de la cabeza flexionando los codos.","Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0194-2IxROQ1.jpg","gif":"0194-2IxROQ1.gif"},{"id":"1319","n":"Remo con rotación de palma con polea","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Sujeta una agarradera a una máquina de cable a la altura de la cintura.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Sujeta la agarradera con un agarre prono, con las palmas hacia abajo.","Retrocede un paso para crear tensión en el cable, manteniendo la espalda recta y las rodillas ligeramente flexionadas.","Jala la agarradera hacia el cuerpo, rotando las palmas hacia arriba mientras lo haces.","Aprieta los omóplatos al final del movimiento.","Suelta lentamente la agarradera de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1319-OmQ8w0p.jpg","gif":"1319-OmQ8w0p.gif"},{"id":"0195","n":"Curl predicador con polea","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ajusta la máquina de cable de modo que la almohadilla para curl en banco scott quede a la altura del pecho.","Siéntate en el banco scott y coloca la parte superior de los brazos sobre la almohadilla, agarrando el accesorio del cable con un agarre supino.","Mantén la espalda recta y los codos pegados a los costados.","Curva lentamente el accesorio del cable hacia los hombros, apretando los bíceps en la parte más alta del movimiento.","Haz una pausa por un momento y luego baja lentamente el accesorio del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0195-P2lNrGL.jpg","gif":"0195-P2lNrGL.gif"},{"id":"1268","n":"Press con polea sobre balón fitball","bp":"chest","eq":"cable","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y las rodillas en un ángulo de 90 grados.","Sujeta las agarraderas del cable a la altura del pecho con las palmas hacia abajo y los codos flexionados.","Activa el core y empuja las agarraderas del cable hacia adelante hasta que los brazos queden completamente extendidos.","Haz una pausa por un momento y luego libera lentamente la tensión, regresando las agarraderas del cable a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1268-vAwm6rK.jpg","gif":"1268-vAwm6rK.gif"},{"id":"0196","n":"Pull through con polea (con cuerda)","bp":"upper legs","eq":"cable","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Ponte de pie de espaldas a la máquina de cable con los pies separados a la altura de los hombros.","Agarra el accesorio de cuerda con ambas manos y da un paso hacia adelante, creando tensión en el cable.","Flexiona las caderas y baja la parte superior del cuerpo hasta que quede paralela al suelo, manteniendo la espalda recta.","Activa los glúteos y los isquiotibiales para llevar el cuerpo de vuelta hacia arriba, a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0196-OM46QHm.jpg","gif":"0196-OM46QHm.gif"},{"id":"0198","n":"Jalón al pecho con polea","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Ajusta la máquina de jalón de cable de modo que el asiento quede a una altura cómoda y la almohadilla de rodillas esté asegurada.","Siéntate con la espalda recta y los pies apoyados planos en el suelo.","Sujeta la barra del cable con un agarre prono, un poco más separado que el ancho de los hombros.","Inclínate ligeramente hacia atrás y activa el core.","Jala la barra del cable hacia el pecho, apretando los omóplatos entre sí.","Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0198-RVwzP10.jpg","gif":"0198-RVwzP10.gif"},{"id":"0197","n":"Jalón al pecho con polea agarre ancho","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Ajusta la altura del asiento para que tus muslos queden paralelos al suelo y tus pies queden apoyados planos en el suelo.","Sujeta la barra de jalón con un agarre prono, un poco más separado que el ancho de los hombros.","Siéntate e inclínate ligeramente hacia atrás, manteniendo el pecho elevado y la espalda recta.","Jala la barra hacia el pecho, apretando los omóplatos entre sí.","Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0197-qdRxqCj.jpg","gif":"0197-qdRxqCj.gif"},{"id":"1638","n":"Curl de bíceps con polea alta","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sujeta una barra recta a la máquina de cable en el ajuste más alto.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.","Mantén los codos cerca de los costados y los brazos superiores quietos.","Exhala y curva lentamente la barra hacia los muslos, manteniendo las muñecas rectas.","Haz una pausa por un momento en la parte baja del movimiento, apretando los bíceps.","Inhala y regresa lentamente la barra a la posición inicial, extendiendo los brazos por completo.","Repite el número de repeticiones deseado."],"img":"1638-QTXKWPh.jpg","gif":"1638-QTXKWPh.gif"},{"id":"0201","n":"Extensión de tríceps con polea","bp":"upper arms","eq":"cable","tg":"triceps","mg":"forearms","sm":["forearms"],"st":["Sujeta una barra recta a una máquina de cable con polea alta.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas.","Sujeta la barra con un agarre prono, con las manos separadas a la altura de los hombros.","Mantén los codos cerca de los costados y los brazos superiores quietos.","Exhala y empuja la barra hacia abajo hasta que los codos queden completamente extendidos.","Haz una pausa por un momento, luego inhala y regresa lentamente la barra a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0201-3ZflifB.jpg","gif":"0201-3ZflifB.gif"},{"id":"0199","n":"Extensión de tríceps con polea (brazo recto) v. 2","bp":"back","eq":"cable","tg":"lats","mg":"triceps","sm":["triceps","shoulders"],"st":["Sujeta una barra recta a una máquina de cable con polea alta.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas.","Sujeta la barra con un agarre prono, manteniendo los brazos rectos y las palmas hacia abajo.","Activa el core y mantén la espalda recta mientras exhalas y empujas la barra hacia abajo en dirección a los muslos.","Haz una pausa por un momento en la parte baja y luego regresa lentamente la barra a la posición inicial mientras inhalas.","Repite el número de repeticiones deseado."],"img":"0199-PskORrA.jpg","gif":"0199-PskORrA.gif"},{"id":"0200","n":"Extensión de tríceps con polea (con cuerda)","bp":"upper arms","eq":"cable","tg":"triceps","mg":"forearms","sm":["forearms"],"st":["Sujeta un accesorio de cuerda a una polea alta en una máquina de cable.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas.","Sujeta la cuerda con un agarre prono, con las palmas una frente a la otra.","Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio.","Exhala y empuja la cuerda hacia abajo extendiendo los codos hasta que los brazos queden completamente extendidos.","Haz una pausa por un momento, luego inhala y regresa lentamente a la posición inicial permitiendo que los codos se flexionen.","Repite el número de repeticiones deseado."],"img":"0200-dU605di.jpg","gif":"0200-dU605di.gif"},{"id":"0202","n":"Remo para deltoide posterior con polea (estribos)","bp":"shoulders","eq":"cable","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids","biceps"],"st":["Sujeta un asa de estribo a una polea de cable baja y ponte de pie frente a la máquina.","Sujeta el asa con la mano izquierda y retrocede un paso con el pie derecho, colocando el cuerpo en un ligero ángulo.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.","Con el brazo izquierdo extendido y la palma hacia abajo, jala el asa hacia el pecho retrayendo el omóplato.","Haz una pausa por un momento en la parte más alta del movimiento, apretando el omóplato.","Suelta lentamente el asa de vuelta a la posición inicial y repite el número de repeticiones deseado.","Cambia de lado y repite el ejercicio con el brazo derecho."],"img":"0202-yUdIGNs.jpg","gif":"0202-yUdIGNs.gif"},{"id":"0203","n":"Remo para deltoide posterior con polea (con cuerda)","bp":"shoulders","eq":"cable","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids","biceps"],"st":["Sujeta una agarradera de cuerda a una máquina de cable con polea baja.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Sujeta la agarradera de cuerda con un agarre prono, con las palmas una frente a la otra.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Mantén los codos ligeramente flexionados y jala la cuerda hacia el pecho, apretando los omóplatos entre sí.","Haz una pausa por un momento en la parte más alta del movimiento y luego libera lentamente la tensión, regresando a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0203-wqNPGCg.jpg","gif":"0203-wqNPGCg.gif"},{"id":"0204","n":"Empuje posterior con polea","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders","back"],"st":["Sujeta una agarradera a una máquina de cable con polea baja y ponte de pie de espaldas a la máquina.","Sujeta la agarradera con un agarre prono y extiende los brazos rectos frente a ti.","Manteniendo los codos inmóviles, jala la agarradera de vuelta hacia el cuerpo, apretando los tríceps al final del movimiento.","Regresa lentamente la agarradera a la posición inicial y repite el número de repeticiones deseado."],"img":"0204-c3QQLPi.jpg","gif":"0204-c3QQLPi.gif"},{"id":"0205","n":"Jalón posterior con polea","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Ajusta la máquina de cable de modo que la polea quede en la posición más alta.","Siéntate frente a la máquina con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas.","Sujeta el accesorio del cable con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.","Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el pecho elevado.","Jala el accesorio del cable hacia el pecho, apretando los omóplatos entre sí.","Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente el cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0205-SpsOSXk.jpg","gif":"0205-SpsOSXk.gif"},{"id":"0873","n":"Crunch invertido con polea","bp":"waist","eq":"cable","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Sujeta un cable a una polea baja y túmbate boca arriba sobre un tapete.","Sujeta el cable con ambas manos y extiende los brazos rectos hacia el techo.","Flexiona las rodillas y levanta las piernas, llevando los muslos hacia el pecho.","Mientras mantienes la parte superior del cuerpo estable, curva la pelvis hacia el pecho, levantando las caderas del tapete.","Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0873-RqOtqD7.jpg","gif":"0873-RqOtqD7.gif"},{"id":"0206","n":"Curl inverso con polea","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Coloca una barra recta en una máquina de cable con polea baja.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.","Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio.","Exhala y flexiona la barra hacia los hombros, contrayendo los bíceps.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"0206-eOG0r6v.jpg","gif":"0206-eOG0r6v.gif"},{"id":"2406","n":"Extensión de tríceps con polea agarre inverso (barra EZ) (con arm blaster)","bp":"upper arms","eq":"cable","tg":"triceps","mg":"forearms","sm":["forearms"],"st":["Sujeta una barra recta a la máquina de cable en el ajuste más alto.","Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Sujeta la barra con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros.","Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio.","Activa los tríceps y empuja lentamente la barra hacia abajo hasta que los brazos queden completamente extendidos.","Haz una pausa por un momento en la parte baja y luego regresa lentamente la barra a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2406-ThKP69G.jpg","gif":"2406-ThKP69G.gif"},{"id":"1413","n":"Curl inverso a un brazo con polea","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.","Sujeta la agarradera del cable con un agarre supino, con la palma hacia abajo.","Mantén el codo cerca del costado y curva lentamente el antebrazo hacia el hombro.","Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1413-gVlnLIJ.jpg","gif":"1413-gVlnLIJ.gif"},{"id":"0209","n":"Curl predicador inverso con polea","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ajusta la máquina de cable de modo que la almohadilla para curl en banco scott quede a la altura del pecho.","Siéntate en el banco scott y coloca la parte superior de los brazos sobre la almohadilla, con las palmas hacia abajo y los codos completamente extendidos.","Agarra las agarraderas del cable con un agarre supino, separadas a la altura de los hombros.","Manteniendo la parte superior de los brazos inmóvil, exhala y curva las agarraderas hacia los hombros, contrayendo los bíceps.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Inhala y baja lentamente las agarraderas de vuelta a la posición inicial, extendiendo los codos por completo.","Repite el número de repeticiones deseado."],"img":"0209-IwX5NqK.jpg","gif":"0209-IwX5NqK.gif"},{"id":"0210","n":"Curl de muñeca inverso con polea","bp":"lower arms","eq":"cable","tg":"forearms","mg":"forearms","sm":["forearms","wrists"],"st":["Sujeta un cable a una polea baja y siéntate en un banco frente a la máquina de cable.","Sujeta la agarradera del cable con un agarre prono, con las palmas hacia abajo.","Apoya los antebrazos sobre los muslos, con las muñecas colgando del borde.","Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible.","Haz una pausa por un momento en la parte alta, luego inhala y baja lentamente las muñecas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0210-eYmsEPR.jpg","gif":"0210-eYmsEPR.gif"},{"id":"0207","n":"Extensión de tríceps con polea agarre inverso","bp":"upper arms","eq":"cable","tg":"triceps","mg":"forearms","sm":["forearms"],"st":["Sujeta una barra recta a una máquina de cable con polea alta.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Sujeta la barra con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros.","Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio.","Usando los tríceps, empuja la barra hacia abajo hasta que los brazos queden completamente extendidos y los tríceps contraídos.","Haz una pausa por un momento y luego regresa lentamente la barra a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0207-VjYliFZ.jpg","gif":"0207-VjYliFZ.gif"},{"id":"0208","n":"Remo alto sentado con espalda recta y agarre inverso con polea","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Siéntate frente a la máquina de cable con los pies apoyados planos en el suelo.","Sujeta el accesorio del cable con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros.","Mantén la espalda recta e inclínate ligeramente hacia adelante desde las caderas.","Jala el cable hacia el torso retrayendo los omóplatos y apretando los músculos de la espalda.","Haz una pausa breve en el punto máximo de la contracción, luego suelta lentamente el cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0208-PNtsX17.jpg","gif":"0208-PNtsX17.gif"},{"id":"1320","n":"Remo sentado con poleas cruzadas y cuerda","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Siéntate en la máquina de remo con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas.","Sujeta las cuerdas del cable con un agarre prono, con las palmas una frente a la otra.","Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el core activado.","Jala las cuerdas del cable hacia el pecho, apretando los omóplatos entre sí.","Haz una pausa por un momento en el punto más alto del movimiento, luego libera lentamente la tensión y regresa a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1320-UFGF6gk.jpg","gif":"1320-UFGF6gk.gif"},{"id":"1321","n":"Remo sentado elevado con polea y cuerda","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Siéntate en el asiento elevado frente a la máquina de cable.","Agarra las agarraderas de cuerda con un agarre prono, con las palmas una frente a la otra.","Mantén la espalda recta e inclínate ligeramente hacia atrás, conservando una ligera flexión en las rodillas.","Jala el cable hacia el cuerpo retrayendo los omóplatos y apretando los músculos de la espalda.","Haz una pausa por un momento en la posición de contracción completa.","Libera lentamente la tensión y extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1321-c8oybX6.jpg","gif":"1321-c8oybX6.gif"},{"id":"1322","n":"Remo en banco inclinado con cuerda en polea","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Coloca un banco inclinado a un ángulo de 45 grados y sujeta una máquina de cable a la polea baja.","Sujeta una agarradera de cuerda a la máquina de cable y siéntate en el banco inclinado frente a la máquina.","Agarra la agarradera de cuerda con un agarre prono e inclínate hacia adelante, manteniendo la espalda recta.","Extiende los brazos por completo, jalando la cuerda hacia la parte superior del pecho mientras mantienes los codos cerca del cuerpo.","Aprieta los omóplatos al final del movimiento.","Libera lentamente la tensión y vuelve a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1322-MgKwAAo.jpg","gif":"1322-MgKwAAo.gif"},{"id":"1639","n":"Curl martillo en banco predicador con cuerda en polea","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sujeta un accesorio de cuerda a una máquina de cable con polea baja.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Sujeta la cuerda con un agarre neutro (las palmas una frente a la otra).","Coloca la parte superior de los brazos contra la almohadilla del banco scott, manteniendo los codos ligeramente flexionados.","Manteniendo la parte superior de los brazos inmóvil, exhala y curva la cuerda hacia los hombros contrayendo los bíceps.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y baja lentamente la cuerda de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1639-PcPe0P5.jpg","gif":"1639-PcPe0P5.gif"},{"id":"1724","n":"Extensión de tríceps sobre la cabeza con cuerda en polea alta","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Sujeta una cuerda a una polea alta y ajusta el peso según corresponda.","Ponte de pie de espaldas a la máquina de poleas con los pies separados a la altura de los hombros.","Sujeta la cuerda con ambas manos, con las palmas hacia abajo, y lleva las manos por encima de la cabeza.","Mantén la parte superior de los brazos cerca de la cabeza y perpendicular al suelo.","Baja lentamente la cuerda detrás de la cabeza flexionando los codos.","Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1724-NN8nSNT.jpg","gif":"1724-NN8nSNT.gif"},{"id":"1725","n":"Extensión de tríceps en banco inclinado con cuerda en polea","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Sujeta una cuerda a una polea alta y ajusta el banco inclinado a un ángulo cómodo.","Ponte de pie de espaldas a la polea con los pies separados a la altura de los hombros.","Sujeta la cuerda con un agarre prono y extiende los brazos rectos por encima de la cabeza.","Mantén los codos cerca de la cabeza y la parte superior de los brazos inmóvil durante todo el ejercicio.","Baja la cuerda detrás de la cabeza flexionando los codos hasta que los antebrazos toquen los bíceps.","Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1725-ZujAdR9.jpg","gif":"1725-ZujAdR9.gif"},{"id":"1726","n":"Extensión de tríceps tumbado en el suelo con cuerda en polea","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Sujeta una cuerda a una máquina de cable y colócala en la posición más baja.","Túmbate en el suelo boca arriba, con la cabeza orientada hacia la máquina de cable.","Sujeta la cuerda con ambas manos, con las palmas una frente a la otra, y extiende los brazos rectos hacia el techo.","Mantén la parte superior de los brazos inmóvil y baja lentamente la cuerda hacia la frente, flexionando los codos.","Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1726-U3ffHlY.jpg","gif":"1726-U3ffHlY.gif"},{"id":"1640","n":"Curl martillo a una mano en banco predicador con cuerda en polea","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Sujeta una agarradera de cuerda a una máquina de cable con polea baja.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Sujeta la agarradera de cuerda con un agarre supino, con las palmas hacia arriba.","Coloca la parte superior del brazo contra la almohadilla del banco scott, manteniendo el codo ligeramente flexionado.","Mantén la espalda recta y el core activado durante todo el ejercicio.","Curva lentamente la agarradera de cuerda hacia el hombro, manteniendo la parte superior del brazo inmóvil.","Aprieta el bíceps en la parte más alta del movimiento y luego baja lentamente la agarradera de cuerda de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1640-4hATdoB.jpg","gif":"1640-4hATdoB.gif"},{"id":"1323","n":"Remo sentado con cuerda en polea","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Siéntate en la máquina de remo con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas.","Sujeta las cuerdas del cable con un agarre prono, con las palmas una frente a la otra.","Mantén la espalda recta e inclínate ligeramente hacia adelante, manteniendo una ligera flexión en los codos.","Jala las cuerdas del cable hacia el cuerpo, apretando los omóplatos entre sí.","Haz una pausa por un momento en el punto más alto del movimiento, luego libera lentamente la tensión y regresa a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1323-SJqRxOt.jpg","gif":"1323-SJqRxOt.gif"},{"id":"0211","n":"Giros rusos con polea (en fitball)","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Siéntate sobre un balón de estabilidad con los pies apoyados planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Sujeta la agarradera del cable con ambas manos y extiende los brazos rectos frente a ti.","Inclínate ligeramente hacia atrás manteniendo la espalda recta y el core activado.","Gira el torso hacia la derecha, llevando la agarradera del cable hacia la cadera derecha.","Haz una pausa por un momento y luego gira el torso hacia la izquierda, llevando la agarradera del cable hacia la cadera izquierda.","Continúa alternando los giros el número de repeticiones deseado."],"img":"0211-d9Xaxq6.jpg","gif":"0211-d9Xaxq6.gif"},{"id":"2144","n":"Press de pecho sentado en polea","bp":"chest","eq":"cable","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Ajusta la altura del asiento y las agarraderas del cable a una posición cómoda.","Siéntate en el banco con la espalda recta y los pies apoyados planos en el suelo.","Sujeta las agarraderas del cable con un agarre prono a la altura del hombro.","Empuja las agarraderas hacia adelante y alejándolas del cuerpo, extendiendo los brazos por completo.","Haz una pausa por un momento y luego regresa lentamente las agarraderas a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2144-nIR4Rwl.jpg","gif":"2144-nIR4Rwl.gif"},{"id":"0212","n":"Abdominales sentado en polea","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Siéntate en una máquina de cable con los pies apoyados planos en el suelo y las rodillas flexionadas.","Sujeta la agarradera del cable con ambas manos y colócala detrás de la cabeza.","Activa el abdomen y curva lentamente la parte superior del cuerpo hacia adelante, llevando el pecho hacia las rodillas.","Haz una pausa por un momento en la parte alta y luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0212-8xUv4J7.jpg","gif":"0212-8xUv4J7.gif"},{"id":"1641","n":"Curl de bíceps sentado en polea","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en una máquina de cable con los pies apoyados planos en el suelo y la espalda recta.","Sujeta el accesorio del cable con un agarre supino, con las palmas hacia arriba y los brazos completamente extendidos.","Manteniendo la parte superior de los brazos inmóvil, exhala y curva el accesorio del cable hacia los hombros, contrayendo los bíceps.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"1641-8oYqOt9.jpg","gif":"1641-8oYqOt9.gif"},{"id":"0213","n":"Remo alto sentado en polea (barra en V)","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Siéntate en la máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas.","Sujeta el accesorio en V con un agarre prono, con las palmas una frente a la otra y las manos separadas a la altura de los hombros.","Mantén la espalda recta e inclínate ligeramente hacia adelante desde las caderas.","Jala el accesorio en V hacia el torso retrayendo los omóplatos y apretando los músculos de la espalda.","Haz una pausa por un momento en el punto más alto de la contracción, luego libera lentamente la tensión y regresa a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0213-pwt0pnM.jpg","gif":"0213-pwt0pnM.gif"},{"id":"0214","n":"Remo alterno a una mano sentado en polea","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Siéntate en un banco frente a una máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas.","Sujeta la agarradera con una mano y mantén el brazo completamente extendido frente a ti.","Jala la agarradera hacia el cuerpo, retrayendo el omóplato y manteniendo el codo cerca del costado.","Haz una pausa por un momento en la parte más alta del movimiento, apretando los músculos de la espalda.","Suelta lentamente la agarradera de vuelta a la posición inicial.","Repite con el otro brazo.","Alterna entre los brazos el número de repeticiones deseado."],"img":"0214-vpp9Ku2.jpg","gif":"0214-vpp9Ku2.gif"},{"id":"1642","n":"Curl concentrado a una mano sentado en polea","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco con los pies apoyados planos en el suelo y la espalda recta.","Sujeta una agarradera del cable con una mano y coloca el codo en la parte interna del muslo, justo arriba de la rodilla.","Mantén la parte superior del brazo inmóvil y curva la agarradera del cable hacia el hombro mientras exhalas.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Baja lentamente la agarradera del cable de vuelta a la posición inicial mientras inhalas.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1642-rZ80Gbp.jpg","gif":"1642-rZ80Gbp.gif"},{"id":"1643","n":"Curl sobre la cabeza sentado en polea","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Siéntate en un banco frente a la máquina de cable con los pies apoyados planos en el suelo.","Sujeta el accesorio del cable con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros.","Mantén la parte superior de los brazos inmóvil y los codos cerca de los costados.","Exhala y flexiona el accesorio del cable hacia los hombros, contrayendo los bíceps.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"1643-DpWMFP5.jpg","gif":"1643-DpWMFP5.gif"},{"id":"0215","n":"Elevaciones laterales posteriores sentado en polea","bp":"shoulders","eq":"cable","tg":"delts","mg":"traps","sm":["traps","rhomboids"],"st":["Siéntate en un banco frente a la máquina de cable con los pies apoyados planos en el suelo.","Sujeta las agarraderas del cable con un agarre prono y extiende los brazos rectos frente a ti.","Manteniendo los brazos rectos, levántalos lentamente hacia los lados hasta que queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0215-x825CZm.jpg","gif":"0215-x825CZm.gif"},{"id":"0861","n":"Remo sentado con polea","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Siéntate en la máquina de remo con cable con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas.","Sujeta las agarraderas con un agarre prono, manteniendo la espalda recta y los hombros relajados.","Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí.","Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0861-fUBheHs.jpg","gif":"0861-fUBheHs.gif"},{"id":"0216","n":"Rotación interna de hombro sentado en polea","bp":"shoulders","eq":"cable","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","triceps"],"st":["Siéntate en un banco o silla frente a la máquina de cable con los pies apoyados planos en el suelo.","Sujeta la agarradera del cable con el brazo extendido recto frente a ti, paralelo al suelo.","Mantén el codo ligeramente flexionado y los omóplatos retraídos hacia atrás y hacia abajo.","Rota lentamente el brazo hacia adentro, llevando la agarradera del cable hacia el centro del cuerpo.","Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"0216-YPoVrBi.jpg","gif":"0216-YPoVrBi.gif"},{"id":"2399","n":"Giros de torso sentado en polea","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Siéntate en una máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas.","Sujeta la agarradera del cable con ambas manos y extiende los brazos rectos frente a ti.","Manteniendo el core activado, rota lentamente el torso hacia un lado, jalando el cable a través del cuerpo.","Haz una pausa por un momento al final del rango de movimiento y luego rota lentamente de vuelta a la posición inicial.","Repite del otro lado.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"2399-UEjSrKI.jpg","gif":"2399-UEjSrKI.gif"},{"id":"0218","n":"Remo sentado con agarre ancho en polea","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Siéntate en la máquina de remo con cable con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas.","Sujeta la agarradera con un agarre prono amplio, palmas hacia abajo.","Mantén la espalda recta e inclínate ligeramente hacia adelante desde las caderas.","Jala la agarradera hacia la parte baja del pecho, apretando los omóplatos entre sí.","Haz una pausa por un momento en el punto más alto de la contracción.","Suelta lentamente la agarradera de vuelta a la posición inicial, extendiendo los brazos por completo.","Repite el número de repeticiones deseado."],"img":"0218-qcY50ZD.jpg","gif":"0218-qcY50ZD.gif"},{"id":"0219","n":"Press militar en polea","bp":"shoulders","eq":"cable","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Ajusta la máquina de cable de modo que las agarraderas queden a la altura del hombro.","Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.","Sujeta las agarraderas con un agarre prono y llévalas hasta la altura del hombro, con los codos flexionados y apuntando hacia afuera.","Empuja las agarraderas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza.","Haz una pausa por un momento en la parte alta y luego baja lentamente las agarraderas de vuelta a la altura del hombro.","Repite el número de repeticiones deseado."],"img":"0219-PzQanLE.jpg","gif":"0219-PzQanLE.gif"},{"id":"0220","n":"Encogimientos en polea","bp":"back","eq":"cable","tg":"traps","mg":"shoulders","sm":["shoulders"],"st":["Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Sujeta las agarraderas del cable con un agarre prono y deja que los brazos cuelguen frente a ti.","Manteniendo los brazos rectos, encoge los hombros hacia las orejas.","Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0220-Eg98Ft9.jpg","gif":"0220-Eg98Ft9.gif"},{"id":"0222","n":"Flexión lateral en polea","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta la agarradera del cable con una mano.","Mantén la espalda recta y el core activado.","Flexiona lentamente la cintura hacia un lado, bajando la agarradera del cable hacia la rodilla.","Haz una pausa breve y luego vuelve a la posición inicial.","Repite del otro lado.","Alterna los lados durante el número de repeticiones deseado."],"img":"0222-wPypxFY.jpg","gif":"0222-wPypxFY.gif"},{"id":"0221","n":"Abdominales laterales en polea (con bosu)","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando la agarradera del cable con una mano.","Coloca la otra mano en la cadera.","Activa el core y flexiona lentamente la cintura hacia el lado en que sujetas el cable, manteniendo la espalda recta.","Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"0221-qatbkEd.jpg","gif":"0221-qatbkEd.gif"},{"id":"0223","n":"Abdominales laterales en polea","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Coloca un mango de cable en una polea baja y ponte de pie de lado a la máquina.","Agarra el mango con la mano más alejada de la máquina y coloca la otra mano en tu cadera.","Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas.","Con el abdomen activado, flexiona la cintura hacia el lado, bajando el codo hacia la cadera.","Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"0223-q2ADGqV.jpg","gif":"0223-q2ADGqV.gif"},{"id":"1717","n":"Remo en sentadilla en polea (con cuerda)","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Sujeta una cuerda a una máquina de cable a la altura de la cintura.","Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.","Agarra la cuerda con un agarre prono, con las manos separadas a la altura de los hombros.","Activa el core y tira de la cuerda hacia tu cuerpo, apretando los omóplatos entre sí.","Mantén los codos cerca del cuerpo y continúa tirando hasta que las manos lleguen a tu pecho.","Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente la cuerda y extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1717-f7fnAIB.jpg","gif":"1717-f7fnAIB.gif"},{"id":"1644","n":"Curl de bíceps en sentadilla en polea","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Coloca un mango de cable en el ajuste más bajo de una máquina de cable.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Sujeta el mango del cable con un agarre supino, con las palmas hacia arriba y los brazos completamente extendidos.","Baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y las rodillas detrás de las puntas de los pies.","Mientras te agachas, flexiona el mango del cable hacia los hombros, manteniendo los codos cerca de los costados.","Haz una pausa breve en la parte alta del movimiento, apretando los bíceps.","Baja lentamente el mango del cable de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"1644-3XFdb1Z.jpg","gif":"1644-3XFdb1Z.gif"},{"id":"0224","n":"Curl de muñeca inverso de pie en polea","bp":"lower arms","eq":"cable","tg":"forearms","mg":"biceps","sm":["biceps","brachialis"],"st":["Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.","Sujeta el mango del cable con un agarre prono, con las palmas hacia abajo.","Mantén los brazos rectos y los codos cerca de los costados.","Flexiona lentamente las muñecas hacia arriba, llevando el mango del cable hacia tu cuerpo.","Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0224-VhX2JdE.jpg","gif":"0224-VhX2JdE.gif"},{"id":"1375","n":"Elevación de talones de pie en polea","bp":"lower legs","eq":"cable","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.","Sujétate de los mangos de la máquina de cable o coloca una correa de tobillo de cable en tus tobillos.","Levanta los talones del suelo extendiendo los tobillos lo más alto posible.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1375-yl2IYyy.jpg","gif":"1375-yl2IYyy.gif"},{"id":"0225","n":"Aperturas inversas altas cruzadas de pie en polea","bp":"shoulders","eq":"cable","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids","rear deltoids"],"st":["Coloca un mango en D en cada lado de una máquina de cable a la altura de los hombros.","Ponte de pie en el medio de la máquina de cable con los pies separados a la altura de los hombros.","Agarra los mangos con un agarre prono y extiende los brazos hacia los lados, con las palmas hacia adelante.","Mantén una ligera flexión en los codos y conserva la espalda recta durante todo el ejercicio.","Activa los músculos de los hombros y aprieta los omóplatos entre sí mientras tiras de los mangos hacia la parte delantera de tu cuerpo.","Haz una pausa breve en el punto máximo del movimiento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0225-P5p0j8B.jpg","gif":"0225-P5p0j8B.gif"},{"id":"0226","n":"Abdominales de pie en polea","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Coloca un mango de cable en una polea alta y ponte de pie de espaldas a la máquina.","Sujeta el mango con ambas manos y colócalo detrás de la cabeza, manteniendo los codos flexionados.","Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Con el abdomen activado, exhala y flexiona el torso hacia las rodillas, llevando los codos hacia los muslos.","Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0226-jpgqxiS.jpg","gif":"0226-jpgqxiS.gif"},{"id":"0874","n":"Abdominales de pie en polea (con cuerda)","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Sujeta una cuerda a una máquina de cable a la altura del pecho.","Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.","Sujeta la cuerda con ambas manos y llévala detrás de la cabeza, manteniendo los codos flexionados.","Activa el abdomen y flexiona lentamente el torso hacia adelante, llevando los codos hacia las rodillas.","Haz una pausa por un momento en la parte más alta del movimiento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0874-XU3ePuv.jpg","gif":"0874-XU3ePuv.gif"},{"id":"0227","n":"Aperturas de pie en polea","bp":"chest","eq":"cable","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Coloca los mangos en los cables a la altura del pecho.","Ponte de pie con los pies separados a la altura de los hombros, de espaldas a la máquina de cable.","Agarra los mangos con un agarre prono, con las palmas hacia adelante.","Da un paso adelante para crear tensión en los cables.","Mantén el core activado y la espalda recta durante todo el ejercicio.","Con una ligera flexión en los codos, lleva lentamente los brazos hacia adelante y júntalos frente al pecho.","Aprieta los músculos del pecho en el punto máximo del movimiento.","Invierte lentamente el movimiento, regresando los brazos a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0227-Pr9Rhf4.jpg","gif":"0227-Pr9Rhf4.gif"},{"id":"0228","n":"Extensión de cadera de pie en polea","bp":"upper legs","eq":"cable","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Sujeta un cable a una polea baja y ponte de pie de espaldas a la máquina.","Coloca el cable alrededor de tu tobillo y ponte de pie con los pies separados a la altura de los hombros.","Mantén el core activado y la espalda recta durante todo el ejercicio.","Extiende lentamente la pierna hacia atrás, apretando los glúteos en la parte alta del movimiento.","Haz una pausa breve y luego vuelve a la posición inicial.","Repite el número de repeticiones deseado.","Cambia de lado y repite con la otra pierna."],"img":"0228-Kpajagk.jpg","gif":"0228-Kpajagk.gif"},{"id":"0229","n":"Curl interno de pie en polea","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.","Agarra el mango del cable con un agarre supino, con las palmas hacia arriba.","Mantén los codos cerca de los costados y los brazos superiores quietos.","Exhala y flexiona el mango del cable hacia los hombros, contrayendo los bíceps.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Inhala y baja lentamente el mango del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0229-YwnI4ja.jpg","gif":"0229-YwnI4ja.gif"},{"id":"0230","n":"Elevaciones de pie en polea","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Sujeta el mango del cable con ambas manos y colócalo a la altura de la cintura.","Activa el core y mantén la espalda recta durante todo el ejercicio.","Manteniendo los brazos rectos, exhala y eleva el mango del cable hacia el hombro opuesto, rotando el torso.","Haz una pausa breve en la parte alta, luego inhala y baja lentamente el mango del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"0230-qFpAkpP.jpg","gif":"0230-qFpAkpP.gif"},{"id":"0231","n":"Extensión de tríceps a una mano de pie en polea","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros, frente a la máquina de cable.","Sujeta el mango del cable con la mano derecha, con la palma hacia abajo, y coloca el brazo completamente extendido y paralelo al suelo.","Mantén el codo quieto y cerca del cuerpo.","Flexiona lentamente el codo, bajando el mango del cable hacia la parte de atrás de la cabeza.","Haz una pausa breve en la parte baja del movimiento, luego extiende el brazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado y realiza el ejercicio con el brazo izquierdo."],"img":"0231-sYCcnon.jpg","gif":"0231-sYCcnon.gif"},{"id":"1376","n":"Elevación de talón a una pierna de pie en polea","bp":"lower legs","eq":"cable","tg":"calves","mg":"ankles","sm":["ankles","feet"],"st":["Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.","Sujétate de la máquina de cable para apoyarte.","Levanta una pierna del suelo y equilíbrate sobre la otra pierna.","Levanta lentamente el talón del suelo, elevando el cuerpo sobre las puntas de los pies.","Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."],"img":"1376-fgc9Xdl.jpg","gif":"1376-fgc9Xdl.gif"},{"id":"0232","n":"Jalón de pie en polea (con cuerda)","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Sujeta una cuerda a la máquina de cable en el ajuste más alto.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Agarra la cuerda con un agarre prono, con las palmas hacia abajo.","Mantén la espalda recta y el core activado durante todo el ejercicio.","Tira de la cuerda hacia abajo, hacia los muslos, apretando los bíceps.","Haz una pausa breve en la parte baja, luego suelta lentamente la cuerda hacia arriba.","Repite el número de repeticiones deseado."],"img":"0232-CvPn9WV.jpg","gif":"0232-CvPn9WV.gif"},{"id":"0233","n":"Remo para deltoides posterior de pie en polea (con cuerda)","bp":"shoulders","eq":"cable","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids","biceps"],"st":["Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.","Sujeta el accesorio del cable con ambas manos, con las palmas una frente a la otra, y retrocede un paso para crear tensión en el cable.","Mantén la espalda recta y el core activado.","Tira del cable hacia tu cuerpo, apretando los omóplatos entre sí.","Haz una pausa breve en el punto máximo del movimiento, luego suelta lentamente el cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0233-ZfyAGhK.jpg","gif":"0233-ZfyAGhK.gif"},{"id":"1727","n":"Extensión de tríceps sobre la cabeza a una mano con polea, de pie y agarre inverso","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Ponte de pie de espaldas a la máquina de cable con los pies separados a la altura de los hombros.","Sujeta el mango del cable con un agarre supino y extiende el brazo por encima de la cabeza, manteniendo el codo cerca de la cabeza.","Mantén el brazo superior quieto y baja lentamente el mango del cable detrás de la cabeza flexionando el codo.","Haz una pausa breve en la parte baja, luego extiende el brazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1727-i11JWU7.jpg","gif":"1727-i11JWU7.gif"},{"id":"0234","n":"Remo de pie en polea (barra en V)","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Agarra el accesorio en V con un agarre prono, con las palmas hacia abajo.","Mantén la espalda recta y el core activado.","Tira del accesorio en V hacia tu cuerpo, apretando los omóplatos entre sí.","Haz una pausa por un momento en el punto más alto del movimiento, luego libera lentamente la tensión y regresa a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0234-4f8RXP8.jpg","gif":"0234-4f8RXP8.gif"},{"id":"0235","n":"Rotación externa de hombros de pie en polea","bp":"shoulders","eq":"cable","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","trapezius"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta el mango del cable con el brazo extendido frente a ti, paralelo al suelo.","Mantén el codo ligeramente flexionado y los omóplatos retraídos hacia atrás.","Rota lentamente el brazo hacia afuera, alejándolo de tu cuerpo, manteniendo el codo en la misma posición.","Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0235-FWdVhcW.jpg","gif":"0235-FWdVhcW.gif"},{"id":"0236","n":"Remo con giro de pie en polea (barra en V)","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Coloca un accesorio en V en una máquina de cable a la altura del pecho.","Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Agarra el accesorio en V con un agarre prono, con las palmas hacia abajo.","Da un paso atrás para crear tensión en el cable.","Mantén la espalda recta y el core activado durante todo el ejercicio.","Tira del accesorio en V hacia tu torso retrayendo los omóplatos y flexionando los codos.","Mientras tiras, gira el torso hacia un lado, apretando los omóplatos entre sí.","Haz una pausa breve en la parte alta del movimiento, sintiendo la contracción en la parte alta de la espalda.","Suelta lentamente la tensión y regresa a la posición inicial, deshaciendo el giro del torso.","Repite el movimiento el número de repeticiones deseado, alternando la dirección del giro en cada repetición."],"img":"0236-JOZhu2h.jpg","gif":"0236-JOZhu2h.gif"},{"id":"1269","n":"Cruces de poleas altas de pie","bp":"chest","eq":"cable","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Ponte de pie en el medio de una máquina de cable con los pies separados a la altura de los hombros.","Sujeta los mangos de los cables con las palmas hacia abajo y los brazos extendidos hacia los lados.","Manteniendo los brazos rectos, junta las manos frente a tu cuerpo, cruzándolas una sobre la otra.","Haz una pausa breve, luego regresa lentamente a la posición inicial, manteniendo los brazos extendidos.","Repite el número de repeticiones deseado."],"img":"1269-UKWTJWR.jpg","gif":"1269-UKWTJWR.gif"},{"id":"0238","n":"Jalón con brazos extendidos en polea","bp":"back","eq":"cable","tg":"lats","mg":"shoulders","sm":["shoulders","biceps"],"st":["Coloca una barra recta en la polea alta de una máquina de cable.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Sujeta la barra con un agarre prono, manteniendo los brazos rectos y las palmas hacia abajo.","Activa los dorsales y tira de la barra hacia abajo, hacia los muslos, manteniendo los brazos rectos durante todo el movimiento.","Haz una pausa por un momento en la parte baja y luego regresa lentamente la barra a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0238-x69MAlq.jpg","gif":"0238-x69MAlq.gif"},{"id":"0237","n":"Jalón con brazos extendidos en polea (con cuerda)","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Sujeta una cuerda a la máquina de cable en el ajuste más alto.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Agarra la cuerda con ambas manos, con las palmas hacia abajo.","Extiende completamente los brazos frente a ti, manteniendo los codos ligeramente flexionados.","Activa los dorsales y tira lentamente de la cuerda hacia abajo, hacia los muslos, manteniendo los brazos rectos.","Haz una pausa por un momento en la parte inferior, luego suelta lentamente la tensión y regresa a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0237-DT14T9T.jpg","gif":"0237-DT14T9T.gif"},{"id":"0239","n":"Remo sentado en polea con espalda recta","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","forearms","shoulders"],"st":["Siéntate en la máquina de remo con cable con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas.","Agarra los mangos del cable con un agarre prono, con las palmas hacia abajo.","Mantén la espalda recta e inclínate ligeramente hacia adelante desde las caderas.","Tira de los mangos del cable hacia tu cuerpo, apretando los omóplatos entre sí.","Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0239-Tq6gbK6.jpg","gif":"0239-Tq6gbK6.gif"},{"id":"0240","n":"Aperturas inversas en polea en supinación","bp":"shoulders","eq":"cable","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Coloca un mango en D en una máquina de cable con polea baja y túmbate boca abajo en un banco plano.","Agarra el mango en D con cada mano, con las palmas hacia abajo, y extiende los brazos frente a ti.","Manteniendo los brazos rectos, levántalos hacia los lados hasta que estén paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0240-PQcUlDi.jpg","gif":"0240-PQcUlDi.gif"},{"id":"2464","n":"Remo kayak de Thibaudeau en polea","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Coloca un mango de cable en una polea baja y siéntate frente a la máquina con los pies planos en el suelo.","Agarra el mango con la mano derecha y extiende completamente el brazo, manteniendo una ligera flexión en el codo.","Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el abdomen activado.","Tira del mango hacia tu torso retrayendo el omóplato y flexionando el codo, manteniendo el brazo cerca del cuerpo.","Aprieta los músculos de la espalda en la parte alta del movimiento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado y realiza el ejercicio con el brazo izquierdo."],"img":"2464-ZgwWBoC.jpg","gif":"2464-ZgwWBoC.gif"},{"id":"0241","n":"Extensión de tríceps en polea (barra en V)","bp":"upper arms","eq":"cable","tg":"triceps","mg":"forearms","sm":["forearms"],"st":["Coloca un accesorio en V en la máquina de cable en el ajuste más alto.","Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Agarra el accesorio en V con un agarre prono, con las palmas hacia abajo y las manos separadas a la altura de los hombros.","Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio.","Activa los tríceps y exhala mientras empujas el accesorio en V hacia abajo hasta que los brazos estén completamente extendidos.","Haz una pausa breve en la parte baja del movimiento, apretando los tríceps.","Inhala mientras regresas lentamente el accesorio en V a la posición inicial, manteniendo el control.","Repite el número de repeticiones deseado."],"img":"0241-gAwDzB3.jpg","gif":"0241-gAwDzB3.gif"},{"id":"2405","n":"Extensión de tríceps en polea (barra en V) (con arm blaster)","bp":"upper arms","eq":"cable","tg":"triceps","mg":"forearms","sm":["forearms"],"st":["Coloca un accesorio en V en la máquina de cable en el ajuste más alto.","Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.","Agarra el accesorio en V con un agarre prono, con las palmas hacia abajo y las manos separadas a la altura de los hombros.","Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio.","Activa los tríceps y exhala mientras empujas el accesorio en V hacia abajo hasta que los brazos estén completamente extendidos.","Haz una pausa breve en la parte baja del movimiento, apretando los tríceps.","Inhala mientras regresas lentamente el accesorio en V a la posición inicial, manteniendo el control.","Repite el número de repeticiones deseado."],"img":"2405-OxJk1fg.jpg","gif":"2405-OxJk1fg.gif"},{"id":"0242","n":"Crunch inverso con rodillas flexionadas en polea","bp":"waist","eq":"cable","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Sujeta un cable a una polea baja y túmbate boca arriba sobre una esterilla.","Sujeta el cable con ambas manos y extiende los brazos rectos por encima del pecho.","Flexiona las rodillas y levanta las piernas, llevando las rodillas hacia el pecho.","Al mismo tiempo, eleva la pelvis hacia el pecho, levantando las caderas del suelo.","Haz una pausa breve en la parte alta, luego baja lentamente las piernas y las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0242-TXtXc84.jpg","gif":"0242-TXtXc84.gif"},{"id":"0243","n":"Giro de tronco en polea","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Ponte de pie con los pies separados a la altura de los hombros, frente a la máquina de cable.","Sujeta el mango del cable con ambas manos frente al pecho, manteniendo los brazos ligeramente flexionados.","Activa el core y gira el torso hacia la derecha, tirando del cable a través de tu cuerpo.","Haz una pausa breve al final del movimiento, sintiendo la contracción en el abdomen y los oblicuos.","Regresa lentamente a la posición inicial, resistiendo la tracción del cable.","Repite el movimiento hacia el lado izquierdo.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0243-aVs3BR3.jpg","gif":"0243-aVs3BR3.gif"},{"id":"0862","n":"Giro de tronco en polea (arriba-abajo)","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Ponte de pie con los pies separados a la altura de los hombros, frente a la máquina de cable.","Sujeta el mango del cable con ambas manos frente al pecho, manteniendo los brazos ligeramente flexionados.","Activa el core y gira lentamente el torso hacia un lado, manteniendo las caderas y las piernas estables.","Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.","Repite el giro hacia el lado opuesto.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0862-fhZQPlV.jpg","gif":"0862-fhZQPlV.gif"},{"id":"0244","n":"Tracción con giro en polea","bp":"back","eq":"cable","tg":"lats","mg":"shoulders","sm":["shoulders","biceps"],"st":["Coloca un mango de cable en una polea baja y ponte de pie frente a la máquina.","Agarra el mango con la mano izquierda y aléjate de la máquina, extendiendo completamente el brazo.","Coloca los pies separados a la altura de los hombros, con las rodillas ligeramente flexionadas.","Mantén la espalda recta y el core activado durante todo el ejercicio.","Tira del mango hacia tu cuerpo, rotando el torso hacia la derecha al hacerlo.","Aprieta los músculos de la espalda al final del movimiento.","Regresa lentamente a la posición inicial, manteniendo la tensión en el cable.","Repite el número de repeticiones deseado, luego cambia de lado y realiza el ejercicio con la mano derecha."],"img":"0244-zCgxPbV.jpg","gif":"0244-zCgxPbV.gif"},{"id":"1645","n":"Curl de bíceps a dos manos en banco inclinado con polea","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco inclinado con la espalda apoyada en el respaldo y los pies planos en el suelo.","Agarra los mangos del cable con un agarre supino, con las palmas hacia arriba y los brazos completamente extendidos.","Manteniendo los brazos superiores quietos, exhala y flexiona los mangos hacia los hombros mientras contraes los bíceps.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Inhala y baja lentamente los mangos de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"1645-H9y3Dkr.jpg","gif":"1645-H9y3Dkr.gif"},{"id":"1728","n":"Patada de tríceps a dos manos en polea","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta el mango del cable en cada mano con las palmas hacia adentro y los brazos flexionados en un ángulo de 90 grados.","Manteniendo los brazos superiores quietos, extiende los antebrazos hacia atrás hasta que los brazos estén completamente extendidos.","Haz una pausa por un momento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1728-vvNjDJS.jpg","gif":"1728-vvNjDJS.gif"},{"id":"0245","n":"Jalón con agarre supino en polea","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Ajusta la máquina de cable de modo que la barra de jalón quede a una altura por encima de tu cabeza.","Siéntate y agarra la barra de jalón con un agarre supino, con las manos un poco más separadas que el ancho de los hombros.","Mantén la espalda recta e inclínate ligeramente hacia atrás.","Jala la barra hacia el pecho, apretando los omóplatos entre sí.","Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0245-xBYcQHj.jpg","gif":"0245-xBYcQHj.gif"},{"id":"1270","n":"Cruces de poleas para pecho superior","bp":"chest","eq":"cable","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Coloca los mangos en los cables a la altura del pecho.","Ponte de pie en el centro de la máquina de cable con un pie ligeramente delante del otro.","Sujeta las agarraderas con las palmas hacia abajo y los brazos extendidos hacia los lados.","Mantén una ligera flexión en los codos y activa el core.","Tira de los cables juntos frente al pecho, cruzándolos uno sobre el otro.","Aprieta los músculos del pecho en el punto máximo del movimiento.","Suelta lentamente los cables de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1270-j7XMAyn.jpg","gif":"1270-j7XMAyn.gif"},{"id":"1324","n":"Remo en polea alta","bp":"back","eq":"cable","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Sujeta una barra recta a una máquina de cable a la altura del pecho.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.","Mantén la espalda recta y el core activado.","Jala la barra hacia la parte superior del pecho, apretando los omóplatos entre sí.","Haz una pausa breve en la parte alta del movimiento.","Suelta lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1324-PQStVXH.jpg","gif":"1324-PQStVXH.gif"},{"id":"0246","n":"Remo vertical en polea","bp":"shoulders","eq":"cable","tg":"delts","mg":"traps","sm":["traps","biceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta el accesorio del cable con un agarre prono.","Mantén la espalda recta y el core activado durante todo el ejercicio.","Tira del accesorio del cable directamente hacia arriba, hacia tu barbilla, guiando con los codos.","Haz una pausa breve en la parte alta, apretando los omóplatos entre sí.","Baja lentamente el accesorio del cable de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0246-cALKspW.jpg","gif":"0246-cALKspW.gif"},{"id":"1325","n":"Jalón al cuello con agarre ancho en polea","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Ajusta la máquina de cable de modo que la barra de jalón quede a una altura por encima de tu cabeza.","Siéntate y agarra la barra de jalón con un agarre prono amplio.","Mantén la espalda recta y el pecho elevado mientras te reclinas ligeramente hacia atrás.","Jala la barra hacia la parte superior del pecho, apretando los omóplatos entre sí.","Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1325-CmEr4pM.jpg","gif":"1325-CmEr4pM.gif"},{"id":"0247","n":"Curl de muñeca en polea","bp":"lower arms","eq":"cable","tg":"forearms","mg":"biceps","sm":["biceps","brachialis"],"st":["Coloca una barra recta en una máquina de cable con polea baja.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Sujeta la barra con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros.","Apoya los antebrazos en un banco o almohadilla, con las muñecas colgando del borde.","Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible.","Haz una pausa breve en la parte alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0247-LrV4s90.jpg","gif":"0247-LrV4s90.gif"},{"id":"1407","n":"Estiramiento de gemelos con empuje y manos contra la pared","bp":"lower legs","eq":"body weight","tg":"calves","mg":"hamstrings","sm":["hamstrings"],"st":["Ponte de pie frente a una pared con los pies separados a la altura de las caderas.","Coloca las manos contra la pared a la altura de los hombros.","Da un paso atrás con un pie, manteniendo el talón en el suelo y la pierna recta.","Flexiona ligeramente la rodilla delantera e inclínate hacia adelante, sintiendo un estiramiento en la pantorrilla.","Mantén el estiramiento durante 20-30 segundos.","Cambia de pierna y repite el estiramiento."],"img":"1407-PzNxakt.jpg","gif":"1407-PzNxakt.gif"},{"id":"1377","n":"Estiramiento de gemelos con manos contra la pared","bp":"lower legs","eq":"body weight","tg":"calves","mg":"hamstrings","sm":["hamstrings"],"st":["Ponte de pie frente a una pared con los pies separados a la altura de las caderas.","Coloca las manos contra la pared a la altura de los hombros.","Da un paso atrás con el pie derecho, manteniendo el talón en el suelo y la pierna recta.","Flexiona la rodilla izquierda e inclínate hacia adelante, manteniendo la pierna de atrás recta y el talón en el suelo.","Mantén el estiramiento durante 20-30 segundos.","Cambia de pierna y repite el estiramiento."],"img":"1377-m0tCHqc.jpg","gif":"1377-m0tCHqc.gif"},{"id":"1378","n":"Estiramiento de gemelos con cuerda","bp":"lower legs","eq":"rope","tg":"calves","mg":"hamstrings","sm":["hamstrings"],"st":["Ponte de pie frente a una pared u objeto firme con los pies separados a la altura de las caderas.","Sujeta los extremos de la cuerda con cada mano y coloca el centro de la cuerda alrededor de la planta del pie derecho.","Da un paso atrás con el pie izquierdo, manteniendo el talón en el suelo y la pierna recta.","Inclínate hacia adelante, manteniendo la espalda recta, y tira suavemente de la cuerda para estirar la pantorrilla.","Mantén el estiramiento durante 20-30 segundos, luego suelta.","Repite con la otra pierna."],"img":"1378-1LVFcEn.jpg","gif":"1378-1LVFcEn.gif"},{"id":"0248","n":"Remo tumbado con barra EZ","bp":"back","eq":"barbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Coloca una barra en el suelo y túmbate boca abajo en un banco con el pecho justo en el borde.","Estírate hacia abajo y agarra la barra con un agarre prono, un poco más ancho que el ancho de los hombros.","Con las piernas rectas y los pies en el suelo, levanta la barra del suelo extendiendo los brazos.","Tira de la barra hacia el pecho, juntando los omóplatos.","Baja la barra de vuelta a la posición inicial y repite el número de repeticiones deseado."],"img":"0248-R5swFnc.jpg","gif":"0248-R5swFnc.gif"},{"id":"2963","n":"Elevación de piernas rectas en silla romana","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Siéntate en la silla romana con la espalda apoyada en el respaldo y los antebrazos apoyados en las almohadillas.","Mantén la parte superior del cuerpo estable y la espalda recta.","Activa el abdomen y levanta las piernas frente a ti, manteniéndolas rectas.","Continúa levantando hasta que las piernas estén paralelas al suelo o tan alto como puedas llegar cómodamente.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2963-weoDEpH.jpg","gif":"2963-weoDEpH.gif"},{"id":"1548","n":"Estiramiento de pierna extendida en silla","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hamstrings","sm":["hamstrings","calves"],"st":["Siéntate al borde de una silla con la espalda recta y los pies planos en el suelo.","Extiende una pierna recta frente a ti, manteniendo el talón en el suelo.","Inclínate ligeramente hacia adelante, sintiendo un estiramiento en los cuádriceps.","Mantén esta posición durante 20-30 segundos.","Cambia de pierna y repite el estiramiento."],"img":"1548-xGgAGPm.jpg","gif":"1548-xGgAGPm.gif"},{"id":"1271","n":"Estiramiento de pectoral y parte frontal del hombro","bp":"chest","eq":"body weight","tg":"pectorals","mg":"deltoids","sm":["deltoids"],"st":["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.","Extiende los brazos rectos frente a ti a la altura de los hombros.","Cruza los brazos frente a tu cuerpo, con el brazo derecho sobre el brazo izquierdo.","Entrelaza los dedos y presiona las palmas entre sí.","Aprieta suavemente los omóplatos entre sí y empuja las manos hacia adelante, sintiendo un estiramiento en el pecho y la parte delantera de los hombros.","Mantén el estiramiento durante 20-30 segundos, luego suelta.","Repite el número de repeticiones deseado."],"img":"1271-Uto7l43.jpg","gif":"1271-Uto7l43.gif"},{"id":"0251","n":"Fondos de pecho","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Colócate en las barras paralelas con los brazos completamente extendidos y el cuerpo recto.","Baja el cuerpo flexionando los codos hasta que los hombros queden por debajo de los codos.","Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."],"img":"0251-9WTm7dq.jpg","gif":"0251-9WTm7dq.gif"},{"id":"1430","n":"Fondos de pecho (en estación de fondos y dominadas)","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Ajusta las barras de fondos a una altura que te permita agarrarlas cómodamente.","Ponte de pie entre las barras y coloca las manos en cada barra, un poco más separadas que el ancho de los hombros.","Salta y estira los brazos, sosteniendo el peso de tu cuerpo sobre las barras.","Flexiona las rodillas y cruza los tobillos detrás de ti.","Baja el cuerpo flexionando los codos, manteniendo el pecho elevado y los hombros bajos.","Continúa bajando hasta que los hombros queden por debajo de los codos o hasta que sientas un estiramiento en el pecho.","Empuja con las palmas y extiende los codos para subir el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1430-XgWyAiA.jpg","gif":"1430-XgWyAiA.gif"},{"id":"2462","n":"Fondos de pecho en barra recta","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Agarra las barras paralelas con las palmas hacia abajo y los brazos completamente extendidos.","Flexiona las rodillas y cruza los tobillos.","Baja el cuerpo flexionando los brazos hasta que los hombros queden por debajo de los codos.","Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."],"img":"2462-LQFOrMn.jpg","gif":"2462-LQFOrMn.gif"},{"id":"1272","n":"Estiramiento de pecho con pelota de ejercicio","bp":"chest","eq":"stability ball","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Siéntate en el balón de estabilidad con los pies planos en el suelo y la espalda recta.","Sujeta el balón de ejercicio con ambas manos y extiende los brazos rectos frente a ti.","Lleva lentamente el balón de ejercicio hacia tu pecho, sintiendo un estiramiento en los músculos del pecho.","Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1272-ykA5tU7.jpg","gif":"1272-ykA5tU7.gif"},{"id":"3216","n":"Flexiones con toque de pecho (hombre)","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros y el cuerpo en línea recta.","Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.","Mientras te bajas, toca tu pecho con la mano derecha.","Empújate de vuelta hacia arriba hasta la posición inicial.","Repite el movimiento, esta vez tocando tu pecho con la mano izquierda.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"3216-7E06s6d.jpg","gif":"3216-7E06s6d.gif"},{"id":"1326","n":"Dominadas supinas","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Cuélgate de una barra de dominadas con las palmas mirando hacia ti y las manos separadas a la altura de los hombros.","Activa el core y tira de tu cuerpo hacia arriba, hacia la barra, guiando con el pecho.","Continúa subiendo hasta que la barbilla quede por encima de la barra.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1326-T2mxWqc.jpg","gif":"1326-T2mxWqc.gif"},{"id":"0253","n":"Dominadas supinas (agarre paralelo estrecho)","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Cuélgate de una barra de dominadas con un agarre paralelo estrecho, con las palmas hacia ti.","Activa los músculos de la espalda y tira de tu cuerpo hacia arriba, hacia la barra, manteniendo los codos cerca del cuerpo.","Continúa subiendo hasta que la barbilla quede por encima de la barra.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0253-G70mEAJ.jpg","gif":"0253-G70mEAJ.gif"},{"id":"0257","n":"Estiramiento de rodilla con círculos","bp":"lower legs","eq":"body weight","tg":"calves","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las manos en las caderas.","Flexiona ligeramente las rodillas y levanta los talones del suelo, equilibrándote sobre las puntas de los pies.","Manteniendo las rodillas flexionadas, gira las rodillas en un movimiento circular, primero en el sentido de las agujas del reloj y luego en sentido contrario.","Realiza el movimiento el número de repeticiones deseado."],"img":"0257-X7jbxra.jpg","gif":"0257-X7jbxra.gif"},{"id":"1273","n":"Flexiones con palmada","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros.","Baja el cuerpo hacia el suelo flexionando los codos, manteniendo el core activado.","Empuja con las palmas de forma explosiva para impulsar tu cuerpo fuera del suelo.","Mientras estás en el aire, junta las manos en un aplauso antes de aterrizar de vuelta en la posición inicial.","Repite el número de repeticiones deseado."],"img":"1273-wigSg76.jpg","gif":"1273-wigSg76.gif"},{"id":"0258","n":"Flexiones en reloj","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta.","Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.","Mientras bajas, gira el cuerpo hacia la izquierda, extendiendo el brazo izquierdo recto hacia el lado.","Empuja de vuelta hacia arriba hasta la posición inicial, mientras giras el cuerpo hacia el centro.","Repite la flexión de brazos, esta vez girando el cuerpo hacia la derecha y extendiendo el brazo derecho hacia el lado.","Continúa alternando lados en cada repetición."],"img":"0258-CMAxnsG.jpg","gif":"0258-CMAxnsG.gif"},{"id":"1327","n":"Dominadas supinas con agarre cerrado","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Agarra la barra de dominadas con las palmas hacia ti y las manos separadas a la altura de los hombros.","Cuélgate de la barra con los brazos completamente extendidos y los pies fuera del suelo.","Activa los músculos de la espalda y tira de tu cuerpo hacia arriba, hacia la barra, manteniendo los codos cerca del cuerpo.","Continúa subiendo hasta que la barbilla quede por encima de la barra.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1327-VnfUNW7.jpg","gif":"1327-VnfUNW7.gif"},{"id":"0259","n":"Flexiones con agarre cerrado","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Comienza en posición de plancha alta con las manos juntas, directamente debajo de los hombros.","Activa el core y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados.","Empuja con las palmas para extender los brazos y regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0259-x6KpKpq.jpg","gif":"0259-x6KpKpq.gif"},{"id":"2398","n":"Flexiones con agarre cerrado (sobre rodillas)","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Comienza apoyándote sobre las manos y las rodillas, con las manos separadas a la altura de los hombros y las rodillas separadas a la altura de las caderas.","Baja la parte superior del cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.","Haz una pausa breve cuando tu pecho esté justo por encima del suelo.","Empuja con las palmas para estirar los brazos y regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2398-v3vLFW0.jpg","gif":"2398-v3vLFW0.gif"},{"id":"0260","n":"Cocoons","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0260-SLKj2pX.jpg","gif":"0260-SLKj2pX.gif"},{"id":"1468","n":"Giros en posición de cangrejo con toque de pies","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Comienza sentado en el suelo con las rodillas flexionadas y los pies planos en el suelo.","Coloca las manos detrás de ti, con los dedos apuntando hacia los pies, y levanta las caderas del suelo.","Extiende una pierna recta frente a ti mientras al mismo tiempo llevas la mano contraria hacia los dedos del pie.","Regresa a la posición inicial y repite del otro lado.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"1468-xgsGFVM.jpg","gif":"1468-xgsGFVM.gif"},{"id":"0262","n":"Abdominales cruzados","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta la parte superior del cuerpo del suelo y gira para llevar el codo derecho hacia la rodilla izquierda.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite en el otro lado, llevando el codo izquierdo hacia la rodilla derecha.","Repite el número de repeticiones deseado."],"img":"0262-rbu5UUb.jpg","gif":"0262-rbu5UUb.gif"},{"id":"0267","n":"Abdominales (manos sobre la cabeza)","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Extiende los brazos rectos por encima de la cabeza.","Activando el abdomen, levanta la parte superior del cuerpo del suelo, flexionándote hacia adelante en dirección a las rodillas.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0267-kjJ3VoQ.jpg","gif":"0267-kjJ3VoQ.gif"},{"id":"0271","n":"Abdominales (en pelota de estabilidad)","bp":"waist","eq":"stability ball","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Reclínate sobre el balón hasta que la zona lumbar esté apoyada y la parte superior del cuerpo quede paralela al suelo.","Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.","Activa el abdomen y levanta la parte superior del cuerpo hacia las rodillas, flexionando el torso hacia adelante.","Haz una pausa breve en la parte alta del movimiento, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0271-MCUhf1F.jpg","gif":"0271-MCUhf1F.gif"},{"id":"0272","n":"Abdominales (en pelota de estabilidad, brazos rectos)","bp":"waist","eq":"stability ball","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Reclínate sobre el balón hasta que la zona lumbar esté apoyada y la parte superior del cuerpo quede paralela al suelo.","Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.","Activa el abdomen y levanta la parte superior del cuerpo del balón, flexionando los hombros hacia las caderas.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0272-Sn8wxAI.jpg","gif":"0272-Sn8wxAI.gif"},{"id":"0274","n":"Abdominales en el suelo","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activa el abdomen y levanta los hombros del suelo, flexionándote hacia adelante en dirección a las rodillas.","Haz una pausa breve en la parte alta, luego baja lentamente los hombros de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0274-TFqbd8t.jpg","gif":"0274-TFqbd8t.gif"},{"id":"3016","n":"Curl-up","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3016-g2oKspu.jpg","gif":"3016-g2oKspu.gif"},{"id":"3769","n":"Sentadillas de cortesía","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros.","Da un paso en diagonal hacia atrás y a través de tu cuerpo con el pie derecho, cruzándolo detrás de la pierna izquierda.","Flexiona ambas rodillas como si hicieras una reverencia, bajando el cuerpo hacia el suelo.","Mantén el torso erguido y el peso sobre el pie delantero.","Empuja con el pie delantero para regresar a la posición inicial.","Repite en el otro lado, dando un paso en diagonal hacia atrás y a través de tu cuerpo con el pie izquierdo."],"img":"3769-gUjqdei.jpg","gif":"3769-gUjqdei.gif"},{"id":"2331","n":"Elíptica","bp":"cardio","eq":"leverage machine","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","glutes"],"st":["Ajusta la altura del asiento y colócate en la bicicleta elíptica.","Coloca los pies en los pedales y sujeta el manillar.","Comienza a pedalear con un movimiento suave y controlado.","Mantén un ritmo constante y aumenta la resistencia si lo deseas.","Continúa pedaleando durante la duración deseada de tu entrenamiento cardiovascular."],"img":"2331-XSCHmiI.jpg","gif":"2331-XSCHmiI.gif"},{"id":"0276","n":"Dead bug","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Túmbate boca arriba con los brazos extendidos hacia el techo.","Flexiona las rodillas y levanta las piernas del suelo, formando un ángulo de 90 grados en las caderas y las rodillas.","Activa el core y la zona lumbar para presionar la zona lumbar contra el suelo.","Baja lentamente el brazo derecho y la pierna izquierda hacia el suelo, manteniéndolos rectos y justo por encima del suelo.","Haz una pausa breve y luego vuelve a la posición inicial.","Repite el movimiento con el brazo izquierdo y la pierna derecha.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0276-iny3m5y.jpg","gif":"0276-iny3m5y.gif"},{"id":"0277","n":"Crunch en banco declinado","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Túmbate en un banco declinado con los pies sujetos y las rodillas flexionadas en un ángulo de 90 grados.","Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.","Activa el abdomen y levanta la parte superior del cuerpo hacia las rodillas, flexionando el torso.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0277-9Ap7miY.jpg","gif":"0277-9Ap7miY.gif"},{"id":"0279","n":"Flexiones en declive","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Coloca las manos en el suelo un poco más separadas que el ancho de los hombros, con los pies elevados sobre una superficie estable.","Mantén el cuerpo en línea recta de la cabeza a los pies, activando los músculos del core.","Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo.","Empuja con las palmas para extender los brazos y regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0279-i5cEhka.jpg","gif":"0279-i5cEhka.gif"},{"id":"0282","n":"Abdominales completos en banco declinado","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Túmbate en un banco declinado con los pies sujetos y las rodillas flexionadas.","Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.","Activa el abdomen y levanta la parte superior del cuerpo del banco, flexionándote hacia adelante en dirección a las rodillas.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0282-QLL2gdc.jpg","gif":"0282-QLL2gdc.gif"},{"id":"1274","n":"Flexiones profundas","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros y el cuerpo en línea recta.","Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo.","Empuja con las palmas para extender los brazos y regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1274-vptOQ4N.jpg","gif":"1274-vptOQ4N.gif"},{"id":"0283","n":"Flexiones diamante","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Comienza en posición de plancha alta con las manos juntas, formando una figura de diamante con los pulgares y los índices.","Mantén el cuerpo en línea recta de la cabeza a los pies, activando el core y los glúteos.","Baja el pecho hacia la figura de diamante formada por tus manos, manteniendo los codos cerca del cuerpo.","Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0283-soIB2rj.jpg","gif":"0283-soIB2rj.gif"},{"id":"0284","n":"Elevación de talones de burro","bp":"lower legs","eq":"body weight","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Ponte de pie con las puntas de los pies sobre una superficie elevada, como un escalón o un bloque.","Coloca las manos en un soporte estable, como una pared o un pasamanos, para mantener el equilibrio.","Levanta los talones lo más alto posible, elevando el peso de tu cuerpo sobre las puntas de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0284-u5ESqzH.jpg","gif":"0284-u5ESqzH.gif"},{"id":"1275","n":"Flexiones con descenso (drop push up)","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros.","Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo.","Una vez que tu pecho esté justo por encima del suelo, baja rápidamente las rodillas al suelo.","Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."],"img":"1275-Q497lAE.jpg","gif":"1275-Q497lAE.gif"},{"id":"0285","n":"Curl de bíceps alterno con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado, alternando los brazos."],"img":"0285-BU15nH4.jpg","gif":"0285-BU15nH4.gif"},{"id":"2403","n":"Curl de bíceps alterno con mancuernas (con arm blaster)","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante.","Coloca el soporte para brazos en la parte superior de tus brazos, asegurándote de que quede bien ajustado.","Manteniendo los brazos superiores quietos, exhala y flexiona una mancuerna hacia el hombro mientras contraes el bíceps.","Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el movimiento con el brazo contrario.","Continúa alternando los brazos durante el número de repeticiones deseado."],"img":"2403-CfKsRbG.jpg","gif":"2403-CfKsRbG.gif"},{"id":"1646","n":"Curl martillo alterno en banco predicador con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco scott con una mancuerna en cada mano, con las palmas hacia tu torso y los brazos completamente extendidos.","Mantén los brazos superiores fijos y exhala mientras levantas el peso contrayendo los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones recomendado."],"img":"1646-fy7Tgy4.jpg","gif":"1646-fy7Tgy4.gif"},{"id":"1647","n":"Curl alterno en banco predicador con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco scott con una mancuerna en cada mano, con las palmas hacia arriba.","Apoya la parte superior de los brazos en la almohadilla del banco scott, permitiendo que los brazos se extiendan completamente.","Manteniendo los brazos superiores quietos, exhala y flexiona la mancuerna en tu mano derecha mientras contraes el bíceps.","Continúa flexionando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.","Haz una pausa breve, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el movimiento con el brazo izquierdo.","Continúa alternando los brazos durante el número de repeticiones deseado."],"img":"1647-NlfIbzq.jpg","gif":"1647-NlfIbzq.gif"},{"id":"1648","n":"Curl martillo alterno sentado con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia tu torso y los brazos extendidos hacia abajo.","Mantén la espalda recta y los codos cerca del torso.","Exhala y flexiona la mancuerna de tu mano derecha hacia el hombro, manteniendo el brazo superior quieto.","Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.","Haz una pausa breve, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el movimiento con el brazo izquierdo.","Continúa alternando los brazos durante el número de repeticiones deseado."],"img":"1648-6em2Dxj.jpg","gif":"1648-6em2Dxj.gif"},{"id":"0286","n":"Press lateral alterno con mancuernas","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros.","Empuja una mancuerna por encima de la cabeza mientras mantienes la otra mancuerna a la altura del hombro.","Baja la mancuerna empujada de vuelta a la altura del hombro mientras empujas la otra mancuerna por encima de la cabeza.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0286-izMnLqz.jpg","gif":"0286-izMnLqz.gif"},{"id":"1649","n":"Curl de bíceps alterno con mancuernas y pierna elevada sobre pelota de fitness","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante.","Coloca un balón de ejercicio detrás de ti y apoya un pie sobre él, manteniendo el equilibrio.","Con los brazos completamente extendidos y los codos cerca de los costados, flexiona una mancuerna hacia el hombro mientras mantienes el brazo superior quieto.","Baja la mancuerna de vuelta a la posición inicial y repite con el otro brazo.","Continúa alternando los brazos durante el número de repeticiones deseado."],"img":"1649-Zwiw7XR.jpg","gif":"1649-Zwiw7XR.gif"},{"id":"1650","n":"Curl de bíceps alterno sentado con mancuernas sobre pelota de fitness","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.","Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos.","Manteniendo los brazos superiores quietos, exhala y flexiona una mancuerna mientras rotas el antebrazo hasta que la palma quede frente al hombro.","Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite la flexión con el otro brazo.","Continúa alternando flexiones el número de repeticiones deseado."],"img":"1650-J74XlNf.jpg","gif":"1650-J74XlNf.gif"},{"id":"2137","n":"Press Arnold con mancuernas agarre supino","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest"],"st":["Siéntate en un banco con respaldo y sujeta una mancuerna en cada mano a la altura del hombro, con las palmas hacia tu cuerpo y los codos flexionados.","Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos y las palmas miren hacia adelante.","Rota las muñecas mientras levantas, de modo que las palmas miren hacia adelante en la parte alta del movimiento.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2137-Xy4jlWA.jpg","gif":"2137-Xy4jlWA.gif"},{"id":"0287","n":"Press Arnold con mancuernas agarre neutro","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest"],"st":["Siéntate en un banco con respaldo y sujeta una mancuerna en cada mano a la altura del hombro, con las palmas hacia tu cuerpo y los codos flexionados.","Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos y las palmas miren hacia adelante.","Rota las muñecas mientras levantas, de modo que las palmas terminen mirando hacia adelante en la parte alta del movimiento.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0287-eOrFCnx.jpg","gif":"0287-eOrFCnx.gif"},{"id":"0288","n":"Pullover con mancuernas","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","latissimus dorsi"],"st":["Túmbate en un banco con la cabeza en un extremo y los pies firmemente apoyados en el suelo.","Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima del pecho.","Manteniendo los brazos rectos, baja lentamente la mancuerna detrás de la cabeza en un movimiento de arco.","Haz una pausa breve en la parte baja, luego levanta la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0288-vi8EhoE.jpg","gif":"0288-vi8EhoE.gif"},{"id":"0289","n":"Press de banca con mancuernas","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Sujeta una mancuerna en cada mano, con las palmas hacia adelante y los brazos extendidos por encima del pecho.","Baja lentamente las mancuernas hacia los lados del pecho, manteniendo los codos en un ángulo de 90 grados.","Haz una pausa breve, luego empuja las mancuernas de vuelta hacia arriba hasta la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"0289-SpYC0Kp.jpg","gif":"0289-SpYC0Kp.gif"},{"id":"0290","n":"Press sentado en banco con mancuernas","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","chest"],"st":["Siéntate en un banco con una mancuerna en cada mano, apoyadas en los muslos.","Reclínate hacia atrás y coloca las mancuernas a los lados del pecho, con las palmas hacia adelante.","Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0290-3d7wHyd.jpg","gif":"0290-3d7wHyd.gif"},{"id":"0291","n":"Sentadilla en banco con mancuernas","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Coloca una mancuerna en el suelo frente a un banco.","Ponte de pie de espaldas al banco con los pies separados a la altura de los hombros.","Flexiona las rodillas y las caderas para bajar hacia el banco, manteniendo el pecho elevado y la espalda recta.","Una vez que los glúteos toquen el banco, empuja con los talones para volver a ponerte de pie en la posición inicial.","Repite el número de repeticiones deseado."],"img":"0291-mnzcrIB.jpg","gif":"0291-mnzcrIB.gif"},{"id":"0293","n":"Remo con mancuernas a un brazo","bp":"back","eq":"dumbbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo.","Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.","Deja que los brazos cuelguen rectos hacia el suelo, con los codos ligeramente flexionados.","Tira de las mancuernas hacia arriba, hacia el pecho, apretando los omóplatos entre sí.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0293-BJ0Hz5L.jpg","gif":"0293-BJ0Hz5L.gif"},{"id":"1651","n":"Zancada con curl de bíceps y movimiento de bolos","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con las palmas hacia adelante.","Da un paso adelante con el pie derecho, flexionando la rodilla derecha y bajando el cuerpo a una posición de zancada.","Mientras avanzas en la zancada, flexiona las mancuernas hacia los hombros, manteniendo los codos cerca del cuerpo.","En la parte baja de la zancada, gira el torso hacia la derecha, como si estuvieras lanzando una bola de boliche.","Invierte el movimiento, retrocediendo con el pie derecho y regresando a la posición inicial mientras bajas las mancuernas de nuevo.","Repite el movimiento de zancada y flexión, esta vez girando el torso hacia la izquierda.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"1651-1VpF8db.jpg","gif":"1651-1VpF8db.gif"},{"id":"1652","n":"Curl de bíceps con mancuernas en pelota de fitness con pierna elevada","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.","Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos.","Flexiona lentamente las mancuernas hacia los hombros, manteniendo los codos cerca de los costados.","Haz una pausa breve en la parte alta del movimiento, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Mientras realizas el curl de bíceps, levanta una pierna del suelo y mantenla en el aire durante todo el ejercicio.","Repite el número de repeticiones deseado y luego cambia de pierna y repite."],"img":"1652-2NImIAG.jpg","gif":"1652-2NImIAG.gif"},{"id":"1653","n":"Curl de bíceps con mancuernas en posición de cigüeña","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante.","Extiende una pierna hacia atrás, equilibrándote sobre los dedos de ese pie.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado y luego cambia de pierna y repite."],"img":"1653-uSkDMYl.jpg","gif":"1653-uSkDMYl.gif"},{"id":"0294","n":"Curl de bíceps con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0294-NbVPDMW.jpg","gif":"0294-NbVPDMW.gif"},{"id":"2401","n":"Curl de bíceps con mancuernas (con arm blaster)","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante.","Mantén los codos cerca del torso y los brazos superiores quietos.","Exhala y flexiona las pesas mientras contraes los bíceps.","Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2401-nlJsbkW.jpg","gif":"2401-nlJsbkW.gif"},{"id":"1654","n":"Curl de bíceps inverso con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con una mancuerna en cada mano, con las palmas hacia abajo y los brazos completamente extendidos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1654-nFc4FyV.jpg","gif":"1654-nFc4FyV.gif"},{"id":"1655","n":"Curl de bíceps con mancuernas y sentadilla","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con las palmas hacia adelante.","Manteniendo la espalda recta y los codos cerca de los costados, exhala y flexiona las mancuernas hacia los hombros.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1655-niXESDw.jpg","gif":"1655-niXESDw.gif"},{"id":"1656","n":"Curl de bíceps con mancuernas en V sobre bosu","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Siéntate en un bosu con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos hacia abajo a los lados.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1656-H1XAdpk.jpg","gif":"1656-H1XAdpk.gif"},{"id":"1201","n":"Burpee con mancuernas","bp":"cardio","eq":"dumbbell","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","shoulders","triceps","core"],"st":["Comienza de pie con los pies separados a la altura de los hombros y una mancuerna en cada mano.","Baja el cuerpo a una posición de sentadilla, colocando las mancuernas en el suelo frente a ti.","Lleva los pies hacia atrás a una posición de flexión de brazos, manteniendo el cuerpo en línea recta.","Realiza una flexión de brazos, flexionando los codos y bajando el pecho hacia el suelo.","Salta con los pies hacia tus manos, aterrizando en una posición de sentadilla.","Ponte de pie de forma explosiva, levantando las mancuernas del suelo y llevándolas a los hombros.","Empuja las mancuernas por encima de la cabeza, extendiendo completamente los brazos.","Baja las mancuernas de vuelta a los hombros y repite toda la secuencia el número de repeticiones deseado."],"img":"1201-0JtKWum.jpg","gif":"1201-0JtKWum.gif"},{"id":"0295","n":"Clean con mancuernas","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.","Flexiona las rodillas y baja las caderas hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.","Extiende las caderas y las rodillas de forma explosiva, empujando con los talones para saltar del suelo.","Mientras saltas, encoge los hombros y tira de las mancuernas hacia arriba, hacia los hombros, manteniéndolas cerca del cuerpo.","Atrapa las mancuernas a la altura de los hombros, con los codos apuntando hacia adelante y las palmas hacia arriba.","Baja las mancuernas de vuelta a la posición inicial invirtiendo el movimiento.","Repite el número de repeticiones deseado."],"img":"0295-7Hg55JG.jpg","gif":"0295-7Hg55JG.gif"},{"id":"1731","n":"Press cerrado con mancuernas ambos brazos","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Siéntate en un banco plano con una mancuerna en cada mano, apoyadas en los muslos.","Usando los muslos para ayudar a levantar las mancuernas, levanta las mancuernas una a la vez para poder sostenerlas frente a ti a la altura de los hombros.","Una vez a la altura de los hombros, rota las muñecas hacia adelante de modo que las palmas de las manos miren hacia afuera de ti. Esta será tu posición inicial.","Mientras inhalas, baja lentamente las mancuernas hacia tu lado hasta que queden aproximadamente a la altura del pecho.","Mientras exhalas, usa los tríceps para levantar las mancuernas de vuelta a la posición inicial. Asegúrate de usar solo los tríceps y no usar los antebrazos ni los bíceps para ayudar a levantar las mancuernas.","Después de una pausa de un segundo en la posición contraída, repite el movimiento el número de repeticiones prescrito."],"img":"1731-7jGOBF3.jpg","gif":"1731-7jGOBF3.gif"},{"id":"0296","n":"Press cerrado con una mancuerna","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Siéntate en un banco plano con una mancuerna en cada mano, apoyadas en los muslos.","Usando los muslos para ayudar a levantar las mancuernas, levanta las mancuernas una a la vez para poder sostenerlas frente a ti a la altura de los hombros.","Una vez a la altura de los hombros, rota las muñecas hacia adelante de modo que las palmas de las manos miren hacia afuera de ti. Esta será tu posición inicial.","Mientras inhalas, baja lentamente las mancuernas hacia tu lado hasta que queden aproximadamente a la altura del pecho.","Mientras exhalas, usa los tríceps para levantar las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0296-RxayqAZ.jpg","gif":"0296-RxayqAZ.gif"},{"id":"0297","n":"Curl de concentración con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco con las piernas separadas y una mancuerna en una mano, apoyando el codo en la parte interna del muslo.","Extiende completamente el brazo y sujeta la mancuerna con un agarre supino.","Manteniendo el brazo superior quieto, exhala y flexiona el peso hacia el hombro mientras contraes el bíceps.","Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"0297-gvsWLQw.jpg","gif":"0297-gvsWLQw.gif"},{"id":"3635","n":"Estocada frontal contralateral con mancuernas","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.","Da un paso adelante con el pie derecho, manteniendo la espalda recta y el core activado.","Baja el cuerpo flexionando ambas rodillas hasta que el muslo derecho quede paralelo al suelo.","Empuja con el talón derecho para regresar a la posición inicial.","Repite con la pierna izquierda.","Alterna las piernas el número de repeticiones deseado."],"img":"3635-ecl28tP.jpg","gif":"3635-ecl28tP.gif"},{"id":"0298","n":"Curl martillo cruzado con mancuernas agarre neutro","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con una mancuerna en cada mano, con las palmas hacia tu cuerpo.","Mantén los codos cerca del torso y los brazos superiores quietos.","Exhala y flexiona los brazos contrayendo los bíceps, llevando las mancuernas a través del cuerpo hacia el hombro opuesto.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0298-Qyk5J3p.jpg","gif":"0298-Qyk5J3p.gif"},{"id":"1657","n":"Curl martillo cruzado con mancuernas agarre neutro-supino","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con una mancuerna en cada mano, con las palmas hacia tu cuerpo.","Mantén los codos cerca del torso y los brazos superiores quietos.","Exhala y flexiona los brazos contrayendo los bíceps, acercando las mancuernas lo más posible al hombro opuesto.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1657-HDYiZcY.jpg","gif":"1657-HDYiZcY.gif"},{"id":"0299","n":"Press cubano con mancuernas agarre neutro-prono","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a la altura de los hombros con las palmas hacia abajo.","Manteniendo el core activado y los codos ligeramente flexionados, empuja las mancuernas hacia arriba por encima de la cabeza hasta que los brazos queden completamente extendidos.","Gira las muñecas de modo que las palmas queden mirando hacia adelante.","Baja lentamente las mancuernas a la posición inicial, girando las muñecas de vuelta a la posición inicial mientras lo haces.","Repite el número de repeticiones deseado."],"img":"0299-QfAKy1G.jpg","gif":"0299-QfAKy1G.gif"},{"id":"2136","n":"Press cubano con mancuernas agarre prono","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a la altura de los hombros con las palmas hacia abajo.","Manteniendo el core activado y la espalda recta, empuja las mancuernas directamente hacia arriba por encima de la cabeza hasta que los brazos queden completamente extendidos.","Gira las muñecas de modo que las palmas queden mirando hacia adelante.","Baja las mancuernas de nuevo hasta la altura de los hombros, girando las muñecas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2136-BqgCRif.jpg","gif":"2136-BqgCRif.gif"},{"id":"0300","n":"Peso muerto con mancuernas","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Ponte de pie con los pies separados a la altura de los hombros, con las puntas de los pies apuntando hacia adelante.","Sostén una mancuerna en cada mano, con las palmas hacia el cuerpo y los brazos extendidos hacia abajo.","Flexiona las caderas y las rodillas, bajando las mancuernas hacia el suelo mientras mantienes la espalda recta.","Empuja con los talones y extiende las caderas y las rodillas, levantando las mancuernas de nuevo a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0300-nUwVh7b.jpg","gif":"0300-nUwVh7b.gif"},{"id":"0301","n":"Press de banca declinado con mancuernas","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.","Sostén una mancuerna en cada mano y extiende los brazos rectos hacia arriba por encima del pecho, con las palmas hacia adelante.","Baja lentamente las mancuernas hacia los lados del pecho, manteniendo los codos en un ángulo de 90 grados.","Empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"0301-DwhEmmE.jpg","gif":"0301-DwhEmmE.gif"},{"id":"0302","n":"Aperturas declinadas con mancuernas","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders"],"st":["Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.","Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos por encima del pecho.","Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho.","Haz una pausa por un momento, luego contrae los músculos del pecho para llevar las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0302-xXm4nYq.jpg","gif":"0302-xXm4nYq.gif"},{"id":"0303","n":"Press martillo declinado con mancuernas","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.","Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos por encima del pecho.","Baja las mancuernas a los lados del pecho, manteniendo los codos ligeramente flexionados.","Empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"0303-1qrWgZ2.jpg","gif":"0303-1qrWgZ2.gif"},{"id":"1276","n":"Aperturas declinadas a una mano con mancuernas","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders"],"st":["Túmbate en un banco declinado con una mancuerna en una mano, apoyándola sobre el muslo.","Usando el muslo para ayudar a levantar la mancuerna, álzala hasta la altura de los hombros con la palma mirando hacia el torso.","Gira la muñeca de modo que la palma de la mano quede mirando hacia adelante.","Mientras inhalas, baja la mancuerna lentamente hacia el lado hasta sentir un estiramiento en el pecho.","Exhala y usa los músculos del pecho para llevar la mancuerna de nuevo hacia arriba hasta la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1276-NL6YBwN.jpg","gif":"1276-NL6YBwN.gif"},{"id":"1617","n":"Press martillo declinado a un brazo con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Túmbate en un banco declinado con una mancuerna en una mano, apoyada sobre el pecho.","Extiende el brazo recto hacia arriba, manteniendo el codo ligeramente flexionado.","Baja la mancuerna hacia el hombro, manteniendo el codo cerca del cuerpo.","Empuja la mancuerna de nuevo hacia arriba hasta la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1617-SHUMp5H.jpg","gif":"1617-SHUMp5H.gif"},{"id":"0305","n":"Encogimiento de hombros declinado con mancuernas hacia delante","bp":"back","eq":"dumbbell","tg":"traps","mg":"shoulders","sm":["shoulders","rhomboids"],"st":["Ajusta un banco declinado a un ángulo de 45 grados.","Túmbate boca abajo en el banco con el pecho y el abdomen apoyados contra él.","Sostén una mancuerna en cada mano con los brazos completamente extendidos hacia el suelo.","Manteniendo los brazos rectos, levanta los hombros hacia las orejas lo más alto posible.","Mantén la contracción por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0305-cwsAI4G.jpg","gif":"0305-cwsAI4G.gif"},{"id":"0304","n":"Encogimiento de hombros declinado con mancuernas hacia atrás","bp":"back","eq":"dumbbell","tg":"traps","mg":"shoulders","sm":["shoulders","rhomboids"],"st":["Ajusta un banco declinado a un ángulo de 45 grados.","Túmbate boca abajo en el banco con el pecho y el abdomen apoyados sobre él.","Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos completamente extendidos.","Manteniendo los brazos rectos, levanta los hombros lo más alto posible mientras juntas los omóplatos.","Mantén la contracción durante una breve pausa, luego baja las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0304-bRlbdjK.jpg","gif":"0304-bRlbdjK.gif"},{"id":"0306","n":"Extensión de tríceps declinada con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Túmbate en un banco declinado con la cabeza más baja que los pies y sostén una mancuerna en cada mano, con las palmas enfrentadas entre sí.","Extiende completamente los brazos, manteniendo los codos cerca de la cabeza.","Baja lentamente las mancuernas detrás de la cabeza, flexionando los codos.","Haz una pausa por un momento, luego levanta las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0306-OTgkHwR.jpg","gif":"0306-OTgkHwR.gif"},{"id":"0307","n":"Aperturas declinadas con giro con mancuernas","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Túmbate en un banco declinado con la cabeza más baja que las caderas.","Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos rectos hacia arriba sobre el pecho.","Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho.","Mientras bajas las mancuernas, gira las muñecas de modo que las palmas queden mirando hacia adelante en la parte inferior del movimiento.","Invierte el movimiento y lleva las mancuernas de nuevo hacia arriba hasta la posición inicial, contrayendo los músculos del pecho en la parte superior.","Repite el número de repeticiones deseado."],"img":"0307-reFHapa.jpg","gif":"0307-reFHapa.gif"},{"id":"1437","n":"Curl de dedos con mancuernas","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","wrist extensors"],"st":["Siéntate en un banco o silla con los pies apoyados en el suelo y la espalda recta.","Sostén una mancuerna en una mano con agarre supino, apoyando el antebrazo sobre el muslo, con la palma hacia arriba.","Deja que la mancuerna ruede hacia las puntas de los dedos, luego flexiona los dedos para volver a enrollarla hacia arriba.","Repite el número de repeticiones deseado, luego cambia a la otra mano."],"img":"1437-mtXengz.jpg","gif":"1437-mtXengz.gif"},{"id":"0308","n":"Aperturas con mancuernas","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders"],"st":["Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí.","Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos.","Manteniendo una ligera flexión en los codos, baja los brazos hacia los lados en un amplio arco hasta sentir un estiramiento en el pecho.","Haz una pausa por un momento, luego invierte el movimiento y lleva las mancuernas de nuevo hacia arriba hasta la posición inicial.","Repite el número de repeticiones deseado."],"img":"0308-yz9nUhF.jpg","gif":"0308-yz9nUhF.gif"},{"id":"1277","n":"Aperturas con mancuernas sobre fitball","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Siéntate sobre un balón de estabilidad y sostén una mancuerna en cada mano.","Camina con los pies hacia adelante y baja el cuerpo rodando hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón.","Extiende los brazos rectos por encima del pecho, con las palmas enfrentadas entre sí.","Flexiona ligeramente los codos y baja los brazos hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho.","Haz una pausa por un momento, luego invierte el movimiento y contrae los músculos del pecho mientras llevas las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1277-Lt3iWnf.jpg","gif":"1277-Lt3iWnf.gif"},{"id":"1732","n":"Zancada hacia delante con extensión de tríceps con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.","Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.","Mantén la espalda recta y el pecho elevado.","Extiende los brazos rectos por encima de la cabeza, manteniendo los codos cerca de las orejas.","Baja las mancuernas detrás de la cabeza flexionando los codos.","Haz una pausa por un momento, luego estira los brazos para volver a la posición inicial.","Repite el movimiento el número de repeticiones deseado, luego cambia de pierna y repite."],"img":"1732-XalXcvM.jpg","gif":"1732-XalXcvM.gif"},{"id":"0310","n":"Elevación frontal con mancuernas agarre prono","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"biceps","sm":["biceps","trapezius"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia los muslos.","Manteniendo los brazos rectos, exhala y levanta las mancuernas frente a ti hasta que queden a la altura de los hombros.","Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0310-3eGE2JC.jpg","gif":"0310-3eGE2JC.gif"},{"id":"0309","n":"Elevación frontal con una mancuerna agarre neutro","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","biceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia los muslos.","Mantén la espalda recta y activa el core.","Levanta lentamente las mancuernas frente a ti, con los brazos rectos, hasta que queden a la altura de los hombros.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0309-Rr7S3yg.jpg","gif":"0309-Rr7S3yg.gif"},{"id":"0311","n":"Elevación lateral en vaciado de lata («full can») con mancuernas","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","rotator cuff"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia el cuerpo.","Mantén la espalda recta y activa el core.","Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0311-AQ0mC4Y.jpg","gif":"0311-AQ0mC4Y.gif"},{"id":"1760","n":"Sentadilla goblet con mancuerna","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna verticalmente contra el pecho con ambas manos.","Manteniendo el pecho erguido y el core activado, baja el cuerpo a una posición de sentadilla empujando las caderas hacia atrás y flexionando las rodillas.","Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1760-yn8yg1r.jpg","gif":"1760-yn8yg1r.gif"},{"id":"0313","n":"Curl martillo con mancuernas agarre neutro unilateral","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso.","Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante.","Esta será tu posición inicial.","Ahora, manteniendo los brazos superiores quietos, exhala y flexiona los brazos contrayendo los bíceps.","Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Luego, inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones recomendado."],"img":"0313-slDvUAU.jpg","gif":"0313-slDvUAU.gif"},{"id":"1659","n":"Curl martillo con mancuernas sobre fitball","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.","Sostén una mancuerna en cada mano con las palmas hacia el cuerpo y los brazos completamente extendidos.","Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas contrayendo los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1659-fY68AyX.jpg","gif":"1659-fY68AyX.gif"},{"id":"0312","n":"Curl martillo con mancuernas agarre neutro","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso.","Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante.","Esta será tu posición inicial.","Ahora, manteniendo los brazos superiores quietos, exhala y flexiona los brazos contrayendo los bíceps.","Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Luego, inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones recomendado."],"img":"0312-2NpxjC1.jpg","gif":"0312-2NpxjC1.gif"},{"id":"2402","n":"Curl martillo con mancuernas (con arm blaster)","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso.","Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante.","Esta será tu posición inicial.","Ahora, manteniendo el brazo superior quieto, exhala y flexiona los brazos contrayendo los bíceps.","Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Luego, inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones recomendado."],"img":"2402-GNhAeJ0.jpg","gif":"2402-GNhAeJ0.gif"},{"id":"1664","n":"Curl alto con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante.","Mantén los brazos superiores quietos y flexiona las mancuernas lo más alto posible contrayendo los bíceps.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1664-qAmNMJY.jpg","gif":"1664-qAmNMJY.gif"},{"id":"3545","n":"Press inclinado alterno con mancuernas","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Siéntate en un banco inclinado con una mancuerna en cada mano, apoyadas sobre los muslos.","Recuéstate en el banco y usa los muslos para ayudar a levantar las mancuernas hasta la altura de los hombros, con las palmas hacia adelante.","Una vez a la altura de los hombros, gira las muñecas de modo que las palmas de las manos queden mirando hacia adelante.","Empuja las mancuernas hacia arriba con el pecho y los hombros, extendiendo completamente los brazos.","Baja las mancuernas de nuevo hasta la posición inicial, manteniendo los codos ligeramente flexionados.","Repite el número de repeticiones deseado, alternando los brazos."],"img":"3545-TVdivgY.jpg","gif":"3545-TVdivgY.gif"},{"id":"0314","n":"Press de banca inclinado con mancuernas","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Coloca un banco inclinado a un ángulo de 45 grados.","Siéntate en el banco con los pies apoyados en el suelo y la espalda firmemente apoyada contra el banco.","Sostén una mancuerna en cada mano, con las palmas hacia adelante, y levántalas hasta la altura de los hombros.","Baja lentamente las mancuernas hacia los lados del pecho, manteniendo los codos en un ángulo de 90 grados.","Empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"0314-ns0SIbU.jpg","gif":"0314-ns0SIbU.gif"},{"id":"0315","n":"Curl de bíceps inclinado con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0315-F3xgbjF.jpg","gif":"0315-F3xgbjF.gif"},{"id":"0316","n":"Aperturas inclinadas con mancuernas agarre prono","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Coloca un banco inclinado a un ángulo de 45 grados.","Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo.","Sostén una mancuerna en cada mano con agarre prono, con las palmas hacia adelante.","Comienza con los brazos completamente extendidos, perpendiculares al suelo.","Baja lentamente las mancuernas hacia los lados del pecho, manteniendo los codos en un ángulo de 90 grados.","Haz una pausa por un momento en la parte inferior, luego empuja las mancuernas de nuevo hacia arriba hasta la posición inicial.","Repite el número de repeticiones deseado."],"img":"0316-B3Rxp6L.jpg","gif":"0316-B3Rxp6L.gif"},{"id":"0318","n":"Curl inclinado con mancuernas unilateral agarre neutro-supino","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas hacia adelante.","Apoya los brazos superiores en el banco inclinado y deja que los codos cuelguen hacia abajo, extendiendo completamente los brazos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0318-ae9UoXQ.jpg","gif":"0318-ae9UoXQ.gif"},{"id":"0317","n":"Curl inclinado con mancuernas agarre supino","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0317-RaflbWD.jpg","gif":"0317-RaflbWD.gif"},{"id":"0319","n":"Aperturas inclinadas con mancuernas agarre neutro","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders"],"st":["Ajusta un banco inclinado a un ángulo de 45 grados.","Siéntate en el banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí.","Recuéstate en el banco y empuja las mancuernas hacia arriba hasta la posición inicial, directamente por encima del pecho.","Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho.","Haz una pausa por un momento, luego contrae los músculos del pecho para llevar las mancuernas de nuevo hacia arriba hasta la posición inicial.","Repite el número de repeticiones deseado."],"img":"0319-ESOd5Pl.jpg","gif":"0319-ESOd5Pl.gif"},{"id":"1278","n":"Aperturas inclinadas con mancuernas sobre fitball","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders"],"st":["Coloca un banco inclinado a un ángulo de 45 grados.","Siéntate sobre un balón de estabilidad y rueda hacia adelante hasta que la parte superior de la espalda quede apoyada en el banco inclinado.","Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos por encima del pecho.","Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho.","Haz una pausa por un momento, luego contrae los músculos del pecho para llevar las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1278-HYe1ZqR.jpg","gif":"1278-HYe1ZqR.gif"},{"id":"0320","n":"Curl de martillo inclinado con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas hacia el torso y los brazos completamente extendidos.","Mantén la espalda contra el banco y los pies apoyados en el suelo.","Manteniendo los brazos superiores quietos, exhala y flexiona los brazos contrayendo los bíceps.","Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0320-ByX0WxV.jpg","gif":"0320-ByX0WxV.gif"},{"id":"0321","n":"Press inclinado neutro con mancuernas","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, apoyadas sobre los muslos.","Recuéstate en el banco y coloca las mancuernas a la altura de los hombros con las palmas enfrentadas entre sí.","Empuja las mancuernas hacia arriba y alejándolas del cuerpo hasta que los brazos queden completamente extendidos.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0321-PG1kcIb.jpg","gif":"0321-PG1kcIb.gif"},{"id":"1618","n":"Press inclinado neutro con mancuernas sobre fitball","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Siéntate sobre un balón de estabilidad con una mancuerna en cada mano, con las palmas enfrentadas entre sí.","Camina con los pies hacia adelante y baja el cuerpo rodando sobre el balón hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón.","Sostén las mancuernas a la altura de los hombros, con los codos flexionados y apuntando hacia los lados.","Empuja las mancuernas hacia arriba y ligeramente hacia adentro, manteniendo las palmas enfrentadas entre sí.","Extiende completamente los brazos, contrayendo los tríceps en la parte superior del movimiento.","Baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1618-wkgnGfb.jpg","gif":"1618-wkgnGfb.gif"},{"id":"0322","n":"Curl de bíceps interno inclinado con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas enfrentadas entre sí.","Apoya los brazos superiores en el banco, permitiendo que los codos cuelguen hacia abajo y las palmas miren hacia adelante.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0322-LCtQPn8.jpg","gif":"0322-LCtQPn8.gif"},{"id":"1279","n":"Aperturas inclinadas a un brazo con mancuerna","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Ajusta el banco inclinado a un ángulo de 30-45 grados.","Siéntate en el banco con una mancuerna en una mano, apoyándola sobre el muslo.","Recuéstate en el banco, manteniendo los pies apoyados en el suelo.","Sostén la mancuerna con el brazo extendido recto hacia arriba sobre el pecho.","Baja la mancuerna hacia el lado describiendo un amplio arco, manteniendo una ligera flexión en el codo.","Haz una pausa cuando el brazo esté paralelo al suelo, luego invierte el movimiento para llevar la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1279-Gw2HFvW.jpg","gif":"1279-Gw2HFvW.gif"},{"id":"1280","n":"Aperturas inclinadas a un brazo con mancuerna sobre fitball","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders"],"st":["Siéntate sobre un balón de estabilidad con una mancuerna en una mano.","Camina con los pies hacia adelante y baja el cuerpo rodando hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón.","Sostén la mancuerna con el brazo extendido recto hacia arriba sobre el pecho, con la palma hacia adentro.","Baja lentamente la mancuerna hacia el lado, manteniendo una ligera flexión en el codo.","Haz una pausa por un momento cuando el brazo esté paralelo al suelo.","Activa los músculos del pecho para llevar la mancuerna de nuevo hacia arriba hasta la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1280-LLNh6q5.jpg","gif":"1280-LLNh6q5.gif"},{"id":"1619","n":"Press inclinado neutro a un brazo con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","chest"],"st":["Siéntate en un banco inclinado con una mancuerna en una mano, apoyada sobre el muslo.","Recuéstate en el banco y usa el muslo para ayudar a levantar la mancuerna hasta la altura de los hombros.","Gira la muñeca de modo que la palma quede mirando hacia adentro, hacia el cuerpo.","Empuja la mancuerna hacia arriba y alejándola del cuerpo, extendiendo completamente el brazo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1619-LL1UiTX.jpg","gif":"1619-LL1UiTX.gif"},{"id":"1620","n":"Press inclinado neutro a un brazo con mancuerna sobre fitball","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","chest"],"st":["Siéntate sobre un balón de estabilidad con una mancuerna en una mano.","Camina con los pies hacia adelante y baja el cuerpo rodando hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón.","Sostén la mancuerna con la palma hacia adentro y el codo flexionado en un ángulo de 90 grados.","Empuja la mancuerna hacia el techo, estirando el brazo.","Baja la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1620-jDnrkar.jpg","gif":"1620-jDnrkar.gif"},{"id":"0323","n":"Elevación lateral inclinada a un brazo con mancuerna","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","triceps"],"st":["Siéntate en un banco inclinado con una mancuerna en una mano, apoyándola sobre el muslo.","Inclínate hacia adelante y coloca el brazo superior contra la parte interna del muslo.","Levanta la mancuerna hacia el lado, manteniendo el brazo ligeramente flexionado y la palma hacia abajo.","Continúa levantando hasta que el brazo quede paralelo al suelo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"0323-aTNKZiC.jpg","gif":"0323-aTNKZiC.gif"},{"id":"1281","n":"Press inclinado a un brazo con mancuerna","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Siéntate en un banco inclinado con una mancuerna en una mano, apoyada sobre el muslo.","Recuéstate en el banco y coloca la mancuerna a la altura del hombro, con la palma hacia adelante.","Empuja la mancuerna hacia arriba y ligeramente hacia adentro, extendiendo completamente el brazo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"1281-rDAiRf9.jpg","gif":"1281-rDAiRf9.gif"},{"id":"1282","n":"Press inclinado a un brazo con mancuerna sobre fitball","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Siéntate sobre un balón de estabilidad con una mancuerna en una mano, con los pies apoyados en el suelo.","Camina lentamente con los pies hacia adelante, haciendo rodar el balón hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón.","Sostén la mancuerna a la altura del hombro con la palma hacia adelante.","Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"1282-Bg5JKSH.jpg","gif":"1282-Bg5JKSH.gif"},{"id":"0324","n":"Press inclinado con agarre neutro con mancuernas","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Coloca un banco inclinado a un ángulo de 45 grados.","Siéntate en el banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí.","Planta los pies firmemente en el suelo y mantén la espalda recta contra el banco.","Comienza con las mancuernas a la altura de los hombros, con los codos flexionados y las palmas enfrentadas entre sí.","Empuja las mancuernas hacia arriba y alejándolas del cuerpo, extendiendo completamente los brazos.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0324-OVLmUuL.jpg","gif":"0324-OVLmUuL.gif"},{"id":"1283","n":"Press inclinado con mancuernas sobre fitball","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Siéntate sobre un balón de estabilidad con una mancuerna en cada mano, con las palmas hacia adelante.","Camina lentamente con los pies hacia adelante, bajando el cuerpo rodando sobre el balón hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón.","Sostén las mancuernas a la altura de los hombros, con los codos flexionados y apuntando hacia los lados.","Empuja las mancuernas hacia arriba, extendiendo completamente los brazos.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1283-bfiHMpI.jpg","gif":"1283-bfiHMpI.gif"},{"id":"0325","n":"Elevación frontal inclinada con mancuernas","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","triceps"],"st":["Siéntate en un banco inclinado con una mancuerna en cada mano, apoyadas sobre los muslos.","Recuéstate en el banco y levanta las mancuernas hasta la altura de los hombros, con las palmas hacia adelante.","Manteniendo la espalda contra el banco, exhala y levanta las mancuernas por encima de la cabeza, extendiendo completamente los brazos.","Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la altura de los hombros.","Repite el número de repeticiones deseado."],"img":"0325-nxW6BkN.jpg","gif":"0325-nxW6BkN.gif"},{"id":"0326","n":"Elevaciones laterales posteriores con mancuernas en banco inclinado","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","rhomboids"],"st":["Coloca un banco inclinado a un ángulo de 45 grados.","Siéntate en el banco con el pecho contra el respaldo y sostén una mancuerna en cada mano.","Extiende los brazos rectos hacia abajo con las palmas enfrentadas entre sí.","Manteniendo una ligera flexión en los codos, levanta los brazos hacia los lados hasta que queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0326-vYk8lqw.jpg","gif":"0326-vYk8lqw.gif"},{"id":"0327","n":"Remo con mancuernas en banco inclinado","bp":"back","eq":"dumbbell","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Coloca un banco inclinado a un ángulo de 45 grados.","Toma una mancuerna en cada mano y siéntate en el banco con el pecho apoyado contra la inclinación.","Extiende completamente los brazos, dejando que las mancuernas cuelguen rectas hacia abajo desde los hombros.","Tira de las mancuernas hacia arriba, hacia el pecho, apretando los omóplatos entre sí.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0327-7vG5o25.jpg","gif":"0327-7vG5o25.gif"},{"id":"0328","n":"Elevación de hombros con mancuernas en banco inclinado","bp":"chest","eq":"dumbbell","tg":"serratus anterior","mg":"deltoids","sm":["deltoids","trapezius"],"st":["Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas hacia abajo.","Apoya las mancuernas sobre los muslos y recuéstate en el banco.","Usa los muslos para ayudar a levantar las mancuernas hasta la altura de los hombros, luego gira las muñecas de modo que las palmas queden mirando hacia adelante.","Exhala y levanta lentamente las mancuernas por encima de la cabeza, manteniendo una ligera flexión en los codos.","Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la altura de los hombros.","Repite el número de repeticiones deseado."],"img":"0328-6e2DcYX.jpg","gif":"0328-6e2DcYX.gif"},{"id":"0329","n":"Encogimientos de hombros con mancuernas en banco inclinado","bp":"back","eq":"dumbbell","tg":"traps","mg":"shoulders","sm":["shoulders"],"st":["Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano.","Coloca los pies planos sobre el suelo y deja que los brazos cuelguen rectos hacia abajo con las palmas hacia el cuerpo.","Manteniendo los brazos rectos, encoge los hombros hacia las orejas lo más alto posible.","Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0329-JymLInS.jpg","gif":"0329-JymLInS.gif"},{"id":"3542","n":"Elevaciones en T con mancuernas en banco inclinado","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","rhomboids"],"st":["Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas hacia adentro.","Inclínate hacia adelante y deja que los brazos cuelguen rectos hacia abajo, perpendiculares al suelo.","Manteniendo los brazos rectos, levántalos hacia los lados hasta que queden paralelos al suelo, formando una 'T' con el cuerpo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3542-jgbvVJ0.jpg","gif":"3542-jgbvVJ0.gif"},{"id":"0330","n":"Extensión de tríceps con mancuernas en banco inclinado","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas hacia adentro.","Extiende completamente los brazos por encima de la cabeza, manteniendo los codos cerca de la cabeza.","Baja las mancuernas detrás de la cabeza flexionando los codos, manteniendo los brazos superiores quietos.","Haz una pausa por un momento, luego levanta las mancuernas de vuelta a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."],"img":"0330-OVIKwsd.jpg","gif":"0330-OVIKwsd.gif"},{"id":"0331","n":"Aperturas inclinadas con mancuernas y giro","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas enfrentadas entre sí.","Recuéstate en el banco y empuja las mancuernas hacia arriba hasta la posición inicial, directamente por encima del pecho, con los brazos extendidos.","Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho.","Mientras bajas las mancuernas, gira las muñecas de modo que las palmas queden mirando hacia adelante en la parte inferior del movimiento.","Invierte el movimiento y lleva las mancuernas de nuevo hacia arriba hasta la posición inicial, contrayendo los músculos del pecho en la parte superior.","Repite el número de repeticiones deseado."],"img":"0331-1PLE8e9.jpg","gif":"0331-1PLE8e9.gif"},{"id":"1733","n":"Extensión a dos brazos con mancuernas en banco inclinado","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Siéntate en un banco inclinado con una mancuerna en cada mano, apoyadas sobre los muslos.","Recuéstate lentamente en el banco, manteniendo las mancuernas cerca del pecho.","Una vez completamente recostado, extiende los brazos rectos hacia el techo, manteniendo los codos ligeramente flexionados.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1733-U7D9Fx3.jpg","gif":"1733-U7D9Fx3.gif"},{"id":"3541","n":"Elevaciones en Y con mancuernas en banco inclinado","bp":"back","eq":"dumbbell","tg":"upper back","mg":"shoulders","sm":["shoulders","rear deltoids"],"st":["Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas hacia adentro.","Inclínate ligeramente hacia adelante y deja que los brazos cuelguen rectos hacia abajo, manteniendo una ligera flexión en los codos.","Levanta los brazos hacia los lados y hacia arriba formando una Y hasta que queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3541-PbzNu7c.jpg","gif":"3541-PbzNu7c.gif"},{"id":"0332","n":"Cruz de hierro con mancuernas","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","chest"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados.","Levanta los brazos hacia los lados hasta que queden paralelos al suelo, formando una T con el cuerpo.","Haz una pausa por un momento, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0332-cALkHHX.jpg","gif":"0332-cALkHHX.gif"},{"id":"0333","n":"Patada de tríceps con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Acerca los brazos superiores a los costados, con los codos flexionados en un ángulo de 90 grados.","Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento.","Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0333-W6PxUkg.jpg","gif":"0333-W6PxUkg.gif"},{"id":"1734","n":"Patada de tríceps con mancuernas sobre balón de estabilidad","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","back"],"st":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.","Sostén una mancuerna en cada mano con las palmas hacia adentro y los brazos flexionados en un ángulo de 90 grados.","Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento.","Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1734-cAvTaSg.jpg","gif":"1734-cAvTaSg.gif"},{"id":"1660","n":"Curl de bíceps con mancuernas de rodillas sobre balón de estabilidad","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Arrodíllate en el suelo con un balón de estabilidad frente a ti.","Coloca los codos sobre el balón de estabilidad, sosteniendo una mancuerna en cada mano con las palmas hacia arriba.","Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas contrayendo los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1660-2JCuFTU.jpg","gif":"1660-2JCuFTU.gif"},{"id":"0334","n":"Elevaciones laterales con mancuernas","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo.","Mantén la espalda recta y activa el core.","Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo una ligera flexión en los codos.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0334-DsgkuIt.jpg","gif":"0334-DsgkuIt.gif"},{"id":"0335","n":"Elevaciones laterales a frontales con mancuernas","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","biceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia el cuerpo.","Mantén la espalda recta y activa el core.","Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo una ligera flexión en los codos.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Luego, levanta los brazos frente a ti hasta que queden paralelos al suelo, manteniendo nuevamente una ligera flexión en los codos.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0335-xMjBKwn.jpg","gif":"0335-xMjBKwn.gif"},{"id":"0336","n":"Zancadas con mancuernas","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.","Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.","Mantén la espalda recta y el pecho erguido mientras bajas el cuerpo.","Empuja con el talón derecho para regresar a la posición inicial.","Repite con la pierna izquierda.","Alterna las piernas el número de repeticiones deseado."],"img":"0336-RRWFUcw.jpg","gif":"0336-RRWFUcw.gif"},{"id":"1658","n":"Zancada con curl de bíceps con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"quadriceps","sm":["quadriceps","hamstrings"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con las palmas hacia adelante.","Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada. La rodilla derecha debe quedar flexionada en un ángulo de 90 grados y la rodilla izquierda debe quedar justo por encima del suelo.","Mientras avanzas en la zancada, flexiona simultáneamente las mancuernas hacia los hombros, manteniendo los codos cerca del cuerpo.","Haz una pausa por un momento en la parte baja de la zancada, luego empuja con el talón derecho para volver a la posición inicial, bajando las mancuernas de nuevo a los costados.","Repite la zancada y el curl de bíceps en el lado opuesto, dando un paso adelante con el pie izquierdo.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"1658-Mz6lLcW.jpg","gif":"1658-Mz6lLcW.gif"},{"id":"0337","n":"Extensión tumbada con mancuerna cruzada sobre la cara","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.","Sostén una mancuerna con ambas manos y extiende los brazos rectos hacia arriba sobre el pecho, con las palmas enfrentadas entre sí.","Manteniendo los brazos superiores quietos, baja lentamente la mancuerna describiendo un arco detrás de la cabeza hasta que los antebrazos queden paralelos al suelo.","Haz una pausa por un momento, luego contrae los tríceps para llevar la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0337-L2V5Nan.jpg","gif":"0337-L2V5Nan.gif"},{"id":"1729","n":"Extensiones alternas tumbado con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí.","Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos.","Baja una mancuerna hacia la cabeza, flexionando el codo, mientras mantienes el otro brazo extendido.","Haz una pausa breve en la parte baja, luego levanta la mancuerna de vuelta a la posición inicial.","Repite con el otro brazo, alternando lados el número de repeticiones deseado."],"img":"1729-NfP83rA.jpg","gif":"1729-NfP83rA.gif"},{"id":"0338","n":"Press de codos tumbado con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí y los brazos extendidos rectos hacia arriba sobre el pecho.","Baja las mancuernas hacia los hombros flexionando los codos, manteniendo los brazos superiores quietos.","Haz una pausa por un momento en la parte inferior, luego empuja las mancuernas de nuevo hacia arriba hasta la posición inicial extendiendo los codos.","Repite el número de repeticiones deseado."],"img":"0338-eOCOwIR.jpg","gif":"0338-eOCOwIR.gif"},{"id":"0863","n":"Rotación externa de hombro con mancuerna tumbado","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","triceps"],"st":["Túmbate de lado en un banco plano con el brazo superior contra el costado y el codo flexionado a 90 grados.","Sostén una mancuerna en la mano con la palma hacia abajo.","Manteniendo el brazo superior contra el costado, gira lentamente el antebrazo hacia arriba lo más posible.","Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"0863-bmBf7LN.jpg","gif":"0863-bmBf7LN.gif"},{"id":"0339","n":"Curl femoral con mancuerna tumbado","bp":"upper legs","eq":"dumbbell","tg":"hamstrings","mg":"glutes","sm":["glutes"],"st":["Túmbate boca arriba con las piernas extendidas y una mancuerna apoyada sobre el abdomen bajo.","Flexiona las rodillas y lleva la mancuerna hacia los glúteos, manteniendo los pies apoyados en el suelo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0339-FkBIE6a.jpg","gif":"0339-FkBIE6a.gif"},{"id":"0340","n":"Press martillo con mancuernas tumbado","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí y los brazos extendidos rectos hacia arriba.","Baja las mancuernas a los lados del pecho, manteniendo los codos en un ángulo de 90 grados.","Empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"0340-7gdLIXa.jpg","gif":"0340-7gdLIXa.gif"},{"id":"2470","n":"Elevación para deltoides posterior con mancuernas tumbado en el suelo","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Túmbate boca abajo en el suelo con una mancuerna en cada mano, con las palmas enfrentadas entre sí.","Extiende los brazos rectos frente a ti, manteniendo una ligera flexión en los codos.","Activando los músculos de los hombros, levanta los brazos hacia arriba y hacia los lados, juntando los omóplatos.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2470-Ion0XWz.jpg","gif":"2470-Ion0XWz.gif"},{"id":"0341","n":"Pájaro a un brazo con mancuerna tumbado","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Túmbate boca abajo en un banco plano con una mancuerna en una mano, con la palma hacia adentro.","Extiende el brazo recto hacia el suelo, manteniéndolo cerca del cuerpo.","Levanta el brazo hacia arriba y hacia atrás, acercando el omóplato hacia la columna.","Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"0341-gSw59a4.jpg","gif":"0341-gSw59a4.gif"},{"id":"0343","n":"Press con mancuerna a un brazo tumbado agarre supino","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Túmbate boca arriba en un banco con una mancuerna en una mano y los pies apoyados en el suelo.","Sostén la mancuerna a la altura del hombro con la palma hacia adelante.","Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"0343-zGSIWQi.jpg","gif":"0343-zGSIWQi.gif"},{"id":"0342","n":"Press con mancuerna a un brazo tumbado agarre neutro","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Túmbate boca arriba en un banco con la espalda apoyada y los pies planos sobre el suelo.","Sostén una mancuerna en una mano con la palma hacia los pies.","Extiende el brazo recto hacia el techo, manteniendo el codo ligeramente flexionado.","Baja lentamente la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo.","Haz una pausa por un momento en la parte inferior, luego empuja la mancuerna de nuevo hacia arriba hasta la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"0342-K3dIO25.jpg","gif":"0342-K3dIO25.gif"},{"id":"0344","n":"Extensión de tríceps a un brazo tumbado con agarre prono con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Túmbate boca arriba en un banco con la espalda y la cabeza apoyadas, y los pies planos sobre el suelo.","Sostén una mancuerna en una mano con la palma hacia abajo, y extiende el brazo recto por encima del hombro.","Manteniendo el brazo superior quieto, baja lentamente la mancuerna detrás de la cabeza flexionando el codo.","Haz una pausa por un momento en la parte inferior, luego extiende el brazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"0344-wyaqzOS.jpg","gif":"0344-wyaqzOS.gif"},{"id":"0345","n":"Elevación lateral posterior a un brazo con mancuerna tumbado","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","rhomboids"],"st":["Túmbate boca abajo en un banco plano con una mancuerna en una mano, colgando hacia el suelo.","Mantén el brazo recto y levanta la mancuerna hacia el lado, alejándola del cuerpo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"0345-KwFGiEP.jpg","gif":"0345-KwFGiEP.gif"},{"id":"0346","n":"Extensión de tríceps a un brazo tumbado con agarre supino con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"forearms","sm":["forearms"],"st":["Túmbate boca arriba en un banco con la espalda y la cabeza apoyadas, y los pies planos sobre el suelo.","Sostén una mancuerna en una mano con agarre supino, y extiende el brazo recto por encima del hombro.","Manteniendo el brazo superior quieto, baja lentamente la mancuerna detrás de la cabeza flexionando el codo.","Haz una pausa por un momento en la parte inferior, luego extiende el brazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"0346-zZlORz6.jpg","gif":"0346-zZlORz6.gif"},{"id":"0347","n":"Pronación con mancuerna tumbado","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"biceps","sm":["biceps","shoulders"],"st":["Túmbate boca abajo en un banco con el pecho hacia abajo y los brazos extendidos rectos hacia abajo, sosteniendo una mancuerna en cada mano.","Gira las palmas de modo que queden mirando hacia arriba.","Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas mientras giras las palmas hacia abajo.","Inhala y baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0347-mym4hJo.jpg","gif":"0347-mym4hJo.gif"},{"id":"2705","n":"Pronación con mancuerna tumbado en el suelo","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"biceps","sm":["biceps","triceps"],"st":["Túmbate boca abajo en el suelo con los brazos extendidos rectos frente a ti, sosteniendo una mancuerna en cada mano.","Gira las palmas de modo que queden mirando hacia el suelo.","Manteniendo los brazos rectos, levanta las mancuernas del suelo contrayendo los antebrazos.","Continúa levantando hasta que los antebrazos estén completamente contraídos y las mancuernas queden a la altura de los hombros.","Mantén la posición por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2705-7RWNjiB.jpg","gif":"2705-7RWNjiB.gif"},{"id":"1284","n":"Pullover con mancuerna tumbado sobre pelota de pilates","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","back"],"st":["Siéntate sobre un balón de estabilidad y rueda hacia adelante hasta que la parte superior de la espalda quede apoyada en el balón.","Sostén una mancuerna con ambas manos y extiende los brazos rectos hacia arriba sobre el pecho.","Baja lentamente la mancuerna detrás de la cabeza manteniendo los brazos rectos.","Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1284-iK59oEA.jpg","gif":"1284-iK59oEA.gif"},{"id":"1328","n":"Remo para deltoides posterior con mancuernas tumbado","bp":"back","eq":"dumbbell","tg":"upper back","mg":"shoulders","sm":["shoulders","biceps"],"st":["Túmbate boca abajo en un banco plano con una mancuerna en cada mano, con las palmas hacia adentro.","Extiende los brazos rectos hacia el suelo, manteniendo una ligera flexión en los codos.","Activando los músculos de la espalda, levanta las mancuernas hacia el pecho, juntando los omóplatos.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1328-XUUD0Fs.jpg","gif":"1328-XUUD0Fs.gif"},{"id":"0348","n":"Elevaciones laterales posteriores con mancuernas tumbado","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","rhomboids"],"st":["Túmbate boca abajo en un banco plano con una mancuerna en cada mano, con las palmas enfrentadas entre sí.","Extiende los brazos rectos hacia el suelo, manteniendo una ligera flexión en los codos.","Activando los músculos de los hombros, levanta los brazos hacia los lados hasta que queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0348-53Ttlck.jpg","gif":"0348-53Ttlck.gif"},{"id":"1735","n":"Extensión a un brazo con mancuerna tumbado","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Túmbate boca arriba en un banco con una mancuerna en una mano y el brazo completamente extendido por encima del pecho.","Baja la mancuerna de manera controlada hacia la frente, manteniendo el brazo superior quieto.","Haz una breve pausa en la parte inferior del movimiento, luego extiende el brazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1735-6MfS53i.jpg","gif":"1735-6MfS53i.gif"},{"id":"0349","n":"Supinación con mancuerna tumbado","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"biceps","sm":["biceps","shoulders"],"st":["Túmbate boca arriba en un banco con los pies planos sobre el suelo.","Sostén una mancuerna en cada mano con las palmas hacia arriba y los brazos completamente extendidos.","Manteniendo los brazos superiores quietos, flexiona las mancuernas hacia los hombros contrayendo los antebrazos.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0349-M2Pm3zj.jpg","gif":"0349-M2Pm3zj.gif"},{"id":"2706","n":"Supinación con mancuerna tumbado en el suelo","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"biceps","sm":["biceps","shoulders"],"st":["Túmbate boca arriba en el suelo con las piernas extendidas y los brazos a los costados, sosteniendo una mancuerna en cada mano.","Gira las palmas hacia arriba, manteniendo los codos cerca de los costados.","Flexiona lentamente las mancuernas hacia los hombros, contrayendo los antebrazos.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2706-rEhi2o5.jpg","gif":"2706-rEhi2o5.gif"},{"id":"1661","n":"Curl de bíceps supino con mancuernas tumbado","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Túmbate boca arriba en un banco con la espalda y la cabeza apoyadas, y los pies planos sobre el suelo.","Sostén una mancuerna en cada mano con las palmas hacia arriba y los brazos completamente extendidos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1661-XVzF3iZ.jpg","gif":"1661-XVzF3iZ.gif"},{"id":"0350","n":"Curl supino con mancuernas tumbado","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas hacia arriba y los brazos completamente extendidos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0350-KUaZst7.jpg","gif":"0350-KUaZst7.gif"},{"id":"0351","n":"Extensión de tríceps tumbado con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí.","Extiende los brazos rectos hacia arriba sobre el pecho, manteniendo los codos cerca del cuerpo.","Baja las mancuernas hacia la frente, flexionando los codos.","Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0351-mpKZGWz.jpg","gif":"0351-mpKZGWz.gif"},{"id":"1662","n":"Curl tumbado con agarre ancho con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas hacia arriba y los brazos completamente extendidos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1662-qm9veZw.jpg","gif":"1662-qm9veZw.gif"},{"id":"0352","n":"Press de banca con mancuernas y agarre neutro","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Sostén una mancuerna en cada mano con agarre neutro (palmas enfrentadas entre sí) y los brazos extendidos rectos hacia arriba sobre el pecho.","Baja lentamente las mancuernas hacia el pecho, manteniendo los codos cerca del cuerpo.","Haz una pausa por un momento en la parte inferior, luego empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"0352-pP8wP2P.jpg","gif":"0352-pP8wP2P.gif"},{"id":"1285","n":"Aperturas en banco a un brazo con mancuerna","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders"],"st":["Siéntate en un banco plano con una mancuerna en una mano, apoyándola sobre el muslo.","Recuéstate en el banco, manteniendo la mancuerna presionada contra el muslo.","Usando la mano libre, ayuda a levantar la mancuerna hasta la posición inicial.","Sostén la mancuerna directamente sobre el hombro con el brazo extendido y la palma hacia adentro.","Baja la mancuerna hacia el lado describiendo un amplio arco, manteniendo una ligera flexión en el codo.","Haz una pausa cuando el brazo esté paralelo al suelo, luego invierte el movimiento y lleva la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo y repite."],"img":"1285-o5Jsk92.jpg","gif":"1285-o5Jsk92.gif"},{"id":"0292","n":"Remo inclinado a un brazo con mancuerna","bp":"back","eq":"dumbbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con la palma hacia el cuerpo.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.","Deja que la mancuerna cuelgue recta hacia el suelo, con el brazo completamente extendido.","Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"0292-C0MA9bC.jpg","gif":"0292-C0MA9bC.gif"},{"id":"1286","n":"Aperturas de pecho a un brazo con mancuerna sobre fitball","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Siéntate sobre un balón de estabilidad con una mancuerna en una mano y los pies apoyados en el suelo.","Camina con los pies hacia adelante, haciendo rodar el balón hasta que la parte superior de la espalda quede apoyada en el balón y la cabeza, el cuello y los hombros queden fuera de él.","Extiende el brazo con la mancuerna recto hacia arriba sobre el pecho, con la palma hacia adentro.","Baja lentamente la mancuerna hacia el lado, manteniendo una ligera flexión en el codo.","Haz una pausa por un momento cuando el brazo esté paralelo al suelo.","Activa los músculos del pecho para llevar la mancuerna de nuevo hacia arriba hasta la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1286-Bpkf41o.jpg","gif":"1286-Bpkf41o.gif"},{"id":"0353","n":"Curl concentrado a un brazo con mancuerna (sobre pelota de estabilidad)","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate sobre un balón de estabilidad con los pies apoyados planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Sostén una mancuerna en una mano con la palma hacia arriba y el brazo extendido hacia el suelo.","Apoya el codo en la parte interna del muslo, justo por encima de la rodilla.","Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps.","Haz una pausa por un momento en la parte superior del movimiento, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo y repite."],"img":"0353-k5IpyHg.jpg","gif":"0353-k5IpyHg.gif"},{"id":"1287","n":"Press de pecho declinado a un brazo con mancuerna","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Túmbate en un banco declinado con una mancuerna en una mano, apoyada sobre el pecho.","Coloca los pies planos sobre el suelo y mantén la espalda presionada contra el banco.","Extiende el brazo y empuja la mancuerna hacia el techo, extendiendo completamente el codo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"1287-REGM1dE.jpg","gif":"1287-REGM1dE.gif"},{"id":"1288","n":"Aperturas a un brazo con mancuerna sobre fitball","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Siéntate sobre un balón de estabilidad con una mancuerna en una mano y los pies apoyados en el suelo.","Camina con los pies hacia adelante y baja el cuerpo rodando hasta que la parte superior de la espalda quede apoyada sobre el balón de estabilidad.","Extiende el brazo con la mancuerna recto hacia arriba sobre el pecho, con la palma hacia adentro.","Baja lentamente la mancuerna hacia el lado, manteniendo una ligera flexión en el codo.","Haz una pausa por un momento, luego contrae los músculos del pecho para llevar la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1288-Am02iPd.jpg","gif":"1288-Am02iPd.gif"},{"id":"1736","n":"Press francés a un brazo con mancuerna sobre fitball","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.","Sostén una mancuerna en una mano con la palma hacia arriba y el codo flexionado en un ángulo de 90 grados.","Extiende el brazo recto hacia el techo, manteniendo el codo quieto.","Baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1736-ziFKQXP.jpg","gif":"1736-ziFKQXP.gif"},{"id":"1663","n":"Curl predicador tipo martillo a un brazo con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco scott con una mancuerna en una mano y el brazo superior apoyado sobre la almohadilla.","Sostén la mancuerna con agarre neutro (palmas hacia el cuerpo).","Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1663-4dF3maG.jpg","gif":"1663-4dF3maG.gif"},{"id":"1621","n":"Press con agarre neutro a un brazo con mancuerna sobre fitball","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","chest"],"st":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.","Sostén una mancuerna en una mano con la palma hacia adentro y el codo flexionado en un ángulo de 90 grados.","Coloca la otra mano en la cadera para mantener el equilibrio.","Empuja la mancuerna hacia arriba, extendiendo completamente el brazo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1621-VYmYxK5.jpg","gif":"1621-VYmYxK5.gif"},{"id":"1289","n":"Press de pecho inclinado a un brazo con mancuerna","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Ajusta el banco inclinado a un ángulo de 45 grados.","Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo.","Sostén una mancuerna en una mano con agarre prono, apoyándola sobre el hombro.","Empuja la mancuerna hacia arriba y alejándola del cuerpo, extendiendo completamente el brazo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"1289-PDaMuyV.jpg","gif":"1289-PDaMuyV.gif"},{"id":"0354","n":"Patada de tríceps a un brazo con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en la mano derecha.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Lleva el codo derecho hacia el costado, manteniéndolo flexionado en un ángulo de 90 grados.","Extiende el brazo derecho recto hacia atrás, contrayendo el tríceps en la parte superior del movimiento.","Baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"0354-bQy2Eni.jpg","gif":"0354-bQy2Eni.gif"},{"id":"0355","n":"Elevación lateral a un brazo con mancuerna","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","triceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con la palma hacia el cuerpo.","Mantén la espalda recta y el core activado durante todo el ejercicio.","Levanta la mancuerna hacia el lado, manteniendo el brazo recto y la palma hacia abajo.","Continúa levantando hasta que el brazo quede paralelo al suelo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"0355-n5cWCsI.jpg","gif":"0355-n5cWCsI.gif"},{"id":"0356","n":"Elevación lateral con apoyo a un brazo con mancuerna","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rotator cuff"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en una mano, con la palma hacia el cuerpo.","Coloca la otra mano sobre una superficie estable, como un banco o una pared, para apoyarte.","Mantén la espalda recta y activa el core.","Levanta la mancuerna hacia el lado, manteniendo el brazo recto y la palma hacia abajo.","Continúa levantando hasta que el brazo quede paralelo al suelo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"0356-Yg7MJAT.jpg","gif":"0356-Yg7MJAT.gif"},{"id":"1290","n":"Press a un brazo con mancuerna sobre fitball","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps","core"],"st":["Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Sostén una mancuerna en una mano y colócala a la altura del hombro, con el codo flexionado y la palma hacia adelante.","Empuja lentamente la mancuerna hacia arriba hasta que el brazo quede completamente extendido, manteniendo el core activado y el equilibrio sobre el balón de estabilidad.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"1290-QZFv5ui.jpg","gif":"1290-QZFv5ui.gif"},{"id":"1665","n":"Curl en decúbito prono a un brazo con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Túmbate boca abajo en un banco plano con una mancuerna en una mano, con la palma hacia abajo.","Extiende completamente el brazo, dejando que cuelgue recto hacia el suelo.","Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro contrayendo el bíceps.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1665-JWjujiY.jpg","gif":"1665-JWjujiY.gif"},{"id":"1666","n":"Curl martillo en decúbito prono a un brazo con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Túmbate boca abajo en un banco plano con una mancuerna en una mano, con la palma hacia el cuerpo y el brazo completamente extendido.","Mantén el brazo superior quieto y flexiona la mancuerna hacia el hombro, contrayendo el bíceps.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1666-LIGZSTA.jpg","gif":"1666-LIGZSTA.gif"},{"id":"1291","n":"Pullover a un brazo con mancuerna sobre fitball","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","latissimus dorsi","rhomboids"],"st":["Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Sostén una mancuerna con una mano y extiende el brazo recto hacia arriba sobre el pecho.","Baja lentamente la mancuerna detrás de la cabeza manteniendo el brazo recto.","Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1291-bQHPBU3.jpg","gif":"1291-bQHPBU3.gif"},{"id":"0358","n":"Curl de muñeca inverso a un brazo con mancuerna","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"wrist extensors","sm":["wrist extensors"],"st":["Siéntate en un banco o silla con los pies apoyados en el suelo.","Sostén una mancuerna en una mano con agarre prono, con la palma hacia abajo.","Apoya el antebrazo sobre el muslo, con la muñeca colgando fuera del borde.","Baja lentamente la mancuerna hacia el suelo flexionando la muñeca.","Haz una pausa por un momento en la parte inferior, luego flexiona lentamente la muñeca de vuelta hacia el cuerpo.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"0358-BwSNDGt.jpg","gif":"0358-BwSNDGt.gif"},{"id":"0359","n":"Pájaros a un brazo con mancuerna (con apoyo)","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Siéntate en un banco con los pies apoyados planos en el suelo y la espalda recta.","Sostén una mancuerna en una mano con la palma hacia adentro.","Inclínate hacia adelante y coloca la mano libre sobre el banco para apoyarte.","Mantén el brazo ligeramente flexionado y levántalo hacia el lado hasta que quede paralelo al suelo.","Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"0359-e25F58f.jpg","gif":"0359-e25F58f.gif"},{"id":"1622","n":"Press a un brazo con agarre inverso con mancuerna","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Siéntate en un banco plano con una mancuerna en una mano, con la palma hacia el cuerpo.","Coloca los pies planos sobre el suelo y mantén la espalda recta.","Levanta la mancuerna hasta la altura del hombro, manteniendo el codo cerca del cuerpo.","Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"1622-Ze7MoIb.jpg","gif":"1622-Ze7MoIb.gif"},{"id":"1414","n":"Curl predicador inverso a un brazo con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco scott con el pecho contra la almohadilla y el brazo extendido sobre el borde del banco, sosteniendo una mancuerna con agarre supino.","Baja lentamente la mancuerna hasta que el brazo quede completamente extendido.","Flexiona la mancuerna de nuevo hacia el hombro, manteniendo el brazo superior quieto.","Contrae el bíceps en la parte más alta del movimiento, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1414-bWxq4op.jpg","gif":"1414-bWxq4op.gif"},{"id":"1667","n":"Curl araña inverso a un brazo con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con una mancuerna en una mano, con la palma hacia abajo y el brazo completamente extendido.","Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro flexionando el codo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1667-VdLZ3nB.jpg","gif":"1667-VdLZ3nB.gif"},{"id":"1668","n":"Curl de bíceps sentado a un brazo sobre pelota de ejercicios con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.","Sostén una mancuerna en una mano con la palma hacia arriba y el brazo completamente extendido.","Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro contrayendo el bíceps.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1668-s999Hdo.jpg","gif":"1668-s999Hdo.gif"},{"id":"1669","n":"Curl martillo sentado a un brazo con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sostén una mancuerna en una mano con agarre neutro (palmas enfrentadas entre sí).","Apoya el codo en la parte interna del muslo, justo por encima de la rodilla.","Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1669-jK2hZ6n.jpg","gif":"1669-jK2hZ6n.gif"},{"id":"1415","n":"Curl de muñeca con agarre neutro sentado a un brazo con mancuerna","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"biceps","sm":["biceps","brachialis"],"st":["Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en una mano, con la palma hacia arriba.","Apoya el antebrazo sobre el muslo, dejando que la muñeca cuelgue fuera del borde.","Manteniendo el antebrazo quieto, flexiona la muñeca hacia arriba lo más posible.","Haz una pausa por un momento en la parte superior, luego baja lentamente la muñeca de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia a la otra mano."],"img":"1415-YtaCTYl.jpg","gif":"1415-YtaCTYl.gif"},{"id":"0361","n":"Press de hombros a un brazo con mancuerna agarre prono y mancuerna isométrica en el otro brazo","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en una mano a la altura del hombro, con la palma hacia adelante.","Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido por encima de la cabeza.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"0361-84RyJf8.jpg","gif":"0361-84RyJf8.gif"},{"id":"0360","n":"Press de hombros a un brazo con mancuerna agarre prono","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en una mano a la altura del hombro, con la palma hacia adelante.","Activa el core y empuja la mancuerna directamente hacia arriba por encima de la cabeza, extendiendo completamente el brazo.","Haz una pausa por un momento en la parte superior, luego baja lentamente la mancuerna de vuelta a la altura del hombro.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"0360-1TkiAFK.jpg","gif":"0360-1TkiAFK.gif"},{"id":"3888","n":"Arrancada a un brazo con mancuerna","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con agarre prono.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.","Baja la mancuerna hacia el suelo, manteniéndola cerca del cuerpo.","Extiende explosivamente las caderas, las rodillas y los tobillos, impulsando la mancuerna hacia arriba en línea recta.","Cuando la mancuerna alcance la altura del hombro, gira rápidamente la mano y empújala por encima de la cabeza, extendiendo completamente el brazo.","Recibe la mancuerna por encima de la cabeza con una ligera flexión en las rodillas y las caderas.","Baja la mancuerna de nuevo a la posición inicial de manera controlada.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"3888-6pTkI99.jpg","gif":"3888-6pTkI99.gif"},{"id":"1670","n":"Curl de pie a un brazo con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con una mancuerna en una mano, con la palma hacia adelante y el brazo completamente extendido.","Manteniendo el brazo superior quieto, exhala y flexiona el peso hacia arriba contrayendo el bíceps.","Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1670-ffQsyBj.jpg","gif":"1670-ffQsyBj.gif"},{"id":"1671","n":"Curl martillo de pie a un brazo con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso.","Mantén los codos cerca del torso y los brazos superiores quietos.","Exhala y flexiona las pesas mientras contraes los bíceps.","Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1671-2sQGZ5b.jpg","gif":"1671-2sQGZ5b.gif"},{"id":"0362","n":"Extensión de tríceps a un brazo en banco con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sostén una mancuerna en una mano y coloca la otra mano sobre el banco para apoyarte.","Levanta la mancuerna por encima de la cabeza, manteniendo el brazo superior cerca de la cabeza y el codo apuntando hacia adelante.","Baja la mancuerna detrás de la cabeza flexionando el codo, manteniendo el brazo superior quieto.","Extiende el brazo de vuelta a la posición inicial, estirando completamente el codo.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"0362-nAuHPcD.jpg","gif":"0362-nAuHPcD.gif"},{"id":"0363","n":"Remo al cuello a un brazo con mancuerna","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","biceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con agarre prono.","Deja que la mancuerna cuelgue a la distancia de un brazo frente a los muslos, con la palma hacia el cuerpo.","Manteniendo la espalda recta y el core activado, exhala y levanta la mancuerna recta hacia la barbilla, guiando con el codo.","Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"0363-6cKQC5E.jpg","gif":"0363-6cKQC5E.gif"},{"id":"0364","n":"Curl de muñeca a un brazo con mancuerna","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"biceps","sm":["biceps","brachialis"],"st":["Siéntate en un banco o silla con los pies apoyados en el suelo.","Sostén una mancuerna en una mano con agarre supino, apoyando el antebrazo sobre el muslo.","Permite que la muñeca se extienda, dejando que la mancuerna ruede hacia los dedos.","Flexiona lentamente la muñeca hacia arriba, acercando la mancuerna hacia el antebrazo.","Repite el número de repeticiones deseado, luego cambia a la otra mano."],"img":"0364-q8aHNoF.jpg","gif":"0364-q8aHNoF.gif"},{"id":"1672","n":"Curl predicador Zottman a un brazo con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco scott y sostén una mancuerna en una mano con agarre supino.","Apoya el brazo superior sobre la almohadilla del banco scott, permitiendo que el brazo se extienda completamente.","Flexiona la mancuerna de nuevo hacia el hombro, manteniendo el brazo superior quieto.","En la parte superior del curl, gira la muñeca de modo que la palma quede hacia arriba.","Baja lentamente la mancuerna de vuelta a la posición inicial, girando la muñeca de regreso a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1672-sxY5Biu.jpg","gif":"1672-sxY5Biu.gif"},{"id":"1292","n":"Aperturas a una pierna sobre pelota de ejercicios con mancuernas","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Siéntate sobre un balón de estabilidad con una mancuerna en cada mano, con las palmas enfrentadas entre sí.","Coloca un pie en el suelo y extiende la otra pierna recta hacia adelante.","Inclínate ligeramente hacia adelante y lleva los brazos hacia los lados, manteniendo una ligera flexión en los codos.","Baja lentamente las mancuernas hacia abajo y hacia los lados, sintiendo un estiramiento en el pecho.","Haz una pausa por un momento en la parte inferior, luego contrae los músculos del pecho para llevar las mancuernas de nuevo hacia arriba hasta la posición inicial.","Repite el número de repeticiones deseado y luego cambia de pierna y repite."],"img":"1292-pH2x2jj.jpg","gif":"1292-pH2x2jj.gif"},{"id":"0365","n":"Curl de muñeca con agarre neutro sobre banco con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en cada mano, con las palmas hacia arriba.","Apoya los antebrazos sobre el banco, dejando que las muñecas cuelguen del borde.","Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas hacia los hombros.","Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0365-BKa8dmT.jpg","gif":"0365-BKa8dmT.gif"},{"id":"0366","n":"Curl de muñeca con agarre neutro a un brazo sobre banco con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco con una mancuerna en una mano y el brazo extendido sobre el banco, con la palma hacia arriba.","Mantén el brazo superior quieto y flexiona la mancuerna hacia el hombro, manteniendo la muñeca en posición neutra.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"0366-IvV6C9M.jpg","gif":"0366-IvV6C9M.gif"},{"id":"1441","n":"Curl de muñeca inverso a un brazo con mancuerna sobre banco","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"biceps","sm":["biceps","brachialis"],"st":["Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano, con la palma hacia abajo.","Apoya el antebrazo en el banco con la muñeca colgando del borde.","Flexiona lentamente la muñeca hacia arriba, acercando la mancuerna hacia el antebrazo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"1441-4Jc36XM.jpg","gif":"1441-4Jc36XM.gif"},{"id":"0367","n":"Curl de muñeca a un brazo con mancuerna sobre banco","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"biceps","sm":["biceps","shoulders"],"st":["Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano, con la palma hacia abajo.","Apoya el antebrazo en el banco con la muñeca colgando del borde.","Flexiona lentamente la muñeca hacia arriba, acercando la mancuerna hacia el antebrazo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"0367-KI1DjNN.jpg","gif":"0367-KI1DjNN.gif"},{"id":"0368","n":"Curl de muñeca inverso con mancuernas sobre banco","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"biceps","sm":["biceps","brachialis"],"st":["Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna en cada mano, con las palmas hacia abajo.","Apoya los antebrazos sobre el banco, dejando que las muñecas cuelguen del borde.","Flexiona lentamente las muñecas hacia arriba, acercando las mancuernas hacia tu cuerpo.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0368-3tAXPQ6.jpg","gif":"0368-3tAXPQ6.gif"},{"id":"0369","n":"Curl de muñeca con mancuernas sobre banco","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"biceps","sm":["biceps","brachialis"],"st":["Siéntate en un banco con los antebrazos apoyados en él y las palmas hacia arriba, sujetando una mancuerna en cada mano.","Deja que tus muñecas cuelguen del borde del banco.","Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos en la parte superior del movimiento.","Haz una pausa por un momento y luego baja lentamente las muñecas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0369-D1xYJAU.jpg","gif":"0369-D1xYJAU.gif"},{"id":"1329","n":"Remo inclinado con mancuernas y rotación de palmas","bp":"back","eq":"dumbbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.","Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y las rodillas ligeramente flexionadas.","Deja que los brazos cuelguen rectos hacia abajo, con las palmas hacia tu cuerpo.","Activa el core y tira de las mancuernas hacia tu pecho, manteniendo los codos cerca del cuerpo.","Mientras subes las mancuernas, gira las palmas para que queden mirando hacia afuera, alejadas de tu cuerpo.","Junta los omóplatos en la parte superior del movimiento.","Baja lentamente las mancuernas hasta la posición inicial, girando las palmas de vuelta a su posición original.","Repite el número de repeticiones deseado."],"img":"1329-wt6rwjk.jpg","gif":"1329-wt6rwjk.gif"},{"id":"1623","n":"Press de banca inclinado con mancuernas y agarre neutro","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Coloca un banco inclinado a un ángulo de 45 grados.","Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos en el suelo.","Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia adentro.","Extiende los brazos rectos hacia arriba, por encima del pecho, manteniendo una ligera flexión en los codos.","Baja las mancuernas lentamente hacia los hombros, manteniendo los codos cerca del cuerpo.","Haz una pausa por un momento en la posición más baja y luego presiona las mancuernas de vuelta hacia arriba, hasta la posición inicial.","Repite el número de repeticiones deseado."],"img":"1623-8eqjhOl.jpg","gif":"1623-8eqjhOl.gif"},{"id":"0370","n":"Curl martillo en banco Scott con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso.","Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante.","Esta será tu posición inicial.","Ahora, manteniendo los brazos superiores quietos, exhala y flexiona los brazos contrayendo los bíceps.","Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Luego, inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones recomendado."],"img":"0370-F1KxjBa.jpg","gif":"0370-F1KxjBa.gif"},{"id":"0371","n":"Sentadilla pliométrica con mancuernas","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados.","Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.","Cuando llegues al punto más bajo de la sentadilla, impúlsate explosivamente hacia arriba, saltando del suelo.","Mientras estás en el aire, cambia rápidamente la posición de los pies, aterrizando con el pie opuesto adelante.","Baja inmediatamente el cuerpo de vuelta a la posición de sentadilla y repite el salto, cambiando de nuevo los pies.","Continúa alternando la posición de los pies en cada salto durante el número de repeticiones deseado."],"img":"0371-S4pwGlc.jpg","gif":"0371-S4pwGlc.gif"},{"id":"0372","n":"Curl de bíceps en banco Scott con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco scott con la parte superior de los brazos apoyada en la almohadilla y el pecho contra ella.","Sostén una mancuerna en cada mano con las palmas hacia arriba y los brazos completamente extendidos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0372-jivWf8n.jpg","gif":"0372-jivWf8n.gif"},{"id":"1673","n":"Curl de bíceps predicador con mancuerna sobre fitball","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.","Sujeta una mancuerna con una mano con agarre supino, apoyando el codo sobre el balón de estabilidad.","Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro.","Haz una pausa por un momento arriba, luego inhala y baja lentamente la mancuerna a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1673-hwygydB.jpg","gif":"1673-hwygydB.gif"},{"id":"1293","n":"Press con mancuernas sobre fitball","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Siéntate sobre un balón de estabilidad con los pies planos en el suelo y una mancuerna en cada mano, apoyadas sobre los muslos.","Camina lentamente hacia adelante con los pies, haciendo rodar el balón de estabilidad hasta que tu zona lumbar quede apoyada sobre el balón y tus rodillas formen un ángulo de 90 grados.","Sube las mancuernas hasta la altura de los hombros, con las palmas hacia adelante.","Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1293-O8o7q4d.jpg","gif":"1293-O8o7q4d.gif"},{"id":"0373","n":"Extensión de tríceps con mancuernas y agarre prono","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco o silla con la espalda recta y los pies apoyados en el suelo.","Sujeta una mancuerna con ambas manos, con las palmas hacia abajo, y extiende los brazos rectos por encima de la cabeza.","Manteniendo la parte superior de los brazos cerca de la cabeza y los codos apuntando hacia adelante, baja lentamente la mancuerna detrás de la cabeza flexionando los codos.","Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0373-bpJL2Qs.jpg","gif":"0373-bpJL2Qs.gif"},{"id":"0374","n":"Curl de bíceps prono en banco inclinado con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ajusta el banco a una inclinación de 45 grados.","Túmbate boca abajo en el banco con el pecho y el abdomen apoyados contra él.","Sujeta una mancuerna en cada mano con las palmas hacia abajo y los brazos completamente extendidos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0374-mwpPcr1.jpg","gif":"0374-mwpPcr1.gif"},{"id":"1674","n":"Curl martillo prono en banco inclinado con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ajusta el banco a una inclinación de 45 grados.","Túmbate boca abajo en el banco con una mancuerna en cada mano, con las palmas mirándose entre sí.","Deja que los brazos cuelguen rectos hacia el suelo, manteniendo los codos ligeramente flexionados.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1674-cWemPG8.jpg","gif":"1674-cWemPG8.gif"},{"id":"0375","n":"Pullover con mancuerna","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"latissimus dorsi","sm":["latissimus dorsi","triceps"],"st":["Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo.","Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima del pecho.","Manteniendo una ligera flexión en los codos, baja lentamente la mancuerna detrás de la cabeza hasta sentir un estiramiento en el pecho y los hombros.","Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0375-9XjtHvS.jpg","gif":"0375-9XjtHvS.gif"},{"id":"1294","n":"Pullover con extensión de cadera sobre fitball con mancuerna","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Siéntate sobre un balón de estabilidad con los pies planos en el suelo y la mancuerna apoyada sobre los muslos.","Camina lentamente hacia adelante con los pies, haciendo rodar el balón de estabilidad por tu espalda hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón.","Sujeta la mancuerna con ambas manos y extiende los brazos rectos por encima del pecho, manteniendo una ligera flexión en los codos.","Baja la mancuerna detrás de la cabeza, manteniendo los brazos rectos y con control total.","Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial.","Manteniendo los brazos extendidos, levanta las caderas del suelo, apretando los glúteos y activando el core.","Baja las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1294-lI7easp.jpg","gif":"1294-lI7easp.gif"},{"id":"1295","n":"Pullover con mancuerna sobre fitball","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","latissimus dorsi"],"st":["Siéntate sobre un balón de estabilidad y sujeta una mancuerna con ambas manos por encima del pecho, con los brazos extendidos.","Baja lentamente la mancuerna detrás de la cabeza manteniendo los brazos rectos.","Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1295-FSD6PGL.jpg","gif":"1295-FSD6PGL.gif"},{"id":"1700","n":"Push press con mancuernas","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros.","Flexiona ligeramente las rodillas y baja el cuerpo, luego extiende las piernas de forma explosiva y presiona las mancuernas por encima de la cabeza.","Bloquea los brazos en la parte superior del movimiento, luego baja las mancuernas de vuelta a la altura de los hombros.","Repite el número de repeticiones deseado."],"img":"1700-FS63wTN.jpg","gif":"1700-FS63wTN.gif"},{"id":"0376","n":"Elevación con mancuernas","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","rhomboids"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo.","Mantén la espalda recta y activa el core.","Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo una ligera flexión en los codos.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0376-c9MnDRp.jpg","gif":"0376-c9MnDRp.gif"},{"id":"2292","n":"Pájaros con mancuernas para deltoides posterior","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2292-mu5Guxt.jpg","gif":"2292-mu5Guxt.gif"},{"id":"0377","n":"Remo con mancuernas para deltoides posterior (hombro)","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo.","Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado.","Extiende los brazos rectos hacia el suelo, con una ligera flexión en los codos.","Levanta las mancuernas hacia los lados, apretando los omóplatos entre sí.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0377-EKXOMEh.jpg","gif":"0377-EKXOMEh.gif"},{"id":"0378","n":"Pájaros con mancuernas","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Extiende los brazos rectos hacia el suelo, con las palmas mirándose entre sí.","Manteniendo una ligera flexión en los codos, levanta los brazos hacia los lados y aprieta los omóplatos entre sí.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0378-8DiFDVA.jpg","gif":"0378-8DiFDVA.gif"},{"id":"0380","n":"Elevaciones laterales posteriores con mancuernas","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","rhomboids"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.","Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0380-v1qBec9.jpg","gif":"0380-v1qBec9.gif"},{"id":"0379","n":"Elevaciones laterales posteriores con mancuernas (con apoyo para la cabeza)","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","rhomboids"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0379-UzkLrem.jpg","gif":"0379-UzkLrem.gif"},{"id":"0381","n":"Zancadas hacia atrás con mancuernas","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.","Da un paso hacia atrás con el pie derecho, bajando el cuerpo a una posición de zancada.","Flexiona la rodilla izquierda y baja el cuerpo hasta que el muslo izquierdo quede paralelo al suelo.","Haz una pausa por un momento, luego empuja con el talón izquierdo para volver a la posición inicial.","Repite del otro lado, dando un paso hacia atrás con el pie izquierdo."],"img":"0381-SSsBDwB.jpg","gif":"0381-SSsBDwB.gif"},{"id":"0382","n":"Curl de bíceps con mancuernas y agarre invertido","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con una mancuerna en cada mano, con las palmas hacia abajo y los brazos completamente extendidos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0382-e4ojVhP.jpg","gif":"0382-e4ojVhP.gif"},{"id":"1624","n":"Press de banca con mancuernas y agarre invertido","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Túmbate boca arriba en un banco con los pies apoyados en el suelo y las rodillas flexionadas.","Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia tus pies.","Extiende los brazos rectos hacia el techo, manteniendo una ligera flexión en los codos.","Baja lentamente las mancuernas hacia el pecho, permitiendo que los codos se abran hacia los lados.","Haz una pausa por un momento en la parte inferior, luego empuja las mancuernas de nuevo hacia arriba hasta la posición inicial.","Repite el número de repeticiones deseado."],"img":"1624-UIbGx6H.jpg","gif":"1624-UIbGx6H.gif"},{"id":"0383","n":"Aperturas inversas con mancuernas","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Extiende los brazos rectos hacia adelante, con las palmas mirándose entre sí.","Manteniendo una ligera flexión en los codos, levanta los brazos hacia los lados hasta que queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0383-EAs3xL9.jpg","gif":"0383-EAs3xL9.gif"},{"id":"1330","n":"Remo con mancuerna a un brazo en banco inclinado con agarre supino","bp":"back","eq":"dumbbell","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Coloca un banco inclinado a un ángulo de 45 grados.","Coloca una mancuerna en el suelo junto al banco.","Ponte de pie frente al banco con los pies separados a la altura de los hombros.","Inclínate desde la cintura y coloca la rodilla izquierda y la mano izquierda sobre el banco para apoyarte.","Toma la mancuerna con la mano derecha usando un agarre inverso (con la palma hacia abajo).","Mantén la espalda recta y el core activado.","Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo.","Aprieta los músculos de la espalda en la parte superior del movimiento.","Baja la mancuerna de nuevo a la posición inicial de manera controlada.","Repite el número de repeticiones deseado.","Cambia de lado y repite el ejercicio con el brazo izquierdo."],"img":"1330-ZIViNh1.jpg","gif":"1330-ZIViNh1.gif"},{"id":"1331","n":"Remo con mancuernas a dos brazos en banco inclinado con agarre supino","bp":"back","eq":"dumbbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Coloca un banco inclinado a un ángulo de 45 grados.","Siéntate en el banco con el pecho apoyado en el respaldo y los pies planos en el suelo.","Sujeta una mancuerna en cada mano con agarre supino.","Inclínate hacia adelante y deja que tus brazos cuelguen rectos hacia abajo, completamente extendidos.","Tira de las mancuernas hacia arriba, hacia el pecho, apretando los omóplatos entre sí.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1331-9pQSkH8.jpg","gif":"1331-9pQSkH8.gif"},{"id":"2327","n":"Remo con mancuernas y agarre invertido (mujer)","bp":"back","eq":"dumbbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia tu cuerpo.","Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado.","Deja que tus brazos cuelguen rectos hacia abajo, completamente extendidos, con una ligera flexión en los codos.","Tira de las mancuernas hacia arriba, hacia el pecho, apretando los omóplatos entre sí.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2327-Nh3mvOO.jpg","gif":"2327-Nh3mvOO.gif"},{"id":"0384","n":"Curl predicador invertido con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco predicador con los brazos superiores apoyados en el cojín y el pecho contra el soporte.","Sujeta una mancuerna en cada mano con agarre supino, con las palmas hacia arriba.","Manteniendo la parte superior de los brazos fija, exhala y flexiona las mancuernas mientras contraes los bíceps.","Continúa flexionando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0384-O8Aq69u.jpg","gif":"0384-O8Aq69u.gif"},{"id":"1675","n":"Curl araña invertido con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con la espalda recta, con una mancuerna en cada mano, las palmas hacia tu cuerpo y los brazos completamente extendidos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1675-6sMAmNv.jpg","gif":"1675-6sMAmNv.gif"},{"id":"0385","n":"Curl de muñeca invertido con mancuernas","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"biceps","sm":["biceps","brachialis"],"st":["Siéntate en un banco o silla con los pies apoyados en el suelo.","Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia abajo.","Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde.","Flexiona lentamente las muñecas hacia arriba, acercando las mancuernas hacia tu cuerpo.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0385-BLCvwr2.jpg","gif":"0385-BLCvwr2.gif"},{"id":"1459","n":"Peso muerto rumano con mancuernas","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.","Manteniendo la espalda recta y el core activado, inclínate desde las caderas y baja las mancuernas hacia el suelo, permitiendo que las rodillas se flexionen ligeramente.","Baja las mancuernas hasta sentir un estiramiento en los isquiotibiales, luego empuja con los talones y activa los glúteos para volver a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1459-rR0LJzx.jpg","gif":"1459-rR0LJzx.gif"},{"id":"0386","n":"Pájaros con mancuernas con rotación","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adentro.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.","Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo.","Gira los brazos de modo que las palmas queden mirando hacia abajo.","Baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0386-prbWx1D.jpg","gif":"0386-prbWx1D.gif"},{"id":"2397","n":"Press Scott con mancuernas","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","chest"],"st":["Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adelante.","Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante.","Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2397-5vfAI0I.jpg","gif":"2397-5vfAI0I.gif"},{"id":"0387","n":"Elevaciones frontales alternas sentadas con mancuernas","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","biceps"],"st":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo y los brazos extendidos hacia abajo a los lados.","Manteniendo los brazos rectos, levanta una mancuerna frente a ti hasta que quede paralela al suelo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite con el otro brazo.","Alterna entre los brazos el número de repeticiones deseado."],"img":"0387-gH5fRsC.jpg","gif":"0387-gH5fRsC.gif"},{"id":"1676","n":"Curl de martillo alterno sentado sobre balón de ejercicio con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.","Sostén una mancuerna en cada mano con las palmas hacia el cuerpo y los brazos completamente extendidos.","Manteniendo la parte superior de los brazos fija, exhala y flexiona una mancuerna hacia el hombro mientras mantienes la palma hacia tu cuerpo.","Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el movimiento con el brazo contrario.","Continúa alternando los brazos durante el número de repeticiones deseado."],"img":"1676-QLRmNeT.jpg","gif":"1676-QLRmNeT.gif"},{"id":"0388","n":"Press de hombros alterno sentado con mancuernas agarre neutro","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","chest"],"st":["Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adelante.","Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante.","Presiona una mancuerna hacia arriba, por encima de la cabeza, extendiendo completamente el brazo.","Baja la mancuerna de vuelta a la altura de los hombros.","Repite con el otro brazo.","Continúa alternando los brazos durante el número de repeticiones deseado."],"img":"0388-QT5Q0nK.jpg","gif":"0388-QT5Q0nK.gif"},{"id":"3546","n":"Press de hombros alterno sentado con mancuernas agarre prono","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta una mancuerna en cada mano, con las palmas hacia adentro, y levántalas a la altura de los hombros.","Presiona una mancuerna hacia arriba, por encima de la cabeza, mientras mantienes la otra mancuerna a la altura de los hombros.","Baja la mancuerna levantada de vuelta a la altura de los hombros mientras presionas simultáneamente la otra mancuerna por encima de la cabeza.","Continúa alternando entre los brazos durante el número de repeticiones deseado."],"img":"3546-q7qkONO.jpg","gif":"3546-q7qkONO.gif"},{"id":"0389","n":"Extensión de tríceps sentado en banco con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima de la cabeza.","Baja lentamente la mancuerna detrás de la cabeza, manteniendo los codos cerca de las orejas.","Haz una pausa por un momento, luego sube la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0389-JhYSVwT.jpg","gif":"0389-JhYSVwT.gif"},{"id":"2317","n":"Elevaciones laterales sentado con brazos flexionados con mancuernas","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo y los brazos flexionados en un ángulo de 90 grados.","Manteniendo los codos flexionados, levanta los brazos hacia los lados hasta que queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2317-JzQbv7J.jpg","gif":"2317-JzQbv7J.gif"},{"id":"1730","n":"Patada de tríceps alterna sentado e inclinado hacia delante con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","back"],"st":["Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adentro.","Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y paralela al suelo.","Extiende un brazo recto hacia atrás, manteniéndolo cerca de tu cuerpo, hasta que el brazo esté completamente extendido.","Haz una pausa por un momento, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite con el otro brazo.","Continúa alternando los brazos durante el número de repeticiones deseado."],"img":"1730-x0lwvfq.jpg","gif":"1730-x0lwvfq.gif"},{"id":"1737","n":"Extensión de tríceps sentado e inclinado hacia delante con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","back"],"st":["Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna en cada mano.","Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y la cabeza erguida.","Extiende los brazos rectos hacia atrás, manteniendo los codos cerca de la cabeza.","Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1737-4ievMJ9.jpg","gif":"1737-4ievMJ9.gif"},{"id":"1677","n":"Curl de bíceps sentado con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en cada mano, con las palmas hacia arriba.","Mantén la espalda recta y los codos cerca del torso.","Exhala y flexiona las mancuernas hacia los hombros, contrayendo los bíceps.","Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1677-xiA6lRr.jpg","gif":"1677-xiA6lRr.gif"},{"id":"0390","n":"Curl de bíceps sentado con mancuernas (en fitball)","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta.","Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos.","Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas contrayendo los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0390-WgJnBH5.jpg","gif":"0390-WgJnBH5.gif"},{"id":"3547","n":"Curl de bíceps a press de hombros sentado con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"shoulders","sm":["shoulders"],"st":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos.","Manteniendo los codos cerca de tus costados, flexiona las mancuernas hacia los hombros.","Una vez que tus antebrazos estén verticales, gira las muñecas de modo que las palmas queden hacia adelante.","Presiona las mancuernas por encima de la cabeza hasta que los brazos estén completamente extendidos.","Baja las mancuernas de vuelta a la posición inicial invirtiendo el movimiento.","Repite el número de repeticiones deseado."],"img":"3547-OeL23VY.jpg","gif":"3547-OeL23VY.gif"},{"id":"1379","n":"Elevación de talones sentado con mancuernas","bp":"lower legs","eq":"dumbbell","tg":"calves","mg":"hamstrings","sm":["hamstrings"],"st":["Siéntate en un banco o silla con los pies apoyados en el suelo y una mancuerna apoyada sobre los muslos.","Coloca la punta de los pies sobre una superficie elevada, como un escalón o un bloque, con los talones colgando del borde.","Sujétate de la mancuerna para mantener la estabilidad.","Levanta los talones lo más alto posible, elevando el peso de tu cuerpo sobre las puntas de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1379-r29jP7S.jpg","gif":"1379-r29jP7S.gif"},{"id":"0391","n":"Curl sentado con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco con los pies apoyados en el suelo y una mancuerna en cada mano, con las palmas hacia adelante.","Mantén la espalda recta y los codos cerca del torso.","Exhala y flexiona las mancuernas hacia los hombros, contrayendo los bíceps.","Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0391-TiaZTxx.jpg","gif":"0391-TiaZTxx.gif"},{"id":"0392","n":"Elevaciones frontales sentado con mancuernas","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","biceps"],"st":["Siéntate en un banco con los pies apoyados en el suelo y una mancuerna en cada mano, apoyadas sobre los muslos.","Mantén la espalda recta y el core activado.","Levanta las mancuernas frente a ti, con las palmas hacia abajo, hasta que queden a la altura de los hombros.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0392-Ys97II0.jpg","gif":"0392-Ys97II0.gif"},{"id":"1678","n":"Curl de martillo sentado con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia tu torso y los brazos extendidos rectos hacia abajo.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1678-IGtBdNT.jpg","gif":"1678-IGtBdNT.gif"},{"id":"0393","n":"Curl de bíceps interno sentado con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en cada mano, con las palmas hacia arriba.","Apoya la parte superior de los brazos sobre los muslos, dejando que las mancuernas cuelguen hacia abajo.","Manteniendo la parte superior de los brazos fija, flexiona las mancuernas hacia los hombros contrayendo los bíceps.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0393-KXyoEtA.jpg","gif":"0393-KXyoEtA.gif"},{"id":"0394","n":"Patada de tríceps sentado con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna en cada mano.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Acerca la parte superior de los brazos a tus costados y mantén los codos flexionados en un ángulo de 90 grados.","Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento.","Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0394-en550rk.jpg","gif":"0394-en550rk.gif"},{"id":"0396","n":"Elevaciones laterales sentado con mancuernas sin respaldo","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","upper back"],"st":["Siéntate en un banco con los pies apoyados en el suelo y una mancuerna en cada mano, apoyadas sobre los muslos.","Mantén la espalda recta y el core activado.","Levanta las mancuernas hacia los lados con una ligera flexión en los codos, hasta que tus brazos queden paralelos al suelo.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0396-hxyTtWj.jpg","gif":"0396-hxyTtWj.gif"},{"id":"0395","n":"Elevaciones laterales sentado con mancuernas con respaldo","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","triceps"],"st":["Siéntate en un banco con los pies apoyados en el suelo y una mancuerna en cada mano, apoyadas sobre los muslos.","Mantén la espalda recta y el core activado.","Levanta las mancuernas hacia los lados con una ligera flexión en los codos, hasta que tus brazos queden paralelos al suelo.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0395-hrrS0Ed.jpg","gif":"0395-hrrS0Ed.gif"},{"id":"0397","n":"Curl de muñeca neutro sentado con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna en cada mano, con las palmas mirándose entre sí.","Apoya los antebrazos sobre los muslos, dejando que las mancuernas cuelguen hacia abajo.","Manteniendo las muñecas en posición neutra, flexiona las mancuernas hacia los hombros.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0397-uJmK7Z1.jpg","gif":"0397-uJmK7Z1.gif"},{"id":"1679","n":"Curl de bíceps a un brazo sentado en fitball con pierna levantada con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.","Sostén una mancuerna en una mano con la palma hacia arriba y el brazo completamente extendido.","Coloca la otra mano en la cadera para mantener el equilibrio.","Flexiona lentamente la mancuerna hacia tu hombro, manteniendo fija la parte superior del brazo.","Haz una pausa por un momento en la parte más alta del movimiento, apretando el bíceps.","Baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado.","Cambia de brazo y repite el ejercicio."],"img":"1679-84sESNy.jpg","gif":"1679-84sESNy.gif"},{"id":"0398","n":"Patada de tríceps a un brazo sentado con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano.","Inclina el torso hacia adelante desde la cintura, manteniendo la espalda recta y paralela al suelo.","Extiende el brazo recto hacia atrás, manteniendo el codo cerca de tu cuerpo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"0398-VQ3sNCn.jpg","gif":"0398-VQ3sNCn.gif"},{"id":"0399","n":"Rotación externa a un brazo sentado con mancuerna","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"shoulders","sm":["shoulders","biceps"],"st":["Siéntate en un banco con la espalda recta y sujeta una mancuerna con una mano, apoyándola sobre el muslo.","Sube la mancuerna hasta la altura del hombro, manteniendo el codo cerca de tu cuerpo.","Gira el antebrazo hacia afuera, alejándolo de tu cuerpo, mientras mantienes fija la parte superior del brazo.","Haz una pausa por un momento en la parte superior, luego gira lentamente el antebrazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"0399-7f2jsqP.jpg","gif":"0399-7f2jsqP.gif"},{"id":"0400","n":"Elevación de talones sentado a una pierna con mancuerna","bp":"lower legs","eq":"dumbbell","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Siéntate en un banco o silla con los pies apoyados en el suelo y una mancuerna apoyada sobre el muslo derecho.","Extiende la pierna izquierda recta hacia adelante, manteniendo el pie flexionado.","Coloca la punta del pie derecho sobre una superficie elevada, como un escalón o un disco de peso.","Usando los músculos de la pantorrilla, eleva el talón derecho lo más alto posible.","Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."],"img":"0400-Ia7tumC.jpg","gif":"0400-Ia7tumC.gif"},{"id":"1380","n":"Elevación de talones sentado a una pierna con mancuerna (agarre neutro)","bp":"lower legs","eq":"dumbbell","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Siéntate en un banco o silla con los pies apoyados en el suelo y una mancuerna apoyada sobre los muslos.","Coloca un pie sobre una superficie elevada, como un escalón o un bloque, con el talón colgando del borde.","Sujeta la mancuerna con agarre neutro, es decir, con las palmas mirándose entre sí y los dedos envolviendo la barra.","Manteniendo el core activado y la espalda recta, eleva lentamente el talón lo más alto posible empujando con la punta del pie.","Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia a la otra pierna."],"img":"1380-FxhcxUW.jpg","gif":"1380-FxhcxUW.gif"},{"id":"1381","n":"Elevación de talones sentado a una pierna con mancuerna (palmas hacia arriba)","bp":"lower legs","eq":"dumbbell","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Siéntate en un banco o silla con la espalda recta y los pies apoyados en el suelo.","Sujeta una mancuerna con una mano y colócala sobre el muslo, con la palma hacia arriba.","Levanta una pierna del suelo y extiéndela frente a ti, manteniendo la rodilla ligeramente flexionada.","Eleva el talón lo más alto posible empujando con la punta del pie.","Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta hacia abajo.","Repite el número de repeticiones deseado y luego cambia de pierna y repite."],"img":"1381-VW88JNd.jpg","gif":"1381-VW88JNd.gif"},{"id":"0401","n":"Curl de muñeca sentado con mancuernas en supinación","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"biceps","sm":["biceps","shoulders"],"st":["Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en cada mano, con las palmas hacia arriba.","Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde.","Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos en la parte superior del movimiento.","Haz una pausa por un momento y luego baja las muñecas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0401-2dImyQ8.jpg","gif":"0401-2dImyQ8.gif"},{"id":"0402","n":"Curl predicador sentado con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco scott con los pies apoyados en el suelo.","Sujeta una mancuerna con una mano con agarre supino, apoyando la parte superior del brazo en la almohadilla del banco scott.","Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro.","Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"0402-7D5bgLT.jpg","gif":"0402-7D5bgLT.gif"},{"id":"0403","n":"Curl concentrado sentado con mancuerna en pronación","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en una mano, con la palma hacia arriba.","Apoya el codo en la parte interna del muslo, justo por encima de la rodilla.","Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"0403-lyKCLmK.jpg","gif":"0403-lyKCLmK.gif"},{"id":"1738","n":"Extensión de tríceps unilateral por encima de la cabeza sentado con mancuerna y agarre inverso","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta una mancuerna con agarre supino y extiende el brazo recto por encima de la cabeza.","Baja la mancuerna detrás de la cabeza flexionando el codo, manteniendo el brazo superior quieto.","Haz una pausa por un momento, luego extiende el brazo de vuelta hacia arriba, hasta la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1738-5fKX7wi.jpg","gif":"1738-5fKX7wi.gif"},{"id":"0405","n":"Press de hombros sentado con mancuernas","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Siéntate en un banco con una mancuerna en cada mano, apoyadas en los muslos.","Sube las mancuernas hasta la altura de los hombros, con las palmas hacia adelante.","Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza.","Haz una pausa por un momento en la parte superior, luego baja lentamente las mancuernas de vuelta a la altura de los hombros.","Repite el número de repeticiones deseado."],"img":"0405-znQUdHY.jpg","gif":"0405-znQUdHY.gif"},{"id":"0404","n":"Press de hombros sentado con mancuernas (agarre neutro)","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adentro.","Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante.","Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza.","Haz una pausa por un momento en la parte superior, luego baja lentamente las mancuernas de vuelta a la altura de los hombros.","Repite el número de repeticiones deseado."],"img":"0404-f1jf47L.jpg","gif":"0404-f1jf47L.gif"},{"id":"2188","n":"Extensión de tríceps sentado con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima de la cabeza.","Flexiona los codos y baja la mancuerna detrás de la cabeza, manteniendo la parte superior de los brazos cerca de las orejas.","Haz una pausa por un momento, luego endereza los brazos y vuelve a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2188-kont8Ut.jpg","gif":"2188-kont8Ut.gif"},{"id":"0406","n":"Encogimiento de hombros con mancuernas","bp":"back","eq":"dumbbell","tg":"traps","mg":"shoulders","sm":["shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo.","Mantén los brazos rectos y deja que las mancuernas cuelguen a tus costados.","Eleva los hombros lo más alto posible, como si intentaras tocarte las orejas con ellos.","Mantén la contracción durante un segundo, luego baja lentamente los hombros de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0406-NJzBsGJ.jpg","gif":"0406-NJzBsGJ.gif"},{"id":"0407","n":"Flexión lateral de tronco con mancuerna","bp":"waist","eq":"dumbbell","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna con una mano y dejando que cuelgue a tu costado.","Manteniendo la espalda recta y el core activado, inclínate lentamente hacia el lado opuesto de la mancuerna, bajando el peso tanto como te sea posible con comodidad.","Haz una pausa por un momento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado y repite."],"img":"0407-IpONWYv.jpg","gif":"0407-IpONWYv.gif"},{"id":"0408","n":"Elevación lateral unilateral tumbado de lado con mancuerna","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Túmbate de lado con las piernas extendidas y la cabeza apoyada sobre el brazo.","Sujeta una mancuerna con la mano de arriba, con la palma hacia abajo.","Manteniendo el brazo recto, sube la mancuerna hasta la altura del hombro.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"0408-fTlkJop.jpg","gif":"0408-fTlkJop.gif"},{"id":"3664","n":"Plancha lateral con pájaro con mancuerna","bp":"back","eq":"dumbbell","tg":"upper back","mg":"shoulders","sm":["shoulders","core"],"st":["Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra.","Coloca el antebrazo en el suelo, justo debajo del hombro, manteniendo el codo flexionado en un ángulo de 90 grados.","Sujeta una mancuerna con la mano de arriba, con el brazo extendido recto hacia el suelo.","Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los talones.","Manteniendo la posición de plancha lateral, levanta la mancuerna hacia el techo, apretando los omóplatos entre sí.","Baja la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"3664-X6ytgYZ.jpg","gif":"3664-X6ytgYZ.gif"},{"id":"3548","n":"Paseo unilateral con mancuerna por encima de la cabeza","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano.","Levanta la mancuerna por encima de la cabeza, extendiendo completamente el brazo.","Activa el core y mantén la espalda recta mientras caminas hacia adelante, sosteniendo la mancuerna por encima de la cabeza.","Continúa caminando durante la distancia o el tiempo deseado.","Cambia de mano y repite el ejercicio."],"img":"3548-mWBtgmb.jpg","gif":"3548-mWBtgmb.gif"},{"id":"0409","n":"Elevación de talones a una pierna con mancuerna","bp":"lower legs","eq":"dumbbell","tg":"calves","mg":"ankles","sm":["ankles"],"st":["Ponte de pie en el borde de un escalón o plataforma, con los talones colgando y la punta de los pies sobre el escalón.","Sujeta una mancuerna con una mano y coloca la otra mano sobre una pared o barandilla para apoyarte.","Eleva el talón lo más alto posible, levantando el cuerpo sobre la punta de los pies.","Haz una pausa por un momento en la parte superior, luego baja lentamente el talón por debajo del nivel del escalón.","Repite el número de repeticiones deseado, luego cambia a la otra pierna."],"img":"0409-1kB3Wmk.jpg","gif":"0409-1kB3Wmk.gif"},{"id":"1757","n":"Peso muerto a una pierna con mancuernas","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Ponte de pie con los pies separados a la altura de las caderas, sujetando una mancuerna con la mano derecha.","Traslada tu peso a la pierna izquierda y levanta el pie derecho ligeramente del suelo.","Manteniendo la espalda recta, inclínate hacia adelante desde las caderas y baja la mancuerna hacia el suelo.","Al mismo tiempo, extiende la pierna derecha recta hacia atrás, manteniendo una ligera flexión en la rodilla izquierda.","Baja la mancuerna hasta que tu torso y tu pierna derecha queden paralelos al suelo.","Haz una pausa por un momento, luego activa los glúteos y los isquiotibiales para volver a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"1757-gKozT8X.jpg","gif":"1757-gKozT8X.gif"},{"id":"2805","n":"Peso muerto a una pierna con mancuernas y apoyo en cajón","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Ponte de pie con los pies separados a la altura de las caderas, sujetando una mancuerna con la mano derecha.","Coloca el pie izquierdo sobre un cajón de step o una superficie elevada detrás de ti.","Manteniendo la espalda recta y el core activado, inclínate hacia adelante desde las caderas, bajando la mancuerna hacia el suelo.","Mientras bajas la mancuerna, levanta al mismo tiempo la pierna izquierda detrás de ti, manteniendo una línea recta desde la cabeza hasta el talón.","Baja la mancuerna hasta sentir un estiramiento en el isquiotibial derecho, luego vuelve a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"2805-daBmy1Y.jpg","gif":"2805-daBmy1Y.gif"},{"id":"0410","n":"Sentadilla búlgara con mancuernas","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.","Da un paso hacia adelante con un pie y coloca los pies de modo que el pie delantero quede plano en el suelo y el pie trasero quede elevado sobre un banco o escalón.","Baja el cuerpo flexionando la rodilla y la cadera delanteras, manteniendo la rodilla trasera ligeramente flexionada y el talón trasero levantado del suelo.","Continúa bajando hasta que el muslo delantero quede paralelo al suelo, luego empuja con el talón delantero para volver a la posición inicial.","Repite el número de repeticiones deseado y luego cambia de pierna y repite."],"img":"0410-qx4fgX7.jpg","gif":"0410-qx4fgX7.gif"},{"id":"0411","n":"Sentadilla a una pierna con mancuernas","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.","Extiende una pierna hacia adelante y mantenla levantada del suelo durante todo el ejercicio.","Flexiona la pierna de apoyo y baja el cuerpo como si te sentaras en una silla.","Mantén el pecho arriba y la espalda recta.","Haz una pausa por un momento en la posición más baja, luego empuja con el talón para volver a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."],"img":"0411-H6ybluc.jpg","gif":"0411-H6ybluc.gif"},{"id":"0413","n":"Sentadilla con mancuernas","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados.","Manteniendo el pecho arriba y el core activado, baja el cuerpo flexionando las rodillas y las caderas, como si te sentaras en una silla.","Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0413-HsvHqgf.jpg","gif":"0413-HsvHqgf.gif"},{"id":"3560","n":"Curl martillo y press alterno de pie con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Ponte de pie con una mancuerna en cada mano, con las palmas hacia tu cuerpo.","Mantén los codos cerca del torso y la espalda recta.","Exhala y flexiona la mancuerna de tu mano derecha hacia el hombro, manteniendo el brazo superior quieto.","Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.","Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el curl con la mano izquierda.","Después de completar el curl con la mano izquierda, exhala y presiona la mancuerna de la mano derecha por encima de la cabeza.","Extiende completamente el brazo y mantén la posición por un momento en la parte superior.","Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el press con la mano izquierda.","Continúa alternando entre curls y press durante el número de repeticiones deseado."],"img":"3560-LeaZOIz.jpg","gif":"3560-LeaZOIz.gif"},{"id":"0414","n":"Press militar alterno de pie con mancuernas","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros, con las palmas hacia adelante.","Presiona una mancuerna por encima de la cabeza, extendiendo completamente el brazo.","Baja la mancuerna de vuelta a la altura de los hombros.","Repite con el otro brazo.","Continúa alternando los brazos durante el número de repeticiones deseado."],"img":"0414-bBi35y3.jpg","gif":"0414-bBi35y3.gif"},{"id":"0415","n":"Elevaciones alternas de pie con mancuernas","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia el cuerpo.","Mantén la espalda recta y el core activado.","Levanta una mancuerna hacia el lado, manteniendo el brazo recto y la palma hacia abajo.","Continúa levantando hasta que el brazo quede paralelo al suelo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite con el otro brazo.","Alterna entre los brazos el número de repeticiones deseado."],"img":"0415-SxHteRW.jpg","gif":"0415-SxHteRW.gif"},{"id":"1739","n":"Patada de tríceps alterna de pie con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Extiende los brazos rectos hacia atrás, manteniendo los codos cerca del cuerpo.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite con el otro brazo, alternando lados en cada repetición."],"img":"1739-Gi2BXfK.jpg","gif":"1739-Gi2BXfK.gif"},{"id":"2143","n":"Alrededor del mundo de pie con mancuernas","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.","Extiende los brazos rectos hacia los lados a la altura de los hombros, con las palmas hacia abajo.","Manteniendo los brazos rectos, gira lentamente los brazos en un movimiento circular, llevando las mancuernas frente al cuerpo y luego por encima de la cabeza.","Continúa el movimiento circular, bajando las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2143-RSOsp5d.jpg","gif":"2143-RSOsp5d.gif"},{"id":"1740","n":"Extensión de tríceps a un brazo inclinado hacia delante con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","back"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano.","Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y paralela al suelo.","Extiende el brazo recto hacia atrás, manteniendo el codo cerca de tu cuerpo.","Baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1740-CJwa0vD.jpg","gif":"1740-CJwa0vD.gif"},{"id":"1741","n":"Extensión de tríceps a dos brazos inclinado hacia delante con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","back"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.","Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y las rodillas ligeramente flexionadas.","Extiende los brazos rectos hacia atrás, manteniendo los codos cerca del cuerpo.","Baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1741-3T12T87.jpg","gif":"1741-3T12T87.gif"},{"id":"0416","n":"Curl de bíceps de pie con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0416-3s4NnTh.jpg","gif":"0416-3s4NnTh.gif"},{"id":"0417","n":"Elevación de talones de pie con mancuernas","bp":"lower legs","eq":"dumbbell","tg":"calves","mg":"ankles","sm":["ankles"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.","Levanta los talones del suelo lo más alto posible, usando las pantorrillas.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0417-dPmaUaU.jpg","gif":"0417-dPmaUaU.gif"},{"id":"0418","n":"Curl concentrado de pie con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano, con el brazo completamente extendido y la palma hacia adentro.","Apoya la otra mano sobre el muslo para mayor estabilidad.","Manteniendo fija la parte superior del brazo, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps.","Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"0418-7inpWch.jpg","gif":"0418-7inpWch.gif"},{"id":"0419","n":"Elevación frontal sobre la cabeza de pie con mancuernas","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","biceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.","Mantén los brazos rectos y levanta las mancuernas frente a ti, elevándolas por encima de la cabeza.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0419-laVRfDf.jpg","gif":"0419-laVRfDf.gif"},{"id":"2321","n":"Curl de bíceps interno de pie con mancuernas v. 2","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso.","Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante.","Manteniendo fija la parte superior de los brazos, flexiona los pesos mientras contraes los bíceps.","Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Comienza a llevar lentamente las mancuernas de vuelta a la posición inicial mientras inhalas.","Repite el número de repeticiones recomendado."],"img":"2321-vKilzz3.jpg","gif":"2321-vKilzz3.gif"},{"id":"0420","n":"Patada de tríceps de pie con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento.","Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0420-UmpPAAe.jpg","gif":"0420-UmpPAAe.gif"},{"id":"0421","n":"Curl concentrado a un brazo de pie con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna con una mano, con la palma hacia arriba.","Coloca la mano libre sobre el muslo para apoyarte.","Manteniendo fija la parte superior del brazo, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps.","Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"0421-8fgqP5a.jpg","gif":"0421-8fgqP5a.gif"},{"id":"0422","n":"Curl a un brazo apoyado en banco inclinado de pie con mancuerna espalda recta","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano, con la palma hacia adelante.","Coloca la otra mano sobre un banco inclinado para apoyarte.","Manteniendo fija la parte superior del brazo, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps.","Haz una pausa por un momento arriba, luego inhala y baja lentamente la mancuerna a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"0422-BIb1tGo.jpg","gif":"0422-BIb1tGo.gif"},{"id":"1680","n":"Curl a un brazo apoyado en banco inclinado de pie con mancuerna espalda inclinada","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano.","Coloca la otra mano sobre un banco inclinado para apoyarte.","Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro contrayendo el bíceps.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1680-EmlJR2y.jpg","gif":"1680-EmlJR2y.gif"},{"id":"0423","n":"Extensión a un brazo de pie con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano.","Levanta la mancuerna por encima de la cabeza, extendiendo completamente el brazo.","Mantén la parte superior del brazo cerca de la cabeza y perpendicular al suelo.","Baja lentamente la mancuerna detrás de la cabeza, flexionando el codo.","Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0423-BCUR88E.jpg","gif":"0423-BCUR88E.gif"},{"id":"0424","n":"Press a un brazo con agarre neutro de pie con mancuerna","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano a la altura del hombro, con la palma hacia adentro.","Activa el core y mantén la espalda recta.","Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"0424-ocYc6Db.jpg","gif":"0424-ocYc6Db.gif"},{"id":"0425","n":"Curl inverso a un brazo de pie con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna con una mano con agarre prono.","Mantén el brazo completamente extendido y cerca del cuerpo, con la palma hacia abajo.","Flexiona lentamente la mancuerna hacia tu hombro, manteniendo fija la parte superior del brazo.","Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"0425-DU5Kkj2.jpg","gif":"0425-DU5Kkj2.gif"},{"id":"0426","n":"Press militar de pie con mancuernas","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros, con las palmas hacia adelante.","Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza.","Haz una pausa por un momento en la parte superior, luego baja lentamente las mancuernas de vuelta a la altura de los hombros.","Repite el número de repeticiones deseado."],"img":"0426-A6wtbuL.jpg","gif":"0426-A6wtbuL.gif"},{"id":"0427","n":"Press de hombros de pie con mancuernas y agarre neutro","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","chest"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros, con las palmas hacia adentro.","Manteniendo el core activado y la espalda recta, presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0427-UilDHSs.jpg","gif":"0427-UilDHSs.gif"},{"id":"0428","n":"Curl predicador de pie con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante.","Apoya la parte posterior de la parte superior de los brazos contra el banco scott o un banco inclinado, con los codos ligeramente flexionados.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0428-hq2hyDH.jpg","gif":"0428-hq2hyDH.gif"},{"id":"0429","n":"Curl inverso de pie con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano, con las palmas hacia tu cuerpo.","Manteniendo fija la parte superior de los brazos, exhala y flexiona los pesos mientras contraes los bíceps. Continúa subiendo los pesos hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0429-0IgNjSM.jpg","gif":"0429-0IgNjSM.gif"},{"id":"0430","n":"Extensión de tríceps de pie con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano.","Levanta la mancuerna por encima de la cabeza, manteniendo el brazo recto.","Flexiona el codo y baja la mancuerna detrás de la cabeza, manteniendo fija la parte superior del brazo.","Extiende el brazo de vuelta hacia arriba, hasta la posición inicial.","Repite el número de repeticiones deseado."],"img":"0430-PdmaD0N.jpg","gif":"0430-PdmaD0N.gif"},{"id":"2293","n":"Curl de bíceps Zottman predicador de pie con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante.","Apoya la parte superior de los brazos contra el banco scott y mantén los codos ligeramente flexionados.","Flexiona las mancuernas hacia los hombros mientras mantienes fija la parte superior de los brazos.","En la parte superior del movimiento, gira las muñecas de modo que las palmas queden hacia abajo.","Baja lentamente las mancuernas de vuelta a la posición inicial, girando también las muñecas a su posición original.","Repite el número de repeticiones deseado."],"img":"2293-P2nRiUa.jpg","gif":"2293-P2nRiUa.gif"},{"id":"1684","n":"Step-up con equilibrio sobre una pierna y curl de bíceps con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"quadriceps","sm":["quadriceps","glutes","hamstrings"],"st":["Ponte de pie frente a un escalón o plataforma con una mancuerna en cada mano, con las palmas hacia tu cuerpo.","Coloca el pie derecho sobre el escalón, asegurándote de que todo el pie esté en contacto con la superficie.","Activa el core y empuja con el talón derecho para subir el cuerpo sobre el escalón, llevando la rodilla izquierda hacia el pecho.","En la parte superior del movimiento, realiza un curl de bíceps flexionando los codos y llevando las mancuernas hacia los hombros.","Baja las mancuernas y, al mismo tiempo, baja el pie izquierdo de vuelta al suelo.","Repite el movimiento del lado contrario, subiendo con el pie izquierdo y flexionando las mancuernas.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"1684-76vfTdU.jpg","gif":"1684-76vfTdU.gif"},{"id":"0431","n":"Step-up con mancuernas","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie frente a un banco o escalón con una mancuerna en cada mano, con las palmas hacia tu cuerpo.","Coloca el pie derecho sobre el banco o escalón, asegurándote de que todo el pie esté en contacto con la superficie.","Empuja con el talón derecho y sube el cuerpo sobre el banco o escalón, enderezando la pierna derecha.","Sube el pie izquierdo hasta el banco o escalón, quedando completamente erguido.","Baja con el pie izquierdo, seguido del pie derecho, volviendo a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."],"img":"0431-aXtJhlg.jpg","gif":"0431-aXtJhlg.gif"},{"id":"2796","n":"Zancada con step-up con mancuernas","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Ponte de pie frente a un escalón o plataforma con una mancuerna en cada mano, con las palmas hacia tus costados.","Coloca el pie derecho sobre el escalón, asegurándote de que todo el pie esté sobre la superficie.","Empuja con el talón derecho y sube el cuerpo sobre el escalón, llevando también el pie izquierdo hacia arriba.","Una vez que ambos pies estén sobre el escalón, baja el pie izquierdo de vuelta a la posición inicial, manteniendo el pie derecho sobre el escalón.","Repite el movimiento, alternando el pie con el que subes cada vez.","Continúa durante el número de repeticiones deseado."],"img":"2796-gFyFj9z.jpg","gif":"2796-gFyFj9z.gif"},{"id":"2812","n":"Sentadilla búlgara con subida a banco y mancuernas","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Ponte de pie frente a un banco o escalón con una mancuerna en cada mano, con las palmas hacia tu cuerpo.","Coloca el pie derecho sobre el banco o escalón, asegurándote de que todo el pie esté en contacto con la superficie.","Sube al banco o escalón con el pie derecho, empujando con el talón para levantar el cuerpo.","Mientras subes, levanta al mismo tiempo la rodilla izquierda hacia el pecho.","Haz una pausa en la parte superior del movimiento, luego baja lentamente el pie izquierdo de vuelta al suelo mientras mantienes el pie derecho sobre el banco o escalón.","Repite el movimiento con el pie izquierdo sobre el banco o escalón.","Continúa alternando entre el pie derecho y el izquierdo durante el número de repeticiones deseado."],"img":"2812-QjE2DcA.jpg","gif":"2812-QjE2DcA.gif"},{"id":"0432","n":"Peso muerto con piernas rígidas con mancuernas","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.","Manteniendo la espalda recta y el core activado, inclínate desde las caderas y baja las mancuernas hacia el suelo, permitiendo una ligera flexión en las rodillas.","Baja las mancuernas hasta sentir un estiramiento en los isquiotibiales, luego aprieta los glúteos y empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0432-5eLRITT.jpg","gif":"0432-5eLRITT.gif"},{"id":"0433","n":"Pullover con mancuerna y brazos rectos","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"latissimus dorsi","sm":["latissimus dorsi","triceps"],"st":["Túmbate en un banco con la cabeza en un extremo y los pies firmemente apoyados en el suelo.","Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima del pecho.","Manteniendo los brazos rectos, baja lentamente la mancuerna detrás de la cabeza con un movimiento en forma de arco.","Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0433-i8BdLTK.jpg","gif":"0433-i8BdLTK.gif"},{"id":"0434","n":"Peso muerto con piernas semirrígidas con mancuernas","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.","Manteniendo la espalda recta y el core activado, inclínate desde las caderas y baja las mancuernas hacia el suelo, permitiendo que el torso se incline hacia adelante.","Continúa bajando las mancuernas hasta sentir un estiramiento en los isquiotibiales, manteniendo las rodillas ligeramente flexionadas.","Haz una pausa breve en la posición más baja, luego activa los glúteos y los isquiotibiales para levantar el torso de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0434-oom75KC.jpg","gif":"0434-oom75KC.gif"},{"id":"2808","n":"Pull-through sumo con mancuerna","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","core"],"st":["Ponte de pie con los pies más separados que la altura de los hombros, con las puntas de los pies hacia afuera.","Sujeta una mancuerna con ambas manos frente a tu cuerpo, con los brazos extendidos.","Flexiona las rodillas y baja las caderas hasta una posición de sentadilla, manteniendo la espalda recta.","Baja la mancuerna entre las piernas, manteniendo los brazos rectos.","Empuja con los talones y extiende las caderas hacia adelante, llevando la mancuerna hacia arriba y frente a tu cuerpo.","Aprieta los glúteos en la parte superior del movimiento, luego baja la mancuerna de vuelta entre las piernas.","Repite el número de repeticiones deseado."],"img":"2808-BmrwWzo.jpg","gif":"2808-BmrwWzo.gif"},{"id":"2803","n":"Sentadilla asistida con mancuerna","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados.","Manteniendo el pecho arriba y el core activado, baja lentamente el cuerpo flexionando las rodillas y empujando las caderas hacia atrás.","Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2803-r5DgrW9.jpg","gif":"2803-r5DgrW9.gif"},{"id":"0436","n":"Press Tate con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Siéntate en un banco plano con una mancuerna en cada mano, con las palmas mirándose entre sí.","Sube las mancuernas hasta la altura de los hombros, luego gira las muñecas de modo que las palmas queden mirando hacia afuera.","Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos, luego bájalas de vuelta a la altura de los hombros.","Gira las muñecas de vuelta a la posición inicial y repite el número de repeticiones deseado."],"img":"0436-s5PdDyY.jpg","gif":"0436-s5PdDyY.gif"},{"id":"1742","n":"Patada de tríceps con mancuerna en postura de la cigüeña","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en la mano derecha.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Lleva el codo derecho hacia el costado, manteniéndolo flexionado en un ángulo de 90 grados.","Extiende el brazo derecho recto hacia atrás, apretando el tríceps.","Haz una pausa por un momento, luego baja lentamente la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"1742-wOLmCXc.jpg","gif":"1742-wOLmCXc.gif"},{"id":"1743","n":"Press de banca con mancuernas y giro","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Sujeta una mancuerna en cada mano con agarre prono, con las palmas alejadas de ti.","Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos.","Baja las mancuernas hacia el pecho, manteniendo los codos cerca del cuerpo.","Mientras bajas las mancuernas, gira las muñecas de modo que las palmas queden hacia ti en la parte más baja del movimiento.","Haz una pausa por un momento en la parte más baja, luego invierte el movimiento presionando las mancuernas de vuelta hacia arriba, hasta la posición inicial.","Mientras presionas las mancuernas hacia arriba, gira las muñecas de vuelta a la posición inicial con las palmas alejadas de ti.","Repite el número de repeticiones deseado."],"img":"1743-z6TAHoT.jpg","gif":"1743-z6TAHoT.gif"},{"id":"0437","n":"Remo al mentón con mancuernas","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","biceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.","Deja que las mancuernas cuelguen frente a tus muslos, con los brazos completamente extendidos.","Manteniendo la espalda recta y el core activado, exhala y levanta las mancuernas rectas hacia tu barbilla, guiando el movimiento con los codos.","Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0437-ainizkb.jpg","gif":"0437-ainizkb.gif"},{"id":"1765","n":"Remo al mentón con mancuernas (vista posterior)","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"traps","sm":["traps","biceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.","Deja que las mancuernas cuelguen frente a tus muslos, con los brazos completamente extendidos y las palmas hacia tu cuerpo.","Manteniendo la espalda recta y el core activado, exhala y levanta las mancuernas rectas hacia tu barbilla, guiando el movimiento con los codos.","Continúa subiendo hasta que las mancuernas estén a la altura de los hombros, con los codos apuntando hacia los lados.","Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1765-Iptlv6x.jpg","gif":"1765-Iptlv6x.gif"},{"id":"0864","n":"Rotación externa de hombro de pie con mancuerna","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","trapezius"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo.","Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo los codos ligeramente flexionados.","Gira los brazos hacia afuera, llevando las mancuernas hacia la cabeza mientras mantienes los codos en la misma posición.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0864-x306lCW.jpg","gif":"0864-x306lCW.gif"},{"id":"5201","n":"Curl de bíceps de camarero con mancuerna","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante.","Mantén la parte superior de los brazos cerca del cuerpo y los codos pegados.","Flexiona lentamente las mancuernas hacia los hombros, manteniendo las muñecas rectas.","Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"5201-KOpzGBL.jpg","gif":"5201-KOpzGBL.gif"},{"id":"0438","n":"Press en W con mancuernas","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","chest"],"st":["Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adelante.","Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante.","Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza.","Baja las mancuernas de vuelta a la altura de los hombros.","Repite el número de repeticiones deseado."],"img":"0438-vmwLyCg.jpg","gif":"0438-vmwLyCg.gif"},{"id":"0439","n":"Curl Zottman con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con una mancuerna en cada mano, con las palmas hacia tu cuerpo.","Mantén los codos cerca del torso y gira las palmas para que queden hacia adelante.","Flexiona las mancuernas hacia los hombros mientras mantienes fija la parte superior de los brazos.","En la parte superior del movimiento, gira las muñecas de modo que las palmas queden alejadas de tu cuerpo.","Baja lentamente las mancuernas de vuelta a la posición inicial, girando las palmas de nuevo hacia tu cuerpo.","Repite el número de repeticiones deseado."],"img":"0439-kXaIn5A.jpg","gif":"0439-kXaIn5A.gif"},{"id":"2294","n":"Curl Zottman en banco Scott con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco scott con una mancuerna en cada mano, con las palmas hacia arriba y los codos apoyados en la almohadilla.","Flexiona las mancuernas hacia los hombros, manteniendo fija la parte superior de los brazos y las palmas hacia arriba.","En la parte superior del curl, gira las muñecas de modo que las palmas queden hacia abajo.","Baja lentamente las mancuernas de vuelta a la posición inicial, girando también las muñecas a su posición original mientras lo haces.","Repite el número de repeticiones deseado."],"img":"2294-y5U5B9Y.jpg","gif":"2294-y5U5B9Y.gif"},{"id":"2189","n":"Extensión de tríceps sentado con mancuernas","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta una mancuerna con ambas manos con agarre prono y levántala por encima de la cabeza.","Flexiona los codos y baja la mancuerna detrás de la cabeza, manteniendo la parte superior de los brazos cerca de las orejas.","Extiende los brazos y sube la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2189-FQXdXzY.jpg","gif":"2189-FQXdXzY.gif"},{"id":"1167","n":"Estiramiento dinámico de pecho (hombre)","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.","Extiende los brazos hacia los lados, paralelos al suelo.","Lleva lentamente los brazos hacia adelante, cruzándolos frente al cuerpo.","Siente el estiramiento en los músculos del pecho.","Mantén el estiramiento durante 10-30 segundos.","Vuelve a la posición inicial y repite el número de repeticiones deseado."],"img":"1167-3uj0Ozg.jpg","gif":"1167-3uj0Ozg.gif"},{"id":"3287","n":"Fondos sobre codos","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Siéntate en el borde de un banco o silla con las manos sujetando el borde junto a las caderas.","Desliza las caderas hacia adelante, fuera del banco, y estira las piernas, manteniendo los talones en el suelo.","Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco.","Haz una pausa por un momento en la posición más baja, luego empuja con las manos para enderezar los brazos y levantar el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3287-LkoAWAE.jpg","gif":"3287-LkoAWAE.gif"},{"id":"1772","n":"Elevación de codos - flexión inversa","bp":"back","eq":"body weight","tg":"upper back","mg":"triceps","sm":["triceps","shoulders"],"st":["Comienza tumbado boca abajo en el suelo con las piernas extendidas y las manos colocadas justo debajo de los hombros.","Activa el core y presiona con las palmas para levantar la parte superior del cuerpo del suelo, manteniendo los codos cerca de los costados.","Haz una pausa por un momento en la parte superior, apretando los músculos de la espalda alta.","Baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1772-wbUYILZ.jpg","gif":"1772-wbUYILZ.gif"},{"id":"0443","n":"Codo a rodilla","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Comienza tumbado boca arriba con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activa el abdomen y levanta la parte superior del cuerpo del suelo, llevando el codo derecho hacia la rodilla izquierda.","Al mismo tiempo, lleva la rodilla izquierda hacia el codo derecho, creando un movimiento de torsión.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo y extiende las piernas de vuelta a la posición inicial.","Repite el movimiento, esta vez llevando el codo izquierdo hacia la rodilla derecha y la rodilla derecha hacia el codo izquierdo.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0443-jvp6DiD.jpg","gif":"0443-jvp6DiD.gif"},{"id":"3292","n":"El ascensor","bp":"back","eq":"body weight","tg":"upper back","mg":"shoulders","sm":["shoulders","trapezius"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Coloca las manos sobre las caderas o crúzalas frente al pecho.","Manteniendo la espalda recta, inclínate lentamente hacia adelante desde la cintura, bajando la parte superior del cuerpo hacia el suelo.","Haz una pausa por un momento en la posición más baja, luego sube lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3292-zYmNaoY.jpg","gif":"3292-zYmNaoY.gif"},{"id":"1332","n":"Elevaciones alternas de brazos sobre fitball","bp":"back","eq":"stability ball","tg":"lats","mg":"shoulders","sm":["shoulders","core"],"st":["Siéntate en el balón de estabilidad con los pies planos en el suelo y la espalda recta.","Sujeta una mancuerna en cada mano con las palmas hacia adentro y los brazos extendidos hacia abajo a los lados.","Activa el core y levanta lentamente un brazo hacia el hombro, manteniendo el codo ligeramente flexionado.","Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial.","Repite el movimiento con el otro brazo.","Continúa alternando los brazos durante el número de repeticiones deseado."],"img":"1332-EyLrNC2.jpg","gif":"1332-EyLrNC2.gif"},{"id":"1333","n":"Hiperextensión lumbar sobre fitball con brazos extendidos","bp":"back","eq":"stability ball","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él, con las caderas apoyadas en el balón y los pies contra una pared para mayor estabilidad.","Extiende los brazos rectos hacia adelante, con las palmas hacia abajo.","Activa el core y levanta lentamente la parte superior del cuerpo del balón, manteniendo la espalda recta y el cuello alineado con la columna.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1333-PERjVm8.jpg","gif":"1333-PERjVm8.gif"},{"id":"1334","n":"Hiperextensión lumbar sobre fitball con manos tras la cabeza","bp":"back","eq":"stability ball","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él con las caderas apoyadas en el balón.","Coloca los pies contra una pared u otra superficie estable para apoyarte.","Cruza los brazos detrás de la cabeza, con las manos tocando la parte de atrás de la cabeza.","Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta las caderas.","Haz una pausa breve en la parte alta del movimiento, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1334-o1HGDSq.jpg","gif":"1334-o1HGDSq.gif"},{"id":"1335","n":"Hiperextensión lumbar sobre fitball con rodillas elevadas del suelo","bp":"back","eq":"stability ball","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él, con las caderas apoyadas en el balón y los pies contra una pared para mayor estabilidad.","Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.","Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta los talones.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1335-WME869U.jpg","gif":"1335-WME869U.gif"},{"id":"1336","n":"Hiperextensión lumbar con rotación sobre fitball","bp":"back","eq":"stability ball","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Comienza tumbado boca abajo sobre el balón de estabilidad, con las caderas apoyadas en el balón y los pies firmemente apoyados en el suelo.","Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.","Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta los talones.","Haz una pausa por un momento en la parte superior, luego gira lentamente el torso hacia un lado, manteniendo las caderas y las piernas estables.","Vuelve al centro y repite el giro hacia el otro lado.","Baja la parte superior del cuerpo de vuelta a la posición inicial y repite el número de repeticiones deseado."],"img":"1336-WVD66ff.jpg","gif":"1336-WVD66ff.gif"},{"id":"1744","n":"Fondos en fitball","bp":"upper arms","eq":"stability ball","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Coloca las manos sobre el balón junto a las caderas, con los dedos apuntando hacia adelante.","Activa el tríceps y empuja con las manos para levantar el cuerpo del balón, enderezando los brazos.","Baja el cuerpo flexionando los codos, manteniéndolos cerca de los costados.","Repite el número de repeticiones deseado."],"img":"1744-kprile3.jpg","gif":"1744-kprile3.gif"},{"id":"1559","n":"Estiramiento de flexores de cadera sobre fitball","bp":"upper legs","eq":"stability ball","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings"],"st":["Coloca el balón de estabilidad en el suelo y arrodíllate frente a él.","Coloca el pie derecho sobre el balón de estabilidad, con la rodilla flexionada en un ángulo de 90 grados.","Extiende la pierna izquierda hacia atrás, manteniéndola recta.","Inclínate hacia adelante, empujando las caderas hacia el balón de estabilidad, hasta sentir un estiramiento en el flexor de la cadera derecha.","Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite."],"img":"1559-2LQkNPW.jpg","gif":"1559-2LQkNPW.gif"},{"id":"1338","n":"Abrazo al fitball","bp":"back","eq":"stability ball","tg":"spine","mg":"shoulders","sm":["shoulders","chest"],"st":["Siéntate en el balón de estabilidad con los pies planos en el suelo y la espalda recta.","Sujeta el balón de estabilidad con ambas manos, abrazándolo cerca del pecho.","Activa los músculos del core y reclínate lentamente hacia atrás, manteniendo la espalda recta y los pies apoyados en el suelo.","Continúa reclinándote hacia atrás hasta sentir un estiramiento en los músculos de la espalda.","Mantén la posición durante unos segundos, luego vuelve lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1338-d7z1Y7V.jpg","gif":"1338-d7z1Y7V.gif"},{"id":"1339","n":"Estiramiento de dorsales con fitball","bp":"back","eq":"stability ball","tg":"lats","mg":"shoulders","sm":["shoulders","triceps"],"st":["Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta.","Sujeta una mancuerna con una mano y extiende el brazo recto por encima de la cabeza.","Inclínate lentamente hacia el lado opuesto, sintiendo un estiramiento en el músculo dorsal.","Mantén el estiramiento durante 20-30 segundos, luego vuelve a la posición inicial.","Repite del otro lado."],"img":"1339-sM84pE4.jpg","gif":"1339-sM84pE4.gif"},{"id":"1341","n":"Estiramiento lumbar en fitball (pirámide)","bp":"back","eq":"stability ball","tg":"lats","mg":"glutes","sm":["glutes","hamstrings"],"st":["Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Camina lentamente hacia adelante con los pies, haciendo rodar el balón por tu espalda hasta que tu zona lumbar quede apoyada sobre el balón.","Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.","Activa el core y baja lentamente la parte superior del cuerpo hacia el suelo, permitiendo que tu zona lumbar se estire sobre el balón.","Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1341-yU7w7CA.jpg","gif":"1341-yU7w7CA.gif"},{"id":"1342","n":"Estiramiento lateral de dorsal tumbado sobre fitball","bp":"back","eq":"stability ball","tg":"lats","mg":"shoulders","sm":["shoulders","triceps"],"st":["Túmbate de lado con las piernas extendidas y la cabeza apoyada sobre el balón de estabilidad.","Coloca el brazo de arriba sobre el balón para mantener la estabilidad.","Extiende el brazo de arriba por encima de la cabeza y permite que tu torso gire ligeramente.","Siente el estiramiento en los músculos dorsales del costado de tu cuerpo.","Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite."],"img":"1342-rTbyBYV.jpg","gif":"1342-rTbyBYV.gif"},{"id":"1382","n":"Elevación de talones con fitball apoyado en la pared","bp":"lower legs","eq":"dumbbell","tg":"calves","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Ponte de pie con la espalda contra una pared y coloca un balón de ejercicio entre tu zona lumbar y la pared.","Coloca los pies separados a la altura de los hombros, con la punta de los pies hacia adelante.","Sujeta una mancuerna en cada mano, con los brazos extendidos a los lados.","Levanta los talones del suelo, llevando el peso de tu cuerpo hacia la punta de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1382-xo6sENf.jpg","gif":"1382-xo6sENf.gif"},{"id":"3241","n":"Elevación de talones con fitball en la pared (con pelota de tenis entre los tobillos)","bp":"lower legs","eq":"dumbbell","tg":"calves","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Ponte de pie frente a una pared con los pies separados a la altura de los hombros.","Coloca un balón de ejercicio entre la pared y tu zona lumbar.","Sujeta una mancuerna en cada mano, con los brazos extendidos a los lados.","Coloca una pelota de tenis entre los tobillos.","Levanta los talones del suelo, elevando el cuerpo sobre la punta de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3241-FY3UdNT.jpg","gif":"3241-FY3UdNT.gif"},{"id":"3240","n":"Elevación de talones con fitball en la pared (con pelota de tenis entre las rodillas)","bp":"lower legs","eq":"dumbbell","tg":"calves","mg":"quadriceps","sm":["quadriceps","hamstrings"],"st":["Ponte de pie con la espalda contra una pared y coloca un balón de ejercicio entre tu zona lumbar y la pared.","Coloca los pies separados a la altura de los hombros y ligeramente por delante de ti.","Sujeta una mancuerna en cada mano, con los brazos extendidos a los lados.","Coloca una pelota de tenis entre las rodillas.","Levanta los talones del suelo, elevando el cuerpo sobre la punta de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3240-j74M6Zn.jpg","gif":"3240-j74M6Zn.gif"},{"id":"1416","n":"Rotación del tren inferior en decúbito prono a una pierna sobre fitball","bp":"upper legs","eq":"stability ball","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","core"],"st":["Túmbate boca abajo sobre el balón de estabilidad con las caderas apoyadas en el balón y las piernas extendidas rectas detrás de ti.","Coloca las manos en el suelo frente a ti para mayor apoyo.","Activa los glúteos y el abdomen para estabilizar el cuerpo.","Levanta lentamente una pierna del suelo, manteniéndola recta y paralela al piso.","Gira la pierna hacia afuera, alejándola del cuerpo, mientras mantienes las caderas y la parte superior del cuerpo estables.","Haz una pausa al final de la rotación, luego regresa lentamente la pierna a la posición inicial.","Repite la rotación con la otra pierna.","Continúa alternando las piernas durante el número de repeticiones deseado."],"img":"1416-M72BExt.jpg","gif":"1416-M72BExt.gif"},{"id":"1417","n":"Curl de isquiotibiales a una pierna sobre fitball con patada diagonal","bp":"upper legs","eq":"stability ball","tg":"glutes","mg":"hamstrings","sm":["hamstrings","calves"],"st":["Comienza acostado sobre la espalda con las piernas extendidas y los talones apoyados sobre el balón de estabilidad.","Coloca los brazos a los lados del cuerpo para mantener el equilibrio.","Activa los glúteos y el abdomen para levantar las caderas del suelo, formando una línea recta desde los hombros hasta los talones.","Dobla la rodilla derecha y llévala hacia el pecho, manteniendo la pierna izquierda extendida y el pie en flexión.","Lleva la pierna derecha en diagonal a través del cuerpo, extendiéndola por completo y activando los isquiotibiales.","Regresa lentamente la pierna derecha a la posición inicial, manteniendo el control y el equilibrio.","Repite el movimiento con la pierna izquierda, alternando los lados durante el número de repeticiones deseado."],"img":"1417-GOJKFfO.jpg","gif":"1417-GOJKFfO.gif"},{"id":"1296","n":"Flexión en pica con fitball","bp":"chest","eq":"stability ball","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps","core"],"st":["Comienza en posición de flexión de brazos con las manos en el suelo y las espinillas apoyadas sobre el balón de estabilidad.","Activa el core y levanta las caderas hacia el techo, haciendo rodar el balón hacia las manos.","Mantén las piernas rectas y el cuerpo en posición de pica, formando una V invertida.","Dobla los codos y baja la parte superior del cuerpo hacia el suelo, manteniendo la cabeza alineada con las manos.","Empuja con las manos y extiende los brazos para volver a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1296-sVvXT5J.jpg","gif":"1296-sVvXT5J.gif"},{"id":"1343","n":"Elevación de piernas en decúbito prono sobre fitball","bp":"back","eq":"stability ball","tg":"spine","mg":"abdominals","sm":["abdominals","glutes"],"st":["Túmbate boca abajo sobre una esterilla con las piernas extendidas y los dedos de los pies apoyados sobre el balón de estabilidad.","Coloca las manos en el suelo, separadas a la altura de los hombros, y activa el abdomen.","Manteniendo las piernas rectas, levántalas lentamente del suelo, usando la zona lumbar y los glúteos para elevarlas tan alto como sea posible.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1343-lCKm4Rs.jpg","gif":"1343-lCKm4Rs.gif"},{"id":"1560","n":"Estiramiento de isquiotibiales sentado sobre fitball","bp":"upper legs","eq":"stability ball","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back"],"st":["Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Haz rodar el balón lentamente hacia adelante, caminando con los pies hacia afuera hasta que la parte superior de la espalda quede apoyada sobre el balón y las piernas queden extendidas rectas frente a ti.","Coloca las manos en las caderas para mayor apoyo.","Activa el core y baja lentamente la parte superior del cuerpo hacia el suelo, manteniendo la espalda recta y el pecho elevado.","Detente cuando sientas un estiramiento en los isquiotibiales y mantén la posición durante 20-30 segundos.","Regresa lentamente a la posición inicial empujando con los talones y usando los isquiotibiales para volver a subir.","Repite el número de repeticiones deseado."],"img":"1560-yRYyfdA.jpg","gif":"1560-yRYyfdA.gif"},{"id":"1745","n":"Estiramiento de tríceps sentado sobre fitball","bp":"upper arms","eq":"stability ball","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta.","Sostén una mancuerna con una mano y extiende el brazo recto por encima de la cabeza.","Dobla el codo y baja la mancuerna detrás de la cabeza, manteniendo el brazo cerca de la oreja.","Mantén el estiramiento durante unos segundos, luego regresa a la posición inicial.","Repite con el otro brazo."],"img":"1745-7ePTw4B.jpg","gif":"1745-7ePTw4B.gif"},{"id":"1746","n":"Extensión de tríceps en decúbito supino sobre fitball","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Sostén una mancuerna con ambas manos y extiende los brazos rectos hacia el techo.","Baja lentamente la mancuerna detrás de la cabeza, manteniendo los codos cerca de las orejas.","Haz una pausa por un momento, luego sube la mancuerna de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1746-Gm2Uv1z.jpg","gif":"1746-Gm2Uv1z.gif"},{"id":"1747","n":"Press francés con barra EZ sobre fitball","bp":"upper arms","eq":"ez barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Siéntate sobre un balón de ejercicio y sostén una barra EZ con agarre prono.","Extiende los brazos rectos hacia arriba, manteniendo los codos cerca de la cabeza.","Baja lentamente la barra detrás de la cabeza doblando los codos.","Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1747-CFN9P8G.jpg","gif":"1747-CFN9P8G.gif"},{"id":"3010","n":"Pullover con brazos flexionados tumbado con barra EZ","bp":"back","eq":"ez barbell","tg":"lats","mg":"triceps","sm":["triceps","chest"],"st":["Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo.","Sostén la barra EZ con agarre prono (palmas hacia afuera) y las manos separadas a la altura de los hombros.","Extiende los brazos rectos por encima del pecho, manteniendo una ligera flexión en los codos.","Baja la barra describiendo un arco detrás de la cabeza, manteniendo la ligera flexión en los codos.","Haz una pausa breve, luego regresa la barra a la posición inicial invirtiendo el movimiento del arco.","Repite el número de repeticiones deseado."],"img":"3010-nDK1HJ0.jpg","gif":"3010-nDK1HJ0.gif"},{"id":"1748","n":"Extensión de tríceps tras nuca tumbado con agarre cerrado y barra EZ","bp":"upper arms","eq":"ez barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.","Sostén la barra EZ con agarre cerrado, palmas hacia arriba, y extiende los brazos rectos por encima del pecho.","Manteniendo los brazos superiores fijos, baja lentamente la barra detrás de la cabeza flexionando los codos.","Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1748-6CKUx7o.jpg","gif":"1748-6CKUx7o.gif"},{"id":"1344","n":"Remo inclinado con barra EZ y agarre supino","bp":"back","eq":"ez barbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sostén la barra EZ con agarre supino, palmas hacia arriba, y las manos separadas a la altura de los hombros.","Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado, hasta que el torso quede casi paralelo al suelo.","Tira de la barra EZ hacia la parte baja del pecho, apretando los omóplatos entre sí.","Haz una pausa breve en la parte superior, luego baja lentamente la barra EZ a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1344-G8dXpNG.jpg","gif":"1344-G8dXpNG.gif"},{"id":"1682","n":"Curl concentrado sentado con barra EZ y agarre cerrado","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco con los pies apoyados en el suelo y sostén una barra EZ con agarre supino.","Apoya el codo en la parte interna del muslo, justo por encima de la rodilla.","Sube la barra curvando el brazo hacia el hombro mientras mantienes el brazo superior inmóvil.","Contrae los bíceps en la parte superior del movimiento, luego baja lentamente la barra a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1682-Dsfz0Id.jpg","gif":"1682-Dsfz0Id.gif"},{"id":"1749","n":"Press francés de pie con barra EZ","bp":"upper arms","eq":"ez barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre prono.","Levanta la barra por encima de la cabeza, extendiendo completamente los brazos.","Manteniendo los brazos superiores cerca de la cabeza, baja lentamente la barra detrás de la cabeza flexionando los codos.","Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1749-1cTf2Ux.jpg","gif":"1749-1cTf2Ux.gif"},{"id":"0445","n":"Press antigravedad con barra EZ","bp":"shoulders","eq":"ez barbell","tg":"delts","mg":"triceps","sm":["triceps","chest"],"st":["Comienza de pie con los pies separados a la altura de los hombros y sosteniendo la barra EZ con agarre prono.","Eleva la barra hasta la altura de los hombros, manteniendo los codos ligeramente flexionados y las palmas hacia adelante.","Empuja la barra por encima de la cabeza, extendiendo completamente los brazos.","Baja la barra de vuelta a la altura de los hombros y repite el número de repeticiones deseado."],"img":"0445-fprd84i.jpg","gif":"0445-fprd84i.gif"},{"id":"1627","n":"Curl de bíceps en banco Scott con barra EZ y agarre cerrado","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco scott y coloca los brazos superiores sobre la almohadilla, sujetando la barra EZ con agarre supino.","Apoya los tríceps sobre la almohadilla y extiende los brazos por completo, manteniendo la espalda recta.","Sube lentamente la barra hacia los hombros, contrayendo los bíceps.","Haz una pausa breve en la parte alta, apretando los bíceps.","Baja la barra a la posición inicial, extendiendo los brazos por completo.","Repite el número de repeticiones deseado."],"img":"1627-hacCyUv.jpg","gif":"1627-hacCyUv.gif"},{"id":"0446","n":"Curl con barra EZ con agarre estrecho","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, manos separadas a la altura de los hombros.","Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento.","Sube la barra hacia los hombros, contrayendo los bíceps.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0446-V4ryaZa.jpg","gif":"0446-V4ryaZa.gif"},{"id":"0447","n":"Curl con barra EZ","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, palmas hacia arriba.","Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento.","Exhala mientras subes la barra hacia los hombros, contrayendo los bíceps.","Haz una pausa breve en la parte más alta, luego inhala mientras bajas lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0447-6TG6x2w.jpg","gif":"0447-6TG6x2w.gif"},{"id":"0448","n":"Press facial declinado con barra EZ y agarre estrecho","bp":"upper arms","eq":"ez barbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Túmbate en un banco declinado con la cabeza más baja que los pies.","Sujeta la barra EZ con agarre cerrado, palmas una frente a la otra.","Extiende los brazos rectos por encima del pecho, manteniendo los codos cerca del cuerpo.","Baja la barra hacia la frente doblando los codos.","Haz una pausa breve, luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0448-DgZQ11d.jpg","gif":"0448-DgZQ11d.gif"},{"id":"2186","n":"Extensión de tríceps en banco declinado con barra EZ","bp":"upper arms","eq":"ez barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Túmbate en un banco declinado con la cabeza más baja que los pies y los pies asegurados.","Sostén la barra EZ con agarre prono, manos separadas a la altura de los hombros.","Extiende completamente los brazos, manteniendo los codos cerca de la cabeza.","Baja la barra lentamente hacia la frente, doblando los codos.","Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2186-CQHoDm0.jpg","gif":"2186-CQHoDm0.gif"},{"id":"0449","n":"Extensión de tríceps en banco inclinado con barra EZ","bp":"upper arms","eq":"ez barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Coloca un banco inclinado a un ángulo de 45 grados.","Siéntate en el banco con la espalda apoyada en el respaldo y sostén la barra EZ con agarre prono.","Extiende completamente los brazos por encima de la cabeza, manteniendo los codos cerca de la cabeza.","Baja la barra detrás de la cabeza doblando los codos, manteniendo los brazos superiores inmóviles.","Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0449-KyLtiLT.jpg","gif":"0449-KyLtiLT.gif"},{"id":"0450","n":"Press de banca JM con barra EZ","bp":"upper arms","eq":"ez barbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Sujeta la barra EZ con agarre prono, ligeramente más ancho que la altura de los hombros.","Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"0450-hnOYgH3.jpg","gif":"0450-hnOYgH3.gif"},{"id":"0451","n":"Curl con barra EZ con agarre prono","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino.","Mantén los codos cerca del torso y los brazos superiores inmóviles durante todo el ejercicio.","Sube la barra contrayendo los bíceps, mientras exhalas.","Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Comienza a regresar la barra lentamente a la posición inicial mientras inhalas.","Repite el número de repeticiones deseado."],"img":"0451-Y5X65IB.jpg","gif":"0451-Y5X65IB.gif"},{"id":"0452","n":"Curl predicador con barra EZ y agarre prono","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco scott con el pecho apoyado en la almohadilla y los pies planos sobre el suelo.","Sujeta la barra EZ con agarre supino, manos separadas a la altura de los hombros.","Apoya los brazos superiores en la almohadilla, dejando que los antebrazos cuelguen hacia abajo.","Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros.","Haz una pausa breve en la parte más alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0452-vBNyir7.jpg","gif":"0452-vBNyir7.gif"},{"id":"1458","n":"Curl sentado con barra EZ","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en un banco con los pies apoyados planos en el suelo y la espalda recta.","Sostén la barra EZ con agarre supino, palmas hacia arriba, y las manos separadas a la altura de los hombros.","Apoya los brazos superiores en los muslos, dejando que la barra EZ cuelgue frente a ti.","Manteniendo los brazos superiores inmóviles, exhala y sube la barra EZ hacia los hombros.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente la barra EZ a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1458-jtFKbt5.jpg","gif":"1458-jtFKbt5.gif"},{"id":"0453","n":"Extensión de tríceps sentado con barra EZ","bp":"upper arms","eq":"ez barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sostén la barra EZ con agarre prono, manos separadas a la altura de los hombros.","Levanta la barra por encima de la cabeza, extendiendo completamente los brazos.","Manteniendo los brazos superiores inmóviles, baja la barra detrás de la cabeza doblando los codos.","Haz una pausa breve, luego levanta la barra de vuelta a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."],"img":"0453-iaapw0g.jpg","gif":"0453-iaapw0g.gif"},{"id":"0454","n":"Curl araña con barra EZ tumbado en banco","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, palmas hacia arriba.","Apoya los brazos superiores en un banco scott o en un balón de estabilidad, dejando que los codos cuelguen hacia abajo.","Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0454-Ye5Qxb0.jpg","gif":"0454-Ye5Qxb0.gif"},{"id":"1628","n":"Curl araña con barra EZ de pie en banco preacher","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, palmas hacia arriba.","Apoya los brazos superiores en un banco scott o en un balón de estabilidad, dejando que los codos cuelguen hacia abajo.","Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1628-2kattbR.jpg","gif":"1628-2kattbR.gif"},{"id":"2404","n":"Curl de bíceps con barra EZ (con aislador de bíceps)","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, palmas hacia arriba.","Coloca los brazos superiores contra el soporte de aislamiento de brazos, manteniéndolos inmóviles durante todo el ejercicio.","Manteniendo los codos cerca del cuerpo, exhala y sube la barra hacia los hombros.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"2404-tJ5nYqo.jpg","gif":"2404-tJ5nYqo.gif"},{"id":"2432","n":"Press de banca con agarre estrecho con barra EZ","bp":"upper arms","eq":"ez barbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Sujeta la barra EZ con agarre cerrado, manos separadas a la altura de los hombros, palmas hacia adelante.","Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.","Baja la barra lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.","Haz una pausa breve cuando la barra toque el pecho.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"2432-da4cXST.jpg","gif":"2432-da4cXST.gif"},{"id":"2741","n":"Curl de bíceps de pie con barra EZ y agarre ancho","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, manos más separadas que la altura de los hombros.","Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento.","Sube la barra hacia los hombros contrayendo los bíceps.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2741-OVTZ65k.jpg","gif":"2741-OVTZ65k.gif"},{"id":"2133","n":"Paseo del granjero","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"calves","sm":["calves","forearms","core"],"st":["Ponte de pie con una mancuerna en cada mano, palmas hacia los costados.","Mantén la espalda recta y los hombros hacia atrás.","Da pasos pequeños y controlados hacia adelante, manteniendo una postura erguida.","Continúa caminando durante la distancia o el tiempo deseado.","Para terminar, deja de caminar y baja con cuidado las mancuernas a los costados."],"img":"2133-qPEzJjA.jpg","gif":"2133-qPEzJjA.gif"},{"id":"0455","n":"Curl de dedos","bp":"lower arms","eq":"barbell","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","grip muscles"],"st":["Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre supino, con las palmas hacia arriba.","Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde.","Curva lentamente los dedos hacia las palmas, apretando la barra con fuerza.","Mantén la contracción por un momento, luego suelta lentamente los dedos hasta la posición inicial.","Repite el número de repeticiones deseado."],"img":"0455-awG04cF.jpg","gif":"0455-awG04cF.gif"},{"id":"3303","n":"Bandera humana","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","shoulders"],"st":["Comienza sujetando un poste vertical con ambas manos, palmas una frente a la otra, y los brazos completamente extendidos.","Activa el core y levanta las piernas del suelo, manteniéndolas rectas.","Usando la fuerza del core y de la parte superior del cuerpo, levanta las piernas hasta que queden paralelas al suelo.","Mantén esta posición todo el tiempo que puedas, conservando una línea corporal recta.","Baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3303-pQ0Mx1Z.jpg","gif":"3303-pQ0Mx1Z.gif"},{"id":"0456","n":"Abdominales sit-up con piernas flexionadas (rodillas dobladas)","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Al mismo tiempo, levanta las piernas del suelo, doblando las rodillas y llevándolas hacia el pecho.","Haz una pausa breve en la parte superior, luego baja lentamente la parte superior del cuerpo y las piernas a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0456-AR0ig3o.jpg","gif":"0456-AR0ig3o.gif"},{"id":"0457","n":"Abdominales sit-up con piernas flexionadas (brazos rectos)","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","quadriceps"],"st":["Túmbate boca arriba con las piernas extendidas y los brazos rectos por encima de la cabeza.","Activando el abdomen, levanta la parte superior del cuerpo del suelo mientras al mismo tiempo levantas las piernas hacia el pecho.","Extiende las manos hacia los dedos de los pies mientras levantas la parte superior del cuerpo y las piernas.","Haz una pausa breve en la parte superior, luego baja lentamente la parte superior del cuerpo y las piernas a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0457-KZn52RC.jpg","gif":"0457-KZn52RC.gif"},{"id":"0458","n":"Aperturas en el suelo con barra","bp":"chest","eq":"barbell","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo.","Sostén una barra con agarre prono, brazos extendidos rectos por encima del pecho.","Baja lentamente la barra hacia los lados, manteniendo una ligera flexión en los codos.","Baja la barra hasta que los brazos queden paralelos al suelo, sintiendo un estiramiento en el pecho.","Haz una pausa breve, luego contrae los músculos del pecho para llevar la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0458-neonEDL.jpg","gif":"0458-neonEDL.gif"},{"id":"0459","n":"Aleteo de piernas","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","lower abs"],"st":["Túmbate boca arriba con las piernas extendidas y las manos a los costados.","Activa el core y levanta las piernas del suelo unos 15 centímetros.","Manteniendo las piernas rectas, alterna levantando una pierna ligeramente más alto que la otra.","Continúa este movimiento de aleteo durante el número de repeticiones deseado."],"img":"0459-UVo2Qs2.jpg","gif":"0459-UVo2Qs2.gif"},{"id":"1472","n":"Salto hacia adelante","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","hamstrings","glutes"],"st":["Ponte de pie con los pies separados a la altura de los hombros.","Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla.","Balancea los brazos hacia atrás para generar impulso.","Salta hacia adelante de forma explosiva, extendiendo las caderas, las rodillas y los tobillos.","Aterriza suavemente sobre la punta de los pies y pasa de inmediato al siguiente salto.","Repite el número de repeticiones deseado."],"img":"1472-uZKq7lo.jpg","gif":"1472-uZKq7lo.gif"},{"id":"3470","n":"Zancada hacia adelante (hombre)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de las caderas y las manos en las caderas.","Da un paso grande hacia adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.","Dobla la rodilla derecha hasta unos 90 grados, manteniendo la rodilla alineada con el tobillo.","Empuja con el pie derecho y vuelve a la posición inicial.","Repite con la pierna izquierda, alternando los lados durante el número de repeticiones deseado."],"img":"3470-kMzUs9Y.jpg","gif":"3470-kMzUs9Y.gif"},{"id":"3194","n":"Sentadilla Frankenstein","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén la barra frente al cuerpo con los brazos rectos.","Manteniendo la espalda recta, baja el cuerpo flexionando las rodillas y las caderas, como si fueras a sentarte en una silla.","Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3194-bdWcbaU.jpg","gif":"3194-bdWcbaU.gif"},{"id":"2429","n":"Crunch de rana","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que el torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2429-FFRP97T.jpg","gif":"2429-FFRP97T.gif"},{"id":"3301","n":"Frog planche","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","chest","triceps"],"st":["Comienza en posición de flexión de brazos con las manos separadas a la altura de los hombros y los pies juntos.","Dobla los codos y baja el cuerpo hacia el suelo, manteniendo la espalda recta.","Mientras bajas el cuerpo, levanta los pies del suelo y lleva las rodillas hacia el pecho.","Mantén esta posición durante unos segundos, luego extiende las piernas de nuevo y empújate hacia arriba a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3301-rQhGcin.jpg","gif":"3301-rQhGcin.gif"},{"id":"3296","n":"Front lever","bp":"waist","eq":"body weight","tg":"abs","mg":"lats","sm":["lats","shoulders","forearms"],"st":["Comienza colgado de una barra de dominadas con agarre prono, manos separadas a la altura de los hombros.","Activa el core y lleva los omóplatos hacia abajo y atrás.","Flexiona las rodillas y llévalas hacia el pecho.","Al mismo tiempo, levanta las piernas y extiéndelas rectas frente a ti, manteniendo el cuerpo paralelo al suelo.","Mantén esta posición todo el tiempo que puedas, intentando lograr una posición completa de palanca frontal.","Para soltar, baja lentamente las piernas y regresa a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3296-PkCN2lv.jpg","gif":"3296-PkCN2lv.gif"},{"id":"3295","n":"Repeticiones de front lever","bp":"back","eq":"body weight","tg":"upper back","mg":"core","sm":["core","shoulders"],"st":["Cuélgate de una barra de dominadas con agarre prono, palmas hacia afuera.","Activa el core y lleva los omóplatos hacia abajo y atrás.","Manteniendo el cuerpo recto, levanta las piernas hasta que queden paralelas al suelo.","Mantén esta posición todo el tiempo que puedas, intentando llegar a 10-20 segundos.","Baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3295-hbY9wqG.jpg","gif":"3295-hbY9wqG.gif"},{"id":"0464","n":"Plancha frontal con torsión","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","shoulders"],"st":["Comienza en posición de plancha alta con las manos directamente debajo de los hombros y el cuerpo en línea recta de la cabeza a los pies.","Activa el core y los glúteos para mantener una posición estable.","Gira el torso hacia la derecha, levantando el brazo derecho y extendiéndolo hacia el techo.","Mantén las caderas y las piernas estables mientras giras.","Mantén la posición por un momento, luego regresa a la posición inicial.","Repite el giro hacia el lado izquierdo.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0464-CosupLu.jpg","gif":"0464-CosupLu.gif"},{"id":"3315","n":"Maltese completa","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","chest"],"st":["Comienza de pie con los pies separados a la altura de los hombros y los brazos extendidos rectos hacia los lados.","Inclínate lentamente hacia adelante, manteniendo los brazos rectos, hasta que la parte superior del cuerpo quede paralela al suelo.","Activa el core y mantén esta posición durante unos segundos.","Regresa a la posición inicial empujando con los pies y volviendo a ponerte de pie.","Repite el número de repeticiones deseado."],"img":"3315-YRaCa5Y.jpg","gif":"3315-YRaCa5Y.gif"},{"id":"3299","n":"Full planche","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","chest","triceps"],"st":["Comienza en posición de flexión de brazos con las manos separadas a la altura de los hombros y los dedos apuntando hacia adelante.","Activa el core y desplaza lentamente el peso hacia adelante, levantando los pies del suelo.","Continúa desplazando el peso hacia adelante hasta que el cuerpo quede paralelo al suelo, equilibrándote sobre las manos.","Mantén esta posición todo el tiempo que puedas, conservando una línea corporal recta.","Baja lentamente los pies de nuevo al suelo y regresa a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3299-YZ4961r.jpg","gif":"3299-YZ4961r.gif"},{"id":"3327","n":"Flexión en full planche","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps","core"],"st":["Comienza en posición de flexión de brazos con las manos un poco más separadas que el ancho de los hombros.","Activa el core y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados.","Mientras te bajas, inclina el cuerpo hacia adelante y levanta los pies del suelo, equilibrándote sobre las manos.","Continúa bajando el cuerpo hasta que el pecho quede justo por encima del suelo.","Empuja con las manos y extiende los brazos para volver a subir el cuerpo a la posición inicial.","Mantén una línea recta desde la cabeza hasta los talones durante todo el movimiento.","Repite el número de repeticiones deseado."],"img":"3327-gw9PqGk.jpg","gif":"3327-gw9PqGk.gif"},{"id":"0466","n":"Dominadas al esternón Gironda","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Ponte de pie frente a una barra alta con los pies separados a la altura de los hombros.","Estira los brazos hacia arriba y agarra la barra con agarre prono, ligeramente más ancho que la altura de los hombros.","Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.","Activa los dorsales y los bíceps para llevar el pecho hacia la barra, guiando con el esternón.","Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0466-IL0JUxR.jpg","gif":"0466-IL0JUxR.gif"},{"id":"3561","n":"Puente de glúteos con marcha","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Activa los glúteos y levanta las caderas del suelo, formando una línea recta desde las rodillas hasta los hombros.","Manteniendo las caderas elevadas, levanta un pie del suelo y lleva la rodilla hacia el pecho.","Baja el pie de nuevo al suelo y repite el movimiento con la otra pierna.","Continúa alternando las piernas con un movimiento de marcha mientras mantienes la posición de puente.","Repite el número de repeticiones deseado."],"img":"3561-GibBPPg.jpg","gif":"3561-GibBPPg.gif"},{"id":"3523","n":"Puente de glúteos con dos piernas en banco (hombre)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Siéntate en el borde de un banco con la espalda apoyada en él y los pies planos sobre el suelo.","Coloca las manos en el banco junto a las caderas para mayor apoyo.","Activa los glúteos y los isquiotibiales, luego levanta las caderas del banco hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.","Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3523-aWedzZX.jpg","gif":"3523-aWedzZX.gif"},{"id":"3193","n":"Elevación de glúteos y femorales (GHR)","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back"],"st":["Ajusta la máquina de extensión de glúteos e isquiotibiales para que se adapte a tu cuerpo.","Colócate boca abajo en la máquina con los tobillos asegurados.","Coloca las manos sobre el pecho o crúzalas sobre el pecho.","Activa los isquiotibiales y los glúteos para levantar la parte superior del cuerpo hacia el techo.","Continúa levantando hasta que el cuerpo forme una línea recta desde la cabeza hasta los talones.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3193-Vvwjz6N.jpg","gif":"3193-Vvwjz6N.gif"},{"id":"0467","n":"Dominada gorila","bp":"waist","eq":"body weight","tg":"abs","mg":"forearms","sm":["forearms","biceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta una barra de dominadas con agarre prono, ligeramente más ancho que la altura de los hombros.","Cuélgate de la barra con los brazos completamente extendidos y las palmas hacia afuera.","Activa el core y tira del cuerpo hacia la barra, llevando la barbilla por encima de la barra.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0467-bmwlYvD.jpg","gif":"0467-bmwlYvD.gif"},{"id":"0469","n":"Crunch para aductores","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","inner thighs"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta las piernas del suelo, llevando las rodillas hacia el pecho.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0469-mWppALS.jpg","gif":"0469-mWppALS.gif"},{"id":"1383","n":"Elevación de talones en máquina Hack","bp":"lower legs","eq":"sled machine","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Ajusta la máquina de trineo a un peso adecuado.","Ponte de pie sobre la máquina de trineo con la punta de los pies en la plataforma y los talones colgando.","Sujétate de las asas para mantener el equilibrio.","Levanta los talones lo más alto posible empujando con la punta de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1383-2ORFMoR.jpg","gif":"1383-2ORFMoR.gif"},{"id":"1384","n":"Elevación de talón a una pierna en máquina hack","bp":"lower legs","eq":"sled machine","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Ajusta la máquina de trineo a un peso adecuado.","Ponte de pie sobre la máquina de trineo con un pie, manteniendo el otro pie levantado del suelo.","Sujétate de las asas para mantener el equilibrio.","Levanta el talón lo más alto posible, elevando el cuerpo sobre la punta del pie.","Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.","Repite el número de repeticiones deseado.","Cambia de pierna y repite el ejercicio."],"img":"1384-AxFoqAD.jpg","gif":"1384-AxFoqAD.gif"},{"id":"3221","n":"Semisentadilla (hombre)","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","glutes"],"st":["Ponte de pie con los pies separados a la altura de los hombros.","Dobla las rodillas y baja el cuerpo como si te fueras a sentar en una silla.","Mantén el pecho elevado y el peso en los talones.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3221-ia6kIIl.jpg","gif":"3221-ia6kIIl.gif"},{"id":"3202","n":"Medio sit-up (hombre)","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3202-iQ241UP.jpg","gif":"3202-iQ241UP.gif"},{"id":"1511","n":"Estiramiento de isquiotibiales","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes"],"st":["Ponte de pie con los pies separados a la altura de los hombros.","Da un paso adelante con el pie derecho y traslada el peso hacia la pierna derecha.","Manteniendo la espalda recta, inclínate lentamente hacia adelante desde las caderas, alcanzando el pie derecho con ambas manos.","Mantén el estiramiento durante 20-30 segundos, luego vuelve a la posición inicial.","Repite del otro lado."],"img":"1511-99rWm7w.jpg","gif":"1511-99rWm7w.gif"},{"id":"2139","n":"Pedaleo con manos","bp":"chest","eq":"upper body ergometer","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Ajusta la altura del asiento y la posición del manillar a un nivel cómodo.","Siéntate en el ergómetro con la espalda recta y los pies sobre los pedales.","Sujeta las asas con las manos y coloca los brazos en un ángulo de 90 grados.","Comienza a pedalear con las manos, empujando y tirando de las asas con un movimiento controlado.","Continúa pedaleando durante el tiempo o el número de repeticiones deseado."],"img":"2139-pAIWRGu.jpg","gif":"2139-pAIWRGu.gif"},{"id":"3218","n":"Toque de puntas circular con manos entrelazadas (hombre)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las manos entrelazadas frente al pecho.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Baja las manos hacia los dedos de los pies con un movimiento circular, llegando tan lejos como puedas sin forzar.","Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3218-B5xca8s.jpg","gif":"3218-B5xca8s.gif"},{"id":"3215","n":"Toque de puntas circular con manos entrelazadas invertidas (hombre)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados.","Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y las rodillas ligeramente flexionadas.","Extiende las manos hacia abajo y entrelázalas detrás de las piernas.","Sube lentamente las manos en un movimiento circular por encima de la cabeza, manteniendo las piernas rectas.","Continúa el movimiento circular hasta que las manos toquen los dedos de los pies.","Invierte el movimiento y regresa las manos a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3215-yq3GAJX.jpg","gif":"3215-yq3GAJX.gif"},{"id":"3302","n":"Pino","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Busca un espacio abierto con suficiente espacio para hacer un pino.","Coloca las manos en el suelo separadas a la altura de los hombros, con los dedos apuntando hacia adelante.","Lanza las piernas hacia la pared, usando el core y los hombros para mantener el equilibrio.","Una vez en posición de pino, activa los tríceps para sostener el peso corporal.","Mantén el pino el mayor tiempo posible mientras conserves el equilibrio.","Para bajar, lleva lentamente las piernas de vuelta al suelo.","Repite el número de repeticiones deseado."],"img":"3302-XooAdhl.jpg","gif":"3302-XooAdhl.gif"},{"id":"0471","n":"Flexión haciendo el pino","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders","chest","core"],"st":["Busca una pared y colócate de espaldas a ella, de pie a unos pasos de distancia.","Coloca las manos en el suelo separadas a la altura de los hombros y lanza los pies hacia la pared, llegando a una posición de pino.","Dobla los codos y baja la cabeza hacia el suelo, manteniendo el cuerpo en línea recta.","Empuja con las manos y extiende los brazos para volver a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0471-rQxwMxO.jpg","gif":"0471-rQxwMxO.gif"},{"id":"1764","n":"Elevación de piernas y cadera colgado","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.","Activa el core y levanta las piernas flexionando las caderas y las rodillas hasta que los muslos queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1764-VEcJRo2.jpg","gif":"1764-VEcJRo2.gif"},{"id":"0472","n":"Elevación de piernas colgado","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.","Activa el core y levanta las piernas frente a ti, manteniéndolas rectas.","Continúa levantando hasta que las piernas estén paralelas al suelo o tan alto como puedas llegar cómodamente.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0472-I3tsCnC.jpg","gif":"0472-I3tsCnC.gif"},{"id":"1761","n":"Elevación de rodillas oblicua colgado","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.","Activa el core y levanta las rodillas hacia el pecho, girando el torso hacia un lado mientras lo haces.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite hacia el otro lado, girando el torso en la dirección opuesta.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"1761-BaE7O6U.jpg","gif":"1761-BaE7O6U.gif"},{"id":"0473","n":"Pliegue carpado colgado","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","shoulders"],"st":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.","Activa el core y levanta las piernas hacia la barra, manteniéndolas rectas.","Continúa levantando hasta que el cuerpo forme una 'V', con las piernas paralelas al suelo.","Mantén la posición por un momento, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0473-nuBF9MO.jpg","gif":"0473-nuBF9MO.gif"},{"id":"0474","n":"Elevación de piernas rectas y cadera colgado","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.","Activa el core y levanta las piernas hacia adelante hasta que queden paralelas al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0474-pj0X0tF.jpg","gif":"0474-pj0X0tF.gif"},{"id":"0475","n":"Elevación de piernas rectas colgado","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.","Activa el core y levanta las piernas frente a ti, manteniéndolas rectas.","Continúa levantando hasta que las piernas estén paralelas al suelo o tan alto como puedas llegar cómodamente.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0475-4Ml7QFO.jpg","gif":"0475-4Ml7QFO.gif"},{"id":"0476","n":"Elevación de piernas rectas y cadera con torsión colgado","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las piernas rectas.","Activa el core y levanta las piernas hacia el pecho, manteniéndolas rectas.","Cuando las piernas queden paralelas al suelo, gira las caderas hacia un lado, llevando las piernas hacia ese lado.","Haz una pausa breve y luego vuelve a la posición inicial.","Repite el movimiento, pero esta vez gira las caderas hacia el lado opuesto.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0476-Q6bvyen.jpg","gif":"0476-Q6bvyen.gif"},{"id":"3636","n":"Rodilla al pecho apoyado en pared","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","glutes","calves"],"st":["Ponte de pie frente a una pared con los pies separados a la altura de las caderas.","Coloca las manos en la pared para mayor apoyo.","Activa el core y levanta la rodilla derecha hacia el pecho, mientras mantienes el pie izquierdo en el suelo.","Cambia rápidamente de pierna, llevando la rodilla izquierda hacia el pecho y bajando el pie derecho de nuevo.","Continúa alternando las piernas con un movimiento de carrera, llevando las rodillas lo más alto posible.","Mantén un ritmo rápido y la parte superior del cuerpo estable durante todo el ejercicio.","Repite durante la duración o el número de repeticiones deseado."],"img":"3636-ealLwvX.jpg","gif":"3636-ealLwvX.gif"},{"id":"0484","n":"Elevación de cadera (rodillas flexionadas)","bp":"waist","eq":"body weight","tg":"abs","mg":"glutes","sm":["glutes","hamstrings"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos a los lados, con las palmas hacia abajo.","Activa el core y los glúteos, luego levanta las caderas del suelo hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.","Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0484-196HJGw.jpg","gif":"0484-196HJGw.gif"},{"id":"1418","n":"Abrazo de rodillas al pecho","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Comienza de pie con los pies separados a la altura de los hombros.","Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla.","Al ponerte en cuclillas, lleva las rodillas hacia el pecho y abrázalas con los brazos.","Mantén esta posición por un momento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1418-znP9SIh.jpg","gif":"1418-znP9SIh.gif"},{"id":"3234","n":"Aperturas Hyght con mancuernas","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders"],"st":["Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí.","Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos.","Manteniendo una ligera flexión en los codos, baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho.","Haz una pausa por un momento, luego invierte el movimiento y lleva las mancuernas de nuevo hacia arriba hasta la posición inicial.","Repite el número de repeticiones deseado."],"img":"3234-P9ZRyLT.jpg","gif":"3234-P9ZRyLT.gif"},{"id":"0489","n":"Hiperextensiones","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Ajusta el banco de hiperextensiones para que la parte superior de los muslos quede apoyada en la almohadilla y los pies queden asegurados.","Cruza los brazos sobre el pecho o coloca las manos detrás de la cabeza.","Baja la parte superior del cuerpo hacia el suelo manteniendo la espalda recta.","Haz una pausa breve en la parte baja, luego eleva la parte superior del cuerpo hasta que quede alineada con las piernas.","Repite el número de repeticiones deseado."],"img":"0489-zhMwOwE.jpg","gif":"0489-zhMwOwE.gif"},{"id":"0488","n":"Hiperextensiones en banco","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Ajusta el banco de hiperextensiones para que las caderas queden apoyadas cómodamente en la almohadilla y los pies queden asegurados.","Cruza los brazos sobre el pecho o coloca las manos detrás de la cabeza.","Baja lentamente la parte superior del cuerpo hacia el suelo manteniendo la espalda recta.","Haz una pausa breve en la parte baja, luego eleva la parte superior del cuerpo hasta que quede alineada con las piernas.","Repite el número de repeticiones deseado."],"img":"0488-zkgRrbK.jpg","gif":"0488-zkgRrbK.gif"},{"id":"3289","n":"Fondos imposibles","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Colócate entre dos barras paralelas con los brazos completamente extendidos y el cuerpo suspendido en el aire.","Flexiona las rodillas y cruza los tobillos.","Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.","Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.","Repite el número de repeticiones deseado."],"img":"3289-05Cf2v8.jpg","gif":"3289-05Cf2v8.gif"},{"id":"1471","n":"El gusano (inchworm) completo","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","hamstrings"],"st":["Comienza de pie con los pies separados a la altura de las caderas.","Inclínate hacia adelante desde la cintura y coloca las manos en el suelo frente a ti.","Camina con las manos hacia adelante hasta quedar en posición de plancha alta, con el cuerpo en línea recta de la cabeza a los pies.","Haz una pausa breve, luego camina con las manos de vuelta hacia los pies, manteniendo las piernas lo más rectas posible.","Cuando las manos lleguen a los pies, ponte de pie de nuevo en la posición inicial.","Repite el número de repeticiones deseado."],"img":"1471-ZgsNQ6d.jpg","gif":"1471-ZgsNQ6d.gif"},{"id":"3698","n":"El gusano (inchworm) a pike","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","hamstrings"],"st":["Comienza de pie con los pies separados a la altura de las caderas.","Inclínate hacia adelante desde la cintura y coloca las manos en el suelo frente a ti.","Camina con las manos hacia adelante hasta quedar en posición de plancha alta, con el cuerpo en línea recta de la cabeza a los pies.","Manteniendo las piernas rectas, camina con los pies hacia las manos, llevando las caderas hacia el techo.","Continúa caminando con las manos hacia adelante, repitiendo el movimiento durante el número de repeticiones deseado."],"img":"3698-TV87DNB.jpg","gif":"3698-TV87DNB.gif"},{"id":"0490","n":"Flexiones inclinadas con agarre cerrado","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Coloca las manos sobre una superficie elevada, como un banco o un escalón, ligeramente más separadas que la altura de los hombros.","Extiende las piernas detrás de ti, apoyándote en la punta de los pies, con el cuerpo formando una línea recta desde la cabeza hasta los talones.","Baja el pecho hacia la superficie elevada doblando los codos, manteniéndolos cerca de los costados.","Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.","Repite el número de repeticiones deseado."],"img":"0490-1YB40kg.jpg","gif":"0490-1YB40kg.gif"},{"id":"0491","n":"Elevación de piernas y cadera en banco inclinado (piernas rectas)","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Túmbate en un banco inclinado con la espalda apoyada plana en el banco y las piernas extendidas rectas frente a ti.","Coloca las manos a los lados del banco para apoyarte.","Activando el abdomen, levanta las piernas del banco, elevándolas tan alto como puedas mientras las mantienes rectas.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0491-eVxAzgz.jpg","gif":"0491-eVxAzgz.gif"},{"id":"0492","n":"Salto en profundidad a flexión inclinada","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Busca una superficie elevada, como un banco o un escalón, y coloca las manos separadas a la altura de los hombros en el borde.","Da un paso hacia atrás con los pies, manteniendo el cuerpo en línea recta desde la cabeza hasta los talones.","Baja el pecho hacia el borde de la superficie, doblando los codos y manteniendo el cuerpo alineado.","Empuja con las palmas para extender los brazos y regresar a la posición inicial.","Salta desde el borde de la superficie, aterrizando suavemente con las rodillas ligeramente flexionadas.","Repite la flexión de brazos y el salto en profundidad durante el número de repeticiones deseado."],"img":"0492-CB8WET1.jpg","gif":"0492-CB8WET1.gif"},{"id":"0493","n":"Flexiones inclinadas","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Coloca las manos sobre una superficie elevada, como un banco o un escalón, ligeramente más separadas que la altura de los hombros.","Extiende las piernas detrás de ti, apoyándote en la punta de los pies, formando una línea recta desde la cabeza hasta los talones.","Baja el pecho hacia la superficie elevada doblando los codos, manteniendo el cuerpo en línea recta.","Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.","Repite el número de repeticiones deseado."],"img":"0493-B1EVP9F.jpg","gif":"0493-B1EVP9F.gif"},{"id":"3785","n":"Flexiones inclinadas en cajón","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Coloca las manos en el borde de una caja o una superficie elevada, ligeramente más separadas que la altura de los hombros.","Extiende las piernas detrás de ti, apoyándote en la punta de los pies, formando una línea recta desde la cabeza hasta los talones.","Baja el pecho hacia la caja doblando los codos, manteniendo el cuerpo en línea recta.","Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.","Repite el número de repeticiones deseado."],"img":"3785-F7vjXqT.jpg","gif":"3785-F7vjXqT.gif"},{"id":"0494","n":"Flexiones inclinadas con agarre invertido","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Coloca las manos en el borde de un banco o una superficie elevada, ligeramente más separadas que la altura de los hombros.","Extiende las piernas detrás de ti, apoyándote en la punta de los pies, formando una línea recta desde la cabeza hasta los talones.","Baja el pecho hacia el banco doblando los codos, manteniéndolos cerca de los costados.","Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."],"img":"0494-XaaRnRn.jpg","gif":"0494-XaaRnRn.gif"},{"id":"3011","n":"Flexiones escapulares inclinadas","bp":"chest","eq":"body weight","tg":"serratus anterior","mg":"triceps","sm":["triceps","shoulders"],"st":["Coloca un banco inclinado a un ángulo de 45 grados.","Coloca las manos en el banco, ligeramente más separadas que la altura de los hombros.","Coloca los pies en el suelo, separados a la altura de las caderas.","Baja el pecho hacia el banco, manteniendo los codos pegados al cuerpo.","Mientras bajas, retrae los omóplatos, apretándolos entre sí.","Empuja con las palmas para extender los brazos y regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3011-GdMa1ET.jpg","gif":"3011-GdMa1ET.gif"},{"id":"0495","n":"Sit-up inclinado con giro","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Coloca un banco inclinado a un ángulo de 45 grados.","Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies.","Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.","Activa el abdomen y levanta la parte superior del cuerpo del banco, curvándote hacia adelante.","Mientras te incorporas, gira el torso hacia un lado, llevando el codo hacia la rodilla opuesta.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el movimiento, esta vez girando el torso hacia el otro lado.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0495-9ZGZuOD.jpg","gif":"0495-9ZGZuOD.gif"},{"id":"1564","n":"Estiramiento intermedio de flexores de cadera y cuádriceps","bp":"upper legs","eq":"rope","tg":"quads","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.","Sujétate de un objeto estable para mayor apoyo.","Dobla la rodilla derecha y lleva el pie derecho hacia los glúteos, sujetando la cuerda con la mano derecha.","Tira lentamente del pie derecho hacia los glúteos, sintiendo un estiramiento en el cuádriceps derecho.","Mantén el estiramiento durante 20-30 segundos.","Suelta el estiramiento y repite en el lado izquierdo."],"img":"1564-tFGKm99.jpg","gif":"1564-tFGKm99.gif"},{"id":"0496","n":"Curl de piernas invertido (con apoyo en banco)","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","calves"],"st":["Túmbate boca abajo en un banco con las caderas en el borde y las piernas extendidas rectas detrás de ti.","Sujétate del banco para mayor apoyo.","Manteniendo la parte superior del cuerpo quieta, dobla las rodillas y curva las piernas hacia los glúteos.","Haz una pausa breve en la parte superior, luego extiende lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0496-ms7tjSG.jpg","gif":"0496-ms7tjSG.gif"},{"id":"2400","n":"Curl de piernas invertido en máquina de dominadas asistidas","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","calves"],"st":["Ajusta la máquina de cable para que las correas de tobillo estén en el ajuste más bajo.","Túmbate boca abajo en el banco con las piernas extendidas y las correas de tobillo sujetas a los pies.","Sujétate de las agarraderas del banco para mantener la estabilidad.","Dobla las rodillas y curva las piernas hacia los glúteos, contrayendo los isquiotibiales.","Haz una pausa breve en la parte superior del movimiento, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2400-0rHfvy9.jpg","gif":"2400-0rHfvy9.gif"},{"id":"0499","n":"Remo invertido smith/anillas","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Coloca una barra a la altura de la cintura o usa un entrenador de suspensión.","Ponte de pie frente a la barra o al entrenador de suspensión, con los pies separados a la altura de los hombros.","Agarra la barra o las asas con agarre prono, ligeramente más ancho que la altura de los hombros.","Inclínate hacia atrás, manteniendo el cuerpo recto y los talones en el suelo.","Tira del pecho hacia la barra o las asas, apretando los omóplatos entre sí.","Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0499-bZGHsAZ.jpg","gif":"0499-bZGHsAZ.gif"},{"id":"2300","n":"Remo invertido con rodillas flexionadas","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Coloca una barra a la altura de la cintura y túmbate debajo de ella.","Agarra la barra con agarre prono, ligeramente más ancho que la altura de los hombros.","Coloca el cuerpo de manera que los talones queden en el suelo y el cuerpo esté recto.","Tira del pecho hacia arriba en dirección a la barra apretando los omóplatos entre sí.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2300-VPPtusI.jpg","gif":"2300-VPPtusI.gif"},{"id":"2298","n":"Remo invertido con pies en banco","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Coloca un banco a una altura que permita que el cuerpo cuelgue libremente debajo de él.","Túmbate boca arriba en el suelo con la cabeza hacia el banco.","Estira los brazos hacia arriba y agarra el banco con agarre prono, ligeramente más ancho que la altura de los hombros.","Coloca el cuerpo de manera que los talones queden en el suelo y los brazos completamente extendidos.","Activa el core y aprieta los omóplatos entre sí mientras tiras del pecho hacia el banco.","Haz una pausa breve en la parte superior del movimiento, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2298-Mxa7Cr8.jpg","gif":"2298-Mxa7Cr8.gif"},{"id":"0497","n":"Remo invertido colgado","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Coloca una barra a la altura de la cintura en una máquina Smith o usa un entrenador de suspensión.","Ponte de pie frente a la barra o al entrenador de suspensión y agárrala con agarre prono, manos separadas a la altura de los hombros.","Camina con los pies hacia adelante, inclinándote hacia atrás hasta que el cuerpo quede en un ligero ángulo.","Mantén el cuerpo recto y tira del pecho hacia la barra o las asas, apretando los omóplatos entre sí.","Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0497-uX3sUBz.jpg","gif":"0497-uX3sUBz.gif"},{"id":"0498","n":"Remo invertido con correas de suspensión","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Coloca un entrenador de suspensión o correas a la altura del pecho.","Ponte de pie frente al punto de anclaje y agarra las asas con agarre prono.","Camina con los pies hacia adelante, inclinándote hacia atrás hasta que el cuerpo quede en ángulo.","Mantén el cuerpo recto y activa el core.","Tira del pecho hacia las asas, apretando los omóplatos entre sí.","Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0498-jdiExfW.jpg","gif":"0498-jdiExfW.gif"},{"id":"1419","n":"Estiramiento en cruz de hierro","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Túmbate boca arriba con los brazos extendidos hacia los lados.","Levanta las piernas hacia el techo, manteniéndolas rectas.","Baja lentamente las piernas hacia un lado, intentando tocar el suelo con los pies.","Mantén el estiramiento durante unos segundos, luego regresa las piernas a la posición inicial.","Repite el estiramiento en el otro lado.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"1419-pZwUsKB.jpg","gif":"1419-pZwUsKB.gif"},{"id":"1297","n":"Presión isométrica de pecho","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Extiende los brazos rectos frente a ti, paralelos al suelo, con las palmas una frente a la otra.","Aprieta los músculos del pecho con la mayor fuerza posible, manteniendo los brazos rectos.","Mantén esta posición durante unos segundos, concentrándote en contraer los músculos del pecho.","Suelta la contracción y relaja los músculos del pecho.","Repite el número de repeticiones deseado."],"img":"1297-HbSG1Pw.jpg","gif":"1297-HbSG1Pw.gif"},{"id":"0500","n":"Limpiaparabrisas isométrico","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps","core"],"st":["Comienza acostado boca arriba en una esterilla o un banco.","Extiende los brazos hacia los lados, perpendiculares al cuerpo.","Activa el core y levanta ambas piernas del suelo, manteniéndolas juntas y rectas.","Baja lentamente las piernas hacia un lado, intentando tocar el suelo con los pies mientras mantienes el control.","Haz una pausa breve, luego usa el core para llevar las piernas de vuelta a la posición inicial.","Repite el movimiento, esta vez bajando las piernas hacia el lado opuesto.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0500-11wrviz.jpg","gif":"0500-11wrviz.gif"},{"id":"0501","n":"Jack burpee","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","shoulders","triceps","core"],"st":["Comienza de pie con los pies separados a la altura de los hombros.","Baja el cuerpo a una posición de sentadilla, colocando las manos en el suelo frente a ti.","Lanza los pies hacia atrás, aterrizando en posición de flexión de brazos.","Realiza una flexión de brazos, bajando el pecho hacia el suelo y luego empujando de nuevo hacia arriba.","Salta con los pies hacia adelante, aterrizando en posición de sentadilla.","Salta hacia arriba explosivamente, llevando los brazos por encima de la cabeza.","Aterriza suavemente y baja de inmediato a una posición de sentadilla para comenzar la siguiente repetición."],"img":"0501-mr7pkqP.jpg","gif":"0501-mr7pkqP.gif"},{"id":"3224","n":"Jumping jack (hombre)","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","calves"],"st":["Ponte de pie con los pies juntos y los brazos a los costados.","Salta, separando los pies y levantando los brazos por encima de la cabeza.","Al aterrizar, salta rápidamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3224-1g5bPpA.jpg","gif":"3224-1g5bPpA.gif"},{"id":"0507","n":"Abdominales en navaja","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Túmbate boca arriba con las piernas extendidas y los brazos por encima de la cabeza.","Activa el core y levanta las piernas y la parte superior del cuerpo al mismo tiempo, llevando las manos hacia los dedos de los pies.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas y la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0507-mbkgB44.jpg","gif":"0507-mbkgB44.gif"},{"id":"0508","n":"Abdominales Janda","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0508-1GPHRyK.jpg","gif":"0508-1GPHRyK.gif"},{"id":"2612","n":"Salto a la comba","bp":"cardio","eq":"rope","tg":"cardiovascular system","mg":"calves","sm":["calves","quadriceps","hamstrings","glutes"],"st":["Sujeta las asas de la cuerda de saltar con las manos, palmas hacia adentro.","Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Balancea la cuerda por encima de la cabeza y salta sobre ella cuando se acerque a los pies.","Aterriza suavemente sobre la punta de los pies y repite el salto cuando la cuerda vuelva a pasar.","Continúa saltando durante el tiempo o el número de repeticiones deseado."],"img":"2612-e1e76I2.jpg","gif":"2612-e1e76I2.gif"},{"id":"0514","n":"Sentadilla con salto","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros.","Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.","Salta de forma explosiva desde el suelo, extendiendo las caderas, las rodillas y los tobillos.","Mientras estás en el aire, lleva rápidamente los brazos hacia adelante para mantener el equilibrio.","Aterriza suavemente sobre la punta de los pies y pasa de inmediato a la siguiente repetición.","Repite el número de repeticiones deseado."],"img":"0514-LIlE5Tn.jpg","gif":"0514-LIlE5Tn.gif"},{"id":"0513","n":"Sentadilla con salto sumo","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros.","Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.","Salta de forma explosiva, extendiendo por completo las caderas y las rodillas.","Aterriza suavemente sobre la punta de los pies y de inmediato baja el cuerpo de nuevo a una posición de sentadilla.","Repite el número de repeticiones deseado."],"img":"0513-TDYiji6.jpg","gif":"0513-TDYiji6.gif"},{"id":"0517","n":"Molino avanzado con kettlebell","bp":"waist","eq":"kettlebell","tg":"abs","mg":"obliques","sm":["obliques","shoulders"],"st":["Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera.","Sostén una pesa rusa en la mano derecha, con el brazo extendido por encima de la cabeza y la palma hacia adelante.","Gira el pie izquierdo ligeramente hacia la derecha y traslada el peso hacia la pierna izquierda.","Dobla la rodilla izquierda y flexiona la cadera, bajando el torso hacia el lado izquierdo.","Mantén el brazo derecho extendido por encima de la cabeza y la mirada en la pesa rusa.","Mientras bajas el torso, permite que la pierna derecha se enderece y que el pie derecho gire ligeramente.","Baja el torso hasta sentir un estiramiento en el isquiotibial izquierdo y que el brazo derecho apunte hacia el suelo.","Haz una pausa breve, luego activa el core y empuja con el talón izquierdo para regresar a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"0517-Kal9cQQ.jpg","gif":"0517-Kal9cQQ.gif"},{"id":"0518","n":"Cargada colgante alterna con kettlebell","bp":"lower arms","eq":"kettlebell","tg":"forearms","mg":"shoulders","sm":["shoulders","traps","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano con agarre prono.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.","Deja que las pesas rusas cuelguen frente al cuerpo con los brazos completamente extendidos.","En un solo movimiento fluido, extiende las caderas de forma explosiva, encoge los hombros y tira de las pesas rusas hacia los hombros.","Cuando las pesas rusas alcancen la altura de los hombros, gira las muñecas y atrápalas en posición de descanso, con las palmas hacia adentro y las pesas rusas apoyadas en la parte externa de los antebrazos.","Baja las pesas rusas de nuevo a la posición inicial y repite el movimiento con el brazo opuesto.","Continúa alternando los brazos durante el número de repeticiones deseado."],"img":"0518-I4tibZG.jpg","gif":"0518-I4tibZG.gif"},{"id":"0520","n":"Press alterno con kettlebell","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros.","Empuja una pesa rusa por encima de la cabeza, extendiendo el brazo por completo.","Baja la pesa rusa de nuevo a la altura de los hombros.","Repite con el otro brazo.","Continúa alternando los brazos durante el número de repeticiones deseado."],"img":"0520-5KLbZWx.jpg","gif":"0520-5KLbZWx.gif"},{"id":"0519","n":"Press alterno en suelo con kettlebell","bp":"chest","eq":"kettlebell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Comienza acostado boca arriba en el suelo con las rodillas dobladas y los pies planos sobre el suelo.","Sostén una pesa rusa en cada mano, con las palmas hacia los pies y los brazos extendidos rectos hacia el techo.","Baja una pesa rusa hacia el hombro mientras mantienes la otra pesa rusa extendida recta hacia arriba.","Empuja la pesa rusa bajada de vuelta hacia la posición inicial mientras al mismo tiempo bajas la otra pesa rusa hacia el hombro.","Continúa alternando el movimiento de empuje con cada pesa rusa durante el número de repeticiones deseado."],"img":"0519-7w6i0vE.jpg","gif":"0519-7w6i0vE.gif"},{"id":"0521","n":"Remo renegado alterno con kettlebell","bp":"back","eq":"kettlebell","tg":"upper back","mg":"core","sm":["core","shoulders"],"st":["Comienza en posición de plancha alta con las manos sujetando las pesas rusas y los pies separados a la altura de las caderas.","Activa el core y mantén el cuerpo en línea recta desde la cabeza hasta los talones.","Tira de una pesa rusa hacia el pecho, manteniendo el codo cerca del cuerpo.","Baja la pesa rusa de nuevo a la posición inicial y repite con el otro brazo.","Continúa alternando los brazos durante el número de repeticiones deseado."],"img":"0521-b9kqlBy.jpg","gif":"0521-b9kqlBy.gif"},{"id":"0522","n":"Remo alterno con kettlebell","bp":"back","eq":"kettlebell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sostén una pesa rusa en cada mano con las palmas hacia el cuerpo.","Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.","Tira de una pesa rusa hacia el pecho, manteniendo el codo cerca del cuerpo y apretando los omóplatos entre sí.","Baja la pesa rusa de nuevo a la posición inicial y repite con el otro brazo.","Continúa alternando los brazos durante el número de repeticiones deseado."],"img":"0522-Ca76jUE.jpg","gif":"0522-Ca76jUE.gif"},{"id":"0523","n":"Press Arnold con kettlebell","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros con las palmas hacia ti.","Activa el core y empuja las pesas rusas por encima de la cabeza, girando las palmas hacia adelante mientras extiendes los brazos.","Haz una pausa en la parte superior del movimiento, luego baja lentamente las pesas rusas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0523-UM8mgyG.jpg","gif":"0523-UM8mgyG.gif"},{"id":"0524","n":"Bent press con kettlebell","bp":"waist","eq":"kettlebell","tg":"abs","mg":"shoulders","sm":["shoulders","triceps","obliques"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en la mano derecha.","Dobla ligeramente las rodillas y empuja la pesa rusa por encima de la cabeza con el brazo derecho, manteniendo el codo bloqueado.","Rota el torso hacia la izquierda, trasladando tu peso al pie izquierdo.","Flexiona la rodilla izquierda y baja el torso hacia el suelo, manteniendo el brazo derecho extendido por encima de la cabeza.","Mientras bajas, mantén la mirada en la pesa rusa y el pecho elevado.","Cuando tu mano izquierda toque el suelo, empuja con el pie izquierdo y estira la pierna izquierda, llevando las caderas hacia adelante.","Mientras llevas las caderas hacia adelante, usa el core y el brazo derecho para empujar la pesa rusa de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"0524-kjE55n5.jpg","gif":"0524-kjE55n5.gif"},{"id":"0525","n":"Cargada colgante invertida con kettlebell","bp":"upper arms","eq":"kettlebell","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano en agarre prono.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.","Deja que la pesa rusa cuelgue entre tus piernas, con el brazo completamente extendido.","En un solo movimiento fluido, extiende explosivamente las caderas y las rodillas mientras tiras de la pesa rusa hacia el hombro.","Cuando la pesa rusa llegue a la altura del hombro, rota la muñeca de modo que la base de la pesa rusa quede hacia arriba.","Atrapa la pesa rusa a la altura del hombro con el codo flexionado y la palma hacia arriba.","Baja la pesa rusa de vuelta a la posición inicial invirtiendo el movimiento.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"0525-4KJEpzb.jpg","gif":"0525-4KJEpzb.gif"},{"id":"0526","n":"Cargada colgante alterna con dos pesas rusas","bp":"upper arms","eq":"kettlebell","tg":"biceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano con agarre prono.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.","Deja que las pesas rusas cuelguen rectas frente a tu cuerpo.","En un solo movimiento fluido, extiende explosivamente las caderas y las rodillas mientras encoges los hombros.","Mientras las pesas rusas suben, tira de ellas hacia los hombros, manteniendo los codos altos y hacia los lados.","Atrapa las pesas rusas a la altura del hombro, con las palmas hacia adentro y los codos apuntando hacia adelante.","Baja las pesas rusas de vuelta a la posición inicial y repite el número de repeticiones deseado."],"img":"0526-a4F9Oyc.jpg","gif":"0526-a4F9Oyc.gif"},{"id":"0527","n":"Envión doble con pesas rusas","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros.","Flexiona ligeramente las rodillas y activa el core.","Presiona las pesas rusas por encima de la cabeza, extendiendo los brazos por completo.","Flexiona las rodillas y baja rápidamente a una sentadilla parcial.","Extiende explosivamente las caderas y las rodillas, impulsando las pesas rusas hacia arriba.","Bloquea los brazos y atrapa las pesas rusas por encima de la cabeza con las rodillas ligeramente flexionadas.","Ponte de pie recto y vuelve a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0527-tznL2Ad.jpg","gif":"0527-tznL2Ad.gif"},{"id":"0528","n":"Push press doble con pesas rusas","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Comienza de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en cada mano a la altura del hombro.","Flexiona ligeramente las rodillas y activa el core.","Inicia el movimiento extendiendo explosivamente las caderas, las rodillas y los tobillos, impulsando las pesas rusas por encima de la cabeza.","Cuando las pesas rusas lleguen arriba, presiónalas completamente por encima de la cabeza, bloqueando los brazos.","Baja las pesas rusas a la posición inicial flexionando los codos y llevándolas de vuelta a la altura del hombro.","Repite el número de repeticiones deseado."],"img":"0528-I4KkPdl.jpg","gif":"0528-I4KkPdl.gif"},{"id":"0529","n":"Arrancada doble con pesas rusas","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"trapezius","sm":["trapezius","forearms","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en cada mano con el brazo extendido frente a los muslos.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.","En un solo movimiento explosivo, extiende las caderas, las rodillas y los tobillos, y al mismo tiempo tira de las pesas rusas hacia los hombros.","Cuando las pesas rusas lleguen a la altura del hombro, rota las muñecas y lanza las pesas rusas por encima de la cabeza, extendiendo los brazos por completo.","Baja las pesas rusas de vuelta a la posición inicial y repite el número de repeticiones deseado."],"img":"0529-M74kdvm.jpg","gif":"0529-M74kdvm.gif"},{"id":"0530","n":"Molino doble con pesas rusas","bp":"waist","eq":"kettlebell","tg":"abs","mg":"shoulders","sm":["shoulders","hamstrings"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en la mano derecha.","Extiende el brazo derecho por encima de la cabeza, manteniendo la mirada en la pesa rusa.","Rota el pie izquierdo 45 grados hacia la izquierda y el pie derecho 90 grados hacia la derecha.","Flexiona la cintura hacia la izquierda, manteniendo el brazo derecho extendido por encima de la cabeza.","Baja la pesa rusa hacia el suelo, extendiéndote hacia el pie izquierdo.","Haz una pausa breve, luego activa el core y empuja con el pie derecho para volver a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"0530-OaE7CpD.jpg","gif":"0530-OaE7CpD.gif"},{"id":"0531","n":"Press en suelo a un brazo con rango extendido con pesa rusa","bp":"chest","eq":"kettlebell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Comienza acostado boca arriba en el suelo con las rodillas dobladas y los pies planos sobre el suelo.","Sujeta una pesa rusa con una mano, con la palma hacia los pies.","Extiende el brazo recto hacia el techo, manteniendo el codo bloqueado y la muñeca recta.","Baja lentamente la pesa rusa de vuelta a la posición inicial, manteniendo el control durante todo el movimiento.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"0531-rseLfH3.jpg","gif":"0531-rseLfH3.gif"},{"id":"0532","n":"Ocho con pesa rusa","bp":"waist","eq":"kettlebell","tg":"abs","mg":"shoulders","sm":["shoulders","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Pasa la pesa rusa entre las piernas, cambiándola de mano cuando llegue detrás de las piernas.","Cuando la pesa rusa vuelva hacia adelante, pásala a la otra mano entre las piernas.","Continúa pasando la pesa rusa entre las piernas con un movimiento en forma de ocho.","Mantén un ritmo constante y activa el core durante todo el ejercicio.","Repite el número de repeticiones deseado."],"img":"0532-L4ay0PW.jpg","gif":"0532-L4ay0PW.gif"},{"id":"0533","n":"Sentadilla frontal con pesa rusa","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Sujeta la pesa rusa con ambas manos frente al pecho, cerca del cuerpo.","Activa el core y mantén el pecho elevado mientras bajas las caderas hacia abajo y hacia atrás, como si te sentaras en una silla.","Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Empuja con los talones para volver a ponerte de pie, contrayendo los glúteos en la parte más alta.","Repite el número de repeticiones deseado."],"img":"0533-DB0n8AG.jpg","gif":"0533-DB0n8AG.gif"},{"id":"0534","n":"Sentadilla goblet con pesa rusa","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa cerca del pecho con ambas manos.","Manteniendo el pecho elevado y el core activado, baja el cuerpo a una posición de sentadilla flexionando las rodillas y las caderas.","Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0534-ZA8b5hc.jpg","gif":"0534-ZA8b5hc.gif"},{"id":"0535","n":"Cargada colgante con pesa rusa","bp":"upper legs","eq":"kettlebell","tg":"hamstrings","mg":"glutes","sm":["glutes","quadriceps","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente a los muslos.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Baja la pesa rusa hacia el suelo, dejando que se balancee entre las piernas.","Extiende rápidamente las caderas y las rodillas, usando el impulso para hacer que la pesa rusa suba hasta la altura del hombro.","Cuando la pesa rusa llegue a la altura del hombro, rota las muñecas y atrápala en posición de descanso, con el codo pegado al cuerpo y la pesa rusa apoyada en el antebrazo.","Baja la pesa rusa de vuelta a la posición inicial entre las piernas y repite el número de repeticiones deseado."],"img":"0535-LHWF7us.jpg","gif":"0535-LHWF7us.gif"},{"id":"0536","n":"Zancada con pase de pesa rusa","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente al pecho con ambas manos.","Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.","Mientras avanzas en la zancada, pasa la pesa rusa por debajo del muslo derecho y trasládala a la mano izquierda.","Empuja con el pie derecho para volver a la posición inicial, mientras pasas la pesa rusa de vuelta a la mano derecha al mismo tiempo.","Repite la zancada en el lado opuesto, pasando la pesa rusa por debajo del muslo izquierdo.","Continúa alternando zancadas y pasando la pesa rusa entre las manos durante el número de repeticiones deseado."],"img":"0536-WKMQzCD.jpg","gif":"0536-WKMQzCD.gif"},{"id":"0537","n":"Cargada y envión a un brazo con pesa rusa","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano en agarre prono.","Flexiona ligeramente las rodillas y inclínate desde las caderas, bajando la pesa rusa entre las piernas.","Extiende explosivamente las caderas, las rodillas y los tobillos, usando el impulso para hacer que la pesa rusa suba hasta la altura del hombro.","Cuando la pesa rusa llegue a la altura del hombro, rota la muñeca y lanza la mano recta hacia arriba, bloqueando el brazo por encima de la cabeza.","Baja la pesa rusa de vuelta a la posición inicial y repite el número de repeticiones deseado."],"img":"0537-vzAxBtt.jpg","gif":"0537-vzAxBtt.gif"},{"id":"1298","n":"Press en suelo a un brazo con pesa rusa","bp":"chest","eq":"kettlebell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo.","Sujeta la pesa rusa con una mano con la palma hacia los pies y el brazo extendido recto hacia el techo.","Baja lentamente la pesa rusa hacia el pecho flexionando el codo, manteniendo el brazo superior cerca del cuerpo.","Haz una pausa cuando la pesa rusa esté justo encima del pecho, luego empújala de vuelta hacia arriba a la posición inicial extendiendo el codo.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"1298-rg59QCH.jpg","gif":"1298-rg59QCH.gif"},{"id":"0538","n":"Envión a un brazo con pesa rusa","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano a la altura del hombro.","Flexiona ligeramente las rodillas y activa el core.","Presiona la pesa rusa por encima de la cabeza en línea recta, extendiendo el brazo por completo.","Mientras presionas la pesa rusa por encima de la cabeza, flexiona las rodillas simultáneamente y estíralas rápidamente para generar impulso.","Cuando la pesa rusa llegue a su punto más alto, baja rápidamente por debajo de ella flexionando las rodillas y las caderas.","Atrapa la pesa rusa con una ligera flexión de rodillas y caderas, y el brazo completamente extendido por encima de la cabeza.","Ponte de pie recto, extendiendo por completo las rodillas y las caderas, y estabiliza la pesa rusa por encima de la cabeza.","Baja la pesa rusa de vuelta a la posición inicial flexionando las rodillas y las caderas, y repite el número de repeticiones deseado."],"img":"0538-S37C94C.jpg","gif":"0538-S37C94C.gif"},{"id":"0539","n":"Press militar lateral a un brazo con pesa rusa","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano a la altura del hombro.","Activa el core y mantén la espalda recta.","Presiona la pesa rusa por encima de la cabeza, extendiendo el brazo por completo.","Haz una pausa breve en lo alto, luego baja lentamente la pesa rusa de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"0539-yCvYdi7.jpg","gif":"0539-yCvYdi7.gif"},{"id":"0540","n":"Push press a un brazo con pesa rusa","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano a la altura del hombro.","Flexiona ligeramente las rodillas y activa el core.","Presiona la pesa rusa por encima de la cabeza extendiendo el brazo y estirando por completo las piernas.","Baja la pesa rusa de vuelta a la posición inicial flexionando las rodillas y devolviendo la pesa rusa al hombro.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"0540-osdXT3K.jpg","gif":"0540-osdXT3K.gif"},{"id":"0541","n":"Remo a un brazo con pesa rusa","bp":"back","eq":"kettlebell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano en agarre prono.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.","Tira de la pesa rusa hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos.","Haz una pausa breve en lo alto, luego baja lentamente la pesa rusa de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado y repite con el otro brazo."],"img":"0541-g9AsZ8P.jpg","gif":"0541-g9AsZ8P.gif"},{"id":"0542","n":"Arrancada a un brazo con pesa rusa","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"trapezius","sm":["trapezius","forearms","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano entre las piernas.","Flexiona ligeramente las rodillas e inclínate desde las caderas, bajando la pesa rusa hacia el suelo.","Extiende explosivamente las caderas y las rodillas, usando el impulso para hacer que la pesa rusa suba hacia el hombro.","Cuando la pesa rusa llegue a la altura del hombro, rota la mano y lánzala recta hacia arriba por encima de la cabeza, extendiendo el brazo por completo.","Baja la pesa rusa de vuelta entre las piernas y repite el número de repeticiones deseado."],"img":"0542-aXcUyKb.jpg","gif":"0542-aXcUyKb.gif"},{"id":"0543","n":"Pirate supper legs con pesa rusa","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Levanta la pesa rusa hasta la altura del hombro, manteniendo el codo cerca del cuerpo.","Extiende el brazo por completo por encima de la cabeza, enderezando el codo.","Baja la pesa rusa de vuelta a la altura del hombro, luego vuelve a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"0543-kuXhl0o.jpg","gif":"0543-kuXhl0o.gif"},{"id":"0544","n":"Sentadilla pistola con pesa rusa","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente al pecho con ambas manos.","Levanta el pie izquierdo del suelo y extiéndelo hacia adelante, manteniéndolo paralelo al suelo.","Baja lentamente el cuerpo a una posición de sentadilla, manteniendo el pie derecho plano en el suelo y la pierna izquierda extendida.","Haz una pausa breve en la parte baja de la sentadilla, luego empuja con el talón derecho para volver a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."],"img":"0544-5bpPTHv.jpg","gif":"0544-5bpPTHv.gif"},{"id":"0545","n":"Flexión pliométrica sobre kettlebell","bp":"chest","eq":"kettlebell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Comienza en una posición de plancha alta con las manos sobre las pesas rusas, separadas a la altura de los hombros.","Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo.","Empuja con las manos de forma explosiva, levantándolas de las pesas rusas y extendiendo los brazos por completo.","Aterriza suavemente sobre las pesas rusas y baja el pecho de inmediato para la siguiente repetición.","Repite el número de repeticiones deseado."],"img":"0545-ktf3nvW.jpg","gif":"0545-ktf3nvW.gif"},{"id":"0546","n":"Press sentado con kettlebell","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta una pesa rusa en cada mano a la altura del hombro, con las palmas hacia adelante.","Presiona las pesas rusas por encima de la cabeza, extendiendo los brazos por completo.","Baja las pesas rusas de vuelta a la altura del hombro.","Repite el número de repeticiones deseado."],"img":"0546-BkxB8LW.jpg","gif":"0546-BkxB8LW.gif"},{"id":"1438","n":"Press militar sentado a dos brazos con kettlebell","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta una pesa rusa en cada mano a la altura del hombro con las palmas hacia adelante.","Presiona las pesas rusas por encima de la cabeza extendiendo los brazos por completo.","Haz una pausa breve en lo alto, luego baja lentamente las pesas rusas de vuelta a la altura del hombro.","Repite el número de repeticiones deseado."],"img":"1438-ZEkjZDi.jpg","gif":"1438-ZEkjZDi.gif"},{"id":"0547","n":"Press alterno tipo balancín con kettlebell","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros.","Presiona una pesa rusa por encima de la cabeza mientras mantienes la otra pesa rusa a la altura del hombro.","Baja la pesa rusa presionada de vuelta a la altura del hombro mientras presionas simultáneamente la otra pesa rusa por encima de la cabeza.","Continúa alternando el movimiento de presión, creando un movimiento similar a un balancín.","Repite el número de repeticiones deseado."],"img":"0547-UDm6cGl.jpg","gif":"0547-UDm6cGl.gif"},{"id":"0548","n":"Sumo high pull con kettlebell","bp":"back","eq":"kettlebell","tg":"traps","mg":"shoulders","sm":["shoulders","glutes","hamstrings"],"st":["Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies hacia afuera.","Sujeta una pesa rusa con ambas manos frente al cuerpo, con los brazos extendidos hacia abajo.","Flexiona las rodillas y baja las caderas hasta una posición de sentadilla, manteniendo la espalda recta.","Empuja con los talones y extiende explosivamente las caderas y las rodillas, tirando de la pesa rusa hacia la barbilla.","Mientras tiras de la pesa rusa hacia arriba, mantén los codos altos y abiertos, y junta los omóplatos.","Baja la pesa rusa de vuelta a la posición inicial y repite el número de repeticiones deseado."],"img":"0548-8ARQ9Hw.jpg","gif":"0548-8ARQ9Hw.gif"},{"id":"0549","n":"Swing con kettlebell","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Sujeta la pesa rusa con ambas manos frente al cuerpo, con los brazos extendidos.","Flexiona ligeramente las rodillas e inclínate desde las caderas, empujando los glúteos hacia atrás.","Lleva la pesa rusa hacia atrás entre las piernas, manteniendo los brazos rectos y la espalda plana.","Lleva las caderas hacia adelante y haz que la pesa rusa suba hasta la altura del hombro, usando el impulso generado por las caderas.","Deja que la pesa rusa se balancee de vuelta hacia abajo entre las piernas y repite el movimiento el número de repeticiones deseado."],"img":"0549-UHJlbu3.jpg","gif":"0549-UHJlbu3.gif"},{"id":"0550","n":"Thruster con kettlebell","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"quadriceps","sm":["quadriceps","glutes","core"],"st":["Comienza de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente al pecho con ambas manos, con las palmas una frente a la otra.","Baja a una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás, manteniendo el pecho elevado y la espalda recta.","Al llegar a la parte baja de la sentadilla, empuja explosivamente con los talones para ponerte de pie, presionando al mismo tiempo la pesa rusa por encima de la cabeza.","Bloquea los brazos en la parte alta del movimiento, extendiendo los codos por completo.","Baja la pesa rusa de vuelta a la posición inicial invirtiendo el movimiento, flexionando los codos y bajando el peso de vuelta al pecho.","Repite el número de repeticiones deseado."],"img":"0550-yWxMvB5.jpg","gif":"0550-yWxMvB5.gif"},{"id":"0551","n":"Levantamiento turco con kettlebell (estilo sentadilla)","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Comienza tumbado boca arriba con las piernas extendidas y la pesa rusa sostenida en la mano derecha, con el brazo completamente extendido por encima del hombro.","Flexiona la rodilla derecha y coloca el pie derecho plano en el suelo, manteniendo la pierna izquierda extendida.","Presionando con el pie derecho, levanta las caderas del suelo, llegando a una posición de puente.","Desliza la pierna izquierda por debajo del cuerpo, flexionando la rodilla izquierda y colocando el pie izquierdo plano en el suelo.","Rota el torso hacia la izquierda, llevando la mano izquierda al suelo como apoyo.","Presionando con el pie derecho y la mano izquierda, levanta el torso del suelo, llegando a una posición de rodillas.","Desde la posición de rodillas, ponte de pie, manteniendo la pesa rusa extendida por encima de la cabeza.","Invierte el movimiento para volver a la posición inicial.","Repite el ejercicio en el otro lado, comenzando con la pesa rusa en la mano izquierda."],"img":"0551-Ha7SZ3y.jpg","gif":"0551-Ha7SZ3y.gif"},{"id":"0552","n":"Cargada a dos brazos con kettlebell","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"traps","sm":["traps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente a los muslos con ambas manos, con las palmas hacia ti.","Flexiona ligeramente las rodillas e inclínate desde las caderas, bajando la pesa rusa hacia el suelo.","Extiende explosivamente las caderas y las rodillas, usando el impulso para tirar de la pesa rusa hacia los hombros.","Cuando la pesa rusa llegue a la altura del hombro, rota las muñecas y atrápala en posición de descanso, con los codos pegados al cuerpo y la pesa rusa apoyada en la parte posterior del antebrazo.","Baja la pesa rusa de vuelta a la posición inicial y repite el número de repeticiones deseado."],"img":"0552-7Ba7bQ2.jpg","gif":"0552-7Ba7bQ2.gif"},{"id":"0553","n":"Press militar a dos brazos con kettlebell","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en cada mano a la altura del hombro con las palmas hacia adelante.","Activa el core y presiona las pesas rusas por encima de la cabeza, extendiendo los brazos por completo.","Haz una pausa breve en lo alto, luego baja lentamente las pesas rusas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0553-blBXysN.jpg","gif":"0553-blBXysN.gif"},{"id":"1345","n":"Remo a dos brazos con kettlebell","bp":"back","eq":"kettlebell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sostén una pesa rusa en cada mano con las palmas hacia el cuerpo.","Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.","Tira de las pesas rusas hacia el pecho, juntando los omóplatos.","Haz una pausa breve en lo alto, luego baja lentamente las pesas rusas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1345-wf24o8S.jpg","gif":"1345-wf24o8S.gif"},{"id":"0554","n":"Molino con kettlebell","bp":"waist","eq":"kettlebell","tg":"abs","mg":"obliques","sm":["obliques","shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en la mano derecha por encima de la cabeza.","Rota el pie izquierdo hacia afuera unos 45 grados y mantén el pie derecho apuntando hacia adelante.","Inclina el torso hacia el lado izquierdo, manteniendo el brazo derecho extendido por encima de la cabeza y la mirada en la pesa rusa.","Baja el torso tanto como puedas mientras mantienes el brazo derecho recto y el brazo izquierdo extendido hacia el lado.","Haz una pausa breve, luego vuelve a la posición inicial empujando con el pie derecho y activando los oblicuos.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"0554-9Tkqa9O.jpg","gif":"0554-9Tkqa9O.gif"},{"id":"0555","n":"Kick out sit","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"quadriceps","sm":["quadriceps","glutes"],"st":["Siéntate en el borde de un banco o una silla con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Inclínate ligeramente hacia atrás y coloca las manos en el borde del banco o la silla como apoyo.","Activando los isquiotibiales, levanta los pies del suelo y extiende las piernas rectas hacia adelante.","Haz una pausa breve en lo alto, luego flexiona lentamente las rodillas y lleva los pies de vuelta hacia el cuerpo.","Repite el número de repeticiones deseado."],"img":"0555-v7p5bYl.jpg","gif":"0555-v7p5bYl.gif"},{"id":"0558","n":"Muscle-up con balanceo (kipping)","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","triceps","shoulders","core"],"st":["Comienza colgándote de una barra de dominadas con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.","Activa el core y usa un movimiento de balanceo para generar impulso.","Mientras te balanceas hacia adelante, tira del pecho hacia la barra, usando los dorsales y los bíceps para iniciar el movimiento.","Continúa el movimiento ascendente hasta que el pecho llegue a la barra, luego pasa a una posición de fondos empujando hacia abajo en la barra y extendiendo los brazos.","Bájate de vuelta a la posición inicial flexionando los brazos y controlando el descenso.","Repite el número de repeticiones deseado."],"img":"0558-pM07UxU.jpg","gif":"0558-pM07UxU.gif"},{"id":"3640","n":"Crunch con toque de rodillas","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta los omóplatos del suelo y extiende la mano derecha hacia la rodilla izquierda.","Vuelve a la posición inicial y repite, esta vez extendiendo la mano izquierda hacia la rodilla derecha.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"3640-dTg95eZ.jpg","gif":"3640-dTg95eZ.gif"},{"id":"1420","n":"Sentadilla con salto desde rodillas","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Comienza arrodillado en el suelo con los pies separados a la altura de las caderas y los dedos de los pies apuntando hacia adelante.","Sujeta una barra sobre la parte superior de la espalda, apoyándola en los hombros.","Activa el core y los glúteos, luego salta explosivamente hacia arriba, extendiendo las caderas y las rodillas.","Mientras saltas, empuja con los dedos de los pies y extiende por completo los tobillos, las rodillas y las caderas.","Aterriza suavemente de vuelta en el suelo, flexionando las rodillas para absorber el impacto.","Pasa de inmediato a la siguiente repetición, repitiendo el movimiento de sentadilla con salto."],"img":"1420-UgDm3oy.jpg","gif":"1420-UgDm3oy.gif"},{"id":"1346","n":"Estiramiento de dorsales de rodillas","bp":"back","eq":"body weight","tg":"lats","mg":"shoulders","sm":["shoulders","triceps"],"st":["Arrodíllate en el suelo con las rodillas separadas a la altura de las caderas y los dedos de los pies apuntando hacia atrás.","Extiende los brazos por encima de la cabeza y entrelaza los dedos.","Manteniendo la espalda recta, inclínate lentamente hacia el lado derecho, sintiendo un estiramiento en el dorsal izquierdo.","Mantén el estiramiento durante 20-30 segundos, luego vuelve a la posición inicial.","Repite el estiramiento en el lado izquierdo, inclinándote hacia la izquierda y sintiendo un estiramiento en el dorsal derecho.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"1346-f38OEuO.jpg","gif":"1346-f38OEuO.gif"},{"id":"3239","n":"Plancha de rodillas con toque de hombros (hombre)","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","triceps"],"st":["Comienza en posición de rodillas con las manos en el suelo, separadas a la altura de los hombros.","Extiende las piernas hacia atrás, apoyándote en los dedos de los pies, y levanta el cuerpo a una posición de plancha.","Manteniendo el core activado y las caderas estables, levanta una mano del suelo y toca el hombro opuesto.","Devuelve la mano al suelo y repite con la otra mano.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"3239-h1ezqSu.jpg","gif":"3239-h1ezqSu.gif"},{"id":"3211","n":"Flexiones de rodillas (hombre)","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Comienza arrodillado en el suelo con las manos separadas a la altura de los hombros, los dedos apuntando hacia adelante.","Extiende las piernas hacia atrás, apoyándote en la punta de los pies, de modo que tu cuerpo forme una línea recta desde la cabeza hasta los talones.","Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.","Continúa bajando hasta que el pecho esté justo encima del suelo, luego empuja hacia arriba a la posición inicial enderezando los brazos.","Repite el número de repeticiones deseado."],"img":"3211-ZOuKWir.jpg","gif":"3211-ZOuKWir.gif"},{"id":"3288","n":"Fondos coreanos","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Colócate entre dos barras paralelas con los brazos extendidos sosteniendo el peso de tu cuerpo.","Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.","Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.","Repite el número de repeticiones deseado."],"img":"3288-rWoBmi5.jpg","gif":"3288-rWoBmi5.gif"},{"id":"3418","n":"Dominada en L","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros.","Cuélgate con los brazos completamente extendidos y el cuerpo recto.","Activa los dorsales y los bíceps para llevar el cuerpo hacia arriba en dirección a la barra, manteniendo los codos cerca del cuerpo.","Continúa subiendo hasta que la barbilla quede por encima de la barra.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3418-d1GgzTU.jpg","gif":"3418-d1GgzTU.gif"},{"id":"3419","n":"L-sit en el suelo","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Siéntate en el suelo con las piernas extendidas frente a ti.","Coloca las manos en el suelo junto a las caderas, con los dedos apuntando hacia adelante.","Activa el core y levanta las piernas del suelo, manteniéndolas rectas.","Intenta llevar las piernas paralelas al suelo, formando una 'L' con el cuerpo.","Mantén esta posición durante el mayor tiempo posible.","Baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3419-UpWmA5E.jpg","gif":"3419-UpWmA5E.gif"},{"id":"0562","n":"Giro de 180 con barra landmine","bp":"waist","eq":"barbell","tg":"abs","mg":"obliques","sm":["obliques","quadriceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con ambas manos frente al pecho.","Flexiona ligeramente las rodillas y rota el torso hacia la derecha, llevando la barra hacia la cadera derecha.","Cuando llegues a la parte baja del movimiento, invierte rápidamente el movimiento y rota el torso hacia la izquierda, llevando la barra hacia arriba y a través del cuerpo en dirección al hombro izquierdo.","Continúa este movimiento de giro, alternando lados, durante el número de repeticiones deseado."],"img":"0562-QYysSLV.jpg","gif":"0562-QYysSLV.gif"},{"id":"3237","n":"Elevación lateral con landmine","bp":"shoulders","eq":"barbell","tg":"delts","mg":"traps","sm":["traps","upper back"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta la barra con un agarre prono, apoyándola en la parte delantera de los hombros.","Manteniendo el core activado y la espalda recta, levanta la barra alejándola del cuerpo, elevándola hasta la altura del hombro.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3237-eXMFHww.jpg","gif":"3237-eXMFHww.gif"},{"id":"3300","n":"Plancha inclinada hacia delante","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","chest","triceps"],"st":["Comienza en una posición de flexión con las manos separadas a la altura de los hombros y el cuerpo recto.","Activa el core y traslada lentamente el peso hacia adelante, llevando los hombros más allá de las manos.","Mantén los codos ligeramente flexionados y el cuerpo recto mientras te inclinas hacia adelante.","Mantén esta posición durante unos segundos, luego vuelve lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3300-LYJodFS.jpg","gif":"3300-LYJodFS.gif"},{"id":"2271","n":"Gancho de izquierda (boxeo)","bp":"shoulders","eq":"body weight","tg":"delts","mg":"biceps","sm":["biceps","triceps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Mantén la mano izquierda arriba para proteger el rostro y la mano derecha junto a la barbilla.","Rota las caderas y pívota sobre el pie izquierdo mientras extiendes el brazo izquierdo hacia adelante con un movimiento de golpe.","Gira el torso y activa los músculos del core para generar potencia en el golpe.","Lleva el brazo rápidamente de vuelta a la posición inicial y repite el número de repeticiones deseado."],"img":"2271-hoXt6wv.jpg","gif":"2271-hoXt6wv.gif"},{"id":"0570","n":"Encogimientos de piernas en banco plano","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Siéntate en un banco plano con las piernas extendidas rectas hacia adelante.","Coloca las manos en el banco junto a las caderas para mayor apoyo.","Activa el abdomen y levanta las piernas del suelo, llevando las rodillas hacia el pecho.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0570-OyoZ3Pu.jpg","gif":"0570-OyoZ3Pu.gif"},{"id":"1576","n":"Estiramiento de isquiotibiales con pierna levantada","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes"],"st":["Túmbate boca arriba con las piernas extendidas.","Flexiona una rodilla y llévala hacia el pecho, sujetándote del muslo o la espinilla.","Endereza la pierna tanto como sea posible mientras la mantienes elevada.","Mantén el estiramiento durante 20-30 segundos.","Repite con la otra pierna."],"img":"1576-sU5BrfP.jpg","gif":"1576-sU5BrfP.gif"},{"id":"2287","n":"Prensa de piernas alterna en máquina de palanca","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Ajusta el asiento y la plataforma para los pies de la máquina de palanca a la posición deseada.","Siéntate en la máquina con la espalda apoyada en el respaldo y los pies sobre la plataforma para los pies.","Coloca las manos en las asas o en los lados de la máquina para mayor estabilidad.","Empuja un pie contra la plataforma para los pies, extendiendo la pierna hasta que esté casi completamente recta.","Haz una pausa breve, luego flexiona lentamente la pierna y vuelve a la posición inicial.","Repite con la otra pierna.","Continúa alternando las piernas durante el número de repeticiones deseado."],"img":"2287-V07qpXy.jpg","gif":"2287-V07qpXy.gif"},{"id":"0571","n":"Remo sentado alterno con agarre estrecho en máquina de palanca","bp":"back","eq":"leverage machine","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ajusta la altura del asiento y la posición de la placa para los pies para asegurar una alineación correcta.","Siéntate en la máquina con la espalda recta y los pies planos sobre la placa para los pies.","Sujeta las asas con un agarre estrecho, con las palmas una frente a la otra.","Mantén el pecho elevado y los hombros hacia atrás durante todo el ejercicio.","Tira de una asa hacia el torso mientras mantienes la otra asa inmóvil.","Aprieta los omóplatos al final del movimiento.","Devuelve lentamente el asa a la posición inicial y repite con el otro lado.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0571-w2oRpuH.jpg","gif":"0571-w2oRpuH.gif"},{"id":"0572","n":"Dominada supinada asistida en máquina","bp":"back","eq":"leverage machine","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Ajusta la máquina de palanca al nivel de resistencia deseado.","Sube a la plataforma para los pies y agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.","Cuélgate con los brazos completamente extendidos, manteniendo el cuerpo recto.","Activa los músculos de la espalda y tira del cuerpo hacia arriba en dirección a las asas, liderando con el pecho.","Continúa subiendo hasta que la barbilla quede por encima de las agarraderas.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0572-MaMuGH6.jpg","gif":"0572-MaMuGH6.gif"},{"id":"0573","n":"Hiperextensiones lumbares en máquina de palanca","bp":"back","eq":"leverage machine","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Ajusta la máquina según el tamaño de tu cuerpo y tu rango de movimiento.","Siéntate en la máquina con la espalda apoyada en la almohadilla y los pies asegurados.","Coloca las manos en las asas o en las barras de agarre.","Activa el core e inclínate lentamente hacia adelante, permitiendo que la espalda se redondee ligeramente.","Haz una pausa breve en la posición baja, sintiendo un estiramiento en la zona lumbar.","Usando los músculos de la espalda, levanta lentamente el torso de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0573-rUXfn3R.jpg","gif":"0573-rUXfn3R.gif"},{"id":"0574","n":"Remo inclinado en máquina de palanca","bp":"back","eq":"barbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros.","Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado.","Tira de la barra hacia la parte inferior del pecho, juntando los omóplatos.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0574-X3cqyXz.jpg","gif":"0574-X3cqyXz.gif"},{"id":"3200","n":"Remo inclinado con agarre en V en máquina de palanca","bp":"back","eq":"leverage machine","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ajusta la altura del asiento y colócate frente a la máquina.","Sujeta la barra en V con un agarre prono, manteniendo la espalda recta y las rodillas ligeramente flexionadas.","Tira de la barra en V hacia el abdomen, juntando los omóplatos.","Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente el peso de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3200-LuBEORI.jpg","gif":"3200-LuBEORI.gif"},{"id":"0575","n":"Curl de bíceps en máquina de palanca","bp":"upper arms","eq":"leverage machine","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla.","Sujeta las asas con un agarre supino, con las palmas hacia arriba, y mantén los codos cerca de los costados.","Exhala y flexiona las asas hacia arriba, contrayendo los bíceps.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Inhala y baja lentamente los mangos de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"0575-q6y3OhV.jpg","gif":"0575-q6y3OhV.gif"},{"id":"2289","n":"Elevación de talones en máquina de palanca","bp":"lower legs","eq":"leverage machine","tg":"calves","mg":"hamstrings","sm":["hamstrings"],"st":["Ajusta el asiento de la máquina de palanca de modo que los hombros queden alineados con la almohadilla de la palanca.","Coloca los dedos de los pies sobre la almohadilla de la palanca, con los talones colgando fuera del borde.","Sujeta las asas o los soportes laterales para mayor estabilidad.","Empuja la almohadilla de la palanca hacia abajo extendiendo los tobillos, contrayendo los músculos de las pantorrillas.","Haz una pausa por un momento en la parte baja del movimiento.","Vuelve lentamente a la posición inicial dejando que los talones se eleven de nuevo.","Repite el número de repeticiones deseado."],"img":"2289-7B4F5nZ.jpg","gif":"2289-7B4F5nZ.gif"},{"id":"0577","n":"Press de pecho en máquina de palanca baja","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Ajusta la altura del asiento y colócate en la máquina con la espalda totalmente apoyada en la almohadilla.","Sujeta las asas con un agarre prono y coloca los codos en un ángulo de 90 grados.","Empuja las asas hacia adelante hasta que los brazos queden completamente extendidos, exhalando durante el movimiento.","Haz una pausa breve al final del movimiento, luego vuelve lentamente a la posición inicial, inhalando mientras lo haces.","Repite el número de repeticiones deseado."],"img":"0577-T0yTjgW.jpg","gif":"0577-T0yTjgW.gif"},{"id":"0576","n":"Press de pecho en máquina de palanca alta","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Ajusta la altura del asiento y colócate en la máquina con la espalda totalmente apoyada en la almohadilla.","Sujeta las asas con un agarre prono y coloca los codos en un ángulo de 90 grados.","Empuja las asas hacia adelante hasta que los brazos queden completamente extendidos, exhalando durante el movimiento.","Haz una pausa breve al final del movimiento, luego vuelve lentamente a la posición inicial, inhalando mientras lo haces.","Repite el número de repeticiones deseado."],"img":"0576-DOoWcnA.jpg","gif":"0576-DOoWcnA.gif"},{"id":"0578","n":"Peso muerto en máquina de palanca","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Ajusta la altura del asiento y la plataforma para los pies a la posición deseada.","Siéntate en la máquina con la espalda apoyada en la almohadilla y los pies planos sobre la plataforma para los pies.","Sujeta las asas o los lados del asiento para mayor estabilidad.","Activa los glúteos y los isquiotibiales, y empuja con los talones para levantar el peso.","Mantén la espalda recta y evita redondear los hombros.","Extiende por completo las caderas en la parte alta del movimiento, apretando los glúteos.","Baja el peso de manera controlada, manteniendo la tensión en los glúteos y los isquiotibiales.","Repite el número de repeticiones deseado."],"img":"0578-GUT8I22.jpg","gif":"0578-GUT8I22.gif"},{"id":"1300","n":"Press de pecho declinado en máquina de palanca","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Ajusta la altura del asiento y el respaldo de la máquina de palanca a una posición cómoda.","Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos en el suelo.","Sujeta las asas con un agarre prono y coloca las manos un poco más separadas que la altura de los hombros.","Empuja las asas hacia adelante y alejándolas del cuerpo hasta que los brazos queden completamente extendidos.","Baja lentamente las asas de vuelta hacia el pecho, manteniendo los codos ligeramente flexionados.","Haz una pausa breve en la parte baja, luego empuja las asas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1300-vsVoPHt.jpg","gif":"1300-vsVoPHt.gif"},{"id":"1253","n":"Elevación de talones tipo burro en máquina de palanca","bp":"lower legs","eq":"leverage machine","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Ajusta la máquina de palanca a la altura adecuada para tu cuerpo.","Colócate de frente a la máquina, con los dedos de los pies en la plataforma y los talones colgando fuera del borde.","Coloca las manos en las asas o en las barras de soporte para mayor estabilidad.","Activa las pantorrillas y levanta los talones tan alto como sea posible, usando la parte delantera de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1253-C9LuR4A.jpg","gif":"1253-C9LuR4A.gif"},{"id":"0579","n":"Jalón frontal en máquina de palanca","bp":"back","eq":"leverage machine","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Ajusta la altura del asiento y colócate en la máquina con las rodillas debajo de las almohadillas y los pies planos en el suelo.","Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.","Siéntate erguido con el pecho elevado y los hombros hacia atrás, manteniendo un ligero arco en la zona lumbar.","Activa los dorsales y tira de las asas hacia el pecho, juntando los omóplatos.","Haz una pausa breve en la parte baja del movimiento, luego suelta lentamente las asas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0579-7F1DVzn.jpg","gif":"0579-7F1DVzn.gif"},{"id":"0580","n":"Encogimiento de hombros sin agarre en máquina de palanca brazos por arriba","bp":"back","eq":"leverage machine","tg":"traps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Ajusta la altura del asiento y colócate en la máquina de palanca.","Sujeta las asas con las palmas hacia adentro y los brazos completamente extendidos.","Manteniendo la espalda recta, exhala y eleva los hombros tan alto como sea posible.","Mantén la contracción por un momento breve, luego inhala y baja lentamente los hombros de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0580-f91FwXG.jpg","gif":"0580-f91FwXG.gif"},{"id":"1439","n":"Encogimiento de hombros sin agarre en máquina de palanca brazos por debajo","bp":"back","eq":"leverage machine","tg":"traps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla.","Sujeta las asas o barras con un agarre prono, manteniendo los brazos rectos.","Manteniendo la espalda recta, eleva los hombros hacia las orejas tan alto como sea posible.","Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1439-cbuFJrn.jpg","gif":"1439-cbuFJrn.gif"},{"id":"2288","n":"Prensa de manos en máquina de palanca","bp":"lower arms","eq":"leverage machine","tg":"forearms","mg":"biceps","sm":["biceps","triceps"],"st":["Ajusta la altura del asiento y sujeta las asas de la máquina de palanca.","Mantén la espalda recta y los pies planos en el suelo.","Exhala y aprieta las asas, contrayendo los antebrazos.","Mantén la contracción durante un segundo, luego suelta lentamente y vuelve a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2288-mKwcrHn.jpg","gif":"2288-mKwcrHn.gif"},{"id":"1615","n":"Curl predicador con agarre neutro en máquina de palanca","bp":"upper arms","eq":"leverage machine","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ajusta la altura del asiento y colócate en la máquina de palanca.","Coloca los brazos superiores sobre la almohadilla de predicador, asegurándote de que el pecho quede apoyado contra ella.","Sujeta las asas con agarre neutro (palmas una frente a la otra).","Manteniendo los brazos superiores inmóviles, exhala y flexiona las asas hacia los hombros.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente las asas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1615-OAguZoG.jpg","gif":"1615-OAguZoG.gif"},{"id":"0581","n":"Remo alto en máquina de palanca","bp":"back","eq":"leverage machine","tg":"upper back","mg":"biceps","sm":["biceps","rear deltoids"],"st":["Ajusta la altura del asiento y la plataforma para los pies a una posición cómoda.","Siéntate en la máquina con el pecho contra la almohadilla y los pies planos sobre la plataforma para los pies.","Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.","Mantén la espalda recta y activa el core.","Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí.","Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0581-nZZZy9m.jpg","gif":"0581-nZZZy9m.gif"},{"id":"2286","n":"Extensión de cadera en máquina de palanca v. 2","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings"],"st":["Ajusta la máquina a tu cuerpo y siéntate en ella con la espalda apoyada en el respaldo.","Coloca los pies en los apoyapiés y sujeta las asas para mayor estabilidad.","Activa los glúteos y los isquiotibiales, luego empuja contra los apoyapiés para extender las caderas y levantar las piernas hacia atrás.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2286-OPqShYN.jpg","gif":"2286-OPqShYN.gif"},{"id":"2611","n":"Prensa de piernas horizontal unilateral en máquina de palanca","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ajusta el asiento de la máquina de modo que las rodillas queden en un ángulo de 90 grados cuando los pies estén sobre la placa para los pies.","Siéntate en la máquina con la espalda apoyada en el respaldo y los pies separados a la altura de los hombros sobre la placa para los pies.","Coloca las manos en las asas o en los lados de la máquina para mayor estabilidad.","Empuja la placa para los pies alejándola del cuerpo extendiendo la pierna, manteniendo la espalda apoyada en el respaldo.","Haz una pausa breve en la posición completamente extendida, luego flexiona lentamente la pierna para volver a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."],"img":"2611-9KU9TYF.jpg","gif":"2611-9KU9TYF.gif"},{"id":"1299","n":"Press de pecho inclinado en máquina de palanca espalda recta","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Ajusta el asiento y el respaldo de la máquina de palanca a una posición cómoda.","Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos en el suelo.","Sujeta las asas con un agarre prono y coloca las manos un poco más separadas que la altura de los hombros.","Empuja las asas hacia adelante y alejándolas del cuerpo hasta que los brazos queden completamente extendidos.","Haz una pausa breve, luego flexiona lentamente los codos y baja las asas de vuelta hacia el pecho.","Repite el número de repeticiones deseado."],"img":"1299-jHAnWmT.jpg","gif":"1299-jHAnWmT.gif"},{"id":"1479","n":"Press de pecho inclinado en máquina de palanca espalda inclinada","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Ajusta la altura del asiento y el ángulo del respaldo de la máquina de palanca a una posición cómoda.","Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos en el suelo.","Sujeta las asas con un agarre prono y coloca las manos un poco más separadas que la altura de los hombros.","Empuja las asas hacia adelante y alejándolas del cuerpo hasta que los brazos queden completamente extendidos, pero sin bloquear los codos.","Haz una pausa breve en la posición completamente extendida, luego flexiona lentamente los codos y baja las asas de vuelta hacia el pecho.","Repite el número de repeticiones deseado."],"img":"1479-o17Jfkt.jpg","gif":"1479-o17Jfkt.gif"},{"id":"0582","n":"Curl de piernas de rodillas en máquina de palanca","bp":"upper legs","eq":"leverage machine","tg":"hamstrings","mg":"glutes","sm":["glutes"],"st":["Ajusta la máquina a tu cuerpo y selecciona el peso deseado.","Arrodíllate en la máquina mirando hacia abajo, con las rodillas apoyadas en la almohadilla y los pies asegurados bajo las almohadillas para los pies.","Sujeta las asas o los lados de la máquina para mayor estabilidad.","Manteniendo quieta la parte superior del cuerpo, exhala y flexiona las piernas hacia los glúteos doblando las rodillas.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los isquiotibiales.","Inhala y baja lentamente las piernas de vuelta a la posición inicial, extendiendo por completo las rodillas.","Repite el número de repeticiones deseado."],"img":"0582-nnmCTLN.jpg","gif":"0582-nnmCTLN.gif"},{"id":"0583","n":"Giro de torso de rodillas en máquina de palanca","bp":"waist","eq":"leverage machine","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Ajusta la altura del asiento y colócate en la máquina con las rodillas apoyadas en las almohadillas y la parte superior del cuerpo mirando hacia adelante.","Sujeta las asas o los lados de la máquina para mayor estabilidad.","Manteniendo el core activado, gira el torso hacia un lado tanto como sea cómodamente posible.","Haz una pausa por un momento, luego regresa lentamente a la posición inicial.","Repite el giro hacia el lado opuesto.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0583-sZOR9EV.jpg","gif":"0583-sZOR9EV.gif"},{"id":"0584","n":"Elevaciones laterales en máquina de palanca","bp":"shoulders","eq":"leverage machine","tg":"delts","mg":"traps","sm":["traps","upper back"],"st":["Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla.","Sujeta las asas con un agarre prono y mantén los brazos rectos.","Exhala y levanta los brazos hacia los lados hasta que queden paralelos al suelo.","Haz una pausa breve en lo alto, luego inhala y baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0584-dRTfGZT.jpg","gif":"0584-dRTfGZT.gif"},{"id":"0585","n":"Extensión de piernas en máquina de palanca","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"hamstrings","sm":["hamstrings"],"st":["Ajusta la altura del asiento y el respaldo de la máquina a tu cuerpo.","Siéntate en la máquina con la espalda apoyada en el respaldo y los pies sobre la almohadilla para los pies.","Sujeta las asas o las barras laterales para mayor estabilidad.","Extiende las piernas hacia adelante enderezando las rodillas, levantando el peso.","Haz una pausa breve en lo alto, luego baja lentamente el peso de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0585-my33uHU.jpg","gif":"0585-my33uHU.gif"},{"id":"0586","n":"Curl de piernas tumbado en máquina de palanca","bp":"upper legs","eq":"leverage machine","tg":"hamstrings","mg":"calves","sm":["calves"],"st":["Ajusta la máquina a tu cuerpo y selecciona el peso deseado.","Túmbate boca abajo en la máquina con las piernas rectas y los talones contra la palanca acolchada.","Sujeta las asas o los lados de la máquina para mayor estabilidad.","Manteniendo la parte superior del cuerpo inmóvil, exhala y flexiona las piernas hacia arriba tanto como sea posible sin levantar las caderas de la almohadilla.","Mantén la posición contraída durante una pausa breve mientras aprietas los isquiotibiales.","Inhala y baja lentamente la palanca de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0586-17lJ1kr.jpg","gif":"0586-17lJ1kr.gif"},{"id":"3195","n":"Curl de piernas tumbado 2-1 en máquina de palanca","bp":"upper legs","eq":"leverage machine","tg":"hamstrings","mg":"glutes","sm":["glutes"],"st":["Ajusta la máquina a tu cuerpo y siéntate en ella con la espalda apoyada en el respaldo.","Coloca las piernas sobre la almohadilla de la palanca, justo encima de los tobillos.","Sujeta las asas a los lados de la máquina para mayor apoyo.","Manteniendo la parte superior del cuerpo inmóvil, exhala y flexiona las piernas hacia los glúteos.","Haz una pausa breve en lo alto, luego inhala y baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3195-UXpKJoq.jpg","gif":"3195-UXpKJoq.gif"},{"id":"0587","n":"Press militar en máquina de palanca","bp":"shoulders","eq":"leverage machine","tg":"delts","mg":"triceps","sm":["triceps","upper chest"],"st":["Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en el respaldo.","Sujeta las asas con un agarre prono y coloca las manos un poco más separadas que la altura de los hombros.","Empuja las asas hacia arriba hasta que los brazos queden completamente extendidos, pero sin bloquear los codos.","Haz una pausa breve en lo alto, luego baja lentamente las asas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0587-CggQhII.jpg","gif":"0587-CggQhII.gif"},{"id":"0588","n":"Remo sentado con agarre estrecho en máquina de palanca","bp":"back","eq":"leverage machine","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ajusta la altura del asiento y los apoyapiés para asegurar una postura correcta.","Siéntate en la máquina con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas.","Sujeta las asas con un agarre estrecho, con las palmas una frente a la otra.","Mantén la espalda recta e inclínate ligeramente hacia adelante.","Tira de las asas hacia el torso, juntando los omóplatos.","Haz una pausa breve en la parte alta del movimiento.","Suelta lentamente las asas y vuelve a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0588-IGjKj1v.jpg","gif":"0588-IGjKj1v.gif"},{"id":"0589","n":"Remo inclinado a una mano en máquina de palanca","bp":"back","eq":"barbell","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una barra con agarre prono.","Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y la cabeza erguida.","Deja que la barra cuelgue frente a ti con los brazos completamente extendidos.","Tira de la barra hacia el pecho, manteniendo los codos cerca del cuerpo.","Junta los omóplatos en la parte superior del movimiento.","Baja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0589-Fhdtwf3.jpg","gif":"0589-Fhdtwf3.gif"},{"id":"1356","n":"Remo alto lateral con palanca a un brazo","bp":"back","eq":"leverage machine","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Ajusta la altura del asiento y colócate frente a la máquina.","Sujeta el asa con una mano y mantén la espalda recta.","Tira del asa hacia el cuerpo, manteniendo el codo cerca del costado.","Aprieta los músculos de la espalda en la parte superior del movimiento.","Suelta lentamente la agarradera de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1356-OIFMAp1.jpg","gif":"1356-OIFMAp1.gif"},{"id":"1347","n":"Jalón lateral amplio con palanca a un brazo","bp":"back","eq":"leverage machine","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo.","Sujeta el asa con un agarre prono y extiende el brazo por completo, manteniendo una ligera flexión en el codo.","Tira del asa hacia abajo y a través del cuerpo en dirección a la cadera opuesta, apretando el dorsal en la parte baja del movimiento.","Devuelve lentamente el asa a la posición inicial, extendiendo el brazo por completo.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"1347-tTuZSDT.jpg","gif":"1347-tTuZSDT.gif"},{"id":"0590","n":"Press de hombros con palanca a un brazo","bp":"shoulders","eq":"leverage machine","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla.","Sujeta el asa de la palanca con una mano y coloca el codo en un ángulo de 90 grados.","Presiona la palanca hacia arriba hasta que el brazo quede completamente extendido por encima de la cabeza.","Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"0590-2KGnL6M.jpg","gif":"0590-2KGnL6M.gif"},{"id":"0591","n":"Fondos de tríceps en máquina de palanca con agarre prono","bp":"upper arms","eq":"leverage machine","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Ajusta la máquina a la altura adecuada y asegura tu cuerpo en posición.","Sujeta las asas con un agarre prono y coloca el cuerpo de modo que los brazos queden completamente extendidos.","Baja el cuerpo flexionando los codos, manteniendo los brazos superiores cerca de los costados.","Continúa bajando hasta que los brazos superiores queden paralelos al suelo.","Haz una pausa breve, luego empújate de vuelta hacia arriba a la posición inicial extendiendo los codos.","Repite el número de repeticiones deseado."],"img":"0591-D5yqP2p.jpg","gif":"0591-D5yqP2p.gif"},{"id":"0592","n":"Curl predicador en máquina de palanca semi-extensión","bp":"upper arms","eq":"leverage machine","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ajusta la altura del asiento y colócate en la máquina de palanca.","Coloca los brazos superiores en la almohadilla y sujeta las asas con un agarre supino.","Mantén la espalda recta y los codos colocados sobre la almohadilla.","Exhala y flexiona los antebrazos hacia los brazos superiores, contrayendo los bíceps.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Inhala y baja lentamente las asas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0592-b6hQYMb.jpg","gif":"0592-b6hQYMb.gif"},{"id":"1614","n":"Curl predicador en máquina de palanca extensión completa","bp":"upper arms","eq":"leverage machine","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ajusta la altura del asiento y colócate en la máquina con los brazos superiores apoyados en la almohadilla y el pecho contra el soporte.","Sujeta las asas con un agarre supino, un poco más separadas que la altura de los hombros.","Mantén los brazos superiores inmóviles y exhala mientras flexionas las asas hacia los hombros, contrayendo los bíceps.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Inhala mientras bajas lentamente las asas de vuelta a la posición inicial, extendiendo los brazos por completo.","Repite el número de repeticiones deseado."],"img":"1614-ye84CTU.jpg","gif":"1614-ye84CTU.gif"},{"id":"2285","n":"Pullover en máquina de palanca","bp":"back","eq":"leverage machine","tg":"lats","mg":"triceps","sm":["triceps","shoulders"],"st":["Ajusta el asiento y las asas de la máquina de palanca a una posición cómoda.","Siéntate en la máquina con la espalda apoyada en la almohadilla y sujeta las asas con un agarre prono.","Mantén los brazos ligeramente flexionados y el core activado.","Tira lentamente de las asas hacia el pecho, apretando los dorsales.","Haz una pausa breve en el punto máximo de contracción, luego vuelve lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2285-4U7iLb5.jpg","gif":"2285-4U7iLb5.gif"},{"id":"2736","n":"Jalón lateral con palanca y agarre supino","bp":"back","eq":"leverage machine","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Ajusta la altura del asiento y colócate en la máquina con las rodillas debajo de las almohadillas y los pies planos en el suelo.","Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.","Siéntate erguido con el pecho hacia afuera y los hombros hacia atrás, manteniendo un ligero arco en la zona lumbar.","Tira de las asas hacia el pecho, liderando con los codos y juntando los omóplatos.","Haz una pausa breve en la parte baja del movimiento, luego suelta lentamente las asas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2736-ky8FLU8.jpg","gif":"2736-ky8FLU8.gif"},{"id":"1616","n":"Curl predicador con palanca y agarre invertido","bp":"upper arms","eq":"leverage machine","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ajusta la altura del asiento y colócate en la máquina de palanca.","Sujeta las asas con un agarre supino, con las palmas hacia arriba.","Apoya los brazos superiores sobre la almohadilla de predicador, asegurándote de que los codos queden completamente extendidos.","Manteniendo los brazos superiores inmóviles, exhala y flexiona las asas hacia los hombros.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Inhala y baja lentamente las agarraderas de vuelta a la posición inicial, extendiendo los codos por completo.","Repite el número de repeticiones deseado."],"img":"1616-kj3hy6W.jpg","gif":"1616-kj3hy6W.gif"},{"id":"1348","n":"Remo vertical con palanca y agarre supino","bp":"back","eq":"leverage machine","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ajusta la altura del asiento y la posición de la placa para los pies para asegurar una alineación correcta.","Siéntate en la máquina con el pecho contra la almohadilla y los pies planos sobre la placa para los pies.","Sujeta las asas con un agarre supino, con las palmas hacia arriba.","Mantén la espalda recta y activa el core.","Tira de las asas hacia el pecho, juntando los omóplatos.","Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente y extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1348-ZqNOWQ6.jpg","gif":"1348-ZqNOWQ6.gif"},{"id":"0593","n":"Hiperextensión inversa en máquina de palanca","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Ajusta la máquina de palanca a tu cuerpo y asegura los pies en las almohadillas para los pies.","Túmbate boca abajo en la máquina con la parte superior del cuerpo colgando fuera del borde y las caderas apoyadas en la almohadilla.","Cruza los brazos sobre el pecho o colócalos detrás de la cabeza.","Activa los glúteos y los isquiotibiales para levantar las piernas hacia arriba hasta que queden paralelas al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0593-Krmb3cB.jpg","gif":"0593-Krmb3cB.gif"},{"id":"1349","n":"Remo con barra T invertido en máquina de palanca","bp":"back","eq":"leverage machine","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ajusta la altura del asiento y la posición de la placa para los pies en la máquina de palanca.","Siéntate en la máquina con el pecho contra la almohadilla y los pies planos sobre la placa para los pies.","Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.","Mantén la espalda recta y activa el core.","Tira de las asas hacia el pecho, juntando los omóplatos.","Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente y extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1349-BgljGjd.jpg","gif":"1349-BgljGjd.gif"},{"id":"2315","n":"Elevación de talones giratoria en máquina de palanca","bp":"lower legs","eq":"leverage machine","tg":"calves","mg":"soleus","sm":["soleus","ankle stabilizers"],"st":["Ajusta la altura del asiento de modo que las rodillas queden ligeramente flexionadas y los pies queden planos sobre la placa para los pies.","Coloca los dedos de los pies sobre la placa para los pies, con los talones colgando fuera del borde.","Sujeta las asas o los lados de la máquina para mayor estabilidad.","Empuja con la parte delantera de los pies, elevando los talones tan alto como sea posible.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2315-MrgP9L6.jpg","gif":"2315-MrgP9L6.gif"},{"id":"2335","n":"Prensa de gemelos sentado en máquina de palanca","bp":"lower legs","eq":"leverage machine","tg":"calves","mg":"soleus","sm":["soleus","hamstrings"],"st":["Ajusta el asiento de la máquina de modo que los hombros queden alineados con la almohadilla de la palanca.","Coloca los dedos de los pies en la parte inferior de la plataforma y posiciona las rodillas debajo de la almohadilla de la palanca.","Sujeta las asas a los lados del asiento para mayor estabilidad.","Presiona la almohadilla de la palanca hacia abajo extendiendo los tobillos, elevando los talones tan alto como sea posible.","Haz una pausa breve en la parte alta del movimiento, luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2335-Ie9UGty.jpg","gif":"2335-Ie9UGty.gif"},{"id":"0594","n":"Elevación de talones sentado en máquina de palanca","bp":"lower legs","eq":"leverage machine","tg":"calves","mg":"soleus","sm":["soleus","ankle stabilizers"],"st":["Ajusta la altura del asiento de modo que las rodillas queden ligeramente flexionadas y los pies queden planos sobre la placa para los pies.","Coloca los dedos de los pies sobre la placa para los pies, con los talones colgando fuera del borde.","Sujeta las asas o los lados del asiento para mayor estabilidad.","Empuja con la parte delantera de los pies para elevar los talones tan alto como sea posible.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0594-bOOdeyc.jpg","gif":"0594-bOOdeyc.gif"},{"id":"1452","n":"Crunch sentado en máquina de palanca","bp":"waist","eq":"leverage machine","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Siéntate en la máquina de palanca con la espalda apoyada en la almohadilla y los pies planos en el suelo.","Sujeta las asas o coloca las manos sobre las almohadillas laterales para mayor apoyo.","Activa el abdomen e inclínate lentamente hacia atrás, dejando que la almohadilla se mueva contigo.","Cuando la parte superior del cuerpo esté en un ángulo de 45 grados, contrae el abdomen y haz un crunch hacia adelante, llevando el pecho hacia las rodillas.","Haz una pausa breve en lo alto, luego suelta lentamente y vuelve a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1452-Wgaz7pm.jpg","gif":"1452-Wgaz7pm.gif"},{"id":"0595","n":"Crunch sentado en máquina de palanca (con apoyo en el pecho)","bp":"waist","eq":"leverage machine","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Ajusta la altura del asiento y la posición de la almohadilla para el pecho según tu comodidad.","Siéntate en la máquina con la espalda apoyada en la almohadilla para el pecho y los pies planos en el suelo.","Sujeta las asas o las barras laterales para mayor estabilidad.","Activa el abdomen y reclínate lentamente hacia atrás, permitiendo que el respaldo se mueva contigo.","Haz una pausa en la contracción máxima, sintiendo la tensión en el abdomen.","Vuelve lentamente a la posición inicial contrayendo el abdomen y tirando de tu cuerpo hacia arriba.","Repite el número de repeticiones deseado."],"img":"0595-ZnJHhMk.jpg","gif":"0595-ZnJHhMk.gif"},{"id":"3760","n":"Crunch sentado en máquina de poleas","bp":"waist","eq":"leverage machine","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Siéntate en la máquina de palanca con la espalda apoyada en el respaldo y los pies sujetos bajo las almohadillas.","Coloca las manos en las asas o en los lados del asiento para mayor apoyo.","Activa el abdomen y flexiona lentamente el torso hacia adelante, llevando el pecho hacia las rodillas.","Haz una pausa por un momento en la parte superior del movimiento, apretando el abdomen.","Vuelve lentamente a la posición inicial, dejando que tu espalda se redondee ligeramente.","Repite el número de repeticiones deseado."],"img":"3760-eXFXCY0.jpg","gif":"3760-eXFXCY0.gif"},{"id":"1451","n":"Fondos sentado en máquina de palanca","bp":"upper arms","eq":"leverage machine","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Ajusta la altura del asiento de modo que tus pies queden planos en el suelo y tus rodillas formen un ángulo de 90 grados.","Agarra las asas de la máquina de palanca con las palmas hacia abajo y los brazos completamente extendidos.","Baja lentamente el cuerpo flexionando los codos hasta que tus brazos queden paralelos al suelo.","Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.","Repite el número de repeticiones deseado."],"img":"1451-BRImeP8.jpg","gif":"1451-BRImeP8.gif"},{"id":"0596","n":"Aperturas sentado en máquina de palanca","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"deltoids","sm":["deltoids","trapezius"],"st":["Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla.","Agarra las asas con un agarre pronado y mantén los codos ligeramente flexionados.","Exhala y empuja las asas hacia adelante, juntándolas frente a tu pecho.","Haz una pausa por un momento, contrayendo los músculos del pecho.","Inhala y vuelve lentamente a la posición inicial, permitiendo que los músculos del pecho se estiren.","Repite el número de repeticiones deseado."],"img":"0596-v3xmPAR.jpg","gif":"0596-v3xmPAR.gif"},{"id":"3759","n":"Buenos días sentado en máquina de palanca","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Ajusta la altura del asiento de modo que tus caderas queden un poco más altas que tus rodillas.","Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos sobre los apoyapiés.","Sujeta las asas o los lados del asiento para mayor estabilidad.","Manteniendo la espalda recta, inclínate lentamente hacia adelante desde las caderas hasta que la parte superior de tu cuerpo quede paralela al suelo.","Haz una pausa por un momento y luego vuelve lentamente a la posición inicial empujando con los glúteos y los isquiotibiales.","Repite el número de repeticiones deseado."],"img":"3759-XsCcxCC.jpg","gif":"3759-XsCcxCC.gif"},{"id":"0597","n":"Abducción de cadera sentado en máquina","bp":"upper legs","eq":"leverage machine","tg":"abductors","mg":"glutes","sm":["glutes","hamstrings"],"st":["Ajusta la altura del asiento de modo que tus rodillas formen un ángulo de 90 grados.","Siéntate en la máquina con la espalda apoyada en el respaldo y los pies sobre los apoyapiés.","Coloca las manos en las asas laterales para mayor estabilidad.","Activa los abductores y empuja lentamente las piernas hacia afuera, alejándolas de la línea media del cuerpo.","Haz una pausa al final del movimiento y luego junta lentamente las piernas de nuevo hasta la posición inicial.","Repite el número de repeticiones deseado."],"img":"0597-CHpahtl.jpg","gif":"0597-CHpahtl.gif"},{"id":"0598","n":"Aducción de cadera sentado en máquina","bp":"upper legs","eq":"leverage machine","tg":"adductors","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en el respaldo.","Coloca los pies sobre los apoyapiés y agarra las asas para mayor estabilidad.","Activa los aductores y junta lentamente las piernas, apretando la parte interna de los muslos.","Haz una pausa breve en el punto máximo de contracción, luego vuelve lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0598-oHsrypV.jpg","gif":"0598-oHsrypV.gif"},{"id":"0599","n":"Curl de piernas sentado en máquina","bp":"upper legs","eq":"leverage machine","tg":"hamstrings","mg":"calves","sm":["calves"],"st":["Ajusta la máquina a tu cuerpo y siéntate en ella con la espalda apoyada en el respaldo.","Coloca la parte baja de las piernas debajo de la palanca acolchada, justo por encima de los tobillos.","Sujeta las asas a los lados de la máquina para mayor apoyo.","Manteniendo la parte superior de las piernas inmóvil, exhala y flexiona las piernas hacia arriba todo lo que puedas.","Mantén la posición contraída durante una pausa breve mientras aprietas los isquiotibiales.","Inhala y baja lentamente la palanca de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0599-Zg3XY7P.jpg","gif":"0599-Zg3XY7P.gif"},{"id":"0600","n":"Crunch con elevación de piernas sentado en máquina","bp":"waist","eq":"leverage machine","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Siéntate en la máquina de palanca con la espalda apoyada en el respaldo y los pies sobre los apoyapiés.","Sujeta las asas o las barras laterales para mayor estabilidad.","Activa el abdomen y eleva lentamente las piernas hacia el pecho, mientras curvas el torso hacia adelante al mismo tiempo.","Haz una pausa por un momento en la parte alta y luego baja lentamente las piernas y el torso a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0600-PQ2AtC3.jpg","gif":"0600-PQ2AtC3.gif"},{"id":"0602","n":"Pájaros sentado en máquina de palanca","bp":"shoulders","eq":"leverage machine","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo.","Agarra las asas con un agarre prono y mantén los brazos ligeramente flexionados.","Exhala y junta las escápulas mientras llevas las asas hacia atrás y hacia afuera, alejándolas de tu cuerpo.","Haz una pausa breve en el punto máximo de contracción, luego inhala y vuelve lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0602-myfUsKf.jpg","gif":"0602-myfUsKf.gif"},{"id":"0601","n":"Pájaros sentado en máquina de palanca (agarre neutro)","bp":"shoulders","eq":"leverage machine","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo.","Agarra las asas con un agarre paralelo, con las palmas enfrentadas, y mantén los brazos ligeramente flexionados.","Exhala y junta las escápulas mientras llevas las asas hacia atrás y hacia afuera, alejándolas de tu cuerpo.","Haz una pausa breve en el punto máximo de contracción, luego inhala y vuelve lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0601-xiHiJcA.jpg","gif":"0601-xiHiJcA.gif"},{"id":"1350","n":"Remo sentado en máquina de palanca","bp":"back","eq":"leverage machine","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ajusta la altura del asiento y los apoyapiés a una posición cómoda.","Siéntate en la máquina con el pecho apoyado en la almohadilla y los pies sobre los apoyapiés.","Agarra las asas con un agarre prono, con las manos separadas a la altura de los hombros.","Mantén la espalda recta y el core activado.","Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí.","Haz una pausa breve en la parte alta del movimiento.","Suelta lentamente las asas y vuelve a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1350-7I6LNUG.jpg","gif":"1350-7I6LNUG.gif"},{"id":"1385","n":"Elevación de talones sentado en máquina de prensa de piernas","bp":"lower legs","eq":"leverage machine","tg":"calves","mg":"quadriceps","sm":["quadriceps","hamstrings","glutes"],"st":["Ajusta el asiento de la máquina de prensa de piernas de modo que tus rodillas queden ligeramente flexionadas cuando los pies estén sobre la plataforma.","Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos sobre la plataforma, separados a la altura de los hombros.","Coloca los dedos y la planta de los pies sobre la plataforma, manteniendo los talones alejados del borde.","Suelta las palancas de seguridad y empuja la plataforma alejándola de ti extendiendo las rodillas.","Una vez que tus rodillas estén completamente extendidas, baja lentamente los talones flexionando las pantorrillas.","Haz una pausa por un momento en la parte baja y luego empuja la plataforma de nuevo hacia arriba extendiendo las pantorrillas.","Repite el número de repeticiones deseado."],"img":"1385-IeDEXTe.jpg","gif":"1385-IeDEXTe.gif"},{"id":"0603","n":"Press de hombros con barra fijada al suelo","bp":"shoulders","eq":"leverage machine","tg":"delts","mg":"triceps","sm":["triceps","chest"],"st":["Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en el respaldo.","Agarra las asas con un agarre prono y coloca las manos a la altura de los hombros.","Empuja las asas hacia arriba hasta que los brazos queden completamente extendidos, pero sin bloquear los codos.","Haz una pausa breve en lo alto, luego baja lentamente las asas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0603-67n3r98.jpg","gif":"0603-67n3r98.gif"},{"id":"0869","n":"Press de hombros en máquina de palanca agarre neutro","bp":"shoulders","eq":"leverage machine","tg":"delts","mg":"triceps","sm":["triceps","chest"],"st":["Ajusta la altura del asiento y el respaldo de la máquina de palanca a una posición cómoda.","Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos en el suelo.","Agarra las asas de la máquina con un agarre prono, un poco más separadas que la anchura de los hombros.","Empuja las asas hacia arriba y hacia adelante hasta que los brazos queden completamente extendidos, pero sin bloquear los codos.","Haz una pausa breve en lo alto, luego baja lentamente las asas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0869-vqsbmL0.jpg","gif":"0869-vqsbmL0.gif"},{"id":"2318","n":"Press de hombros en máquina de palanca agarre prono","bp":"shoulders","eq":"leverage machine","tg":"delts","mg":"triceps","sm":["triceps","chest"],"st":["Ajusta la altura del asiento y el respaldo de la máquina de palanca a una posición cómoda.","Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos en el suelo.","Agarra las asas de la máquina con un agarre prono, un poco más separadas que la anchura de los hombros.","Empuja las asas hacia arriba y hacia adelante hasta que los brazos queden completamente extendidos, pero sin bloquear los codos.","Haz una pausa breve en lo alto, luego baja lentamente las asas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2318-dNFYIU1.jpg","gif":"2318-dNFYIU1.gif"},{"id":"0604","n":"Encogimientos de hombros en máquina de palanca","bp":"back","eq":"leverage machine","tg":"traps","mg":"shoulders","sm":["shoulders"],"st":["Ajusta la altura del asiento y colócate en la máquina de palanca con la espalda apoyada en la almohadilla.","Sujeta las asas con un agarre prono y mantén los brazos rectos.","Manteniendo la espalda recta, eleva los hombros hacia las orejas tan alto como sea posible.","Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0604-ZZKbeMw.jpg","gif":"0604-ZZKbeMw.gif"},{"id":"0605","n":"Elevación de talones de pie en máquina de palanca","bp":"lower legs","eq":"leverage machine","tg":"calves","mg":"soleus","sm":["soleus","ankle stabilizers"],"st":["Ajusta la máquina a tu altura y ponte de pie con los pies separados a la altura de los hombros.","Coloca los hombros debajo de las almohadillas y sujétate de las asas para mayor estabilidad.","Eleva los talones tan alto como puedas extendiendo los tobillos.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0605-ykUOVze.jpg","gif":"0605-ykUOVze.gif"},{"id":"3758","n":"Press de pecho de pie en máquina de palanca","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Ajusta la altura del asiento y colócate en la máquina con los pies planos en el suelo.","Agarra las asas con un agarre prono y coloca las manos a la altura del pecho.","Empuja las asas hacia adelante hasta que los brazos queden completamente extendidos, manteniendo los codos ligeramente flexionados.","Haz una pausa por un momento y luego lleva lentamente las asas de vuelta hacia el pecho, manteniendo el control durante todo el movimiento.","Repite el número de repeticiones deseado."],"img":"3758-WbNq5Xu.jpg","gif":"3758-WbNq5Xu.gif"},{"id":"0606","n":"Remo en barra T en máquina de palanca","bp":"back","eq":"leverage machine","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ajusta la altura del asiento y la posición de la placa para los pies para asegurar una alineación correcta.","Siéntate en la máquina con el pecho contra la almohadilla y los pies planos sobre la placa para los pies.","Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.","Mantén la espalda recta y activa el core.","Tira de las asas hacia el torso, juntando los omóplatos.","Haz una pausa en el punto de máxima contracción y luego suelta lentamente las asas hasta la posición inicial.","Repite el número de repeticiones deseado."],"img":"0606-aaXr7ld.jpg","gif":"0606-aaXr7ld.gif"},{"id":"1351","n":"Remo en barra T con agarre supino en máquina de palanca","bp":"back","eq":"leverage machine","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo.","Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.","Mantén la espalda recta y activa el core.","Tira de las asas hacia el pecho, juntando los omóplatos.","Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente y extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1351-FVM1AUZ.jpg","gif":"1351-FVM1AUZ.gif"},{"id":"0607","n":"Extensión de tríceps en máquina de palanca","bp":"upper arms","eq":"leverage machine","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla.","Agarra las asas con un agarre prono y extiende completamente los brazos frente a ti.","Manteniendo la parte superior de los brazos inmóvil, baja lentamente las asas hacia tu frente flexionando los codos.","Haz una pausa por un momento en la parte baja y luego empuja las asas de vuelta hacia arriba hasta la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."],"img":"0607-Ser9eQp.jpg","gif":"0607-Ser9eQp.gif"},{"id":"1313","n":"Remo unilateral en máquina de palanca","bp":"back","eq":"leverage machine","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ajusta la altura del asiento y colócate frente a la máquina.","Agarra las asas con un agarre prono y mantén la espalda recta.","Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí.","Haz una pausa en el punto máximo del movimiento y luego suelta lentamente, extendiendo los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1313-oROuvrX.jpg","gif":"1313-oROuvrX.gif"},{"id":"0609","n":"Puente de Londres","bp":"back","eq":"rope","tg":"upper back","mg":"shoulders","sm":["shoulders","biceps","forearms"],"st":["Sujeta la cuerda a un punto de anclaje alto.","Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros.","Agarra la cuerda con un agarre prono, con las palmas hacia abajo.","Inclínate ligeramente hacia adelante, manteniendo la espalda recta y el core activado.","Tira de la cuerda hacia tu cuerpo, juntando las escápulas.","Haz una pausa por un momento en el punto más alto del movimiento, luego libera lentamente la tensión y regresa a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0609-bLyQokI.jpg","gif":"0609-bLyQokI.gif"},{"id":"3013","n":"Puente de glúteos bajo en suelo","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca los brazos a los lados del cuerpo, con las palmas hacia abajo.","Activa los glúteos y el core, y luego eleva las caderas del suelo hasta que tu cuerpo forme una línea recta desde las rodillas hasta los hombros.","Haz una pausa breve en la parte alta, apretando los glúteos.","Baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3013-u0cNiij.jpg","gif":"3013-u0cNiij.gif"},{"id":"1352","n":"Hiperextensión lumbar","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Túmbate boca abajo con las piernas extendidas y los brazos a los lados del cuerpo.","Activa los glúteos y los isquiotibiales, y eleva lentamente la parte superior del cuerpo del suelo, curvando la espalda hacia arriba.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1352-ANbbry2.jpg","gif":"1352-ANbbry2.gif"},{"id":"3582","n":"Zancada con salto","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Comienza de pie con los pies separados a la altura de los hombros.","Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.","Empújate con el pie derecho y salta al aire, cambiando la posición de los pies en pleno vuelo.","Aterriza suavemente con el pie izquierdo hacia adelante y baja inmediatamente el cuerpo a una posición de zancada.","Continúa alternando entre zancadas y saltos el número de repeticiones deseado."],"img":"3582-PM1PZjg.jpg","gif":"3582-PM1PZjg.gif"},{"id":"1688","n":"Zancada con giro de torso","bp":"waist","eq":"body weight","tg":"abs","mg":"quadriceps","sm":["quadriceps","glutes","hamstrings"],"st":["Comienza de pie con los pies separados a la altura de los hombros.","Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.","Al hacer la zancada, gira el torso hacia la derecha, llevando el codo izquierdo hacia la rodilla derecha.","Haz una pausa breve y luego vuelve a la posición inicial.","Repite hacia el otro lado, dando un paso adelante con el pie izquierdo y girando el torso hacia la izquierda.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"1688-K9VL0Jq.jpg","gif":"1688-K9VL0Jq.gif"},{"id":"0613","n":"Estiramiento de cuádriceps tumbado de lado","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hamstrings","sm":["hamstrings"],"st":["Túmbate de lado con las piernas rectas.","Flexiona la pierna de arriba y agarra tu tobillo o pie con la mano.","Tira suavemente del tobillo o del pie hacia los glúteos hasta sentir un estiramiento en los cuádriceps.","Mantén el estiramiento durante 20-30 segundos.","Suelta el estiramiento y repite del otro lado."],"img":"0613-BWnJR72.jpg","gif":"0613-BWnJR72.gif"},{"id":"2312","n":"Codo a rodilla tumbado","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activa el abdomen y levanta la parte superior del cuerpo del suelo, llevando el codo derecho hacia la rodilla izquierda.","Al mismo tiempo, extiende la pierna derecha en línea recta y levántala del suelo.","Haz una pausa breve y luego vuelve a la posición inicial.","Repite el movimiento, esta vez llevando el codo izquierdo hacia la rodilla derecha y extendiendo la pierna izquierda.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"2312-AQIhRjM.jpg","gif":"2312-AQIhRjM.gif"},{"id":"0620","n":"Elevación de piernas tumbado en banco plano","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Túmbate en un banco plano con la espalda presionada contra él.","Coloca las manos debajo de los glúteos como apoyo.","Mantén las piernas rectas y juntas, y elévalas hacia el techo.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0620-WhuFnR7.jpg","gif":"0620-WhuFnR7.gif"},{"id":"0865","n":"Elevación de piernas y cadera tumbado","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.","Coloca las manos debajo de los glúteos como apoyo.","Activa el core y levanta las piernas del suelo, elevándolas hacia el techo.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0865-9IxJdtC.jpg","gif":"0865-9IxJdtC.gif"},{"id":"1301","n":"Press de pecho cerrado en máquina","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Ajusta la altura del asiento y colócate en la máquina con la espalda totalmente apoyada en la almohadilla.","Sujeta las asas con un agarre prono y coloca los codos en un ángulo de 90 grados.","Empuja las asas hacia adelante hasta que los brazos queden completamente extendidos, exhalando durante el movimiento.","Haz una pausa al final del movimiento y luego vuelve lentamente a la posición inicial, inhalando mientras lo haces.","Repite el número de repeticiones deseado."],"img":"1301-wDN97Ca.jpg","gif":"1301-wDN97Ca.gif"},{"id":"0624","n":"Sentadilla isométrica en pared con marcha","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con la espalda contra una pared y los pies separados a la altura de las caderas.","Desliza lentamente la espalda hacia abajo por la pared hasta que las rodillas formen un ángulo de 90 grados.","Levanta el pie derecho del suelo y lleva la rodilla hacia el pecho.","Baja el pie derecho de nuevo y levanta el pie izquierdo del suelo, llevando la rodilla hacia el pecho.","Continúa alternando entre levantar el pie derecho y el izquierdo el número de repeticiones deseado."],"img":"0624-sVQCCeG.jpg","gif":"0624-sVQCCeG.gif"},{"id":"1353","n":"Recepción y lanzamiento sobre la cabeza con balón medicinal","bp":"back","eq":"medicine ball","tg":"lats","mg":"shoulders","sm":["shoulders","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un balón medicinal con ambas manos a la altura del pecho.","Flexiona ligeramente las rodillas y activa el core.","Baja el cuerpo a una posición de sentadilla, manteniendo la espalda recta y el pecho hacia arriba.","Extiende explosivamente las caderas y las piernas, mientras lanzas simultáneamente el balón medicinal por encima de la cabeza.","Suelta el balón en la parte más alta del movimiento y atrápalo cuando vaya bajando.","Baja de nuevo el cuerpo a la posición de sentadilla y repite el número de repeticiones deseado."],"img":"1353-PsVS1QP.jpg","gif":"1353-PsVS1QP.gif"},{"id":"1302","n":"Pase de pecho con balón medicinal","bp":"chest","eq":"medicine ball","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo el balón medicinal a la altura del pecho.","Extiende los brazos hacia adelante, empujando el balón medicinal con fuerza para alejarlo del pecho.","Al soltar el balón, continúa el movimiento con los brazos y el torso, transfiriendo el peso del pie de atrás al pie de adelante.","Atrapa el balón cuando rebote en la pared o en tu compañero, y repite el movimiento de inmediato.","Continúa durante el número de repeticiones deseado."],"img":"1302-aDoFKrE.jpg","gif":"1302-aDoFKrE.gif"},{"id":"1303","n":"Empuje de pecho con balón medicinal desde posición de tres puntos","bp":"chest","eq":"medicine ball","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Comienza en una posición de apoyo de 3 puntos con una mano sobre el balón medicinal y la otra en el suelo.","Extiende las piernas y coloca tu cuerpo en línea recta.","Baja el pecho hacia el suelo manteniendo la espalda recta.","Empuja el balón medicinal alejándolo de tu cuerpo, extendiendo completamente el brazo.","Vuelve a la posición inicial y repite el número de repeticiones deseado."],"img":"1303-dCJnuVq.jpg","gif":"1303-dCJnuVq.gif"},{"id":"1304","n":"Empujes continuos de pecho con balón medicinal","bp":"chest","eq":"medicine ball","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un balón medicinal a la altura del pecho.","Extiende los brazos hacia adelante, alejando el balón medicinal de tu pecho.","Haz una pausa por un momento y luego lleva lentamente el balón medicinal de vuelta al pecho.","Repite el número de repeticiones deseado."],"img":"1304-7aolH9D.jpg","gif":"1304-7aolH9D.gif"},{"id":"1305","n":"Empuje simple de pecho con balón medicinal","bp":"chest","eq":"medicine ball","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo el balón medicinal a la altura del pecho.","Extiende los brazos hacia adelante, alejando el balón medicinal de tu pecho.","Haz una pausa por un momento y luego lleva lentamente el balón medicinal de vuelta al pecho.","Repite el número de repeticiones deseado."],"img":"1305-jeHtrlO.jpg","gif":"1305-jeHtrlO.gif"},{"id":"1312","n":"Empuje de pecho con balón medicinal en carrera","bp":"chest","eq":"medicine ball","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un balón medicinal a la altura del pecho.","Da un paso adelante con el pie derecho y, al mismo tiempo, empuja el balón medicinal hacia adelante, extendiendo completamente los brazos.","Mientras empujas el balón hacia adelante, suéltalo y déjalo rodar.","Corre rápidamente hacia adelante y atrapa el balón antes de que toque el suelo.","Una vez que atrapes el balón, llévalo de vuelta al pecho y repite el movimiento con el pie izquierdo adelante.","Continúa alternando piernas y repitiendo el ejercicio el número de repeticiones deseado."],"img":"1312-pX9Elbe.jpg","gif":"1312-pX9Elbe.gif"},{"id":"1701","n":"Flexión sobre balón medicinal con agarre cerrado","bp":"upper arms","eq":"medicine ball","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Comienza en una posición de plancha alta con las manos sobre el balón medicinal, separadas a la altura de los hombros.","Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.","Empuja de vuelta hasta la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"1701-8K7m2SS.jpg","gif":"1701-8K7m2SS.gif"},{"id":"1354","n":"Lanzamiento de balón medicinal contra el suelo sobre la cabeza","bp":"back","eq":"medicine ball","tg":"upper back","mg":"shoulders","sm":["shoulders","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un balón medicinal con ambas manos por encima de la cabeza.","Activa el core y mantén la espalda recta.","Flexiona ligeramente las rodillas y lanza con fuerza el balón medicinal contra el suelo frente a ti.","Al lanzar el balón al suelo, utiliza todo el cuerpo para generar potencia, incluidos los hombros y el core.","Atrapa el balón al rebotar y repite el número de repeticiones deseado."],"img":"1354-oHg8eop.jpg","gif":"1354-oHg8eop.gif"},{"id":"1750","n":"Lanzamiento de pecho supino con balón medicinal","bp":"upper arms","eq":"medicine ball","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Túmbate boca arriba en un banco con las rodillas flexionadas y los pies planos en el suelo.","Sostén el balón medicinal con ambas manos, extendiendo los brazos rectos por encima del pecho.","Baja el balón medicinal hacia el pecho, manteniendo los codos cerca del cuerpo.","Empuja el balón medicinal explosivamente hacia arriba, extendiendo completamente los brazos y lanzando el balón lo más alto posible.","Atrapa el balón medicinal y repite el número de repeticiones deseado."],"img":"1750-Al3tP0D.jpg","gif":"1750-Al3tP0D.gif"},{"id":"0627","n":"Dominadas con agarre mixto","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Agarra la barra de dominadas con un agarre supino (las palmas hacia ti) y las manos un poco más separadas que la anchura de los hombros.","Cuélgate de la barra con los brazos completamente extendidos y los pies fuera del suelo.","Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, llevando el pecho por delante.","Continúa subiendo hasta que la barbilla quede por encima de la barra.","Haz una pausa por un momento en la parte alta y luego baja lentamente tu cuerpo, con control, hasta la posición inicial.","Repite el número de repeticiones deseado."],"img":"0627-T8UpLkb.jpg","gif":"0627-T8UpLkb.gif"},{"id":"3217","n":"Flexión hindú modificada (hombre)","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies separados a la altura de las caderas.","Baja el cuerpo hacia el suelo, flexionando los codos y manteniendo el core activado.","Mientras bajas el cuerpo, desplaza el peso hacia atrás y eleva las caderas hacia el techo, formando una V invertida con tu cuerpo.","Sigue bajando el cuerpo hasta que el pecho quede justo por encima del suelo y luego invierte el movimiento, empujando las caderas hacia abajo y extendiendo los brazos para volver a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3217-epOSYUZ.jpg","gif":"3217-epOSYUZ.gif"},{"id":"1421","n":"Flexión modificada a antebrazos","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"triceps","sm":["triceps","chest","shoulders"],"st":["Comienza en posición de flexión con las manos directamente debajo de los hombros y el cuerpo en línea recta.","Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de tu costado.","Cuando los codos formen un ángulo de 90 grados, baja los antebrazos hasta el suelo, manteniendo los codos justo debajo de los hombros.","Haz una pausa por un momento y luego empuja con las palmas para llevar los antebrazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1421-arvaszz.jpg","gif":"1421-arvaszz.gif"},{"id":"0628","n":"Paso del monstruo (monster walk)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Coloca una banda elástica alrededor de los tobillos.","Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas.","Da un paso hacia el lado con el pie derecho, manteniendo la tensión en la banda elástica.","Continúa con el pie izquierdo, dando un paso lateral para volver a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"0628-O95afRA.jpg","gif":"0628-O95afRA.gif"},{"id":"0630","n":"Escalador (mountain climber)","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"core","sm":["core","shoulders","triceps"],"st":["Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta.","Activa el core y lleva la rodilla derecha hacia el pecho, luego cambia rápidamente y lleva la rodilla izquierda hacia el pecho.","Continúa alternando las piernas con un movimiento de carrera, manteniendo las caderas bajas y el core activado.","Mantén un ritmo constante y respira de forma regular durante todo el ejercicio.","Repite el número de repeticiones deseado."],"img":"0630-RJgzwny.jpg","gif":"0630-RJgzwny.gif"},{"id":"0631","n":"Muscle-up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","triceps","shoulders","chest"],"st":["Comienza colgándote de una barra de dominadas con las palmas hacia afuera y los brazos completamente extendidos.","Activa el core y tira de tu cuerpo hacia arriba, hacia la barra, guiando con el pecho.","Al llegar a la parte alta del movimiento, cambia el agarre de modo que las palmas queden hacia ti.","Sigue tirando hacia arriba hasta que el pecho quede por encima de la barra y los brazos estén completamente flexionados.","Invierte el movimiento bajando lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0631-yJUHKTn.jpg","gif":"0631-yJUHKTn.gif"},{"id":"1401","n":"Muscle-up (en barra vertical)","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","triceps","forearms"],"st":["Comienza colgándote de una barra vertical con las palmas hacia afuera y los brazos completamente extendidos.","Activa el core y tira de tu cuerpo hacia arriba, hacia la barra, guiando con el pecho.","Al subir tu cuerpo, inclínate ligeramente hacia atrás y lleva los codos hacia los costados.","Sigue tirando hasta que el pecho llegue a la barra y los codos estén completamente flexionados.","Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1401-Af0EW2I.jpg","gif":"1401-Af0EW2I.gif"},{"id":"2328","n":"Flexión cerrada sobre fitball","bp":"upper arms","eq":"stability ball","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Coloca el balón de estabilidad en el suelo y ponte en posición de flexión con las manos sobre el balón, un poco más juntas que la anchura de los hombros.","Activa el core y mantén el cuerpo en línea recta de la cabeza a los pies.","Baja el pecho hacia el balón flexionando los codos, manteniéndolos cerca del cuerpo.","Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.","Repite el número de repeticiones deseado."],"img":"2328-4cWjYEN.jpg","gif":"2328-4cWjYEN.gif"},{"id":"1403","n":"Estiramiento lateral de cuello","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"trapezius","sm":["trapezius","sternocleidomastoid"],"st":["Ponte de pie o siéntate erguido con los hombros relajados.","Inclina la cabeza hacia un lado, llevando la oreja hacia el hombro.","Mantén el estiramiento durante 15-30 segundos.","Repite del otro lado.","Realiza de 2 a 4 series por cada lado."],"img":"1403-x2chWLO.jpg","gif":"1403-x2chWLO.gif"},{"id":"0634","n":"Crunch abdominal negativo","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0634-szIn2UK.jpg","gif":"0634-szIn2UK.gif"},{"id":"1495","n":"Crunch para oblicuos v. 2","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.","Activa el abdomen y levanta las escápulas del suelo, rotando el torso hacia un lado.","Haz una pausa por un momento y luego baja las escápulas de nuevo a la posición inicial.","Repite del otro lado.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"1495-cJgSTmh.jpg","gif":"1495-cJgSTmh.gif"},{"id":"0635","n":"Crunch para oblicuos en suelo","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Túmbate boca arriba con las rodillas flexionadas y los pies planos en el suelo.","Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.","Activa el abdomen y levanta las escápulas del suelo, rotando el torso hacia un lado.","Haz una pausa por un momento y luego baja las escápulas de nuevo hasta el suelo.","Repite hacia el otro lado, alternando los lados en cada repetición."],"img":"0635-QUDd8WS.jpg","gif":"0635-QUDd8WS.gif"},{"id":"0636","n":"Curl martillo con barra olímpica","bp":"upper arms","eq":"olympic barbell","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra olímpica con un agarre prono.","Deja que la barra cuelgue a la altura de los brazos frente a tus muslos, con las palmas hacia tu cuerpo.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0636-o1ntciW.jpg","gif":"0636-o1ntciW.gif"},{"id":"0637","n":"Extensión de tríceps con barra olímpica","bp":"upper arms","eq":"olympic barbell","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Comienza de pie con los pies separados a la altura de los hombros y sosteniendo la barra con un agarre prono.","Levanta la barra por encima de la cabeza, extendiendo completamente los brazos.","Manteniendo los brazos superiores cerca de la cabeza, baja lentamente la barra detrás de la cabeza flexionando los codos.","Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0637-wu5LXwz.jpg","gif":"0637-wu5LXwz.gif"},{"id":"1355","n":"Estiramiento con un brazo apoyado en pared","bp":"back","eq":"body weight","tg":"lats","mg":"shoulders","sm":["shoulders","triceps"],"st":["Ponte de pie frente a una pared con los pies separados a la altura de los hombros.","Extiende un brazo recto hacia adelante y coloca la palma contra la pared.","Activa el core e inclina el cuerpo hacia adelante, manteniendo el brazo recto y la espalda plana.","Empuja lentamente la pared con la palma, activando los dorsales.","Mantén la posición durante unos segundos, luego suelta y repite con el otro brazo."],"img":"1355-ZZTGMKh.jpg","gif":"1355-ZZTGMKh.gif"},{"id":"0638","n":"Dominada supina con un brazo","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Ponte de pie frente a una barra de dominadas con los pies separados a la altura de los hombros.","Estírate y agarra la barra con un agarre supino, con una mano sujetando la barra y la otra sosteniendo la muñeca como apoyo.","Cuélgate de la barra con el brazo completamente extendido, manteniendo el cuerpo recto y el core activado.","Tira de tu cuerpo hacia la barra flexionando el codo y contrayendo los músculos de la espalda.","Continúa subiendo hasta que la barbilla quede por encima de la barra, luego bájate lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo y repite."],"img":"0638-HjdqmZa.jpg","gif":"0638-HjdqmZa.gif"},{"id":"0639","n":"Fondo con un brazo","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Ponte de pie de espaldas a un banco o silla, con los pies separados a la altura de los hombros.","Coloca una mano en el banco o silla detrás de ti, con los dedos apuntando hacia tu cuerpo.","Extiende las piernas hacia adelante, manteniendo los talones en el suelo.","Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco o silla.","Haz una pausa por un momento en la parte baja y luego empuja con las palmas para estirar los brazos y volver a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado y repite con el otro brazo."],"img":"0639-FAoIFMw.jpg","gif":"0639-FAoIFMw.gif"},{"id":"0640","n":"Slam con un brazo (con balón medicinal)","bp":"waist","eq":"medicine ball","tg":"abs","mg":"shoulders","sm":["shoulders","back"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo el balón medicinal con una mano frente a la cintura.","Flexiona ligeramente las rodillas y activa el core.","Eleva el balón medicinal por encima de la cabeza, extendiendo completamente el brazo.","Lanza con fuerza el balón medicinal contra el suelo, usando el core y los hombros para generar potencia.","Atrapa el balón medicinal al rebotar y repite el número de repeticiones deseado."],"img":"0640-jCrtE9b.jpg","gif":"0640-jCrtE9b.gif"},{"id":"1773","n":"Remo con un brazo y toalla","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una toalla con una mano.","Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado.","Extiende completamente el brazo, dejando que la toalla cuelgue frente a ti.","Tira de la toalla hacia el pecho, juntando los omóplatos.","Haz una pausa breve en la parte más alta, luego baja lentamente la toalla de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"img":"1773-bKWbrTA.jpg","gif":"1773-bKWbrTA.gif"},{"id":"1386","n":"Elevación de talones tipo burro a una pierna","bp":"lower legs","eq":"body weight","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Ponte de pie con los pies separados a la altura de los hombros, con las puntas de los pies apuntando hacia adelante.","Coloca las manos sobre una superficie estable para apoyarte, como una pared o una barra.","Levanta una pierna del suelo, manteniendo la rodilla ligeramente flexionada.","Eleva el talón lo más alto posible, usando los músculos de la pantorrilla.","Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta hacia abajo.","Repite el número de repeticiones deseado, luego cambia de pierna."],"img":"1386-A2upspL.jpg","gif":"1386-A2upspL.gif"},{"id":"1387","n":"Elevación de talón a una pierna en el suelo","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","feet"],"st":["Ponte de pie con los pies separados a la altura de las caderas y coloca las manos en una pared u objeto firme para mantener el equilibrio.","Levanta un pie del suelo y mantén el equilibrio sobre el otro pie.","Levanta lentamente el talón del suelo, elevando el cuerpo sobre las puntas de los pies.","Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.","Repite el número de repeticiones deseado y luego cambia de pierna y repite."],"img":"1387-0jp9Rlz.jpg","gif":"1387-0jp9Rlz.gif"},{"id":"1476","n":"Sentadilla a una pierna","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros.","Extiende una pierna hacia adelante, manteniéndola elevada del suelo.","Flexiona la pierna de apoyo y baja el cuerpo como si te sentaras en una silla.","Mantén el pecho arriba y la espalda recta.","Empuja con el talón para regresar a la posición inicial.","Repite con la otra pierna."],"img":"1476-C31LMnP.jpg","gif":"1476-C31LMnP.gif"},{"id":"0641","n":"Otis-up","bp":"waist","eq":"weighted","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0641-UVL20oz.jpg","gif":"0641-UVL20oz.gif"},{"id":"0642","n":"Flexión con patada lateral hacia fuera","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos.","Baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta y el core activado.","Al empujar de vuelta hacia arriba, lanza una pierna hacia el lado, extendiéndola completamente y activando los glúteos.","Vuelve a colocar la pierna en la posición inicial y repite la flexión, alternando las piernas en cada repetición.","Continúa alternando las patadas de pierna y las flexiones el número de repeticiones deseado."],"img":"0642-jNU1gFQ.jpg","gif":"0642-jNU1gFQ.gif"},{"id":"0643","n":"Estiramiento de tríceps por encima de la cabeza","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Ponte de pie o siéntate erguido con los pies separados a la altura de los hombros.","Extiende un brazo por encima de la cabeza, flexionando el codo de modo que la mano llegue hacia la escápula opuesta.","Con la otra mano, tira suavemente del codo del brazo extendido hacia el lado opuesto de la cabeza, sintiendo un estiramiento en el tríceps.","Mantén el estiramiento durante 15-30 segundos, luego suelta.","Repite del otro lado."],"img":"0643-Z5YStHW.jpg","gif":"0643-Z5YStHW.gif"},{"id":"3147","n":"Basculación pélvica","bp":"waist","eq":"body weight","tg":"abs","mg":"lower back","sm":["lower back"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos a los lados del cuerpo.","Activa el abdomen e inclina la pelvis hacia arriba, presionando la zona lumbar contra el suelo.","Mantén esta posición durante unos segundos, concentrándote en contraer el abdomen.","Deshaz la inclinación y vuelve a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3147-NKJ8o6x.jpg","gif":"3147-NKJ8o6x.gif"},{"id":"1422","n":"Basculación pélvica a puente de glúteos","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca los brazos a los lados del cuerpo con las palmas hacia abajo.","Activa los glúteos y los músculos del core.","Inclina la pelvis hacia arriba, levantando las caderas del suelo.","Mantén la posición de puente durante unos segundos.","Baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1422-D9qe7CM.jpg","gif":"1422-D9qe7CM.gif"},{"id":"1388","n":"Estiramiento de peroneos","bp":"lower legs","eq":"rope","tg":"calves","mg":"ankles","sm":["ankles","feet"],"st":["Siéntate en el suelo con las piernas extendidas frente a ti.","Enrolla la cuerda alrededor de la planta del pie y sujeta los extremos de la cuerda con las manos.","Tira suavemente de la cuerda hacia ti, flexionando el pie y estirando los músculos de la pantorrilla.","Mantén el estiramiento durante 15-30 segundos.","Suelta la tensión de la cuerda y repite el estiramiento en la otra pierna.","Repite el número de repeticiones deseado."],"img":"1388-XhfS1DZ.jpg","gif":"1388-XhfS1DZ.gif"},{"id":"3662","n":"Flexión de pino a cobra","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"core","sm":["core","shoulders","triceps"],"st":["Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos.","Activa el core y eleva las caderas hacia el techo, formando una V invertida con tu cuerpo.","Baja la parte superior del cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo.","Al bajar, desplaza el peso hacia adelante y haz la transición a una postura de cobra estirando los brazos y elevando el pecho.","Invierte el movimiento flexionando los codos y bajando el pecho de nuevo hacia el suelo.","Empuja con las manos para volver a la posición de V invertida.","Continúa el movimiento bajando las caderas de nuevo hacia el suelo, volviendo a la posición inicial de flexión.","Repite el número de repeticiones deseado."],"img":"3662-XPUDTt7.jpg","gif":"3662-XPUDTt7.gif"},{"id":"1306","n":"Flexión pliométrica","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros.","Baja el pecho hacia el suelo flexionando los codos, manteniendo el cuerpo en línea recta.","Empuja explosivamente contra el suelo, usando los músculos del pecho para impulsar la parte superior del cuerpo fuera del suelo.","Aterriza suavemente con las manos de vuelta en la posición inicial.","Repite el número de repeticiones deseado."],"img":"1306-Snj1wSv.jpg","gif":"1306-Snj1wSv.gif"},{"id":"1687","n":"Paso atrás con extensión de brazos sobre la cabeza","bp":"waist","eq":"body weight","tg":"abs","mg":"glutes","sm":["glutes","hamstrings","quadriceps","shoulders"],"st":["Ponte de pie con los pies separados a la altura de las caderas y los brazos a los lados del cuerpo.","Da un paso hacia atrás con el pie derecho, apoyándote en la punta del pie.","Flexiona la rodilla izquierda y baja el cuerpo a una posición de zancada.","Mientras bajas a la zancada, lleva simultáneamente los brazos por encima de la cabeza.","Haz una pausa por un momento en la parte baja de la zancada y luego vuelve a la posición inicial empujando con el talón izquierdo y llevando el pie derecho hacia adelante.","Repite el movimiento hacia el otro lado, retrocediendo con el pie izquierdo y flexionando la rodilla derecha.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"1687-ErqK3UL.jpg","gif":"1687-ErqK3UL.gif"},{"id":"1389","n":"Estiramiento del tibial posterior","bp":"lower legs","eq":"rope","tg":"calves","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Siéntate en el suelo con las piernas extendidas frente a ti.","Enrolla la cuerda alrededor de la planta del pie y sujeta los extremos de la cuerda con las manos.","Tira suavemente de la cuerda hacia ti, flexionando el pie y estirando los músculos de la pantorrilla.","Mantén el estiramiento durante 20-30 segundos.","Suelta la tensión de la cuerda y relaja el pie.","Repite el estiramiento en la otra pierna."],"img":"1389-DEEqoI2.jpg","gif":"1389-DEEqoI2.gif"},{"id":"3119","n":"Sentadilla profunda","bp":"waist","eq":"body weight","tg":"abs","mg":"quadriceps","sm":["quadriceps","glutes"],"st":["Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.","Baja el cuerpo flexionando las rodillas y empujando las caderas hacia atrás como si te sentaras en una silla.","Mantén el pecho hacia arriba y la espalda recta durante todo el movimiento.","Baja hasta que los muslos queden paralelos al suelo o hasta donde puedas llegar cómodamente.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3119-75Bgtjy.jpg","gif":"3119-75Bgtjy.gif"},{"id":"3132","n":"Sentadilla profunda asistida","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.","Sujétate de un apoyo estable, como una silla o una pared, para mantener el equilibrio.","Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.","Mantén el pecho hacia arriba y la espalda recta durante todo el movimiento.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3132-b63ZzGe.jpg","gif":"3132-b63ZzGe.gif"},{"id":"0648","n":"Power clean","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"glutes","sm":["glutes","quadriceps","calves"],"st":["Comienza con la barra en el suelo frente a ti, con los pies separados a la altura de los hombros.","Agáchate y agarra la barra con un agarre prono, un poco más separado que la anchura de los hombros.","Mantén la espalda recta y el pecho hacia arriba al levantar la barra del suelo, extendiendo las caderas y las rodillas.","Cuando la barra llegue a la mitad del muslo, tira de ella explosivamente hacia arriba, encogiendo los hombros y llevando los codos hacia arriba y hacia los lados.","Cuando la barra alcance su punto más alto, baja rápidamente debajo de ella, rotando los codos y atrapando la barra sobre los hombros en una posición de sentadilla frontal.","Ponte de pie con la barra, extendiendo completamente las caderas y las rodillas.","Baja la barra de nuevo a la posición inicial, manteniendo el control del peso durante todo el movimiento.","Repite el número de repeticiones deseado."],"img":"0648-SiWCcTN.jpg","gif":"0648-SiWCcTN.gif"},{"id":"3665","n":"Plancha power point","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","triceps","glutes"],"st":["Comienza en posición de plancha alta con las manos directamente debajo de los hombros y el cuerpo en línea recta de la cabeza a los pies.","Activa el core y aprieta los glúteos para mantener una posición estable.","Baja el cuerpo hasta los antebrazos, un brazo a la vez, manteniendo una línea recta de la cabeza a los pies.","Mantén esta posición durante el tiempo deseado, con el core y los glúteos activados.","Para volver a la posición inicial, empuja con los antebrazos y eleva el cuerpo de nuevo a una posición de plancha alta.","Repite el número de repeticiones deseado."],"img":"3665-hCjGsRQ.jpg","gif":"3665-hCjGsRQ.gif"},{"id":"3203","n":"Medio sit-up de prisionero (hombre)","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3203-mgejmGP.jpg","gif":"3203-mgejmGP.gif"},{"id":"1707","n":"Torsión en decúbito prono sobre fitball","bp":"waist","eq":"stability ball","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Comienza tumbándote boca abajo sobre un balón de estabilidad con los pies separados a la altura de los hombros y los dedos de los pies tocando el suelo.","Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.","Activa los músculos del core y eleva lentamente la parte superior del cuerpo del balón, manteniendo la espalda recta.","Rota el torso hacia un lado, llevando el hombro hacia la cadera. Mantén las caderas y las piernas estables durante todo el movimiento.","Haz una pausa breve y luego vuelve a la posición inicial.","Repite la rotación hacia el otro lado.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"1707-1IG6gVF.jpg","gif":"1707-1IG6gVF.gif"},{"id":"0651","n":"Dominada (agarre neutro)","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Cuélgate de una barra de dominadas con un agarre neutro (las palmas enfrentadas) y los brazos completamente extendidos.","Activa el core y junta los omóplatos.","Tira de tu cuerpo hacia la barra flexionando los codos y llevándolos hacia las caderas.","Continúa subiendo hasta que la barbilla quede por encima de la barra.","Haz una pausa por un momento en la parte alta y luego baja lentamente tu cuerpo, con control, hasta la posición inicial.","Repite el número de repeticiones deseado."],"img":"0651-0V2YQjW.jpg","gif":"0651-0V2YQjW.gif"},{"id":"0650","n":"Encogimiento de piernas sobre fitball","bp":"waist","eq":"stability ball","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Comienza sentándote en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas a un ángulo de 90 grados.","Coloca las manos a los lados del balón de estabilidad para mayor apoyo.","Activa el abdomen y rueda lentamente las caderas hacia adelante, llevando las rodillas hacia el pecho.","Haz una pausa por un momento en la parte alta del movimiento y luego extiende lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0650-UQr48Oi.jpg","gif":"0650-UQr48Oi.gif"},{"id":"0652","n":"Dominada","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Cuélgate de una barra de dominadas con las palmas hacia afuera y los brazos completamente extendidos.","Activa el core y junta los omóplatos.","Tira de tu cuerpo hacia la barra flexionando los codos y llevando el pecho hacia la barra.","Haz una pausa en la parte alta del movimiento y luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0652-lBDjFxJ.jpg","gif":"0652-lBDjFxJ.gif"},{"id":"1689","n":"Empuje y tracción con peso corporal","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","deltoids"],"st":["Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y el cuerpo en línea recta.","Baja el pecho hacia el suelo flexionando los codos, manteniendo el cuerpo recto.","Empuja con las palmas para extender los brazos y regresar a la posición inicial.","Desde la posición de flexión, tira del pecho hacia el suelo flexionando los codos, manteniendo el cuerpo recto.","Empuja con las palmas para extender los brazos y regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1689-wXvUZC8.jpg","gif":"1689-wXvUZC8.gif"},{"id":"3638","n":"Flexión con salida a carrera","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Comienza en posición de flexión con las manos separadas a la altura de los hombros y el cuerpo en línea recta.","Baja el pecho hacia el suelo flexionando los codos, manteniendo el cuerpo recto.","Empuja con las manos para extender los brazos y volver a la posición inicial.","Lleva rápidamente una rodilla hacia el pecho, luego cambia rápidamente y lleva la otra rodilla hacia el pecho.","Continúa alternando las rodillas tan rápido como puedas manteniendo una buena forma.","Continúa durante el tiempo o el número de repeticiones deseado."],"img":"3638-PrQbjvB.jpg","gif":"3638-PrQbjvB.gif"},{"id":"1307","n":"Flexión sobre bosu","bp":"chest","eq":"bosu ball","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Coloca el bosu en el suelo con el lado plano hacia arriba.","Colócate en posición de flexión con las manos en los bordes exteriores del bosu.","Activa el core y baja el cuerpo hacia el bosu flexionando los codos.","Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."],"img":"1307-wVompEp.jpg","gif":"1307-wVompEp.gif"},{"id":"0662","n":"Flexión","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","deltoids","core"],"st":["Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y los pies juntos.","Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniendo el cuerpo en línea recta.","Haz una pausa cuando el pecho esté justo por encima del suelo y luego empújate de vuelta a la posición inicial estirando los brazos.","Repite el número de repeticiones deseado."],"img":"0662-I4hDWkc.jpg","gif":"0662-I4hDWkc.gif"},{"id":"0653","n":"Flexión (en bosu)","bp":"chest","eq":"bosu ball","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Coloca el bosu en el suelo con el lado plano hacia arriba.","Colócate en posición de flexión con las manos en los bordes exteriores del bosu.","Activa el core y baja el cuerpo hacia el bosu flexionando los codos.","Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."],"img":"0653-2kr2lWy.jpg","gif":"0653-2kr2lWy.gif"},{"id":"0655","n":"Flexión inclinada (sobre fitball) diamante","bp":"chest","eq":"stability ball","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Coloca el balón de estabilidad en el suelo y ponte boca abajo con las manos sobre el balón, separadas a la altura de los hombros.","Extiende las piernas rectas detrás de ti, equilibrándote sobre los dedos de los pies.","Activa el core y baja el pecho hacia el balón flexionando los codos, manteniendo el cuerpo en línea recta.","Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.","Repite el número de repeticiones deseado."],"img":"0655-Y4BRNQF.jpg","gif":"0655-Y4BRNQF.gif"},{"id":"0656","n":"Flexión declinada (sobre fitball) normal","bp":"chest","eq":"stability ball","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Coloca el balón de estabilidad en el suelo y ponte boca abajo con las manos sobre el balón, separadas a la altura de los hombros.","Extiende las piernas rectas detrás de ti, equilibrándote sobre los dedos de los pies.","Activa el core y baja el pecho hacia el balón flexionando los codos, manteniendo el cuerpo en línea recta.","Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.","Repite el número de repeticiones deseado."],"img":"0656-tgryw5Y.jpg","gif":"0656-tgryw5Y.gif"},{"id":"0659","n":"Flexión (en pared) cerrado","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","deltoids"],"st":["Ponte de pie frente a una pared, a una distancia aproximada de un brazo.","Coloca las manos en la pared a la altura de los hombros, un poco más separadas que la anchura de los hombros.","Da un paso atrás, manteniendo el cuerpo recto y los pies separados a la altura de las caderas.","Flexiona los codos y baja el pecho hacia la pared, manteniendo el cuerpo en línea recta.","Empuja de vuelta a la posición inicial, estirando los brazos.","Repite el número de repeticiones deseado."],"img":"0659-LEH9jxP.jpg","gif":"0659-LEH9jxP.gif"},{"id":"0658","n":"Flexión (en pared) abierto","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Ponte de pie frente a una pared, a una distancia aproximada de un brazo.","Coloca las manos en la pared a la altura de los hombros, un poco más separadas que la anchura de los hombros.","Retrocede con los pies, manteniéndolos separados a la altura de las caderas.","Activa el core y mantén el cuerpo en línea recta desde la cabeza hasta los talones.","Flexiona los codos y baja el pecho hacia la pared, manteniendo el cuerpo recto.","Haz una pausa por un momento y luego empújate de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0658-NCmbLCw.jpg","gif":"0658-NCmbLCw.gif"},{"id":"0660","n":"Flexión con agarre cerrado sobre mancuernas","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Comienza en posición de flexión con las manos juntas, directamente debajo de los hombros.","Sostén una mancuerna en cada mano, apoyándolas en el suelo.","Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.","Empuja con las palmas para extender los brazos y regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0660-KZXAtKQ.jpg","gif":"0660-KZXAtKQ.gif"},{"id":"0661","n":"Flexión con patada interior","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos.","Baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta y el core activado.","Al empujar de vuelta hacia arriba, levanta una pierna del suelo y lánzala hacia el lado, manteniéndola recta.","Baja la pierna de nuevo y repite la flexión, luego cambia a la otra pierna.","Continúa alternando las patadas de pierna en cada repetición de la flexión."],"img":"0661-0br45wL.jpg","gif":"0661-0br45wL.gif"},{"id":"0663","n":"Flexión sobre balón medicinal","bp":"chest","eq":"medicine ball","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Comienza en una posición de plancha alta con las manos sobre el balón medicinal, separadas a la altura de los hombros.","Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta.","Empuja con las palmas para extender los brazos y regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0663-W8KAlkI.jpg","gif":"0663-W8KAlkI.gif"},{"id":"1467","n":"Flexión sobre antebrazos","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Comienza en posición de plancha con los antebrazos en el suelo y los codos directamente debajo de los hombros.","Activa el core y mantén el cuerpo en línea recta de la cabeza a los pies.","Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo.","Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1467-4Jt8QsQ.jpg","gif":"1467-4Jt8QsQ.gif"},{"id":"3145","n":"Flexión plus","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y el cuerpo en línea recta desde la cabeza hasta los talones.","Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.","Cuando el pecho esté justo por encima del suelo, empuja con las manos para extender los brazos y levantar la parte superior del cuerpo.","En la parte alta del movimiento, separa las escápulas empujando la parte superior de la espalda hacia el techo.","Haz una pausa por un momento y luego invierte el movimiento juntando las escápulas y bajando el cuerpo de nuevo a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3145-pvBMLHA.jpg","gif":"3145-pvBMLHA.gif"},{"id":"0664","n":"Flexión a plancha lateral","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","chest","triceps"],"st":["Comienza en posición de flexión con las manos separadas a la altura de los hombros y el cuerpo en línea recta.","Baja el cuerpo hacia el suelo flexionando los codos, manteniendo el core activado.","Empuja hacia arriba para volver a la posición inicial.","Desplaza el peso hacia la mano izquierda y rota el cuerpo hacia la derecha, elevando el brazo derecho hacia el techo.","Mantén la posición de plancha lateral durante unos segundos y luego vuelve a la posición inicial.","Repite la flexión y la plancha lateral en el lado opuesto.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0664-KhHJ338.jpg","gif":"0664-KhHJ338.gif"},{"id":"3533","n":"Sentadilla búlgara con peso corporal","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Ponte de pie con los pies separados a la altura de los hombros.","Baja el cuerpo flexionando las rodillas y empujando las caderas hacia atrás como si te sentaras en una silla.","Mantén el pecho arriba y la espalda recta.","Baja hasta que los muslos queden paralelos al suelo.","Empuja con los talones para volver a ponerte de pie en la posición inicial.","Repite el número de repeticiones deseado."],"img":"3533-6YUfHPL.jpg","gif":"3533-6YUfHPL.gif"},{"id":"3201","n":"Abdominal parcial","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3201-enxnJcM.jpg","gif":"3201-enxnJcM.gif"},{"id":"3552","n":"Pies rápidos v. 2","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","hamstrings"],"st":["Ponte de pie con los pies separados a la altura de los hombros y los brazos a los costados.","Comienza moviendo los pies rápidamente hacia arriba y hacia abajo, como si estuvieras corriendo en el sitio.","Mantén los movimientos rápidos y ligeros, concentrándote en quedarte sobre la punta de los pies.","Continúa durante el tiempo o el número de repeticiones deseado."],"img":"3552-mweqJin.jpg","gif":"3552-mweqJin.gif"},{"id":"0666","n":"Flexión a una mano con elevación","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos.","Extiende un brazo hacia el lado, paralelo al suelo.","Baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta y el core activado.","Empuja de vuelta a la posición inicial, usando los músculos del pecho para elevar el cuerpo.","Repite con el otro brazo extendido."],"img":"0666-13TpY4H.jpg","gif":"0666-13TpY4H.gif"},{"id":"0668","n":"Puente posterior invertido declinado","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Túmbate boca arriba con los pies planos en el suelo y las rodillas flexionadas.","Coloca los brazos a los lados del cuerpo con las palmas hacia abajo.","Activa los glúteos y los isquiotibiales, y eleva las caderas del suelo hasta que tu cuerpo forme una línea recta desde las rodillas hasta los hombros.","Mantén esta posición durante unos segundos y luego baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0668-UpAlold.jpg","gif":"0668-UpAlold.gif"},{"id":"0669","n":"Estiramiento de deltoides posterior","bp":"shoulders","eq":"body weight","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.","Extiende el brazo derecho a través del pecho, colocando la mano izquierda sobre el codo derecho.","Tira suavemente del brazo derecho hacia el hombro izquierdo, sintiendo un estiramiento en el hombro derecho.","Mantén el estiramiento durante 15-30 segundos, luego suelta.","Repite del otro lado."],"img":"0669-xifhB5W.jpg","gif":"0669-xifhB5W.gif"},{"id":"0670","n":"Dominada tras nuca","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros.","Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.","Activa los músculos de la espalda y tira de tu cuerpo hacia arriba, hacia la barra, manteniendo los codos cerca del cuerpo.","Continúa subiendo hasta que la barbilla quede por encima de la barra.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0670-CbFSYC1.jpg","gif":"0670-CbFSYC1.gif"},{"id":"1582","n":"Postura del dedo gordo del pie reclinada con cuerda","bp":"upper legs","eq":"rope","tg":"hamstrings","mg":"calves","sm":["calves","glutes"],"st":["Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.","Enrolla la cuerda alrededor de la planta del pie derecho y sujeta los extremos de la cuerda con las manos.","Eleva lentamente la pierna derecha hacia el pecho, manteniendo la rodilla recta y el pie flexionado.","Mantén el estiramiento durante unos segundos y luego baja lentamente la pierna de vuelta a la posición inicial.","Repite con la pierna izquierda.","Continúa alternando las piernas durante el número de repeticiones deseado."],"img":"1582-K5xgdvI.jpg","gif":"1582-K5xgdvI.gif"},{"id":"3236","n":"Empuje de cadera de rodillas con banda de resistencia (mujer)","bp":"upper legs","eq":"resistance band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Comienza arrodillándote en el suelo con las rodillas separadas a la altura de las caderas y los pies flexionados.","Envuelve la banda elástica alrededor de los muslos, justo por encima de las rodillas.","Coloca las manos en las caderas o extiéndelas frente a ti para mantener el equilibrio.","Activa los glúteos y los músculos del core.","Empuja las caderas hacia adelante y aprieta los glúteos mientras levantas las rodillas del suelo, extendiendo las caderas hasta que los muslos queden paralelos al suelo.","Mantén la posición por un momento y luego baja lentamente las rodillas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3236-Pjbc0Kt.jpg","gif":"3236-Pjbc0Kt.gif"},{"id":"3007","n":"Extensión de piernas con banda de resistencia","bp":"upper legs","eq":"resistance band","tg":"quads","mg":"hamstrings","sm":["hamstrings"],"st":["Sujeta la banda elástica a un punto de anclaje firme y asegúrala alrededor de tu tobillo.","Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.","Manteniendo el core activado y la parte superior del cuerpo estable, extiende la pierna recta frente a ti.","Haz una pausa por un momento en la parte alta y luego vuelve lentamente la pierna a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."],"img":"3007-Y1MsI1l.jpg","gif":"3007-Y1MsI1l.gif"},{"id":"3123","n":"Curl de bíceps sentado con banda de resistencia","bp":"upper arms","eq":"resistance band","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo.","Sostén la banda elástica con un agarre supino, con las palmas hacia arriba y los brazos extendidos a los lados del cuerpo.","Manteniendo la parte superior de los brazos inmóvil, exhala y flexiona la banda elástica hacia los hombros.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente la banda elástica de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3123-XFc3vpY.jpg","gif":"3123-XFc3vpY.gif"},{"id":"3124","n":"Press de pecho sentado con banda de resistencia","bp":"chest","eq":"resistance band","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo.","Sostén las asas de la banda elástica en cada mano, con las palmas hacia abajo y los codos flexionados en un ángulo de 90 grados.","Extiende los brazos hacia adelante, alejando la banda elástica de tu pecho.","Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3124-4x5Okof.jpg","gif":"3124-4x5Okof.gif"},{"id":"3006","n":"Abducción de cadera sentada con banda de resistencia","bp":"upper legs","eq":"resistance band","tg":"abductors","mg":"glutes","sm":["glutes","hamstrings"],"st":["Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo.","Envuelve la banda elástica alrededor de los muslos, justo por encima de las rodillas.","Coloca las manos en los lados de la silla o el banco para mayor apoyo.","Activa los abductores (los músculos externos del muslo) y empuja lentamente las rodillas hacia afuera, contra la resistencia de la banda.","Haz una pausa al final del movimiento y luego junta lentamente las rodillas de nuevo.","Repite el número de repeticiones deseado."],"img":"3006-0xDpB4L.jpg","gif":"3006-0xDpB4L.gif"},{"id":"3122","n":"Press de hombros sentado con banda de resistencia","bp":"shoulders","eq":"resistance band","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo.","Sostén la banda elástica con ambas manos, con las palmas hacia adelante, y elévala hasta la altura de los hombros.","Empuja la banda por encima de la cabeza, extendiendo completamente los brazos.","Haz una pausa por un momento en la parte alta y luego baja lentamente la banda hasta la altura de los hombros.","Repite el número de repeticiones deseado."],"img":"3122-S93zLTG.jpg","gif":"3122-S93zLTG.gif"},{"id":"3144","n":"Remo sentado con espalda recta y banda de resistencia","bp":"back","eq":"resistance band","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Siéntate en el suelo con las piernas extendidas y enrolla la banda elástica alrededor de los pies.","Sostén los extremos de la banda elástica con las manos, con las palmas enfrentadas.","Mantén la espalda recta e inclínate ligeramente hacia atrás, activando el core.","Tira de la banda elástica hacia el pecho, juntando las escápulas.","Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3144-Nu7jqFE.jpg","gif":"3144-Nu7jqFE.gif"},{"id":"0872","n":"Crunch inverso","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Túmbate boca arriba con los brazos extendidos a los lados del cuerpo.","Flexiona las rodillas y levanta los pies del suelo, llevando los muslos perpendiculares al suelo.","Contrae el abdomen y eleva las caderas del suelo, llevando las rodillas hacia el pecho.","Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0872-nCU1Ekp.jpg","gif":"0872-nCU1Ekp.gif"},{"id":"0672","n":"Fondos invertidos","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Colócate entre dos barras paralelas con los brazos completamente extendidos y el cuerpo recto.","Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.","Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.","Repite el número de repeticiones deseado."],"img":"0672-NZ5Qqkz.jpg","gif":"0672-NZ5Qqkz.gif"},{"id":"0673","n":"Jalón al pecho en máquina con agarre invertido","bp":"back","eq":"leverage machine","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Ajusta la altura del asiento y colócate en la máquina con las rodillas debajo de las almohadillas y los pies planos en el suelo.","Sujeta las asas con un agarre supino, un poco más separadas que la altura de los hombros.","Siéntate erguido con el pecho hacia afuera y los hombros hacia atrás, manteniendo un ligero arco en la zona lumbar.","Tira de las asas hacia el pecho, juntando las escápulas.","Haz una pausa breve en la parte baja del movimiento, luego suelta lentamente las asas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0673-ecpY0rH.jpg","gif":"0673-ecpY0rH.gif"},{"id":"0674","n":"Dominada con agarre supino","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Agarra la barra de dominadas con un agarre supino, con las manos separadas a la altura de los hombros.","Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.","Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, llevando el pecho por delante.","Continúa subiendo hasta que la barbilla quede por encima de la barra.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0674-YAk5dIw.jpg","gif":"0674-YAk5dIw.gif"},{"id":"0675","n":"Hiperextensión inversa (en balón de estabilidad)","bp":"upper legs","eq":"stability ball","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Túmbate boca abajo sobre un balón de estabilidad con las caderas apoyadas en el balón y las piernas extendidas rectas detrás de ti.","Coloca las manos en el suelo frente a ti para mayor estabilidad.","Activando los glúteos y los isquiotibiales, eleva las piernas hacia el techo tan alto como puedas.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0675-vM5YS2g.jpg","gif":"0675-vM5YS2g.gif"},{"id":"1423","n":"Hiperextensión inversa en banco plano","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Túmbate boca abajo en un banco plano con las caderas en el borde y las piernas colgando del banco.","Sujétate del banco para mantener la estabilidad.","Manteniendo las piernas rectas, elévalas hacia el techo tan alto como puedas.","Aprieta los glúteos en la parte alta del movimiento.","Baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1423-OrETs32.jpg","gif":"1423-OrETs32.gif"},{"id":"3663","n":"Plancha invertida con elevación de pierna","bp":"waist","eq":"body weight","tg":"abs","mg":"glutes","sm":["glutes","hamstrings","shoulders"],"st":["Siéntate en el suelo con las piernas extendidas frente a ti y las manos apoyadas en el suelo detrás de ti, con los dedos apuntando hacia los pies.","Presiona con las manos y levanta las caderas del suelo, llegando a una posición de plancha inversa.","Activa el core y levanta una pierna del suelo, extendiéndola recta hacia el techo.","Mantén la posición por un momento y luego baja la pierna de nuevo.","Repite con la otra pierna.","Continúa alternando las piernas durante el número de repeticiones deseado."],"img":"3663-tFToB7l.jpg","gif":"3663-tFToB7l.gif"},{"id":"0677","n":"Fondos en anillas","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Comienza colgándote de las anillas con los brazos completamente extendidos y el cuerpo recto.","Baja el cuerpo flexionando los codos hasta que los hombros queden por debajo de los codos.","Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."],"img":"0677-ezTvXcr.jpg","gif":"0677-ezTvXcr.gif"},{"id":"2571","n":"Estiramiento de la rana con balanceo","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Comienza arrodillándote en el suelo con las rodillas separadas a la altura de las caderas.","Coloca las manos en el suelo frente a ti para mayor apoyo.","Inclínate lentamente hacia adelante, desplazando el peso hacia las manos y extendiendo las piernas detrás de ti.","Mantén la espalda recta y activa los glúteos mientras empujas las caderas hacia atrás y hacia arriba en dirección al techo.","Mantén esta posición durante unos segundos, sintiendo un estiramiento en los glúteos.","Vuelve lentamente a la posición inicial flexionando las rodillas y bajando las caderas de nuevo.","Repite el número de repeticiones deseado."],"img":"2571-2Dk4xQV.jpg","gif":"2571-2Dk4xQV.gif"},{"id":"0678","n":"Dominada Rocky con jalón","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Ponte de pie frente a una barra de dominadas con los pies separados a la altura de los hombros.","Estira los brazos hacia arriba y agarra la barra con agarre prono, ligeramente más ancho que la altura de los hombros.","Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.","Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, llevando el pecho por delante.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0678-cQ19bBP.jpg","gif":"0678-cQ19bBP.gif"},{"id":"2208","n":"Estiramiento de espalda con rodillo de espuma","bp":"back","eq":"roller","tg":"spine","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Comienza sentándote en el suelo con las piernas extendidas frente a ti.","Coloca el rodillo perpendicular a tu cuerpo, justo debajo de los glúteos.","Rueda lentamente el cuerpo hacia atrás, dejando que el rodillo se desplace hacia arriba por tu espalda.","Continúa rodando hasta que el rodillo llegue a la parte superior de tu espalda.","Haz una pausa por un momento y luego rueda lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2208-isofgzg.jpg","gif":"2208-isofgzg.gif"},{"id":"2204","n":"Sierra corporal con rodillo de espuma","bp":"waist","eq":"roller","tg":"abs","mg":"shoulders","sm":["shoulders","triceps","core"],"st":["Comienza en posición de plancha con los antebrazos sobre el rodillo y el cuerpo en línea recta.","Activa el core y rueda lentamente el rodillo hacia adelante, extendiendo el cuerpo tanto como puedas mientras mantienes el control.","Haz una pausa por un momento en el punto más lejano y luego rueda lentamente el rodillo de vuelta hacia tu posición inicial.","Repite el número de repeticiones deseado."],"img":"2204-XeMvLgE.jpg","gif":"2204-XeMvLgE.gif"},{"id":"2205","n":"Estiramiento de dorsal y cadera con rodillo de espuma","bp":"upper legs","eq":"roller","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Comienza arrodillándote en el suelo con el rodillo colocado debajo de las caderas.","Coloca las manos sobre el rodillo para mayor apoyo.","Rueda lentamente el rodillo hacia adelante, extendiendo las caderas y estirando los glúteos.","Mantén el estiramiento durante unos segundos, luego regresa a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2205-0L2KwtI.jpg","gif":"2205-0L2KwtI.gif"},{"id":"2202","n":"Estiramiento de cadera con rodillo de espuma","bp":"upper legs","eq":"roller","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Comienza sentándote en el suelo con las piernas extendidas frente a ti.","Coloca el rodillo debajo de los glúteos, justo por encima de las rodillas.","Inclínate hacia atrás y coloca las manos en el suelo detrás de ti para apoyarte.","Activa los glúteos y rueda lentamente el rodillo hacia adelante, flexionando las rodillas y llevándolas hacia el pecho.","Haz una pausa al final del movimiento, sintiendo un estiramiento en los glúteos.","Rueda lentamente el rodillo de vuelta a la posición inicial, extendiendo las piernas.","Repite el número de repeticiones deseado."],"img":"2202-oMypNrz.jpg","gif":"2202-oMypNrz.gif"},{"id":"2206","n":"Crunch invertido con rodillo de espuma","bp":"waist","eq":"roller","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Túmbate boca arriba con los brazos extendidos rectos por encima de la cabeza y las piernas rectas frente a ti.","Coloca el rodillo entre los pies y sujétalo con los dedos de los pies.","Activando el abdomen, levanta las piernas del suelo y flexiona las rodillas hacia el pecho, rodando el rodillo hacia tu cuerpo.","Haz una pausa por un momento en la parte alta y luego baja lentamente las piernas de vuelta a la posición inicial, rodando el rodillo alejándolo de tu cuerpo.","Repite el número de repeticiones deseado."],"img":"2206-SKXQAx3.jpg","gif":"2206-SKXQAx3.gif"},{"id":"2203","n":"Flexión, depresión y retracción de hombros sentado con rodillo de espuma","bp":"chest","eq":"roller","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Siéntate sobre una superficie plana con las piernas extendidas frente a ti.","Sostén el rodillo con ambas manos, con las palmas hacia abajo, y colócalo sobre tus muslos.","Inclínate ligeramente hacia delante y aleja el rodillo de tu cuerpo, extendiendo los brazos rectos frente a ti.","Haz una pausa por un momento, luego rueda el rodillo lentamente de vuelta hacia tu cuerpo, doblando los brazos y trayéndolo de nuevo hacia los muslos.","Repite el número de repeticiones deseado."],"img":"2203-8coXSYU.jpg","gif":"2203-8coXSYU.gif"},{"id":"2209","n":"Flexión, depresión y retracción de hombros sentado a una pierna con rodillo de espuma","bp":"chest","eq":"roller","tg":"pectorals","mg":"deltoids","sm":["deltoids","triceps"],"st":["Siéntate sobre una superficie plana con las piernas extendidas frente a ti.","Sostén el rodillo con ambas manos, con las palmas hacia abajo, y colócalo sobre tus muslos.","Inclínate ligeramente hacia atrás y contrae los músculos del core.","Eleva el rodillo hasta la altura de los hombros, manteniendo los brazos rectos.","Baja lentamente el rodillo de nuevo hacia los muslos.","Repite el número de repeticiones deseado."],"img":"2209-CjETvlw.jpg","gif":"2209-CjETvlw.gif"},{"id":"2207","n":"Estiramiento lateral de dorsal con rodillo de espuma","bp":"back","eq":"roller","tg":"lats","mg":"shoulders","sm":["shoulders","triceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta el rodillo con ambas manos frente al cuerpo.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Extiende los brazos hacia delante y rueda el rodillo hacia los pies, sintiendo un estiramiento en los dorsales.","Mantén el estiramiento durante unos segundos, luego rueda el rodillo lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2207-c3Pfhti.jpg","gif":"2207-c3Pfhti.gif"},{"id":"0680","n":"Escalada de cuerda","bp":"back","eq":"rope","tg":"upper back","mg":"forearms","sm":["forearms","biceps","shoulders"],"st":["Ponte de pie frente a la cuerda con los pies separados a la altura de los hombros.","Sujeta la cuerda con ambas manos, con las palmas mirando hacia ti.","Flexiona ligeramente las rodillas y activa el core.","Comienza a subir por la cuerda alternando los movimientos de las manos.","Usa las piernas para ayudar en el movimiento ascendente.","Continúa trepando hasta alcanzar la altura deseada o la parte superior de la cuerda.","Para descender, invierte el movimiento alterno de las manos mientras controlas tu descenso.","Repite el número de repeticiones deseado."],"img":"0680-yaAxcQr.jpg","gif":"0680-yaAxcQr.gif"},{"id":"0685","n":"Carrera continua","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Comienza de pie con los pies separados a la altura de la cadera.","Activa el core y mantén la parte superior del cuerpo relajada.","Comienza a trotar en el lugar, levantando las rodillas hacia el pecho y aterrizando suavemente sobre la punta de los pies.","Mantén un ritmo constante y continúa trotando durante la duración o distancia deseada.","Recuerda respirar profundamente y mantener una buena postura durante todo el ejercicio."],"img":"0685-oLrKqDH.jpg","gif":"0685-oLrKqDH.gif"},{"id":"0684","n":"Carrera (con equipamiento)","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Comienza de pie con los pies separados a la altura de la cadera.","Activa el core y mantén la parte superior del cuerpo relajada.","Comienza a trotar en el lugar, levantando las rodillas hacia el pecho y aterrizando suavemente sobre la punta de los pies.","Mantén un ritmo constante y continúa trotando durante la duración o distancia deseada.","Recuerda respirar profundamente y mantener una buena postura durante todo el ejercicio."],"img":"0684-y5p0H8a.jpg","gif":"0684-y5p0H8a.gif"},{"id":"1585","n":"Estiramiento del corredor","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","quadriceps"],"st":["Ponte de pie con los pies separados a la altura de la cadera.","Da un paso hacia delante con el pie derecho, manteniendo el pie izquierdo firme en el suelo.","Dobla la rodilla derecha y baja el cuerpo, manteniendo la pierna izquierda recta.","Coloca las manos sobre el muslo derecho para apoyarte.","Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite."],"img":"1585-0mB6wHO.jpg","gif":"1585-0mB6wHO.gif"},{"id":"0687","n":"Giro ruso","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Siéntate en el suelo con las rodillas flexionadas y los pies apoyados en el suelo.","Inclínate ligeramente hacia atrás manteniendo la espalda recta y el core activado.","Junta las manos frente al pecho o sujeta una pesa si lo deseas.","Levanta los pies del suelo, equilibrándote sobre los isquiones.","Gira el torso hacia la derecha, llevando las manos o la pesa hacia el lado derecho del cuerpo.","Haz una pausa por un momento, luego gira el torso hacia la izquierda, llevando las manos o la pesa hacia el lado izquierdo del cuerpo.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0687-XVDdcoj.jpg","gif":"0687-XVDdcoj.gif"},{"id":"3012","n":"Fondos escapulares","bp":"back","eq":"body weight","tg":"traps","mg":"rhomboids","sm":["rhomboids","deltoids"],"st":["Comienza de pie con los pies separados a la altura de los hombros y los brazos extendidos frente a ti.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Baja el cuerpo doblando los codos y retrayendo las escápulas, como si intentaras apretar un lápiz entre ellas.","Haz una pausa por un momento en la posición baja, luego empuja con las manos para extender los codos y volver a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3012-7xeukSt.jpg","gif":"3012-7xeukSt.gif"},{"id":"3021","n":"Flexiones escapulares","bp":"chest","eq":"body weight","tg":"serratus anterior","mg":"triceps","sm":["triceps","shoulders"],"st":["Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta.","Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo.","A medida que bajas, junta las escápulas y empuja el pecho hacia delante.","Haz una pausa por un momento en la posición baja, luego empuja de nuevo hacia arriba hasta la posición inicial.","Repite el número de repeticiones deseado."],"img":"3021-jV65tKx.jpg","gif":"3021-jV65tKx.gif"},{"id":"0688","n":"Dominadas escapulares","bp":"back","eq":"body weight","tg":"traps","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Comienza colgándote de una barra de dominadas con las palmas hacia afuera y los brazos completamente extendidos.","Retrae las escápulas llevándolas hacia abajo y atrás.","Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, enfocándote en juntar las escápulas.","Haz una pausa breve en la parte superior del movimiento, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0688-uTBt1HV.jpg","gif":"0688-uTBt1HV.gif"},{"id":"3219","n":"Saltos de tijera (hombre)","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros.","Salta del suelo y al mismo tiempo cruza la pierna derecha por delante de la pierna izquierda.","Al aterrizar, cambia rápidamente de pierna, cruzando la pierna izquierda por delante de la pierna derecha.","Continúa alternando las piernas y saltando lo más rápido posible.","Repite el número de repeticiones deseado."],"img":"3219-Eh2v5Iu.jpg","gif":"3219-Eh2v5Iu.gif"},{"id":"1390","n":"Estiramiento de gemelos sentado (hombre)","bp":"lower legs","eq":"body weight","tg":"calves","mg":"hamstrings","sm":["hamstrings"],"st":["Siéntate en el borde de una silla o banco con los pies planos sobre el suelo.","Extiende una pierna recta frente a ti, manteniendo el talón en el suelo.","Inclínate ligeramente hacia delante, sintiendo un estiramiento en la pantorrilla.","Mantén el estiramiento durante 20-30 segundos.","Cambia de pierna y repite el estiramiento."],"img":"1390-17bqEXD.jpg","gif":"1390-17bqEXD.gif"},{"id":"1424","n":"Estiramiento de glúteos sentado","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings"],"st":["Siéntate en el suelo con las piernas extendidas frente a ti.","Dobla la rodilla derecha y cruza el tobillo derecho sobre el muslo izquierdo.","Coloca la mano derecha en el suelo detrás de ti para apoyarte.","Con la mano izquierda, presiona suavemente la rodilla derecha para profundizar el estiramiento.","Mantén el estiramiento durante 30 segundos a 1 minuto.","Cambia de lado y repite."],"img":"1424-DeDThfG.jpg","gif":"1424-DeDThfG.gif"},{"id":"0689","n":"Elevación de piernas sentado","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Siéntate en un banco plano con la espalda recta y los pies planos sobre el suelo.","Coloca las manos a los lados del banco para apoyarte.","Manteniendo las piernas rectas, levántalas lentamente frente a ti hasta que queden paralelas al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0689-Hgs6Nl1.jpg","gif":"0689-Hgs6Nl1.gif"},{"id":"0690","n":"Estiramiento lumbar sentado","bp":"back","eq":"body weight","tg":"lats","mg":"glutes","sm":["glutes","hamstrings"],"st":["Siéntate en el borde de una silla con los pies planos sobre el suelo.","Coloca las manos sobre los muslos o a los lados de la silla para apoyarte.","Inclínate lentamente hacia delante desde la cadera, manteniendo la espalda recta.","Siente el estiramiento en la zona lumbar y mantén la posición durante 20-30 segundos.","Regresa lentamente a la posición inicial y repite el número de repeticiones deseado."],"img":"0690-QFmz6ch.jpg","gif":"0690-QFmz6ch.gif"},{"id":"2567","n":"Estiramiento del piramidal sentado","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings"],"st":["Siéntate en el suelo con las piernas extendidas frente a ti.","Dobla la rodilla derecha y coloca el pie derecho en la parte exterior de la rodilla izquierda.","Coloca el codo izquierdo en la parte exterior de la rodilla derecha y gira suavemente el torso hacia la derecha.","Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite."],"img":"2567-QY39eBr.jpg","gif":"2567-QY39eBr.gif"},{"id":"0691","n":"Crunch lateral sentado (en pared)","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Siéntate en el suelo con la espalda contra una pared y las piernas extendidas frente a ti.","Dobla las rodillas y coloca los pies planos sobre el suelo, separados a la altura de la cadera.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Contrae el abdomen e inclínate hacia un lado, llevando el codo hacia la cadera.","Haz una pausa breve y luego vuelve a la posición inicial.","Repite del otro lado.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0691-Y9hNPcN.jpg","gif":"0691-Y9hNPcN.gif"},{"id":"1587","n":"Secuencia de postura sentada en ángulo abierto","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"quadriceps","sm":["quadriceps","calves"],"st":["Siéntate en el suelo con las piernas extendidas formando un ángulo amplio.","Flexiona los pies y contrae los cuádriceps.","Coloca las manos en el suelo detrás de ti para apoyarte.","Manteniendo la espalda recta, inclínate hacia delante desde la cadera.","Continúa inclinándote hacia delante hasta sentir un estiramiento en los isquiotibiales.","Mantén esta posición durante unas cuantas respiraciones.","Libera lentamente el estiramiento y vuelve a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1587-HIgYKAB.jpg","gif":"1587-HIgYKAB.gif"},{"id":"0697","n":"Curl de piernas invertido autoasistido en máquina nórdica","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","calves"],"st":["Túmbate boca arriba sobre una esterilla o banco con las piernas extendidas.","Coloca las manos a los lados o debajo de los glúteos para apoyarte.","Dobla las rodillas y levanta los pies del suelo, llevando los muslos hacia el pecho.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0697-GwYwElT.jpg","gif":"0697-GwYwElT.gif"},{"id":"1766","n":"Curl de piernas invertido autoasistido sujeto en banco","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","calves"],"st":["Túmbate boca abajo en una máquina de curl femoral con las piernas extendidas y los tobillos enganchados bajo la palanca acolchada.","Coloca las manos en las asas laterales de la máquina para apoyarte.","Manteniendo la parte superior del cuerpo inmóvil, exhala y flexiona las piernas hacia arriba lo más posible.","Mantén la posición contraída durante una pausa breve mientras aprietas los isquiotibiales.","Baja lentamente las piernas de vuelta a la posición inicial mientras inhalas.","Repite el número de repeticiones deseado."],"img":"1766-ZSY3MsL.jpg","gif":"1766-ZSY3MsL.gif"},{"id":"0696","n":"Curl de piernas invertido autoasistido (en suelo)","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","calves"],"st":["Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.","Dobla las rodillas y coloca los pies planos sobre el suelo, separados a la altura de la cadera.","Levanta las caderas del suelo, activando los glúteos y los isquiotibiales.","Flexiona lentamente las piernas hacia los glúteos, manteniendo las caderas elevadas.","Haz una pausa breve en la parte superior, luego extiende lentamente las piernas de vuelta a la posición inicial.","Baja las caderas de nuevo hacia el suelo.","Repite el número de repeticiones deseado."],"img":"0696-E4PwJqI.jpg","gif":"0696-E4PwJqI.gif"},{"id":"3222","n":"Salto en media sentadilla (hombre)","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros.","Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla.","Salta de forma explosiva, extendiendo las caderas y las rodillas mientras balanceas los brazos para generar impulso.","Aterriza suavemente sobre la punta de los pies y pasa de inmediato a la siguiente repetición.","Repite el número de repeticiones deseado."],"img":"3222-6FMU51h.jpg","gif":"3222-6FMU51h.gif"},{"id":"3656","n":"Carrera con zancada corta","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Busca un espacio abierto o una cinta de correr para realizar el ejercicio.","Ponte de pie con los pies separados a la altura de la cadera.","Comienza a trotar en el lugar, levantando las rodillas alto y moviendo los brazos.","Después de unos segundos, comienza a dar pasos cortos hacia delante, manteniendo un ritmo rápido.","Continúa corriendo con pasos cortos durante la duración o distancia deseada."],"img":"3656-CcWEoWV.jpg","gif":"3656-CcWEoWV.gif"},{"id":"1763","n":"Dominada con agarre al ancho de hombros","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Sujeta la barra de dominadas con un agarre a la altura de los hombros, con las palmas mirando hacia fuera.","Cuélgate libremente con los brazos completamente extendidos.","Activa los músculos de la espalda y tira de tu cuerpo hacia la barra hasta que la barbilla quede por encima de ella.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1763-YtgD7Xq.jpg","gif":"1763-YtgD7Xq.gif"},{"id":"3699","n":"Toque de hombros en plancha","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","triceps"],"st":["Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta.","Activa el core y levanta la mano derecha del suelo, extendiéndola para tocar el hombro izquierdo.","Coloca la mano derecha de nuevo en el suelo y repite tocando el hombro derecho con la mano izquierda.","Continúa alternando los toques de hombro mientras mantienes las caderas y el torso estables.","Repite el número de repeticiones deseado."],"img":"3699-yRpV5TC.jpg","gif":"3699-yRpV5TC.gif"},{"id":"0699","n":"Flexión con toque de hombros","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","core"],"st":["Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y el cuerpo en línea recta desde la cabeza hasta los talones.","Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.","Mientras empujas hacia arriba, levanta la mano derecha del suelo y toca el hombro izquierdo.","Vuelve a colocar la mano derecha en el suelo y repite la flexión, esta vez levantando la mano izquierda y tocando el hombro derecho.","Continúa alternando los toques de hombro en cada repetición de la flexión.","Mantén el core estable y evita una rotación excesiva de la cadera durante todo el ejercicio.","Repite el número de repeticiones deseado."],"img":"0699-qEse6fe.jpg","gif":"0699-qEse6fe.gif"},{"id":"1774","n":"Abducción de cadera en puente lateral","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","obliques"],"st":["Túmbate de lado con las piernas extendidas y una sobre la otra.","Apóyate sobre el antebrazo, manteniendo el codo directamente debajo del hombro.","Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies.","Manteniendo el core activado, levanta la pierna superior lo más alto posible sin rotar las caderas.","Haz una pausa por un momento en la posición alta, luego baja la pierna de nuevo.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"1774-WL4EmxJ.jpg","gif":"1774-WL4EmxJ.gif"},{"id":"0705","n":"Puente lateral v. 2","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","glutes"],"st":["Túmbate de lado con las piernas extendidas y una sobre la otra.","Coloca el antebrazo en el suelo justo debajo del hombro, con el codo flexionado en un ángulo de 90 grados.","Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies.","Mantén esta posición durante el tiempo deseado.","Baja las caderas de vuelta a la posición inicial.","Repite del otro lado."],"img":"0705-RKjH6Lt.jpg","gif":"0705-RKjH6Lt.gif"},{"id":"0709","n":"Elevación lateral de cadera (en barras paralelas)","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Ponte de pie entre dos barras paralelas con los pies separados a la altura de los hombros.","Coloca las manos sobre las barras y levanta el cuerpo del suelo, apoyando tu peso en los brazos.","Contrae el abdomen y levanta lentamente las piernas hacia el lado, manteniéndolas rectas.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0709-jTkSc6o.jpg","gif":"0709-jTkSc6o.gif"},{"id":"0710","n":"Abducción lateral de cadera","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","quadriceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las manos en las caderas.","Traslada el peso a una pierna y levanta la pierna opuesta hacia el lado, manteniéndola recta.","Haz una pausa por un momento en la posición alta, luego baja lentamente la pierna de nuevo a la posición inicial.","Repite del otro lado.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0710-7WaDzyL.jpg","gif":"0710-7WaDzyL.gif"},{"id":"1358","n":"Estiramiento en el suelo en decúbito lateral","bp":"back","eq":"body weight","tg":"lats","mg":"obliques","sm":["obliques","glutes"],"st":["Túmbate de lado con las piernas rectas y el brazo de abajo extendido recto por encima de la cabeza.","Dobla la rodilla de arriba y coloca el pie en el suelo frente a la pierna de abajo.","Extiende el brazo de arriba por encima de la cabeza y agárrate a algo estable, como una pared o un mueble.","Levanta lentamente la pierna de abajo del suelo, manteniéndola recta, hasta sentir un estiramiento en el costado.","Mantén el estiramiento durante 20-30 segundos, luego baja lentamente la pierna de nuevo.","Repite del otro lado."],"img":"1358-jDOKRM5.jpg","gif":"1358-jDOKRM5.gif"},{"id":"3667","n":"Aducción de cadera tumbado de lado (hombre)","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"glutes","sm":["glutes","hamstrings"],"st":["Túmbate de lado con las piernas rectas y apiladas una sobre la otra.","Coloca el brazo de abajo bajo la cabeza para apoyarte.","Activa los aductores y levanta la pierna de arriba lo más alto posible sin rotar las caderas ni inclinarte hacia atrás.","Haz una pausa por un momento en la posición alta, luego baja lentamente la pierna de nuevo a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"3667-c8f5cSY.jpg","gif":"3667-c8f5cSY.gif"},{"id":"1775","n":"Aducción de cadera en plancha lateral","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"obliques","sm":["obliques","glutes"],"st":["Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra.","Apóyate sobre el antebrazo, manteniendo el codo directamente debajo del hombro.","Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies.","Manteniendo la posición de plancha lateral, levanta la pierna de arriba hacia el techo, manteniéndola recta.","Baja lentamente la pierna de nuevo a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"1775-VO2qeJg.jpg","gif":"1775-VO2qeJg.gif"},{"id":"0716","n":"Estiramiento de cuello con empuje lateral","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"trapezius","sm":["trapezius","sternocleidomastoid"],"st":["Ponte de pie o siéntate erguido con los hombros relajados.","Inclina la cabeza hacia la derecha, llevando la oreja derecha hacia el hombro derecho.","Coloca la mano derecha en el lado izquierdo de la cabeza y aplica una presión suave para aumentar el estiramiento.","Mantén el estiramiento durante 15-30 segundos.","Repite hacia el otro lado, inclinando la cabeza hacia la izquierda y aplicando presión con la mano izquierda.","Repite el estiramiento 2-3 veces en cada lado."],"img":"0716-oQRJYkC.jpg","gif":"0716-oQRJYkC.gif"},{"id":"0717","n":"Flexión lateral","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders","chest","core"],"st":["Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra.","Coloca la mano de abajo en el suelo directamente debajo del hombro, con los dedos apuntando hacia delante.","Empuja con la mano de abajo para levantar el cuerpo del suelo, manteniendo las piernas rectas y el core activado.","Extiende el brazo de arriba recto hacia el techo, formando una línea recta desde la cabeza hasta los talones.","Baja el cuerpo de nuevo a la posición inicial con control.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"0717-wpbD28t.jpg","gif":"0717-wpbD28t.gif"},{"id":"0721","n":"Estiramiento lateral tirando de la muñeca","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrists","sm":["wrists","hands"],"st":["Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos frente a ti.","Extiende el brazo derecho hacia el lado, paralelo al suelo, con la palma hacia abajo.","Con la mano izquierda, sujeta la mano derecha y tira de ella suavemente hacia tu cuerpo, sintiendo un estiramiento en el antebrazo derecho.","Mantén el estiramiento durante 15-30 segundos, luego suelta.","Repite del otro lado."],"img":"0721-UtmIqcI.jpg","gif":"0721-UtmIqcI.gif"},{"id":"0720","n":"Dominaciones supinas de lado a lado","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta una barra de dominadas con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.","Cuélgate de la barra con los brazos completamente extendidos y el cuerpo relajado.","Levántate doblando los codos y llevando la barbilla hacia la barra, manteniendo el cuerpo recto.","Una vez que la barbilla esté por encima de la barra, bájate de nuevo a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0720-isAAZWA.jpg","gif":"0720-isAAZWA.gif"},{"id":"3213","n":"Toque de puntas alterno de lado a lado (hombre)","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados.","Dobla la cintura hacia la derecha, llevando la mano derecha hacia el pie derecho mientras mantienes la mano izquierda extendida hacia el lado.","Vuelve a la posición inicial y luego dobla la cintura hacia la izquierda, llevando la mano izquierda hacia el pie izquierdo mientras mantienes la mano derecha extendida hacia el lado.","Repite el movimiento de flexión lateral el número de repeticiones deseado."],"img":"3213-WCAvOfC.jpg","gif":"3213-WCAvOfC.gif"},{"id":"0725","n":"Flexión a una mano","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Comienza en posición de flexión con las manos separadas a la altura de los hombros y una mano colocada un poco más ancha que la otra.","Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta.","Al bajar, traslada el peso hacia un lado y levanta el brazo opuesto del suelo, extendiéndolo recto hacia el lado.","Empuja con el pecho y los tríceps para subir el cuerpo de nuevo a la posición inicial, mientras bajas simultáneamente el brazo extendido de vuelta al suelo.","Repite el movimiento, alternando el brazo que extiendes en cada repetición."],"img":"0725-MUic5zN.jpg","gif":"0725-MUic5zN.gif"},{"id":"3645","n":"Puente a una pierna con pierna extendida","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Extiende una pierna recta hacia delante.","Activa los glúteos y levanta las caderas del suelo, formando una línea recta desde las rodillas hasta los hombros.","Mantén la posición alta por un momento, luego baja lentamente las caderas de nuevo a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."],"img":"3645-rmEukuS.jpg","gif":"3645-rmEukuS.gif"},{"id":"0727","n":"Elevación de talones a una pierna (sobre mancuerna)","bp":"lower legs","eq":"dumbbell","tg":"calves","mg":"ankles","sm":["ankles","feet"],"st":["Ponte de pie con los pies separados a la altura de la cadera y sujeta una mancuerna en una mano.","Levanta un pie del suelo y mantén el equilibrio sobre el otro pie.","Eleva lentamente el talón lo más alto posible, usando los músculos de la pantorrilla.","Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta hacia abajo.","Repite el número de repeticiones deseado, luego cambia a la otra pierna."],"img":"0727-fKZgDEO.jpg","gif":"0727-fKZgDEO.gif"},{"id":"0730","n":"Deslizamiento de plataforma a una pierna","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","quadriceps"],"st":["Comienza de pie con un pie sobre una plataforma o tabla deslizante.","Dobla ligeramente la rodilla y desliza el pie sobre la plataforma hacia atrás, extendiendo la pierna.","Mantén el core activado y conserva una postura recta durante todo el movimiento.","Vuelve lentamente a la posición inicial deslizando el pie de regreso a la posición inicial.","Repite el movimiento el número de repeticiones deseado y luego cambia de pierna."],"img":"0730-LNE3wfo.jpg","gif":"0730-LNE3wfo.gif"},{"id":"1759","n":"Sentadilla a una pierna (pistol squat) hombre","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos frente a ti.","Levanta el pie derecho del suelo y extiéndelo hacia delante.","Baja lentamente el cuerpo doblando la rodilla izquierda y empujando las caderas hacia atrás.","Mantén el pecho elevado y la espalda recta mientras bajas el cuerpo.","Baja hasta que el muslo izquierdo quede paralelo al suelo, o lo más abajo que puedas llegar cómodamente.","Haz una pausa por un momento en la posición baja, luego empuja con el talón izquierdo para volver a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."],"img":"1759-nqs5HGV.jpg","gif":"1759-nqs5HGV.gif"},{"id":"1489","n":"Sentadilla sissy","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","glutes"],"st":["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.","Sujétate de un objeto estable para mantener el equilibrio si es necesario.","Baja lentamente el cuerpo doblando las rodillas e inclinándote hacia atrás, manteniendo el torso erguido.","Continúa bajando hasta que los muslos queden paralelos al suelo o tan lejos como puedas llegar cómodamente.","Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1489-xdYPUtE.jpg","gif":"1489-xdYPUtE.gif"},{"id":"0735","n":"Abdominales sit-up v. 2","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0735-Bn6TXyO.jpg","gif":"0735-Bn6TXyO.gif"},{"id":"3679","n":"Abdominales sit-up con brazos en el pecho","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Cruza los brazos sobre el pecho.","Contrayendo el abdomen, levanta la parte superior del cuerpo del suelo hacia las rodillas.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3679-6ZCiYWQ.jpg","gif":"3679-6ZCiYWQ.gif"},{"id":"3361","n":"Saltos del patinador","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","glutes","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros.","Dobla ligeramente las rodillas y salta hacia la derecha, aterrizando sobre el pie derecho.","Al aterrizar, balancea la pierna izquierda detrás de la pierna derecha y toca el suelo con los dedos del pie izquierdo.","Salta inmediatamente hacia la izquierda, aterrizando sobre el pie izquierdo.","Al aterrizar, balancea la pierna derecha detrás de la pierna izquierda y toca el suelo con los dedos del pie derecho.","Continúa alternando los lados, saltando y tocando el suelo con cada pierna.","Repite el número de repeticiones deseado."],"img":"3361-zfNHMN9.jpg","gif":"3361-zfNHMN9.gif"},{"id":"2142","n":"Ergómetro de esquí","bp":"upper arms","eq":"skierg machine","tg":"triceps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Ajusta la altura del asiento y los apoyapiés a una posición cómoda.","Sujeta las agarraderas con un agarre prono, con las palmas hacia abajo.","Siéntate erguido con los pies planos sobre los apoyapiés.","Extiende los brazos rectos frente a ti, manteniendo los codos ligeramente flexionados.","Activa los tríceps y empuja las asas hacia abajo, hacia los muslos.","Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2142-vpQaQkH.jpg","gif":"2142-vpQaQkH.gif"},{"id":"3671","n":"Paso de esquí","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","glutes","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros.","Dobla ligeramente las rodillas y mantén la espalda recta.","Salta hacia la derecha, aterrizando sobre el pie derecho mientras balanceas la pierna izquierda detrás de la pierna derecha.","Salta inmediatamente hacia la izquierda, aterrizando sobre el pie izquierdo mientras balanceas la pierna derecha detrás de la pierna izquierda.","Continúa alternando los saltos de lado a lado, imitando un movimiento de esquí.","Repite el número de repeticiones deseado."],"img":"3671-5MRH8H2.jpg","gif":"3671-5MRH8H2.gif"},{"id":"3304","n":"Skin the cat","bp":"back","eq":"body weight","tg":"upper back","mg":"shoulders","sm":["shoulders","core"],"st":["Comienza colgándote de una barra con los brazos completamente extendidos y el cuerpo relajado.","Activa el core y levanta las piernas, llevando las rodillas hacia el pecho.","Continúa levantando las piernas por encima de la cabeza, permitiendo que el cuerpo pase entre los brazos.","Una vez que las piernas estén completamente extendidas por encima de la cabeza, comienza a bajarlas de nuevo hacia la posición inicial.","Mientras bajas las piernas, permite que el cuerpo pase de nuevo entre los brazos hasta quedar colgado con los brazos completamente extendidos otra vez.","Repite el número de repeticiones deseado."],"img":"3304-MSfvriJ.jpg","gif":"3304-MSfvriJ.gif"},{"id":"1425","n":"Prensa de piernas a 45 grados a una pierna","bp":"upper legs","eq":"sled machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ajusta la máquina de trineo a un ángulo de 45 grados.","Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies sobre la placa.","Coloca un pie sobre la placa y extiende la pierna, empujando el trineo alejándolo de ti.","Dobla lentamente la rodilla y baja el trineo de vuelta a la posición inicial.","Repite con la otra pierna.","Continúa alternando las piernas durante el número de repeticiones deseado."],"img":"1425-WWD6FzI.jpg","gif":"1425-WWD6FzI.gif"},{"id":"0738","n":"Prensa de gemelos a 45°","bp":"lower legs","eq":"sled machine","tg":"calves","mg":"hamstrings","sm":["hamstrings"],"st":["Ajusta la máquina de trineo a un ángulo de 45 grados.","Coloca los pies sobre la plataforma del trineo con los dedos de los pies apuntando hacia delante.","Empuja la plataforma del trineo alejándola de ti extendiendo los tobillos y las pantorrillas.","Haz una pausa por un momento en la posición alta, luego baja lentamente la plataforma del trineo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0738-qCNVnaU.jpg","gif":"0738-qCNVnaU.gif"},{"id":"0739","n":"Prensa de piernas a 45°","bp":"upper legs","eq":"sled machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ajusta el asiento y la placa de la máquina de trineo a una posición cómoda.","Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies separados a la altura de los hombros sobre la placa.","Sujeta las asas a los lados del asiento para mayor estabilidad.","Empuja la placa alejándola de tu cuerpo extendiendo las piernas, manteniendo los talones sobre la placa.","Continúa empujando hasta que las piernas estén casi completamente extendidas, pero sin bloquear las rodillas.","Haz una pausa por un momento en la parte alta del movimiento, luego baja lentamente la placa de vuelta hacia tu cuerpo doblando las rodillas.","Repite el número de repeticiones deseado."],"img":"0739-10Z2DXU.jpg","gif":"0739-10Z2DXU.gif"},{"id":"1464","n":"Prensa de piernas a 45° (vista trasera)","bp":"upper legs","eq":"sled machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ajusta el asiento de la máquina de trineo de modo que las rodillas queden en un ángulo de 45 grados.","Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies separados a la altura de los hombros sobre la placa.","Sujeta las asas a los lados del asiento para mayor estabilidad.","Empuja la placa alejándola de tu cuerpo extendiendo las piernas, manteniendo los talones sobre la placa.","Haz una pausa por un momento en la posición completamente extendida.","Dobla lentamente las rodillas y baja la placa de vuelta hacia tu cuerpo, controlando el movimiento.","Repite el número de repeticiones deseado."],"img":"1464-yn2lLSI.jpg","gif":"1464-yn2lLSI.gif"},{"id":"1463","n":"Prensa de piernas a 45° en máquina de trineo (vista lateral)","bp":"upper legs","eq":"sled machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ajusta el asiento de la máquina de trineo de modo que las rodillas queden en un ángulo de 90 grados cuando los pies estén sobre la placa.","Siéntate en la máquina de trineo con la espalda plana contra el respaldo y los pies separados a la altura de los hombros sobre la placa.","Sujeta las asas a los lados del asiento para mayor estabilidad.","Empuja contra la placa para extender las piernas, estirándolas por completo.","Haz una pausa por un momento en la posición alta, luego dobla lentamente las rodillas para bajar la placa de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1463-2Qh2J1e.jpg","gif":"1463-2Qh2J1e.gif"},{"id":"0740","n":"Prensa de piernas a 45° con pies separados en trineo","bp":"upper legs","eq":"sled machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ajusta la máquina de trineo a un ángulo de 45 grados.","Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies sobre la plataforma.","Coloca los pies más separados que el ancho de los hombros.","Empuja contra la plataforma para extender las piernas y enderezar las rodillas.","Haz una pausa por un momento al final del movimiento, luego dobla lentamente las rodillas para volver a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0740-tj41Nu6.jpg","gif":"0740-tj41Nu6.gif"},{"id":"1391","n":"Prensa de gemelos en máquina de prensa de piernas","bp":"lower legs","eq":"sled machine","tg":"calves","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Ajusta el asiento de la máquina de prensa de piernas de modo que las rodillas queden ligeramente flexionadas cuando los pies estén sobre el trineo.","Coloca los pies separados a la altura de los hombros sobre el trineo, con los dedos de los pies apuntando hacia delante.","Suelta las asas de seguridad y empuja el trineo alejándolo de ti extendiendo las rodillas y los tobillos.","Haz una pausa por un momento en la parte alta del movimiento, luego baja lentamente el trineo doblando las rodillas y los tobillos.","Repite el número de repeticiones deseado."],"img":"1391-ykHcWme.jpg","gif":"1391-ykHcWme.gif"},{"id":"0741","n":"Sentadilla hack con pies juntos en trineo","bp":"upper legs","eq":"sled machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ajusta la máquina de trineo a un peso cómodo y colócate con la espalda contra el respaldo.","Coloca los pies separados a la altura de los hombros sobre la plataforma, con los dedos de los pies ligeramente apuntando hacia fuera.","Sujeta las asas a los lados de la máquina para mayor estabilidad.","Activa el core y baja lentamente el cuerpo doblando las rodillas y las caderas, manteniendo la espalda recta.","Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo.","Haz una pausa por un momento en la posición baja, luego empuja con los talones para extender las piernas y volver a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0741-gf3ZjB9.jpg","gif":"0741-gf3ZjB9.gif"},{"id":"0742","n":"Elevación de gemelos inclinada hacia delante en trineo","bp":"lower legs","eq":"sled machine","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Ajusta la máquina de trineo a un peso cómodo y colócate en la máquina con la punta de los pies sobre la plataforma y los talones colgando.","Coloca las manos en las asas o a los lados de la máquina para apoyarte.","Activa las pantorrillas y eleva lentamente los talones lo más alto posible, empujando contra la resistencia del trineo.","Haz una pausa breve en la parte alta del movimiento, luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0742-XDOiFns.jpg","gif":"0742-XDOiFns.gif"},{"id":"0743","n":"Sentadilla hack en trineo","bp":"upper legs","eq":"sled machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ajusta la máquina de trineo a una posición cómoda según tu altura.","Ponte de pie con los pies separados a la altura de los hombros sobre la plataforma, con los dedos de los pies ligeramente apuntando hacia fuera.","Sujétate de las asas o barras para mayor estabilidad.","Baja el cuerpo doblando las rodillas y las caderas, manteniendo la espalda recta y el pecho elevado.","Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo.","Haz una pausa por un momento, luego empuja con los talones para subir el cuerpo de nuevo a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0743-Qa55kX1.jpg","gif":"0743-Qa55kX1.gif"},{"id":"2334","n":"Prensa de gemelos tumbado en trineo","bp":"lower legs","eq":"sled machine","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Ajusta la máquina de trineo a un peso adecuado.","Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies sobre la plataforma.","Coloca la punta y la almohadilla de los pies en el borde de la plataforma, con los talones colgando.","Empuja la plataforma alejándola de ti extendiendo los tobillos, manteniendo las rodillas ligeramente flexionadas.","Continúa empujando hasta que las pantorrillas estén completamente contraídas.","Mantén la contracción por un momento, luego baja lentamente la plataforma de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2334-g376LuL.jpg","gif":"2334-g376LuL.gif"},{"id":"0744","n":"Sentadilla tumbado en trineo","bp":"upper legs","eq":"sled machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ajusta la máquina de trineo a un peso adecuado.","Túmbate boca arriba en la máquina de trineo con los pies sobre la placa.","Coloca los pies separados a la altura de los hombros y ligeramente angulados hacia fuera.","Sujeta las asas de la máquina de trineo para mayor estabilidad.","Activa los glúteos y los músculos del core.","Empuja con los talones y extiende las piernas para levantar el trineo.","Baja el trineo de nuevo doblando las rodillas y las caderas.","Repite el número de repeticiones deseado."],"img":"0744-9n2149Z.jpg","gif":"0744-9n2149Z.gif"},{"id":"1392","n":"Prensa de gemelos a una pierna en máquina de prensa de piernas","bp":"lower legs","eq":"sled machine","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Ajusta el asiento de la máquina de prensa de piernas de modo que las rodillas queden ligeramente flexionadas cuando los pies estén sobre el trineo.","Siéntate en la máquina con la espalda contra el respaldo y los pies sobre el trineo, separados a la altura de los hombros.","Coloca la punta y la almohadilla de los pies sobre el trineo, manteniendo los talones levantados.","Empuja el trineo hacia delante extendiendo los tobillos, manteniendo las rodillas ligeramente flexionadas.","Haz una pausa por un momento en la posición alta, luego baja lentamente el trineo flexionando los tobillos.","Repite el número de repeticiones deseado."],"img":"1392-u0pLNgz.jpg","gif":"1392-u0pLNgz.gif"},{"id":"1496","n":"Golpeo con maza","bp":"waist","eq":"hammer","tg":"abs","mg":"forearms","sm":["forearms","shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta el mazo con ambas manos.","Activa el core y mantén la espalda recta.","Balancea el mazo hacia el suelo, usando la fuerza del core y de la parte superior del cuerpo.","Mientras balanceas hacia abajo, gira las caderas y transfiere la fuerza al mazo.","Repite el número de repeticiones deseado."],"img":"1496-REXmfVC.jpg","gif":"1496-REXmfVC.gif"},{"id":"0746","n":"Encogimiento de hombros posterior en máquina Smith","bp":"back","eq":"smith machine","tg":"traps","mg":"shoulders","sm":["shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.","Mantén los brazos rectos y deja que la barra cuelgue frente a los muslos.","Levanta los hombros directamente hacia las orejas, contrayendo los trapecios en la parte alta.","Mantén la posición por un momento, luego baja los hombros de nuevo a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0746-MzNnwx9.jpg","gif":"0746-MzNnwx9.gif"},{"id":"0747","n":"Press tras nuca en máquina Smith","bp":"shoulders","eq":"smith machine","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Ajusta la altura del asiento de la máquina Smith de modo que la barra quede a la altura de los hombros.","Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.","Levanta la barra del soporte y da un paso atrás, manteniendo una postura estable.","Baja la barra hacia la parte de atrás del cuello, manteniendo los codos apuntando hacia delante.","Empuja la barra hacia arriba, por encima de la cabeza, hasta que los brazos queden completamente extendidos.","Haz una pausa por un momento en la posición alta, luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0747-Gpn4ADc.jpg","gif":"0747-Gpn4ADc.gif"},{"id":"0748","n":"Press de banca en máquina Smith","bp":"chest","eq":"smith machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Ajusta la altura de la barra de la máquina Smith a la altura del pecho.","Túmbate en el banco con los pies firmemente apoyados en el suelo.","Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.","Suelta la barra del soporte y bájala hacia el pecho, manteniendo los codos pegados al cuerpo.","Haz una pausa por un momento cuando la barra toque el pecho.","Empuja la barra de vuelta a la posición inicial, extendiendo los brazos por completo.","Repite el número de repeticiones deseado."],"img":"0748-trqKQv2.jpg","gif":"0748-trqKQv2.gif"},{"id":"0749","n":"Buenos días con rodillas flexionadas en máquina Smith","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Comienza de pie con los pies separados a la altura de los hombros, con los dedos de los pies apuntando hacia delante.","Coloca la barra sobre la parte superior de la espalda, apoyándola en los trapecios.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales.","Activa los glúteos y los isquiotibiales para levantar el torso de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0749-1bQkKZK.jpg","gif":"0749-1bQkKZK.gif"},{"id":"1359","n":"Remo inclinado en máquina Smith","bp":"back","eq":"smith machine","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Configura la máquina Smith con la barra a la altura de la cadera.","Ponte de pie frente a la barra con los pies separados a la altura de los hombros.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.","Tira de la barra hacia la parte baja del pecho, juntando las escápulas.","Haz una pausa por un momento en la posición alta, luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1359-ZX9UZmj.jpg","gif":"1359-ZX9UZmj.gif"},{"id":"0750","n":"Sentadilla en silla en máquina Smith","bp":"upper legs","eq":"smith machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Ajusta la altura de la barra de la máquina Smith a una posición cómoda.","Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Coloca la barra sobre la parte superior de la espalda, apoyándola en los trapecios.","Activa el core y mantén el pecho elevado mientras bajas lentamente el cuerpo doblando las rodillas y las caderas.","Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0750-Gu2rNJd.jpg","gif":"0750-Gu2rNJd.gif"},{"id":"0751","n":"Press de banca con agarre cerrado en máquina Smith","bp":"upper arms","eq":"smith machine","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Ajusta la altura del asiento y colócate en el banco con los pies planos sobre el suelo.","Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros.","Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo.","Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0751-WcHl7ru.jpg","gif":"0751-WcHl7ru.gif"},{"id":"0752","n":"Peso muerto en máquina Smith","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","lower back"],"st":["Configura la máquina Smith con la barra a la altura de la cadera.","Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.","Dobla las caderas y las rodillas, manteniendo la espalda recta y el pecho elevado, y sujeta la barra con un agarre prono un poco más ancho que los hombros.","Activa el core y levanta la barra extendiendo las caderas y las rodillas, manteniendo la barra cerca del cuerpo.","Ponte de pie erguido, extendiendo por completo las caderas y las rodillas.","Baja la barra de nuevo doblando las caderas y las rodillas, manteniendo el control y la espalda recta.","Repite el número de repeticiones deseado."],"img":"0752-UfePqpx.jpg","gif":"0752-UfePqpx.gif"},{"id":"0753","n":"Press de banca declinado en máquina Smith","bp":"chest","eq":"smith machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Ajusta el banco declinado al ángulo deseado.","Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.","Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0753-ETZfAbZ.jpg","gif":"0753-ETZfAbZ.gif"},{"id":"0754","n":"Press declinado con agarre inverso en máquina Smith","bp":"chest","eq":"smith machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Ajusta la máquina Smith a una posición declinada.","Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies.","Agarra la barra con un agarre invertido, manos un poco más separadas que el ancho de los hombros.","Suelta la barra y bájala hacia el pecho, manteniendo los codos pegados al cuerpo.","Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0754-MY9P1WA.jpg","gif":"0754-MY9P1WA.gif"},{"id":"1433","n":"Sentadilla frontal en máquina Smith (agarre olímpico)","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Configura la máquina Smith con la barra a la altura de los hombros.","Ponte de pie frente a la barra con los pies separados a la altura de los hombros.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Da un paso atrás y coloca la barra sobre los hombros delanteros, apoyándola en la clavícula y los deltoides.","Mantén el pecho elevado, la espalda recta y el core activado.","Baja el cuerpo doblando las rodillas y las caderas, como si te sentaras en una silla.","Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo.","Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1433-lFhb2Rw.jpg","gif":"1433-lFhb2Rw.gif"},{"id":"3281","n":"Sentadilla profunda en máquina Smith","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Configura la máquina Smith con la barra a la altura de los hombros.","Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Colócate debajo de la barra y posiciónala sobre la parte alta de la espalda, apoyándola en los trapecios.","Sujeta la barra con las manos un poco más separadas que el ancho de los hombros.","Suelta la barra del soporte y da un paso atrás, manteniendo una postura estable.","Manteniendo el pecho elevado y el core activado, inicia la sentadilla empujando las caderas hacia atrás y doblando las rodillas.","Baja el cuerpo hasta que los muslos queden paralelos al suelo, o tan abajo como tu flexibilidad lo permita.","Haz una pausa por un momento en la posición baja, luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3281-NNoHCEA.jpg","gif":"3281-NNoHCEA.gif"},{"id":"0755","n":"Sentadilla Hack en máquina Smith","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ajusta la barra de la máquina Smith a una altura adecuada para tu cuerpo.","Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Colócate debajo de la barra, apoyándola en la parte alta de los trapecios y los hombros.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Activa el core y mantén el pecho elevado mientras sueltas la barra del soporte.","Da un paso atrás y coloca los pies un poco más separados que el ancho de los hombros.","Dobla las rodillas y baja el cuerpo, manteniendo el pecho elevado y la espalda recta.","Continúa descendiendo hasta que los muslos queden paralelos al suelo o un poco por debajo.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0755-ZuPXtCK.jpg","gif":"0755-ZuPXtCK.gif"},{"id":"0756","n":"Elevación de cadera en máquina Smith","bp":"waist","eq":"smith machine","tg":"abs","mg":"glutes","sm":["glutes","hamstrings"],"st":["Colócate en la máquina Smith con la espalda contra la almohadilla y los pies separados a la altura de los hombros.","Coloca las manos en la barra, un poco más separadas que el ancho de los hombros.","Activa el core y los glúteos, luego empuja con los talones para levantar las caderas del suelo.","Continúa levantando hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.","Mantén la posición alta por un momento, luego baja lentamente las caderas de nuevo a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0756-CqhoytW.jpg","gif":"0756-CqhoytW.gif"},{"id":"0757","n":"Press de banca inclinado en máquina Smith","bp":"chest","eq":"smith machine","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Ajusta el banco a una inclinación de 30-45 grados.","Siéntate en el banco con la espalda plana contra la almohadilla y los pies firmemente apoyados en el suelo.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Suelta la barra y bájala lentamente hacia la parte alta del pecho, manteniendo los codos ligeramente pegados al cuerpo.","Haz una pausa por un momento en la posición baja, luego empuja la barra de vuelta a la posición inicial, extendiendo los brazos por completo.","Repite el número de repeticiones deseado."],"img":"0757-5v7KYld.jpg","gif":"0757-5v7KYld.gif"},{"id":"0758","n":"Press inclinado con agarre invertido en máquina Smith","bp":"chest","eq":"smith machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Ajusta el asiento de la máquina Smith a un ángulo de inclinación cómodo.","Siéntate en la máquina con la espalda contra la almohadilla y los pies planos sobre el suelo.","Sujeta la barra con un agarre prono un poco más ancho que el ancho de los hombros.","Suelta la barra y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.","Haz una pausa por un momento cuando la barra esté justo por encima del pecho.","Empuja la barra de vuelta a la posición inicial, extendiendo los brazos por completo.","Repite el número de repeticiones deseado."],"img":"0758-78VqWQK.jpg","gif":"0758-78VqWQK.gif"},{"id":"0759","n":"Elevaciones de hombros en banco inclinado en máquina Smith","bp":"chest","eq":"smith machine","tg":"serratus anterior","mg":"deltoids","sm":["deltoids","trapezius"],"st":["Ajusta la máquina Smith a una posición inclinada.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.","Mantén la espalda recta y el core activado.","Eleva la barra hacia el techo, guiando el movimiento con los codos.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0759-ayAHcEm.jpg","gif":"0759-ayAHcEm.gif"},{"id":"0760","n":"Prensa de piernas en máquina Smith","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ajusta el asiento y la placa para los pies de la máquina Smith a una posición cómoda.","Siéntate en la máquina con la espalda apoyada en el respaldo y los pies separados a la altura de los hombros sobre la placa para los pies.","Sujeta las asas o los lados de la máquina para mayor estabilidad.","Empuja la placa alejándola de ti extendiendo las piernas, manteniendo la espalda contra el respaldo.","Haz una pausa por un momento en la posición completamente extendida.","Dobla lentamente las rodillas y baja la placa de vuelta hacia ti, regresando a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0760-7zdxRTl.jpg","gif":"0760-7zdxRTl.gif"},{"id":"1434","n":"Sentadilla con barra baja en máquina Smith","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Configura la máquina Smith con la barra a una altura que te permita apoyarla cómodamente en la parte alta de la espalda.","Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Colócate debajo de la barra y posiciónala sobre la parte alta de la espalda, apoyándola en los trapecios.","Sujeta la barra con las manos un poco más separadas que el ancho de los hombros.","Suelta la barra del soporte estirando las piernas y dando un paso atrás para alejarte del soporte.","Respira profundamente y tensa el core.","Inicia la sentadilla empujando las caderas hacia atrás y doblando las rodillas.","Baja el cuerpo hasta que los muslos queden paralelos al suelo o un poco por debajo.","Mantén el pecho hacia arriba y la espalda recta durante todo el movimiento.","Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.","Repite el número de repeticiones deseado."],"img":"1434-RGLscZM.jpg","gif":"1434-RGLscZM.gif"},{"id":"1683","n":"Curl de bíceps en máquina Smith","bp":"upper arms","eq":"smith machine","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ajusta la altura de la barra de la máquina Smith a la altura de la cintura.","Ponte de pie frente a la máquina Smith con los pies separados a la altura de los hombros.","Sujeta la barra con un agarre supino, con las manos un poco más separadas que el ancho de los hombros.","Mantén los codos cerca de los costados y los brazos superiores quietos.","Exhala y flexiona la barra hacia los hombros, contrayendo los bíceps.","Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.","Inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1683-zILLZ98.jpg","gif":"1683-zILLZ98.gif"},{"id":"1625","n":"Press de banca declinado con agarre cerrado en máquina Smith","bp":"upper arms","eq":"smith machine","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Ajusta el banco de la máquina Smith a una posición declinada.","Túmbate en el banco con los pies firmemente apoyados en el suelo.","Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros.","Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.","Haz una pausa breve cuando la barra esté justo encima del pecho.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"1625-yB9SvIF.jpg","gif":"1625-yB9SvIF.gif"},{"id":"1752","n":"Extensión de tríceps inclinada en máquina Smith","bp":"upper arms","eq":"smith machine","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Ajusta el asiento de la máquina Smith de modo que la barra quede a la altura de los hombros.","Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo.","Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.","Extiende los brazos por completo, levantando la barra del soporte y sosteniéndola directamente sobre el pecho.","Baja la barra lentamente hacia la frente, manteniendo los codos cerca de la cabeza.","Haz una pausa por un momento en la posición baja, luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1752-o8aOcrz.jpg","gif":"1752-o8aOcrz.gif"},{"id":"1626","n":"Press de banca declinado con agarre invertido y cerrado en máquina Smith","bp":"chest","eq":"smith machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Ajusta la máquina Smith a una posición declinada.","Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies.","Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros.","Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.","Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1626-QyO6Uma.jpg","gif":"1626-QyO6Uma.gif"},{"id":"0761","n":"Remo con agarre estrecho en máquina Smith","bp":"back","eq":"smith machine","tg":"upper back","mg":"biceps","sm":["biceps","rear deltoids"],"st":["Ajusta la altura del asiento y colócate en la máquina con los pies planos sobre el suelo.","Sujeta las asas con un agarre prono, un poco más estrecho que el ancho de los hombros.","Mantén la espalda recta y el pecho elevado mientras tiras de las asas hacia tu cuerpo, juntando las escápulas.","Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0761-JGKowMS.jpg","gif":"0761-JGKowMS.gif"},{"id":"1360","n":"Remo a una mano en máquina Smith","bp":"back","eq":"smith machine","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Ajusta la altura de la barra de la máquina Smith a la altura de la cintura.","Ponte de pie frente a la máquina Smith con los pies separados a la altura de los hombros.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Sujeta la barra con una mano usando un agarre prono, con la palma hacia abajo.","Mantén el codo cerca del cuerpo y tira de la barra hacia la cintura, juntando las escápulas.","Haz una pausa por un momento en la parte alta del movimiento, luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"img":"1360-Q4DSJPC.jpg","gif":"1360-Q4DSJPC.gif"},{"id":"1393","n":"Elevación de talón a una pierna en suelo en máquina Smith","bp":"lower legs","eq":"smith machine","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Colócate en el suelo debajo de la barra de la máquina Smith, mirando en dirección contraria a la máquina.","Coloca la punta de los pies sobre una superficie elevada, como un disco de peso o un bloque.","Coloca la barra de la máquina Smith sobre la parte baja de las piernas, justo por encima de los tobillos.","Sujeta la barra con las manos para mayor estabilidad.","Levanta los talones del suelo extendiendo los tobillos, elevando el cuerpo hacia arriba.","Haz una pausa en la parte alta del movimiento, luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1393-9GXrTE6.jpg","gif":"1393-9GXrTE6.gif"},{"id":"0762","n":"Remo para deltoides posterior en máquina Smith","bp":"shoulders","eq":"smith machine","tg":"delts","mg":"trapezius","sm":["trapezius","rhomboids","biceps"],"st":["Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo.","Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.","Mantén la espalda recta y el core activado mientras tiras de las asas hacia el pecho, juntando las escápulas.","Haz una pausa por un momento en la parte alta del movimiento, luego suelta lentamente las asas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0762-nFUwqG6.jpg","gif":"0762-nFUwqG6.gif"},{"id":"0763","n":"Elevaciones invertidas de gemelos en máquina Smith agarre alto prono por la espalda","bp":"lower legs","eq":"smith machine","tg":"calves","mg":"hamstrings","sm":["hamstrings"],"st":["Ajusta la barra de la máquina Smith a una altura justo debajo de los hombros.","Ponte de pie frente a la barra con los pies separados a la altura de la cadera y los dedos de los pies apuntando hacia delante.","Coloca la punta de los pies en el borde de un escalón o plataforma, con los talones colgando.","Sujétate de la barra para apoyarte, manteniendo la espalda recta y el core activado.","Levanta los talones lo más alto posible, elevando el peso de tu cuerpo sobre las puntas de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0763-ywaNfuh.jpg","gif":"0763-ywaNfuh.gif"},{"id":"1394","n":"Elevaciones invertidas de gemelos en máquina Smith agarre bajo prono por la espalda","bp":"lower legs","eq":"smith machine","tg":"calves","mg":"hamstrings","sm":["hamstrings"],"st":["Ajusta la barra de la máquina Smith a una altura justo debajo de los hombros.","Ponte de pie frente a la barra con los pies separados a la altura de la cadera y los dedos de los pies apuntando hacia delante.","Coloca la punta de los pies en el borde de un escalón o plataforma, con los talones colgando.","Sujétate de la barra para apoyarte.","Levanta los talones lo más alto posible, elevando el cuerpo sobre la punta de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1394-Lsqrgh4.jpg","gif":"1394-Lsqrgh4.gif"},{"id":"1361","n":"Remo inclinado con agarre invertido en máquina Smith","bp":"back","eq":"smith machine","tg":"upper back","mg":"biceps","sm":["biceps","forearms"],"st":["Configura la máquina Smith con la barra a la altura de la cadera.","Ponte de pie frente a la barra con los pies separados a la altura de los hombros.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.","Tira de la barra hacia la parte baja del pecho, juntando las escápulas.","Haz una pausa por un momento en la posición alta, luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1361-aaxA3cm.jpg","gif":"1361-aaxA3cm.gif"},{"id":"0764","n":"Press en máquina Smith con agarre invertido","bp":"chest","eq":"smith machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Ajusta la altura de la barra de la máquina Smith a la altura del pecho.","Ponte de pie frente a la barra con los pies separados a la altura de los hombros.","Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.","Da un paso atrás y colócate con una ligera flexión en las rodillas.","Mantén el pecho elevado y el core activado durante todo el ejercicio.","Baja la barra hacia el pecho, manteniendo los codos pegados al cuerpo.","Haz una pausa por un momento en la posición baja, luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0764-zK8Fu1W.jpg","gif":"0764-zK8Fu1W.gif"},{"id":"1395","n":"Elevación de talones a una pierna sentado en máquina Smith","bp":"lower legs","eq":"smith machine","tg":"calves","mg":"hamstrings","sm":["hamstrings"],"st":["Siéntate en la máquina con la espalda contra la almohadilla y los pies sobre el apoyapiés.","Coloca una pierna sobre el apoyapiés y mantén la otra pierna fuera de él.","Eleva el talón lo más alto posible, usando los músculos de la pantorrilla.","Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.","Repite el número de repeticiones deseado y luego cambia de pierna y repite."],"img":"1395-0S75mYG.jpg","gif":"1395-0S75mYG.gif"},{"id":"0765","n":"Press de hombros sentado en máquina Smith","bp":"shoulders","eq":"smith machine","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Ajusta la altura del asiento de modo que las asas queden a la altura de los hombros.","Siéntate en la máquina con la espalda contra la almohadilla y los pies planos sobre el suelo.","Sujeta las asas con un agarre prono y levántalas de los soportes, extendiendo los brazos por completo.","Baja las asas hasta la altura de los hombros, manteniendo los codos ligeramente flexionados.","Empuja las asas hacia arriba, por encima de la cabeza, hasta que los brazos queden completamente extendidos.","Haz una pausa por un momento en la parte alta y luego baja lentamente las agarraderas de vuelta a la altura del hombro.","Repite el número de repeticiones deseado."],"img":"0765-xUwnBMT.jpg","gif":"0765-xUwnBMT.gif"},{"id":"1426","n":"Curl de muñeca sentado en máquina Smith","bp":"lower arms","eq":"smith machine","tg":"forearms","mg":"biceps","sm":["biceps","brachialis"],"st":["Siéntate en un banco frente a una máquina Smith con los pies planos sobre el suelo.","Sujeta la barra con un agarre supino, con las manos separadas a la altura de los hombros.","Apoya los antebrazos sobre los muslos, permitiendo que las muñecas cuelguen.","Flexiona lentamente las muñecas hacia arriba, llevando la barra hacia los antebrazos.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1426-B6dAO1t.jpg","gif":"1426-B6dAO1t.gif"},{"id":"0766","n":"Press de hombros en máquina Smith","bp":"shoulders","eq":"smith machine","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Ajusta la altura del asiento y colócate en la máquina Smith con los pies separados a la altura de los hombros.","Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.","Levanta la barra del soporte y colócala a la altura de los hombros, con los codos flexionados y las palmas hacia delante.","Empuja la barra hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza.","Haz una pausa por un momento en la posición alta, luego baja lentamente la barra de vuelta a la altura de los hombros.","Repite el número de repeticiones deseado."],"img":"0766-903mzG8.jpg","gif":"0766-903mzG8.gif"},{"id":"0767","n":"Encogimientos de hombros en máquina Smith","bp":"back","eq":"smith machine","tg":"traps","mg":"shoulders","sm":["shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.","Mantén los brazos rectos y los hombros relajados.","Levanta los hombros hacia las orejas, contrayendo los trapecios en la parte alta.","Mantén la posición por un momento y luego baja lentamente los hombros de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0767-OUQ0ZyW.jpg","gif":"0767-OUQ0ZyW.gif"},{"id":"0768","n":"Sentadilla búlgara en máquina Smith","bp":"upper legs","eq":"smith machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings"],"st":["Ponte de pie frente a la máquina Smith con los pies separados a la altura de los hombros.","Coloca un pie detrás de ti sobre un banco o escalón, con los dedos del pie apuntando hacia delante.","Sujétate de la barra de la máquina Smith para mayor estabilidad.","Dobla la rodilla delantera y baja el cuerpo hacia una posición de zancada, manteniendo la espalda recta.","Haz una pausa por un momento en la posición baja, luego empuja con el talón delantero para volver a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."],"img":"0768-wWFspEi.jpg","gif":"0768-wWFspEi.gif"},{"id":"0769","n":"Zancada de velocista en máquina Smith","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Configura la máquina Smith con la barra a la altura de la cadera.","Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.","Da un paso atrás con el pie derecho y colócalo sobre la barra, apoyando la parte superior del pie en ella.","Dobla la rodilla izquierda y baja el cuerpo hacia una posición de zancada, manteniendo la espalda recta.","Empuja con el talón izquierdo para volver a la posición inicial.","Repite del otro lado, dando un paso hacia atrás con el pie izquierdo.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0769-HsjbB1z.jpg","gif":"0769-HsjbB1z.gif"},{"id":"0770","n":"Sentadilla en máquina Smith","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Configura la máquina Smith con la barra a una altura adecuada para tu sentadilla.","Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Colócate debajo de la barra, apoyándola en la parte alta de los trapecios y los hombros.","Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros.","Activa el core y suelta la barra del soporte, dando un paso atrás para alejarte del soporte.","Manteniendo el pecho elevado y la espalda recta, inicia la sentadilla doblando las caderas y las rodillas.","Baja el cuerpo hasta que los muslos queden paralelos al suelo o un poco por debajo.","Haz una pausa por un momento en la posición baja, luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0770-jFtipLl.jpg","gif":"0770-jFtipLl.gif"},{"id":"0771","n":"Curl de muñeca posterior de pie en máquina Smith","bp":"lower arms","eq":"smith machine","tg":"forearms","mg":"biceps","sm":["biceps","triceps"],"st":["Ponte de pie frente a la máquina Smith con los pies separados a la altura de los hombros.","Sujeta la barra con un agarre prono, con las manos separadas a la altura de los hombros.","Mantén la espalda recta y los codos cerca del cuerpo.","Flexiona lentamente las muñecas hacia arriba, llevando la barra hacia el cuerpo.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0771-hfmQ0Tz.jpg","gif":"0771-hfmQ0Tz.gif"},{"id":"0772","n":"Press militar tras nuca de pie en máquina Smith","bp":"shoulders","eq":"smith machine","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Ajusta la altura del asiento de la máquina Smith de modo que la barra quede a la altura de los hombros.","Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.","Levanta la barra del soporte y da un paso atrás, manteniendo una postura estable.","Coloca la barra detrás de la cabeza, apoyándola en la parte alta de los trapecios.","Mantén el core activado y el pecho elevado durante todo el ejercicio.","Empuja la barra por encima de la cabeza extendiendo los brazos, estirándolos por completo.","Haz una breve pausa en la parte alta del movimiento, luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0772-ht8xDrP.jpg","gif":"0772-ht8xDrP.gif"},{"id":"0773","n":"Elevación de talones de pie en máquina Smith","bp":"lower legs","eq":"smith machine","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Ajusta la barra de la máquina Smith a una altura que te permita estar de pie con los pies planos sobre el suelo y los hombros debajo de la barra.","Colócate debajo de la barra con los pies separados a la altura de los hombros y los dedos de los pies apuntando hacia delante.","Coloca las manos sobre la barra para mayor estabilidad.","Activa las pantorrillas y levanta lentamente los talones del suelo, elevando el cuerpo sobre la punta de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0773-6MaEjVA.jpg","gif":"0773-6MaEjVA.gif"},{"id":"0774","n":"Press militar de pie en máquina Smith","bp":"shoulders","eq":"smith machine","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Levanta la barra del soporte y bájala hasta la altura de los hombros, con las palmas hacia delante.","Empuja la barra hacia arriba hasta que tus brazos queden completamente extendidos por encima de la cabeza.","Haz una pausa de un momento en la parte superior y luego baja lentamente la barra de nuevo hasta la altura de los hombros.","Repite el número de repeticiones deseado."],"img":"0774-jjUPrze.jpg","gif":"0774-jjUPrze.gif"},{"id":"3142","n":"Sentadilla sumo en máquina Smith","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Configura la máquina Smith con la barra a la altura de la cadera.","Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies hacia afuera.","Colócate debajo de la barra, apoyándola sobre la parte superior de la espalda y los hombros.","Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, empujando las caderas hacia atrás y flexionando las rodillas.","Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3142-dzz6BiV.jpg","gif":"3142-dzz6BiV.gif"},{"id":"1396","n":"Elevación de punteras en máquina Smith","bp":"lower legs","eq":"smith machine","tg":"calves","mg":"ankles","sm":["ankles","shins"],"st":["Ajusta la barra de la máquina Smith a una altura que te permita pararte cómodamente con los pies planos sobre el suelo.","Colócate debajo de la barra con los hombros justo debajo de ella y los pies separados a la altura de los hombros.","Coloca la planta de los pies sobre una plataforma elevada o discos de peso, dejando los talones colgando fuera del borde.","Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.","Activa el core y mantén la espalda recta durante todo el ejercicio.","Levanta lentamente los talones lo más alto posible, elevando el peso de tu cuerpo sobre la punta de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1396-Y4QlY8z.jpg","gif":"1396-Y4QlY8z.gif"},{"id":"0775","n":"Remo al mentón en máquina Smith","bp":"shoulders","eq":"smith machine","tg":"delts","mg":"traps","sm":["traps","biceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros, de frente a la máquina Smith.","Agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.","Mantén la espalda recta y el core activado.","Tira de la barra hacia tu barbilla, guiando el movimiento con los codos.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0775-1DN3iz4.jpg","gif":"0775-1DN3iz4.gif"},{"id":"1308","n":"Press de banca con agarre ancho en máquina Smith","bp":"chest","eq":"smith machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Ajusta el banco a una posición cómoda en la máquina Smith.","Túmbate en el banco con los pies planos sobre el suelo.","Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros.","Desengancha la barra y bájala lentamente hacia tu pecho, manteniendo los codos hacia afuera a los costados.","Haz una pausa breve cuando la barra toque el pecho.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"1308-zoOvPcx.jpg","gif":"1308-zoOvPcx.gif"},{"id":"1309","n":"Press de banca declinado con agarre ancho en máquina Smith","bp":"chest","eq":"smith machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Ajusta el banco declinado al ángulo deseado.","Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies.","Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros.","Desengancha la barra y bájala lentamente hacia tu pecho, manteniendo los codos apuntando hacia afuera.","Haz una pausa breve cuando la barra toque el pecho.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"1309-wi2H9QX.jpg","gif":"1309-wi2H9QX.gif"},{"id":"0776","n":"Tirón de arrancada","bp":"upper legs","eq":"barbell","tg":"quads","mg":"hamstrings","sm":["hamstrings","glutes","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros y la barra en el suelo frente a ti.","Flexiona las rodillas y dobla las caderas para bajar a una posición de sentadilla, agarrando la barra con un agarre prono.","Mantén la espalda recta y el pecho elevado mientras empujas con los talones para levantar la barra del suelo, extendiendo las caderas y las rodillas.","Cuando la barra llegue a la altura de la cadera, tira de ella hacia arriba de forma explosiva, encogiendo los hombros y llevando los codos altos y hacia los lados.","Cuando la barra alcance su punto más alto, baja rápidamente debajo de ella, llevando tu cuerpo a una posición de sentadilla profunda.","Recibe la barra por encima de la cabeza con los brazos completamente extendidos y las rodillas flexionadas.","Ponte de pie extendiendo las caderas y las rodillas, manteniendo la barra por encima de la cabeza.","Baja la barra de nuevo a la posición inicial invirtiendo el movimiento.","Repite el número de repeticiones deseado."],"img":"0776-dG5Smob.jpg","gif":"0776-dG5Smob.gif"},{"id":"0777","n":"Lanzamiento de hechizo con mancuerna","bp":"waist","eq":"dumbbell","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde la cintura, manteniendo la espalda recta.","Extiende el brazo con la mancuerna hacia el pie opuesto, rotando el torso mientras lo haces.","Regresa a la posición inicial y repite del otro lado.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0777-p9cCe2r.jpg","gif":"0777-p9cCe2r.gif"},{"id":"1362","n":"Esfinge","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Túmbate boca abajo en el suelo con los antebrazos planos sobre el piso y los codos justo debajo de los hombros.","Activa el core y levanta el pecho del suelo, manteniendo los antebrazos y los dedos de los pies en el piso.","Mantén esta posición durante unos segundos, asegurándote de mantener el cuello en una posición neutral.","Baja lentamente el pecho de nuevo a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1362-DIVyqrU.jpg","gif":"1362-DIVyqrU.gif"},{"id":"0778","n":"Flexión con paso de araña","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"core","sm":["core","chest","shoulders"],"st":["Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos.","Lleva la rodilla derecha hacia el codo derecho, manteniéndola elevada del suelo.","Mientras llevas la rodilla derecha hacia atrás, baja simultáneamente el cuerpo hacia el suelo flexionando los codos.","Empuja de nuevo hacia arriba a la posición inicial y repite llevando la rodilla izquierda hacia el codo izquierdo.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0778-P9GFBME.jpg","gif":"0778-P9GFBME.gif"},{"id":"1363","n":"Estiramiento de columna","bp":"back","eq":"body weight","tg":"spine","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Siéntate en el suelo con las piernas extendidas frente a ti.","Coloca las manos en el suelo detrás de ti, con los dedos apuntando hacia tu cuerpo.","Activa el core e inclínate lentamente hacia atrás, manteniendo la espalda recta.","Sigue inclinándote hacia atrás hasta que sientas un estiramiento en la columna.","Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1363-JbC2iaV.jpg","gif":"1363-JbC2iaV.gif"},{"id":"2329","n":"Torsión de columna","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Siéntate en el suelo con las piernas extendidas frente a ti.","Dobla las rodillas y coloca los pies planos sobre el suelo, separados a la altura de la cadera.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activa el abdomen y gira lentamente el torso hacia la derecha, llevando el codo derecho hacia la rodilla izquierda.","Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.","Repite el giro hacia el lado izquierdo, llevando el codo izquierdo hacia la rodilla derecha.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"2329-2jl9K55.jpg","gif":"2329-2jl9K55.gif"},{"id":"2368","n":"Sentadillas búlgaras","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros.","Da un paso adelante con un pie y colócalo aproximadamente a dos pies de distancia por delante del otro pie.","Baja el cuerpo flexionando las rodillas y las caderas, manteniendo la espalda recta.","Sigue bajando hasta que el muslo delantero quede paralelo al suelo y la rodilla trasera quede justo por encima del suelo.","Haz una pausa breve, luego empuja con el talón delantero para volver a la posición inicial.","Repite el número de repeticiones deseado y luego cambia de pierna y repite."],"img":"2368-9E25EOx.jpg","gif":"2368-9E25EOx.gif"},{"id":"0786","n":"Squat jerk","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","core"],"st":["Comienza con la barra apoyada sobre los hombros y los pies separados a la altura de los hombros.","Baja el cuerpo a una posición de sentadilla, manteniendo el pecho elevado y las rodillas alineadas con la punta de los pies.","Al llegar al punto más bajo de la sentadilla, empuja con fuerza a través de las piernas y eleva la barra por encima de la cabeza.","Cuando la barra alcance su punto más alto, baja rápidamente a una posición de zancada dividida, con un pie adelante y otro atrás.","Recibe la barra por encima de la cabeza con los brazos completamente extendidos y la rodilla trasera tocando ligeramente el suelo.","Ponte de pie desde la posición dividida, juntando de nuevo los pies.","Baja la barra de nuevo a los hombros y repite el número de repeticiones deseado."],"img":"0786-IMRsOCn.jpg","gif":"0786-IMRsOCn.gif"},{"id":"1705","n":"Sentadilla sobre bosu","bp":"upper legs","eq":"bosu ball","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Coloca el bosu en el suelo con el lado plano hacia arriba.","Ponte de pie con los pies separados a la altura de los hombros y colócate encima del bosu.","Baja el cuerpo flexionando las rodillas y las caderas, como si te sentaras en una silla.","Mantén el pecho elevado y el peso en los talones.","Baja hasta que los muslos queden paralelos al suelo.","Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1705-T2fA5Ir.jpg","gif":"1705-T2fA5Ir.gif"},{"id":"1685","n":"Sentadilla con extensión de brazos por encima de la cabeza","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.","Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.","Mientras te levantas de la sentadilla, extiende los brazos por encima de la cabeza, alcanzando hacia el techo.","Vuelve a la posición inicial bajando los brazos y flexionando las rodillas para volver a hacer la sentadilla.","Repite el número de repeticiones deseado."],"img":"1685-QChZi3x.jpg","gif":"1685-QChZi3x.gif"},{"id":"1686","n":"Sentadilla con extensión de brazos sobre la cabeza y torsión","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.","Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.","Mientras te levantas de la sentadilla, eleva los brazos por encima de la cabeza y gira el torso hacia un lado.","Vuelve a la posición inicial y repite la sentadilla, esta vez girando el torso hacia el lado opuesto.","Continúa alternando los lados en cada repetición de la sentadilla."],"img":"1686-5BZHW9s.jpg","gif":"1686-5BZHW9s.gif"},{"id":"2297","n":"Crunch en fitball (rango completo con manos tras la cabeza)","bp":"waist","eq":"stability ball","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, curva lentamente la parte superior del cuerpo hacia adelante, llevando el pecho hacia las rodillas.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2297-Gn5FwYT.jpg","gif":"2297-Gn5FwYT.gif"},{"id":"3291","n":"Prensa Stalder","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Comienza de pie con los pies separados a la altura de los hombros y los brazos extendidos por encima de la cabeza.","Flexiona ligeramente las rodillas y activa el core.","Baja el cuerpo a una posición de sentadilla mientras mantienes los brazos extendidos por encima de la cabeza.","Mientras bajas en la sentadilla, empuja los brazos hacia el suelo, activando los tríceps.","Haz una pausa de un momento en la parte baja de la sentadilla, luego empuja con los talones para levantarte mientras al mismo tiempo elevas de nuevo los brazos por encima de la cabeza.","Repite el número de repeticiones deseado."],"img":"3291-zd4P4B2.jpg","gif":"3291-zd4P4B2.gif"},{"id":"3669","n":"El arquero de pie","bp":"back","eq":"body weight","tg":"upper back","mg":"shoulders","sm":["shoulders","biceps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Extiende los brazos rectos hacia adelante a la altura de los hombros, paralelos al suelo.","Gira el torso hacia la derecha, manteniendo los brazos extendidos y la espalda recta.","Mientras giras, extiende el brazo derecho hacia adelante y el brazo izquierdo hacia atrás, imitando el movimiento de tensar un arco.","Mantén la posición por un momento y luego vuelve a la posición inicial.","Repite el movimiento, esta vez girando el torso hacia la izquierda y extendiendo el brazo izquierdo hacia adelante y el brazo derecho hacia atrás.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"3669-JF8AkMX.jpg","gif":"3669-JF8AkMX.gif"},{"id":"0788","n":"Press militar tras nuca de pie","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén la barra detrás del cuello con un agarre prono.","Mantén la espalda recta y el core activado.","Empuja la barra por encima de la cabeza extendiendo los brazos, estirando completamente los codos.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0788-xDh0lJr.jpg","gif":"0788-xDh0lJr.gif"},{"id":"1490","n":"Elevación de talones de pie (en escalón)","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","feet"],"st":["Ponte de pie en el borde de un escalón o una plataforma firme, con los talones colgando y la punta de los pies sobre el escalón.","Sujétate de una baranda o pared para mantener el equilibrio si es necesario.","Levanta lentamente los talones lo más alto posible, elevando el peso de tu cuerpo sobre la punta de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1490-6HmFgmx.jpg","gif":"1490-6HmFgmx.gif"},{"id":"1397","n":"Gemelos de pie","bp":"lower legs","eq":"body weight","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Ponte de pie con los pies separados a la altura de los hombros, con las puntas de los pies apuntando hacia adelante.","Levanta los talones del suelo lo más alto posible, apoyándote sobre la punta de los pies.","Mantén la posición por un momento y luego baja lentamente los talones de nuevo a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1397-XIHEoCG.jpg","gif":"1397-XIHEoCG.gif"},{"id":"1398","n":"Estiramiento de gemelos de pie","bp":"lower legs","eq":"body weight","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Ponte de pie frente a una pared u objeto firme, a una distancia aproximada de un brazo.","Coloca las manos sobre la pared o el objeto a la altura de los hombros.","Da un paso hacia atrás con un pie, manteniendo el talón plano sobre el suelo.","Flexiona ligeramente la rodilla delantera e inclínate hacia adelante, manteniendo la pierna trasera recta.","Deberías sentir un estiramiento en el músculo de la pantorrilla.","Mantén el estiramiento durante 20-30 segundos.","Repite con la otra pierna."],"img":"1398-qOKcgVP.jpg","gif":"1398-qOKcgVP.gif"},{"id":"1599","n":"Estiramiento de isquiotibiales y gemelos de pie con correa","bp":"upper legs","eq":"rope","tg":"hamstrings","mg":"calves","sm":["calves"],"st":["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.","Sostén la correa con ambas manos y colócala alrededor de la parte anterior de la planta del pie.","Mantén la pierna recta e inclínate lentamente hacia adelante desde las caderas, manteniendo la espalda recta.","Siente el estiramiento en los isquiotibiales y en los músculos de la pantorrilla.","Mantén el estiramiento durante 20-30 segundos.","Suelta el estiramiento y repite con la otra pierna.","Repite el número de repeticiones deseado."],"img":"1599-xTjr103.jpg","gif":"1599-xTjr103.gif"},{"id":"0794","n":"Estiramiento lateral de pie","bp":"back","eq":"body weight","tg":"lats","mg":"shoulders","sm":["shoulders","obliques"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Extiende los brazos hacia los lados, paralelos al suelo.","Inclina lentamente la parte superior del cuerpo hacia un lado, sintiendo un estiramiento en el costado y los dorsales.","Mantén el estiramiento durante 15-30 segundos.","Regresa a la posición inicial y repite del otro lado.","Repite el número de repeticiones deseado."],"img":"0794-1jXLYEw.jpg","gif":"0794-1jXLYEw.gif"},{"id":"1364","n":"Basculación pélvica de pie","bp":"back","eq":"body weight","tg":"spine","mg":"abdominals","sm":["abdominals"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Coloca las manos sobre las caderas o déjalas colgar a los lados.","Activa los músculos del core e inclina la pelvis hacia adelante, empujando la zona lumbar hacia la pared detrás de ti.","Mantén la posición durante unos segundos, luego suelta y vuelve a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1364-cuKYxhu.jpg","gif":"1364-cuKYxhu.gif"},{"id":"0795","n":"Curl femoral a una pierna de pie","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes"],"st":["Ponte de pie con los pies separados a la altura de las caderas y las manos en las caderas.","Traslada tu peso a la pierna izquierda y levanta el pie derecho del suelo, flexionando la rodilla.","Curva lentamente el talón derecho hacia los glúteos, contrayendo el isquiotibial.","Haz una pausa de un momento en la parte superior y luego baja lentamente el pie derecho de nuevo a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."],"img":"0795-C5jncD2.jpg","gif":"0795-C5jncD2.gif"},{"id":"0796","n":"Despliegue con rueda abdominal de pie","bp":"waist","eq":"wheel roller","tg":"abs","mg":"lower back","sm":["lower back","shoulders"],"st":["Comienza de pie, erguido, con los pies separados a la altura de los hombros y el rodillo frente a ti.","Dobla la cintura y haz rodar lentamente el rodillo hacia adelante, manteniendo la espalda recta y el core activado.","Continúa rodando hacia adelante hasta sentir un estiramiento en el abdomen y que tu cuerpo esté extendido lo máximo posible.","Haz una pausa de un momento, luego haz rodar lentamente el rodillo de regreso hacia tu cuerpo, volviendo a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0796-KtRomty.jpg","gif":"0796-KtRomty.gif"},{"id":"3223","n":"Salto en estrella (hombre)","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros y los brazos a los costados.","Flexiona ligeramente las rodillas y salta hacia arriba de forma explosiva.","Mientras saltas, separa las piernas y extiende los brazos hacia los lados, formando una figura de estrella con tu cuerpo.","Aterriza suavemente sobre la punta de los pies con las rodillas ligeramente flexionadas.","Repite el número de repeticiones deseado."],"img":"3223-HtfCpfi.jpg","gif":"3223-HtfCpfi.gif"},{"id":"2138","n":"Pedaleo rápido en bicicleta estática v. 3","bp":"cardio","eq":"stationary bike","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ajusta la altura y la posición del asiento para asegurar una alineación correcta.","Coloca los pies sobre los pedales y sujétalos con las correas si están disponibles.","Comienza a pedalear a un ritmo cómodo.","Mantén un ritmo constante y aumenta la resistencia según lo desees.","Activa los músculos del core para mantener la estabilidad y una postura correcta.","Continúa pedaleando durante la duración deseada de tu entrenamiento.","Disminuye gradualmente la resistencia y reduce la velocidad antes de detenerte por completo.","Estira las piernas y enfría después del entrenamiento."],"img":"2138-H1PESYI.jpg","gif":"2138-H1PESYI.gif"},{"id":"0798","n":"Pedaleo suave en bicicleta estática","bp":"cardio","eq":"leverage machine","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ajusta la altura y la posición del asiento en la bicicleta estática para asegurar una alineación correcta.","Coloca los pies sobre los pedales y sujétalos con las correas si están disponibles.","Comienza a pedalear a un ritmo cómodo, manteniendo la espalda recta y el core activado.","Mantén un ritmo constante y aumenta el nivel de resistencia si lo deseas.","Continúa pedaleando durante la duración deseada de tu entrenamiento cardiovascular.","Enfría reduciendo gradualmente tu ritmo y el nivel de resistencia.","Estira los músculos de las piernas después del entrenamiento para prevenir la rigidez y favorecer la recuperación."],"img":"0798-a8VDgLw.jpg","gif":"0798-a8VDgLw.gif"},{"id":"3314","n":"Maltesa con piernas abiertas","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","chest"],"st":["Comienza colgándote de un par de anillas con los brazos completamente extendidos y el cuerpo en línea recta.","Separa bien las piernas, formando una posición a horcajadas.","Activa el core y baja lentamente el cuerpo hasta que los brazos queden paralelos al suelo.","Mantén esta posición durante unos segundos, luego empújate de nuevo hacia arriba a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3314-HfqciZF.jpg","gif":"3314-HfqciZF.gif"},{"id":"3298","n":"Plancha straddle","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","triceps","chest"],"st":["Comienza en posición de flexión con las manos separadas a la altura de los hombros y los pies bien separados.","Activa el core y traslada lentamente tu peso hacia adelante, llevando los hombros por encima de las manos.","Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados.","Haz una pausa por un momento en la posición más baja, luego empuja con las manos para enderezar los brazos y levantar el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3298-BL3GHeY.jpg","gif":"3298-BL3GHeY.gif"},{"id":"1427","n":"Abducción de cadera con pierna recta","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","hamstrings"],"st":["Túmbate de lado con las piernas rectas y apiladas una sobre la otra.","Coloca el brazo de abajo bajo la cabeza para apoyarte.","Activa el core y levanta la pierna superior lo más alto posible sin rotar las caderas ni inclinarte hacia atrás.","Haz una pausa por un momento en la posición alta, luego baja lentamente la pierna de nuevo a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"1427-mQ1tBXn.jpg","gif":"1427-mQ1tBXn.gif"},{"id":"0803","n":"Flexión de Superman","bp":"chest","eq":"body weight","tg":"pectorals","mg":"core","sm":["core","shoulders"],"st":["Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y los pies juntos.","Activa el core y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados.","Mientras bajas el cuerpo, levanta simultáneamente el brazo derecho y la pierna izquierda del suelo, extendiéndolos completamente.","Haz una pausa de un momento en la parte superior, luego baja el brazo y la pierna mientras te empujas de nuevo hacia arriba a la posición inicial.","Repite el movimiento, esta vez levantando el brazo izquierdo y la pierna derecha.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0803-4GqRrAk.jpg","gif":"0803-4GqRrAk.gif"},{"id":"0805","n":"Despliegue abdominal en suspensión","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Sujeta un entrenador de suspensión a un punto de anclaje alto y ajusta las correas a la altura de la cintura.","Ponte de pie de espaldas al punto de anclaje y sostén las asas con los brazos extendidos frente a ti.","Inclínate hacia adelante desde la cintura, manteniendo el cuerpo recto y el core activado.","Baja el cuerpo todo lo que puedas mientras mantienes el control y la tensión en el abdomen.","Haz una pausa de un momento en la parte baja, luego eleva lentamente el cuerpo de nuevo a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0805-X3TCNEU.jpg","gif":"0805-X3TCNEU.gif"},{"id":"0806","n":"Flexión en suspensión","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Busca un entrenador de suspensión y ajústalo a una altura adecuada.","Ponte de pie de espaldas al punto de anclaje y sostén las asas con un agarre prono.","Camina hacia adelante con los pies, inclinando el cuerpo hacia adelante hasta que tu peso quede sostenido por el entrenador de suspensión.","Mantén el cuerpo recto desde la cabeza hasta los talones, activa el core y baja el pecho hacia las asas.","Empuja con el pecho y los brazos para volver a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0806-IaGQCrC.jpg","gif":"0806-IaGQCrC.gif"},{"id":"0807","n":"Crunch inverso en suspensión","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.","Activa el core y sube las rodillas hacia el pecho, curvando la pelvis hacia la caja torácica.","Haz una pausa de un momento en la parte superior, luego baja lentamente las rodillas de nuevo a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0807-R1WYG5D.jpg","gif":"0807-R1WYG5D.gif"},{"id":"0808","n":"Remo en suspensión","bp":"back","eq":"body weight","tg":"upper back","mg":"biceps","sm":["biceps","shoulders"],"st":["Coloca un entrenador de suspensión a una altura adecuada.","Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.","Sostén las asas con un agarre prono, con las palmas mirándose entre sí.","Inclínate hacia atrás, manteniendo el cuerpo recto y los talones en el suelo.","Tira del pecho hacia las asas, apretando los omóplatos entre sí.","Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0808-4OaumBr.jpg","gif":"0808-4OaumBr.gif"},{"id":"0809","n":"Sentadilla búlgara en suspensión","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Ponte de pie de espaldas a un entrenador de suspensión con los pies separados a la altura de los hombros.","Extiende una pierna hacia adelante y coloca el empeine del pie en el soporte para pie del entrenador de suspensión.","Flexiona la pierna de apoyo y baja el cuerpo a una posición de zancada, manteniendo el pecho elevado y la rodilla alineada con la punta del pie.","Empuja con el talón para regresar a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."],"img":"0809-QpXqiq8.jpg","gif":"0809-QpXqiq8.gif"},{"id":"3433","n":"Pataleo de nadador v. 2 (hombre)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","calves"],"st":["Túmbate boca abajo sobre una esterilla con los brazos extendidos por encima de la cabeza.","Activa el core y levanta el pecho y las piernas del suelo al mismo tiempo.","Mueve las piernas hacia arriba y hacia abajo con un movimiento de aleteo, como si estuvieras nadando.","Continúa el movimiento de patada el número de repeticiones deseado.","Baja el pecho y las piernas de nuevo a la posición inicial."],"img":"3433-SP3hUez.jpg","gif":"3433-SP3hUez.gif"},{"id":"3318","n":"Swing 360","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"shoulders","sm":["shoulders","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Mantén los brazos extendidos rectos frente a ti, paralelos al suelo.","Activa el core y mueve los brazos en un movimiento circular, rotando el torso mientras lo haces.","Continúa el movimiento circular, moviendo los brazos y rotando el torso el número de repeticiones deseado.","Recuerda respirar durante todo el ejercicio."],"img":"3318-tnaj0mT.jpg","gif":"3318-tnaj0mT.gif"},{"id":"1753","n":"Fondos de tríceps entre tres bancos","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Siéntate en un banco con las manos agarrando el borde, los dedos apuntando hacia adelante.","Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos.","Flexiona los codos y baja el cuerpo hasta que la parte superior de los brazos quede paralela al suelo.","Empújate de vuelta hacia arriba hasta la posición inicial.","Repite el número de repeticiones deseado."],"img":"1753-DQ0cqkT.jpg","gif":"1753-DQ0cqkT.gif"},{"id":"2459","n":"Volteo de neumático","bp":"upper legs","eq":"tire","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","core"],"st":["Ponte de pie con los pies separados a la altura de los hombros, de frente al neumático.","Flexiona las rodillas y dobla las caderas, bajando a una posición de sentadilla.","Agáchate y agarra el borde inferior del neumático con ambas manos, con los dedos apuntando hacia ti.","Activa los glúteos y los músculos de las piernas, y empuja con fuerza a través de las piernas para levantar el neumático del suelo.","Mientras el neumático se voltea, usa la fuerza de la parte superior del cuerpo para guiarlo y mantener el control.","Una vez que el neumático esté completamente volteado, retrocede rápidamente y reinicia tu postura.","Repite el número de repeticiones deseado."],"img":"2459-oZjMu1t.jpg","gif":"2459-oZjMu1t.gif"},{"id":"0811","n":"Peso muerto con barra hexagonal","bp":"upper legs","eq":"trap bar","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","lower back"],"st":["Ponte de pie con los pies separados a la altura de los hombros y la barra hexagonal en el suelo frente a ti.","Flexiona las caderas y las rodillas para bajar y agarra las asas de la barra hexagonal con un agarre prono.","Mantén la espalda recta y el pecho elevado mientras comienzas a levantar la barra hexagonal del suelo extendiendo las caderas y las rodillas.","Al levantar, concéntrate en empujar con los talones y contraer los glúteos en la parte superior del movimiento.","Baja la barra hexagonal de nuevo al suelo flexionando las caderas y las rodillas, manteniendo la espalda recta durante todo el movimiento.","Repite el número de repeticiones deseado."],"img":"0811-jQGwmxN.jpg","gif":"0811-jQGwmxN.gif"},{"id":"0814","n":"Fondos de tríceps","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Siéntate en el borde de un banco o silla con las manos sujetando el borde, los dedos apuntando hacia adelante.","Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos.","Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco.","Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0814-X6C6i5Y.jpg","gif":"0814-X6C6i5Y.gif"},{"id":"0812","n":"Fondos de tríceps con pies en banco","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Siéntate en el borde de un banco con las manos agarrando el borde, los dedos apuntando hacia adelante.","Camina con los pies hacia adelante, deslizando los glúteos fuera del banco, y estira los brazos.","Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco.","Empuja con las palmas para estirar los brazos y regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0812-VuoerH0.jpg","gif":"0812-VuoerH0.gif"},{"id":"0813","n":"Fondos de tríceps (entre bancos)","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Siéntate en un banco con las manos agarrando el borde del banco, los dedos apuntando hacia adelante.","Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos.","Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco.","Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0813-Wgbn9qo.jpg","gif":"0813-Wgbn9qo.gif"},{"id":"0815","n":"Fondos de tríceps en el suelo","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Siéntate en el borde de una silla o banco con las manos junto a las caderas, los dedos apuntando hacia adelante.","Desliza los glúteos fuera del frente de la silla con las piernas extendidas frente a ti.","Estira los brazos, manteniendo una ligera flexión en los codos para conservar la tensión en los tríceps y aliviarla en las articulaciones del codo.","Flexiona lentamente los codos para bajar el cuerpo hacia el suelo hasta que los codos formen un ángulo de aproximadamente 90 grados.","Cuando llegues al punto más bajo del movimiento, empuja hacia abajo contra la silla para estirar los codos, volviendo a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0815-7aVz15j.jpg","gif":"0815-7aVz15j.gif"},{"id":"0816","n":"Press de tríceps","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Extiende los brazos rectos frente a ti, paralelos al suelo.","Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la parte superior de los brazos cerca de los costados.","Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0816-fSrPP6B.jpg","gif":"0816-fSrPP6B.gif"},{"id":"0817","n":"Estiramiento de tríceps","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Ponte de pie o siéntate erguido con la espalda recta.","Extiende un brazo por encima de la cabeza, flexionándolo por el codo.","Coloca la mano opuesta sobre el codo flexionado y tira de él suavemente hacia tu cabeza.","Mantén el estiramiento de 15 a 30 segundos, sintiendo un estiramiento suave en el tríceps.","Suelta el estiramiento y repite con el otro brazo."],"img":"0817-uOV3Itw.jpg","gif":"0817-uOV3Itw.gif"},{"id":"0871","n":"Crunch con rodillas al pecho","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta los omóplatos del suelo y lleva las rodillas hacia el pecho, curvando al mismo tiempo la parte superior del cuerpo hacia las rodillas.","Haz una pausa de un momento en la parte superior, luego baja lentamente los omóplatos y extiende las piernas de nuevo a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0871-BMMolZ3.jpg","gif":"0871-BMMolZ3.gif"},{"id":"0818","n":"Jalón al pecho con agarre neutro doble","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Ajusta la altura del asiento y colócate de frente a la máquina de cable.","Agarra las asas con un agarre prono, con las manos separadas a la altura de los hombros.","Siéntate y coloca los muslos debajo de las almohadillas para muslos, manteniendo los pies planos sobre el suelo.","Inclínate ligeramente hacia atrás y mantén el pecho elevado, conservando una columna neutral.","Tira de las asas hacia la parte superior del pecho, apretando los omóplatos entre sí.","Haz una pausa por un momento en la parte inferior del movimiento, sintiendo la contracción en los dorsales.","Suelta lentamente las asas y vuelve a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0818-rkg41Fb.jpg","gif":"0818-rkg41Fb.gif"},{"id":"1466","n":"Elevación de cadera con giro","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"obliques","sm":["obliques","hamstrings"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos a los lados para mayor apoyo.","Activa los glúteos y levanta las caderas del suelo, formando una línea recta desde las rodillas hasta los hombros.","Manteniendo las caderas elevadas, gira la parte inferior del cuerpo hacia el lado derecho, llevando las rodillas hacia el suelo.","Vuelve a la posición inicial y repite el giro hacia el lado izquierdo.","Continúa alternando los giros el número de repeticiones deseado."],"img":"1466-AX1kB0o.jpg","gif":"1466-AX1kB0o.gif"},{"id":"2802","n":"Elevación de piernas con giro","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.","Coloca las manos debajo de los glúteos como apoyo.","Activa el abdomen y levanta ambas piernas del suelo, manteniéndolas rectas.","Mientras levantas las piernas, gira las caderas hacia un lado, llevando las piernas hacia el hombro opuesto.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el movimiento, esta vez girando las caderas hacia el otro lado.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"2802-C0eCeEt.jpg","gif":"2802-C0eCeEt.gif"},{"id":"2801","n":"Elevación de piernas con giro (mujer)","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.","Flexiona las rodillas y levanta las piernas del suelo, llevándolas hacia el pecho.","Mientras levantas las piernas, gira las caderas hacia un lado, llevando las rodillas hacia el hombro opuesto.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el movimiento, esta vez girando las caderas hacia el otro lado.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"2801-yT9tk17.jpg","gif":"2801-yT9tk17.gif"},{"id":"3231","n":"Toque de puntas alterno (hombre)","bp":"back","eq":"body weight","tg":"spine","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados.","Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y las rodillas ligeramente flexionadas.","Estira los brazos hacia la punta de los pies con ambas manos, manteniendo las piernas rectas.","Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3231-p195zsJ.jpg","gif":"3231-p195zsJ.gif"},{"id":"1365","n":"Estiramiento de la parte superior de la espalda","bp":"back","eq":"body weight","tg":"upper back","mg":"shoulders","sm":["shoulders"],"st":["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.","Extiende los brazos rectos frente a ti, paralelos al suelo.","Entrelaza los dedos y gira las palmas alejándolas de tu cuerpo.","Eleva lentamente los brazos por encima de la cabeza, manteniéndolos rectos y paralelos entre sí.","Mientras elevas los brazos, aprieta los omóplatos entre sí.","Mantén el estiramiento de 15 a 30 segundos, luego suelta y repite."],"img":"1365-GSDioYu.jpg","gif":"1365-GSDioYu.gif"},{"id":"1366","n":"Perro boca arriba","bp":"back","eq":"body weight","tg":"spine","mg":"shoulders","sm":["shoulders","chest"],"st":["Túmbate boca abajo en el suelo con las piernas extendidas detrás de ti.","Coloca las manos en el suelo junto a las costillas inferiores, con los dedos apuntando hacia adelante.","Presiona las manos firmemente contra el suelo y estira los brazos, levantando el torso y los muslos del suelo.","Lleva los hombros hacia atrás y hacia abajo, abriendo el pecho y elevando la mirada hacia el techo.","Mantén esta posición durante unas cuantas respiraciones, luego baja lentamente el cuerpo de nuevo a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1366-01qpYSe.jpg","gif":"1366-01qpYSe.gif"},{"id":"3420","n":"V-sit en el suelo","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Siéntate en el suelo con las piernas extendidas frente a ti.","Inclínate ligeramente hacia atrás y levanta las piernas del suelo, manteniéndolas rectas.","Al mismo tiempo, levanta la parte superior del cuerpo del suelo y extiende los brazos hacia las piernas.","Mantén esta posición durante unos segundos, luego baja lentamente la parte superior del cuerpo y las piernas de nuevo a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3420-ZuXu4Eq.jpg","gif":"3420-ZuXu4Eq.gif"},{"id":"0826","n":"Elevación vertical de piernas (en barras paralelas)","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Cuélgate de las barras paralelas con los brazos completamente extendidos y el cuerpo recto.","Activa el core y levanta las piernas frente a ti, manteniéndolas rectas.","Continúa levantando hasta que las piernas queden paralelas al suelo o un poco más arriba.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0826-ZNgOYQU.jpg","gif":"0826-ZNgOYQU.gif"},{"id":"2141","n":"Caminar en bicicleta elíptica","bp":"cardio","eq":"elliptical machine","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","glutes","calves"],"st":["Ajusta el nivel de resistencia y la inclinación de la máquina elíptica a los valores deseados.","Sube a los pedales de la máquina y agarra las asas con suavidad.","Comienza empujando hacia abajo con los pies y tirando de las asas hacia tu cuerpo.","Continúa con este movimiento, alternando entre empujar y tirar, para simular un movimiento de caminar o correr.","Mantén un ritmo constante y conserva el core activado durante todo el ejercicio.","Continúa durante la duración deseada de tu entrenamiento cardiovascular.","Disminuye gradualmente la intensidad y la velocidad de la máquina antes de bajarte."],"img":"2141-rjtuP6X.jpg","gif":"2141-rjtuP6X.gif"},{"id":"3655","n":"Zancadas caminando con elevación de rodilla","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","glutes","calves"],"st":["Ponte de pie con los pies separados a la altura de la cadera.","Levanta la rodilla derecha hacia el pecho lo más alto que puedas mientras mantienes el equilibrio sobre la pierna izquierda.","Da un paso adelante con el pie derecho y baja el cuerpo a una posición de zancada, flexionando ambas rodillas a un ángulo de 90 grados.","Empújate con el pie derecho y lleva la rodilla izquierda hacia el pecho.","Da un paso adelante con el pie izquierdo y baja el cuerpo a una posición de zancada.","Continúa alternando las piernas y avanzando con zancadas, manteniendo el core activado y un ritmo constante.","Repite el número de repeticiones deseado."],"img":"3655-J9zIWig.jpg","gif":"3655-J9zIWig.gif"},{"id":"1460","n":"Zancadas caminando","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros.","Da un paso adelante con la pierna derecha, bajando el cuerpo a una posición de zancada.","Mantén el torso erguido y la rodilla delantera alineada con el tobillo.","Empújate con el pie derecho y lleva el pie izquierdo hacia adelante, entrando en una posición de zancada con la pierna izquierda.","Continúa alternando las piernas y avanzando, manteniendo un ritmo controlado y constante.","Repite el número de repeticiones deseado."],"img":"1460-IZVHb27.jpg","gif":"1460-IZVHb27.gif"},{"id":"3666","n":"Caminar en cinta inclinada","bp":"cardio","eq":"leverage machine","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ajusta el nivel de inclinación de la cinta de correr a la intensidad deseada.","Ponte de pie sobre la cinta de correr con los pies separados a la altura de los hombros.","Comienza a caminar a un ritmo cómodo, asegurándote de mantener una forma correcta.","Activa los músculos del core y mantén la espalda recta durante todo el ejercicio.","Continúa caminando en la cinta inclinada durante la duración deseada de tu entrenamiento cardiovascular.","Disminuye gradualmente la inclinación y la velocidad de la cinta para enfriar antes de detenerte."],"img":"3666-rjiM4L3.jpg","gif":"3666-rjiM4L3.gif"},{"id":"2311","n":"Caminar en máquina de escaleras","bp":"cardio","eq":"stepmill machine","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","glutes","calves"],"st":["Ajusta la máquina de escalones a un nivel cómodo.","Sube a la máquina y coloca las manos sobre los pasamanos para apoyarte.","Comienza a caminar colocando un pie en un escalón y luego el otro, alternando entre las piernas.","Mantén una postura erguida y activa los músculos del core.","Continúa caminando durante la duración o distancia deseada.","Aumenta gradualmente la intensidad o la velocidad a medida que te sientas más cómodo con el ejercicio.","Recuerda enfriar y estirar después de completar el ejercicio."],"img":"2311-j9Q5crt.jpg","gif":"2311-j9Q5crt.gif"},{"id":"0830","n":"Fondos en banco con peso","bp":"upper arms","eq":"weighted","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Siéntate en un banco con las manos agarrando el borde, los dedos apuntando hacia adelante.","Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos.","Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.","Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."],"img":"0830-MU9HnE7.jpg","gif":"0830-MU9HnE7.gif"},{"id":"2987","n":"Dominadas supinas con agarre estrecho y lastre en jaula","bp":"back","eq":"weighted","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Ponte de pie frente a la jaula de fondos y agarra las barras paralelas con un agarre supino, con las manos separadas a la altura de los hombros.","Cuélgate de las barras con los brazos completamente extendidos, los pies levantados del suelo y el cuerpo recto.","Activa los músculos de la espalda y tira de tu cuerpo hacia arriba en dirección a las barras, manteniendo los codos cerca de los costados.","Continúa tirando hasta que tu barbilla quede por encima de las barras, luego haz una pausa de un momento.","Baja lentamente el cuerpo de nuevo a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"img":"2987-Gk1r408.jpg","gif":"2987-Gk1r408.gif"},{"id":"3643","n":"Sentadillas cosacas con lastre (hombre)","bp":"upper legs","eq":"weighted","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies más separados que la anchura de los hombros y la punta de los pies apuntando ligeramente hacia afuera.","Sostén un peso frente al pecho con ambas manos.","Traslada tu peso hacia un lado y baja el cuerpo flexionando la rodilla del lado hacia el que te inclinaste, manteniendo la otra pierna recta.","Baja todo lo que puedas mientras mantienes el equilibrio y el pecho elevado.","Empuja con el talón de la pierna flexionada para volver a la posición inicial.","Repite con el otro lado, alternando entre las piernas."],"img":"3643-GWoKnIm.jpg","gif":"3643-GWoKnIm.gif"},{"id":"0832","n":"Crunch abdominal con lastre","bp":"waist","eq":"weighted","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Sostén un disco de peso o una mancuerna sobre el pecho.","Activa el abdomen y levanta la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que los omóplatos se separen del suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0832-s8nrDXF.jpg","gif":"0832-s8nrDXF.gif"},{"id":"3670","n":"Sit-up en banco declinado con lastre","bp":"waist","eq":"weighted","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Túmbate boca arriba en un banco declinado con los pies sujetos debajo de las almohadillas para los pies.","Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.","Activa el abdomen y levanta lentamente la parte superior del cuerpo del banco, curvándote hacia adelante hasta que el torso quede perpendicular al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3670-EZeDVzO.jpg","gif":"3670-EZeDVzO.gif"},{"id":"0833","n":"Elevación de talones tipo burro con lastre","bp":"lower legs","eq":"weighted","tg":"calves","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Ponte de pie sobre una plataforma elevada con la punta de los pies en el borde y los talones colgando.","Sujétate de un objeto estable para mayor apoyo.","Eleva los talones tan alto como puedas extendiendo los tobillos.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0833-LmaFNZS.jpg","gif":"0833-LmaFNZS.gif"},{"id":"1310","n":"Flexiones con caída y lastre","bp":"chest","eq":"weighted","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y los pies juntos.","Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo.","Cuando el pecho esté justo por encima del suelo, empújate hacia arriba de forma explosiva, levantando las manos del suelo.","Mientras te empujas hacia arriba, mueve rápidamente las manos hacia los lados y un poco hacia adelante, permitiendo que tu cuerpo caiga hacia el suelo.","Recíbete con las manos en la posición más ancha y baja de nuevo el pecho inmediatamente hacia el suelo.","Repite el movimiento de flexión, bajando y recibiéndote con las manos en la posición más estrecha.","Continúa alternando entre las posiciones de manos más ancha y más estrecha el número de repeticiones deseado."],"img":"1310-PSlvNMs.jpg","gif":"1310-PSlvNMs.gif"},{"id":"2135","n":"Plancha frontal con lastre","bp":"waist","eq":"weighted","tg":"abs","mg":"shoulders","sm":["shoulders","lower back"],"st":["Comienza tumbándote boca abajo en el suelo.","Coloca los antebrazos en el suelo, con los codos justo debajo de los hombros.","Extiende las piernas rectas hacia atrás, con la punta de los pies en el suelo.","Activa el core y levanta el cuerpo del suelo, equilibrándote sobre los antebrazos y la punta de los pies.","Mantén el cuerpo en línea recta desde la cabeza hasta los talones.","Mantén esta posición durante el tiempo deseado.","Baja el cuerpo de nuevo a la posición inicial.","Repite el número de repeticiones deseado."],"img":"2135-VBAWRPG.jpg","gif":"2135-VBAWRPG.gif"},{"id":"0834","n":"Elevación frontal con peso","bp":"shoulders","eq":"weighted","tg":"delts","mg":"biceps","sm":["biceps","forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia los muslos.","Manteniendo los brazos rectos, exhala y levanta las mancuernas frente a ti hasta que queden a la altura de los hombros.","Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0834-e4aFmFY.jpg","gif":"0834-e4aFmFY.gif"},{"id":"0866","n":"Elevación de piernas y cadera colgado con lastre","bp":"waist","eq":"weighted","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.","Activa el core y levanta las piernas frente a ti, manteniéndolas rectas.","Continúa levantando hasta que las piernas queden paralelas al suelo o un poco más arriba.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0866-QOA0FD0.jpg","gif":"0866-QOA0FD0.gif"},{"id":"0835","n":"Hiperextensiones con lastre (en balón de estabilidad)","bp":"back","eq":"weighted","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Colócate boca abajo sobre un balón de estabilidad con las caderas apoyadas en el balón y los pies contra una pared para mayor estabilidad.","Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.","Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0835-8urJS9b.jpg","gif":"0835-8urJS9b.gif"},{"id":"3641","n":"Paso de rodillas a pie con balanceo y lastre","bp":"shoulders","eq":"weighted","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Comienza en posición de rodillas con las rodillas separadas a la altura de las caderas y la espalda recta.","Sostén un peso en cada mano, con los brazos extendidos rectos hacia abajo frente a ti.","Activa el core y balancea los pesos hacia arriba y por encima de la cabeza, manteniendo los brazos rectos.","Baja los pesos de nuevo a la posición inicial y repite el número de repeticiones deseado."],"img":"3641-7uFJuXp.jpg","gif":"3641-7uFJuXp.gif"},{"id":"3644","n":"Zancada con balanceo y lastre","bp":"upper legs","eq":"weighted","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un peso en cada mano.","Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.","Mientras avanzas en la zancada, balancea los pesos hacia adelante y hacia arriba, manteniendo los brazos rectos.","Empújate con el pie derecho y vuelve a la posición inicial, balanceando los pesos de nuevo hacia abajo.","Repite con el pie izquierdo y continúa alternando las piernas el número de repeticiones deseado."],"img":"3644-5WiFcYk.jpg","gif":"3644-5WiFcYk.gif"},{"id":"3286","n":"Muscle-up con lastre","bp":"back","eq":"weighted","tg":"lats","mg":"biceps","sm":["biceps","triceps","shoulders","chest"],"st":["Comienza colgándote de una barra de dominadas con las palmas mirando hacia afuera y las manos un poco más separadas que la anchura de los hombros.","Activa el core y tira de tu cuerpo hacia arriba, hacia la barra, guiando con el pecho.","Al llegar a la parte alta del movimiento, cambia el agarre de modo que las palmas queden hacia ti.","Continúa subiendo hasta que el pecho llegue a la barra, luego haz una pausa de un momento.","Baja lentamente de nuevo a la posición inicial, manteniendo el control durante todo el movimiento.","Repite el número de repeticiones deseado."],"img":"3286-JsOV1SU.jpg","gif":"3286-JsOV1SU.gif"},{"id":"3312","n":"Muscle-up en barra con lastre","bp":"back","eq":"weighted","tg":"lats","mg":"biceps","sm":["biceps","triceps","shoulders","forearms"],"st":["Comienza colgándote de una barra de dominadas con las palmas mirando hacia afuera y las manos un poco más separadas que la anchura de los hombros.","Activa el core y lleva los omóplatos hacia abajo y atrás.","Flexiona los codos y tira del pecho hacia la barra, manteniendo el cuerpo recto.","Cuando tu pecho llegue a la barra, empuja hacia abajo con las manos y lleva los codos hacia atrás, elevando el cuerpo por encima de la barra.","Haz una pausa en la parte más alta del movimiento, luego baja lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"3312-MCkqdKE.jpg","gif":"3312-MCkqdKE.gif"},{"id":"3290","n":"Dominada a una mano con lastre","bp":"back","eq":"weighted","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros.","Cuélgate de la barra con un brazo completamente extendido y el cuerpo recto.","Activa el core y tira de tu cuerpo hacia arriba en dirección a la barra flexionando el codo y contrayendo los músculos de la espalda.","Continúa subiendo hasta que la barbilla quede por encima de la barra.","Baja el cuerpo de nuevo a la posición inicial con control.","Repite el número de repeticiones deseado."],"img":"3290-fXfqg1E.jpg","gif":"3290-fXfqg1E.gif"},{"id":"0840","n":"Crunch abdominal con brazos sobre la cabeza y lastre (en balón de estabilidad)","bp":"waist","eq":"weighted","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Siéntate sobre un balón de estabilidad con los pies apoyados planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Sostén un disco de peso o una mancuerna con ambas manos y extiende los brazos por encima de la cabeza.","Activa el abdomen y curva lentamente el torso hacia adelante, llevando el pecho hacia las rodillas.","Haz una pausa de un momento en la parte superior, luego baja lentamente el torso de nuevo a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0840-xmM75XG.jpg","gif":"0840-xmM75XG.gif"},{"id":"0841","n":"Dominada con lastre","bp":"back","eq":"weighted","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros.","Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.","Activa los músculos de la espalda y tira de tu cuerpo hacia arriba, hacia la barra, manteniendo los codos cerca del cuerpo.","Continúa subiendo hasta que la barbilla quede por encima de la barra.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0841-HMzLjXx.jpg","gif":"0841-HMzLjXx.gif"},{"id":"0844","n":"Rotación de brazos en círculo con peso","bp":"shoulders","eq":"weighted","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Eleva los brazos hacia los lados, manteniendo una ligera flexión en los codos.","Continúa elevando los brazos hasta que queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0844-VLYXo8S.jpg","gif":"0844-VLYXo8S.gif"},{"id":"0846","n":"Giro ruso con lastre","bp":"waist","eq":"weighted","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Siéntate en el suelo con las rodillas flexionadas y los pies apoyados en el suelo.","Sostén un peso o un balón medicinal con ambas manos frente al pecho.","Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el core activado.","Gira lentamente el torso hacia la derecha, llevando el peso o el balón medicinal hacia el suelo a tu lado derecho.","Haz una pausa de un momento, luego gira el torso hacia la izquierda, llevando el peso o el balón medicinal hacia el suelo a tu lado izquierdo.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0846-fZFZ704.jpg","gif":"0846-fZFZ704.gif"},{"id":"0845","n":"Giro ruso con piernas elevadas y lastre","bp":"waist","eq":"weighted","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Siéntate en el suelo con las rodillas flexionadas y los pies levantados del suelo, manteniendo las piernas juntas.","Sostén el peso con ambas manos frente al pecho, manteniendo los codos ligeramente flexionados.","Inclínate ligeramente hacia atrás para activar los músculos del core.","Gira el torso hacia la derecha, llevando el peso hacia el suelo a tu lado derecho.","Haz una pausa de un momento, luego gira el torso hacia la izquierda, llevando el peso hacia el suelo a tu lado izquierdo.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0845-WU9BLIs.jpg","gif":"0845-WU9BLIs.gif"},{"id":"2371","n":"Giro ruso con peso v. 2","bp":"waist","eq":"weighted","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Siéntate en el suelo con las rodillas flexionadas y los pies apoyados en el suelo.","Sostén el peso con ambas manos frente al pecho.","Inclínate ligeramente hacia atrás para activar los músculos del core.","Gira el torso hacia la derecha, llevando el peso hacia el lado derecho de tu cuerpo.","Haz una pausa de un momento, luego gira el torso hacia la izquierda, llevando el peso hacia el lado izquierdo de tu cuerpo.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"2371-YIUAtYf.jpg","gif":"2371-YIUAtYf.gif"},{"id":"0847","n":"Curl de bíceps sentado con peso (en pelota de estabilidad)","bp":"upper arms","eq":"medicine ball","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta.","Sostén un balón medicinal con un agarre supino, las palmas hacia arriba, y deja que los brazos cuelguen a los lados.","Manteniendo la parte superior de los brazos quieta, exhala y curva el balón medicinal hacia los hombros.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente el balón medicinal de nuevo a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0847-b4b6afT.jpg","gif":"0847-b4b6afT.gif"},{"id":"0849","n":"Giro sentado con peso (en pelota de estabilidad)","bp":"waist","eq":"weighted","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Siéntate sobre un balón de estabilidad con los pies apoyados planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.","Sostén un disco de peso o una mancuerna con ambas manos cerca del pecho.","Activa el core y rota lentamente el torso hacia un lado, manteniendo las caderas estables.","Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.","Repite la rotación hacia el otro lado.","Continúa alternando lados durante el número de repeticiones deseado."],"img":"0849-s34Y4LR.jpg","gif":"0849-s34Y4LR.gif"},{"id":"0850","n":"Flexión lateral con peso (en pelota de estabilidad)","bp":"waist","eq":"weighted","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Siéntate sobre un balón de estabilidad con los pies separados a la altura de los hombros y planos sobre el suelo.","Sostén un peso en una mano y coloca la otra mano sobre la cadera.","Activa el core e inclínate lentamente hacia el lado del peso, manteniendo la espalda recta.","Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"img":"0850-6bOA1Oi.jpg","gif":"0850-6bOA1Oi.gif"},{"id":"0851","n":"Sentadilla sissy con peso","bp":"upper legs","eq":"weighted","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.","Sostén un peso frente al pecho con ambas manos, o coloca una barra sobre la parte superior de la espalda.","Manteniendo el pecho elevado y el core activado, baja lentamente el cuerpo flexionando las rodillas y las caderas.","Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0851-0lQnxMZ.jpg","gif":"0851-0lQnxMZ.gif"},{"id":"0852","n":"Sentadilla con peso","bp":"upper legs","eq":"weighted","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.","Sostén un peso frente al pecho o sobre los hombros.","Activa el core y mantén el pecho elevado mientras bajas las caderas hacia abajo y hacia atrás, como si te sentaras en una silla.","Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Empuja con los talones para volver a ponerte de pie, contrayendo los glúteos en la parte superior.","Repite el número de repeticiones deseado."],"img":"0852-JZuApnB.jpg","gif":"0852-JZuApnB.gif"},{"id":"0853","n":"Curl de pie con peso","bp":"upper arms","eq":"weighted","tg":"biceps","mg":"forearms","sm":["forearms"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante.","Mantén los codos cerca del torso y exhala mientras curvas los pesos hasta la altura de los hombros.","Haz una pausa de un momento en la parte superior, luego inhala mientras bajas lentamente los pesos de nuevo a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0853-M5Y7GPg.jpg","gif":"0853-M5Y7GPg.gif"},{"id":"0854","n":"Apretón de manos de pie con peso","bp":"lower arms","eq":"weighted","tg":"forearms","mg":"biceps","sm":["biceps","triceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén un peso en cada mano.","Extiende los brazos rectos hacia adelante, con las palmas mirándose entre sí.","Aprieta las manos entre sí con la mayor fuerza posible, activando los antebrazos.","Mantén la contracción durante unos segundos y luego suelta.","Repite el número de repeticiones deseado."],"img":"0854-bjqbauy.jpg","gif":"0854-bjqbauy.gif"},{"id":"3313","n":"Fondos en barra recta con peso","bp":"chest","eq":"weighted","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Colócate entre las barras paralelas con los brazos completamente extendidos y el cuerpo recto.","Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.","Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.","Repite el número de repeticiones deseado."],"img":"3313-Ff18ItA.jpg","gif":"3313-Ff18ItA.gif"},{"id":"3642","n":"Zancada con estiramiento y peso","bp":"upper legs","eq":"weighted","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Ponte de pie con los pies separados a la altura de los hombros.","Da un paso adelante con el pie derecho, manteniendo la espalda recta.","Baja el cuerpo flexionando las rodillas hasta que el muslo derecho quede paralelo al suelo.","Empuja con el talón derecho para regresar a la posición inicial.","Repite con la pierna izquierda.","Continúa alternando las piernas durante el número de repeticiones deseado."],"img":"3642-13VW2VO.jpg","gif":"3642-13VW2VO.gif"},{"id":"0856","n":"Press Svend con peso","bp":"chest","eq":"weighted","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Ponte de pie con los pies separados a la altura de los hombros y sostén un disco de peso frente al pecho con ambas manos.","Mantén los codos ligeramente flexionados y las palmas mirándose entre sí.","Empuja el disco de peso recto hacia adelante, extendiendo completamente los brazos.","Haz una pausa de un momento al final del movimiento, luego lleva lentamente el disco de peso de nuevo a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0856-I1OBLnn.jpg","gif":"0856-I1OBLnn.gif"},{"id":"1754","n":"Fondos entre tres bancos con peso","bp":"upper arms","eq":"weighted","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Siéntate en el borde de un banco con las manos agarrando el borde, los dedos apuntando hacia adelante.","Camina con los pies hacia adelante, deslizando los glúteos fuera del banco y sosteniendo tu peso con los brazos.","Baja el cuerpo flexionando los codos, manteniendo la espalda cerca del banco.","Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1754-gtO1ErP.jpg","gif":"1754-gtO1ErP.gif"},{"id":"1755","n":"Fondos de tríceps con peso","bp":"upper arms","eq":"weighted","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Siéntate en el borde de un banco o silla con las manos sujetando el borde junto a las caderas.","Desliza los glúteos fuera del frente del banco con las piernas extendidas frente a ti.","Mantén la espalda cerca del banco y los codos ligeramente flexionados.","Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.","Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."],"img":"1755-bZq4bwK.jpg","gif":"1755-bZq4bwK.gif"},{"id":"1767","n":"Fondos de tríceps con peso en barras paralelas altas","bp":"upper arms","eq":"weighted","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Colócate entre dos barras paralelas con las manos agarrando las barras y los brazos completamente extendidos.","Flexiona los codos y baja el cuerpo hasta que la parte superior de los brazos quede paralela al suelo.","Haz una pausa de un momento, luego empuja con las palmas para estirar los brazos y volver a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1767-K1vlode.jpg","gif":"1767-K1vlode.gif"},{"id":"0857","n":"Despliegue con rueda abdominal","bp":"waist","eq":"wheel roller","tg":"abs","mg":"lower back","sm":["lower back"],"st":["Arrodíllate en el suelo y coloca el rodillo frente a ti.","Coloca las manos en las asas del rodillo y extiende los brazos rectos hacia adelante.","Activa los músculos del core y haz rodar lentamente el rodillo hacia adelante, manteniendo la espalda recta y el abdomen contraído.","Continúa rodando hacia delante hasta que el cuerpo esté completamente extendido y los brazos por encima de la cabeza.","Haz una pausa de un momento, luego haz rodar lentamente el rodillo de regreso hacia las rodillas, manteniendo el control y el abdomen activado.","Repite el número de repeticiones deseado."],"img":"0857-NAgVB3t.jpg","gif":"0857-NAgVB3t.gif"},{"id":"3637","n":"Carrera con rueda","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Comienza en posición de plancha con las manos sobre el rodillo y el cuerpo recto.","Activa el core y comienza a hacer rodar el rodillo hacia adelante extendiendo los brazos.","Continúa rodando hasta que tu cuerpo quede completamente extendido y los brazos por encima de la cabeza.","Invierte el movimiento tirando del rodillo de vuelta hacia tu cuerpo, usando el core y los brazos.","Repite el número de repeticiones deseado."],"img":"3637-km2Ljzj.jpg","gif":"3637-km2Ljzj.gif"},{"id":"1429","n":"Dominada con agarre ancho","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Cuélgate de una barra de dominadas con las palmas mirando hacia afuera y las manos más separadas que la anchura de los hombros.","Activa el core y junta los omóplatos.","Tira de tu cuerpo hacia arriba en dirección a la barra hasta que tu barbilla quede por encima de la barra.","Baja el cuerpo de nuevo a la posición inicial con control.","Repite el número de repeticiones deseado."],"img":"1429-Qqi7bko.jpg","gif":"1429-Qqi7bko.gif"},{"id":"1367","n":"Dominada trasnuca con agarre ancho","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms"],"st":["Agarra la barra de dominadas con un agarre prono amplio, las manos un poco más separadas que la anchura de los hombros.","Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.","Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, llevando el pecho por delante.","Continúa subiendo hasta que la barbilla quede por encima de la barra.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1367-OYFhXVD.jpg","gif":"1367-OYFhXVD.gif"},{"id":"1311","n":"Flexión con manos separadas","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Comienza en una posición de plancha alta con las manos más separadas que la anchura de los hombros.","Mantén el cuerpo en línea recta de la cabeza a los pies.","Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.","Empuja con las palmas para extender los brazos y regresar a la posición inicial.","Repite el número de repeticiones deseado."],"img":"1311-JmMVpR3.jpg","gif":"1311-JmMVpR3.gif"},{"id":"2363","n":"Fondos para pecho con agarre ancho en barras paralelas altas","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Colócate sobre las barras paralelas con los brazos completamente extendidos y el cuerpo suspendido en el aire.","Inclínate ligeramente hacia adelante y baja el cuerpo flexionando los codos hasta que el pecho quede justo por encima de las barras.","Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.","Repite el número de repeticiones deseado."],"img":"2363-O2K9Vb5.jpg","gif":"2363-O2K9Vb5.gif"},{"id":"0858","n":"Sprints con viento","bp":"waist","eq":"body weight","tg":"abs","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Busca un espacio abierto o una pista para realizar el ejercicio.","Comienza de pie con los pies separados a la altura de los hombros.","Comienza a correr lo más rápido que puedas, bombeando los brazos y elevando las rodillas.","Continúa el sprint durante una distancia o periodo de tiempo específico.","Descansa y repite el número de repeticiones deseado."],"img":"0858-Qoujh3Q.jpg","gif":"0858-Qoujh3Q.gif"},{"id":"1604","n":"El mejor estiramiento del mundo","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","quadriceps","calves"],"st":["Comienza en posición de zancada con el pie derecho adelante y el pie izquierdo atrás.","Coloca las manos en el suelo a ambos lados de tu pie derecho.","Baja la rodilla izquierda hacia el suelo y extiende la pierna derecha, manteniendo el pie derecho plano sobre el suelo.","Gira el torso hacia la derecha, extendiendo el brazo derecho hacia el techo.","Mantén esta posición durante unos segundos, luego vuelve a la posición inicial.","Cambia de lado y repite el estiramiento con el pie izquierdo adelante."],"img":"1604-DFGXwZr.jpg","gif":"1604-DFGXwZr.gif"},{"id":"1428","n":"Círculos de muñeca","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"hands","sm":["hands","wrists"],"st":["Extiende los brazos rectos frente a ti.","Cierra ambas manos en un puño.","Gira las muñecas en un movimiento circular, manteniendo los brazos quietos.","Continúa los círculos de muñeca el número de repeticiones deseado."],"img":"1428-2zNKRUB.jpg","gif":"1428-2zNKRUB.gif"},{"id":"0859","n":"Rodillo de muñeca","bp":"lower arms","eq":"weighted","tg":"forearms","mg":"biceps","sm":["biceps","triceps"],"st":["Sujeta un peso a un extremo de una cuerda o barra.","Sostén el otro extremo de la cuerda o barra con ambas manos, con las palmas hacia abajo.","Ponte de pie con los pies separados a la altura de los hombros y los brazos completamente extendidos frente a ti.","Enrolla lentamente el peso hacia las manos flexionando las muñecas.","Haz una pausa breve en lo alto, luego baja lentamente el peso de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"img":"0859-bd5b860.jpg","gif":"0859-bd5b860.gif"}];
export default EXDB;
